  `history_es` = IF(LOCATE(CAST('El momento estaba bien escogido. La cultura estadounidense del puro entraba a finales de los años sesenta en una fase de expansión y de subida de gama, y el embargo contra Cuba había creado una demanda de alternativas que los centros de producción existentes —República Dominicana, Honduras— no podían satisfacer enteramente. El tabaco nicaragüense de los valles de Jalapa y de Estelí ofrecía un perfil distinto: más terroso y más apimentado que el dominicano, con una intensidad que los catadores experimentados reconocían como otra expresión del tabaco del Nuevo Mundo.

' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El momento estaba bien escogido. La cultura estadounidense del puro entraba a finales de los años sesenta en una fase de expansión y de subida de gama, y el embargo contra Cuba había creado una demanda de alternativas que los centros de producción existentes —República Dominicana, Honduras— no podían satisfacer enteramente. El tabaco nicaragüense de los valles de Jalapa y de Estelí ofrecía un perfil distinto: más terroso y más apimentado que el dominicano, con una intensidad que los catadores experimentados reconocían como otra expresión del tabaco del Nuevo Mundo.

', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der Zeitpunkt war gut gewählt. Die amerikanische Zigarrenkultur trat Ende der sechziger Jahre in eine Phase der Ausweitung und des Aufstiegs in höhere Lagen, und das Embargo gegen Kuba hatte eine Nachfrage nach Alternativen geschaffen, die die bestehenden Erzeugungszentren — Dominikanische Republik, Honduras — nicht vollständig bedienen konnten. Der nicaraguanische Tabak aus den Tälern von Jalapa und Estelí bot ein eigenes Profil: erdiger und pfeffriger als der dominikanische, mit einer Intensität, die erfahrene Verkoster als eine andere Ausdrucksform des Tabaks der Neuen Welt erkannten.

' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der Zeitpunkt war gut gewählt. Die amerikanische Zigarrenkultur trat Ende der sechziger Jahre in eine Phase der Ausweitung und des Aufstiegs in höhere Lagen, und das Embargo gegen Kuba hatte eine Nachfrage nach Alternativen geschaffen, die die bestehenden Erzeugungszentren — Dominikanische Republik, Honduras — nicht vollständig bedienen konnten. Der nicaraguanische Tabak aus den Tälern von Jalapa und Estelí bot ein eigenes Profil: erdiger und pfeffriger als der dominikanische, mit einer Intensität, die erfahrene Verkoster als eine andere Ausdrucksform des Tabaks der Neuen Welt erkannten.

', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('时机选得好。六十年代末，美国的雪茄文化正进入扩张与升级的阶段，而对古巴的禁运造出了对替代来源的需求，现有的产区——多米尼加共和国、洪都拉斯——无法完全满足。哈拉帕与埃斯特利谷地的尼加拉瓜烟草提供了一种分明的风格：比多米尼加的更带泥土、更有胡椒感，其强度被老练的品鉴者认作新大陆烟草的另一种表达。

' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '时机选得好。六十年代末，美国的雪茄文化正进入扩张与升级的阶段，而对古巴的禁运造出了对替代来源的需求，现有的产区——多米尼加共和国、洪都拉斯——无法完全满足。哈拉帕与埃斯特利谷地的尼加拉瓜烟草提供了一种分明的风格：比多米尼加的更带泥土、更有胡椒感，其强度被老练的品鉴者认作新大陆烟草的另一种表达。

', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وكان التوقيت موفَّقًا. فقد دخلت ثقافة السيجار الأمريكية في أواخر الستينيات طورًا من التوسّع والارتقاء، وكان الحظر المفروض على كوبا قد خلق طلبًا على بدائل لم تستطع مراكز الإنتاج القائمة — الجمهورية الدومينيكية وهندوراس — تلبيته بالكامل. وكان التبغ النيكاراغوي من واديَي خالابا وإستيلي يقدّم طابعًا متمايزًا: أكثر ترابية وفلفلية من الدومينيكي، بشدّة رآها الذوّاقة المتمرّسون تعبيرًا آخر عن تبغ العالم الجديد.

' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وكان التوقيت موفَّقًا. فقد دخلت ثقافة السيجار الأمريكية في أواخر الستينيات طورًا من التوسّع والارتقاء، وكان الحظر المفروض على كوبا قد خلق طلبًا على بدائل لم تستطع مراكز الإنتاج القائمة — الجمهورية الدومينيكية وهندوراس — تلبيته بالكامل. وكان التبغ النيكاراغوي من واديَي خالابا وإستيلي يقدّم طابعًا متمايزًا: أكثر ترابية وفلفلية من الدومينيكي، بشدّة رآها الذوّاقة المتمرّسون تعبيرًا آخر عن تبغ العالم الجديد.

', ''), `history_ar`),
  `updated_at` = NOW()
