UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La révolution sandiniste de 1979 referma ce chapitre. La manufacture fut nationalisée, l''encadrement dispersé, et les années 1980 apportèrent crise économique, embargo américain et guerre civile à un pays qui essayait en même temps de cultiver du tabac et de survivre. L''usine tourna par intermittence, à capacité réduite, maintenant une continuité que la plupart des outils industriels n''auraient pas supportée.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La révolution sandiniste de 1979 referma ce chapitre. La manufacture fut nationalisée, l''encadrement dispersé, et les années 1980 apportèrent crise économique, embargo américain et guerre civile à un pays qui essayait en même temps de cultiver du tabac et de survivre. L''usine tourna par intermittence, à capacité réduite, maintenant une continuité que la plupart des outils industriels n''auraient pas supportée.', 'La nouvelle fabrique fut détruite lors du soulèvement populaire de septembre 1978. Après la chute de la dynastie Somoza, le 19 juillet 1979, les ouvriers la reconstruisirent et reprirent la production dans des locaux provisoires, quatre mois sans salaire, dit la maison. La presse du métier précise que l''entreprise fut nationalisée dans les années 1980, les ouvriers en prenant la direction sans parvenir à bien vendre les cigares.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Sandinista revolution of 1979 ended that chapter. The factory was nationalized, the management dispersed, and the 1980s brought economic crisis, American embargo, and civil war to a country trying simultaneously to grow tobacco and survive. The factory operated intermittently on reduced capacity, maintaining continuity through conditions that would have destroyed most manufacturing operations.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Sandinista revolution of 1979 ended that chapter. The factory was nationalized, the management dispersed, and the 1980s brought economic crisis, American embargo, and civil war to a country trying simultaneously to grow tobacco and survive. The factory operated intermittently on reduced capacity, maintaining continuity through conditions that would have destroyed most manufacturing operations.', 'The new factory was destroyed in the popular uprising of September 1978. After the fall of the Somoza dynasty on 19 July 1979, the workers rebuilt it and resumed production in temporary premises, going four months without pay, says the house. The trade press adds that the company was nationalised in the 1980s, with the workers taking over its management without managing to sell the cigars well.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La revolución sandinista de 1979 cerró ese capítulo. La manufactura fue nacionalizada, los cuadros dispersados, y los años ochenta trajeron crisis económica, embargo estadounidense y guerra civil a un país que intentaba a la vez cultivar tabaco y sobrevivir. La fábrica funcionó de manera intermitente, a capacidad reducida, manteniendo una continuidad que la mayoría de las herramientas industriales no habría soportado.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La revolución sandinista de 1979 cerró ese capítulo. La manufactura fue nacionalizada, los cuadros dispersados, y los años ochenta trajeron crisis económica, embargo estadounidense y guerra civil a un país que intentaba a la vez cultivar tabaco y sobrevivir. La fábrica funcionó de manera intermitente, a capacidad reducida, manteniendo una continuidad que la mayoría de las herramientas industriales no habría soportado.', 'La nueva fábrica fue destruida durante el levantamiento popular de septiembre de 1978. Tras la caída de la dinastía Somoza, el 19 de julio de 1979, los obreros la reconstruyeron y reanudaron la producción en locales provisionales, cuatro meses sin salario, dice la casa. La prensa del sector precisa que la empresa fue nacionalizada en los años ochenta, y que los obreros asumieron su dirección sin lograr vender bien los puros.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die sandinistische Revolution von 1979 schloss dieses Kapitel. Die Manufaktur wurde verstaatlicht, die Führung zerstreut, und die achtziger Jahre brachten Wirtschaftskrise, amerikanisches Embargo und Bürgerkrieg über ein Land, das zugleich Tabak anbauen und überleben wollte. Das Werk lief mit Unterbrechungen und verringerter Kapazität und hielt eine Fortdauer aufrecht, die die meisten Industrieanlagen nicht ausgehalten hätten.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die sandinistische Revolution von 1979 schloss dieses Kapitel. Die Manufaktur wurde verstaatlicht, die Führung zerstreut, und die achtziger Jahre brachten Wirtschaftskrise, amerikanisches Embargo und Bürgerkrieg über ein Land, das zugleich Tabak anbauen und überleben wollte. Das Werk lief mit Unterbrechungen und verringerter Kapazität und hielt eine Fortdauer aufrecht, die die meisten Industrieanlagen nicht ausgehalten hätten.', 'Die neue Fabrik wurde beim Volksaufstand im September 1978 zerstört. Nach dem Sturz der Somoza-Dynastie am 19. Juli 1979 bauten die Arbeiter sie wieder auf und nahmen die Produktion in provisorischen Räumen wieder auf, vier Monate ohne Lohn, sagt das Haus. Die Fachpresse präzisiert, das Unternehmen sei in den 1980er Jahren verstaatlicht worden, wobei die Arbeiter die Leitung übernahmen, ohne die Zigarren gut verkaufen zu können.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('1979年的桑地诺革命合上了这一章。工厂被国有化，管理层四散；八十年代给这个既想种烟草又要活下去的国家带来了经济危机、美国禁运与内战。工厂断断续续地开工，产能有限，维持着多数工业设施撑不住的连续性。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '1979年的桑地诺革命合上了这一章。工厂被国有化，管理层四散；八十年代给这个既想种烟草又要活下去的国家带来了经济危机、美国禁运与内战。工厂断断续续地开工，产能有限，维持着多数工业设施撑不住的连续性。', '新工厂在1978年9月的民众起义中被毁。1979年7月19日 Somoza 王朝覆灭后，工人们重建了工厂，在临时场所恢复生产，据公司所述，四个月没有工资。行业媒体补充说，该企业在1980年代被国有化，工人接管了领导权，却未能把雪茄卖好。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أغلقت الثورة الساندينية عام 1979 هذا الفصل. أُمِّم المصنع، وتشتّت الكادر، وجلبت الثمانينيات أزمةً اقتصادية وحظرًا أمريكيًّا وحربًا أهلية إلى بلد كان يحاول في الوقت نفسه زراعة التبغ والبقاء. اشتغل المصنع على فترات متقطّعة وبطاقة مخفّضة، محافظًا على استمرارية ما كانت معظم المنشآت الصناعية لتحتملها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أغلقت الثورة الساندينية عام 1979 هذا الفصل. أُمِّم المصنع، وتشتّت الكادر، وجلبت الثمانينيات أزمةً اقتصادية وحظرًا أمريكيًّا وحربًا أهلية إلى بلد كان يحاول في الوقت نفسه زراعة التبغ والبقاء. اشتغل المصنع على فترات متقطّعة وبطاقة مخفّضة، محافظًا على استمرارية ما كانت معظم المنشآت الصناعية لتحتملها.', 'دُمّر المصنع الجديد خلال الانتفاضة الشعبية في سبتمبر 1978. وبعد سقوط سلالة Somoza في 19 يوليو 1979 أعاد العمال بناءه واستأنفوا الإنتاج في مبانٍ مؤقتة، أربعة شهور بلا أجر، بحسب الدار. وتوضح صحافة المهنة أن الشركة أُمِّمت في ثمانينيات القرن العشرين، وأن العمال تولّوا إدارتها دون أن ينجحوا في بيع السيجار بصورة جيدة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Joya de Nicaragua';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''investissement privé revint en 1994. La reconstruction fut graduelle et délibérée — la nouvelle direction avait compris que l''identité de la marque devait se regagner par la qualité du produit, non par le récit historique. L''Antaño 1970, assemblage conçu pour retrouver la formule de la production de 1970 à partir de tabacs nicaraguayens vieillis six ans, annonça la renaissance. Le Dark Corojo qui suivit pousse l''intensité nicaraguayenne aussi loin que la maison sait la porter.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''investissement privé revint en 1994. La reconstruction fut graduelle et délibérée — la nouvelle direction avait compris que l''identité de la marque devait se regagner par la qualité du produit, non par le récit historique. L''Antaño 1970, assemblage conçu pour retrouver la formule de la production de 1970 à partir de tabacs nicaraguayens vieillis six ans, annonça la renaissance. Le Dark Corojo qui suivit pousse l''intensité nicaraguayenne aussi loin que la maison sait la porter.', 'En 1994, Tabacos Puros de Nicaragua S.A., propriété du Dr Alejandro Martínez Cuenca, acquit Nicaragua Cigar Co. ; la société prend le nom Joya de Nicaragua en 2009. Antaño 1970, assemblage nostalgique de 2001, relança la marque ; Cabinetta Serie et Antaño Dark Corojo suivirent entre 2009 et 2011 (maison). Viennent ensuite deux éditions anniversaire : Cuatro Cinco, pour les 45 ans, 4 500 cigares en 2013 (Cigar Coop, 15 octobre 2013), et Cinco Décadas, pour les 50 ans, en 2018.'), `history`),
  `history_en` = IF(LOCATE(CAST('Private investment returned in 1994. The reconstruction was gradual and deliberate — the new management understood that the brand''s identity had to be reclaimed through product quality rather than historical narrative. The Antaño 1970, a blend designed to replicate the formula of the original 1970 production using 6-year-aged Nicaraguan tobaccos, announced the renaissance with precision. The Dark Corojo that followed became the most extreme expression of Nicaraguan intensity in commercial production — routinely described by reviewers as the most demanding smoke they had experienced.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Private investment returned in 1994. The reconstruction was gradual and deliberate — the new management understood that the brand''s identity had to be reclaimed through product quality rather than historical narrative. The Antaño 1970, a blend designed to replicate the formula of the original 1970 production using 6-year-aged Nicaraguan tobaccos, announced the renaissance with precision. The Dark Corojo that followed became the most extreme expression of Nicaraguan intensity in commercial production — routinely described by reviewers as the most demanding smoke they had experienced.', 'In 1994, Tabacos Puros de Nicaragua S.A., owned by Dr Alejandro Martínez Cuenca, acquired Nicaragua Cigar Co.; the company took the name Joya de Nicaragua in 2009. Antaño 1970, a nostalgic blend from 2001, relaunched the brand; Cabinetta Serie and Antaño Dark Corojo followed between 2009 and 2011 (according to the house). Two anniversary editions then followed: Cuatro Cinco, for the 45th anniversary, 4,500 cigars in 2013 (Cigar Coop, 15 October 2013), and Cinco Décadas, for the 50th anniversary, in 2018.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La inversión privada volvió en 1994. La reconstrucción fue gradual y deliberada —la nueva dirección había comprendido que la identidad de la marca debía reganarse por la calidad del producto, no por el relato histórico. El Antaño 1970, ligada concebida para reencontrar la fórmula de la producción de 1970 a partir de tabacos nicaragüenses envejecidos seis años, anunció el renacimiento. El Dark Corojo que siguió lleva la intensidad nicaragüense tan lejos como la casa sabe llevarla.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La inversión privada volvió en 1994. La reconstrucción fue gradual y deliberada —la nueva dirección había comprendido que la identidad de la marca debía reganarse por la calidad del producto, no por el relato histórico. El Antaño 1970, ligada concebida para reencontrar la fórmula de la producción de 1970 a partir de tabacos nicaragüenses envejecidos seis años, anunció el renacimiento. El Dark Corojo que siguió lleva la intensidad nicaragüense tan lejos como la casa sabe llevarla.', 'En 1994, Tabacos Puros de Nicaragua S.A., propiedad del Dr. Alejandro Martínez Cuenca, adquirió Nicaragua Cigar Co.; la sociedad toma el nombre Joya de Nicaragua en 2009. Antaño 1970, liga nostálgica de 2001, relanzó la marca; Cabinetta Serie y Antaño Dark Corojo siguieron entre 2009 y 2011 (según la casa). Vienen después dos ediciones de aniversario: Cuatro Cinco, por los 45 años, 4 500 puros en 2013 (Cigar Coop, 15 de octubre de 2013), y Cinco Décadas, por los 50 años, en 2018.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Privates Kapital kehrte 1994 zurück. Der Wiederaufbau verlief allmählich und bedacht — die neue Leitung hatte begriffen, dass die Identität der Marke über die Güte des Erzeugnisses zurückzugewinnen war, nicht über die geschichtliche Erzählung. Die Antaño 1970, eine Mischung, die die Rezeptur der Produktion von 1970 aus sechs Jahre gereiften nicaraguanischen Tabaken wiederfinden sollte, kündigte die Wiedergeburt an. Die darauf folgende Dark Corojo treibt die nicaraguanische Intensität so weit, wie das Haus sie zu tragen weiß.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Privates Kapital kehrte 1994 zurück. Der Wiederaufbau verlief allmählich und bedacht — die neue Leitung hatte begriffen, dass die Identität der Marke über die Güte des Erzeugnisses zurückzugewinnen war, nicht über die geschichtliche Erzählung. Die Antaño 1970, eine Mischung, die die Rezeptur der Produktion von 1970 aus sechs Jahre gereiften nicaraguanischen Tabaken wiederfinden sollte, kündigte die Wiedergeburt an. Die darauf folgende Dark Corojo treibt die nicaraguanische Intensität so weit, wie das Haus sie zu tragen weiß.', '1994 erwarb Tabacos Puros de Nicaragua S.A., im Besitz von Dr. Alejandro Martínez Cuenca, die Nicaragua Cigar Co.; die Gesellschaft nimmt 2009 den Namen Joya de Nicaragua an. Antaño 1970, eine nostalgische Mischung von 2001, belebte die Marke neu; Cabinetta Serie und Antaño Dark Corojo folgten zwischen 2009 und 2011 (laut Haus). Danach kommen zwei Jubiläumsausgaben: Cuatro Cinco zum 45-jährigen Bestehen, 4 500 Zigarren im Jahr 2013 (Cigar Coop, 15. Oktober 2013), und Cinco Décadas zum 50-jährigen Bestehen, 2018.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('1994年，私人投资回来了。重建是渐进而审慎的——新的管理层明白，品牌的身份要靠产品品质重新赢回，而不是靠历史叙事。Antaño 1970 以陈化六年的尼加拉瓜烟叶重现1970年的配方，宣告了重生。随后的 Dark Corojo，把尼加拉瓜式的浓烈推到这家字号所能驾驭的尽头。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '1994年，私人投资回来了。重建是渐进而审慎的——新的管理层明白，品牌的身份要靠产品品质重新赢回，而不是靠历史叙事。Antaño 1970 以陈化六年的尼加拉瓜烟叶重现1970年的配方，宣告了重生。随后的 Dark Corojo，把尼加拉瓜式的浓烈推到这家字号所能驾驭的尽头。', '1994年，Dr Alejandro Martínez Cuenca 名下的 Tabacos Puros de Nicaragua S.A. 收购了 Nicaragua Cigar Co.；该公司于2009年改名 Joya de Nicaragua。2001年的怀旧配方 Antaño 1970 让品牌重新起步；Cabinetta Serie 与 Antaño Dark Corojo 在2009年至2011年间相继推出（公司所述）。随后是两款周年版：Cuatro Cinco，为45周年而作，2013年共4 500支（Cigar Coop，2013年10月15日）；以及 Cinco Décadas，为50周年而作，2018年推出。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('عاد الاستثمار الخاص عام 1994. وكانت إعادة البناء تدريجية ومقصودة — فقد فهمت الإدارة الجديدة أن هوية العلامة تُستعاد بجودة المنتج لا بالسرد التاريخي. وأعلنت «أنتانيو 1970»، وهي خلطة صُمِّمت لاستعادة تركيبة إنتاج 1970 من تبغ نيكاراغوي معتَّق ستّ سنوات، عن الولادة الجديدة. أما «دارك كوروخو» التي تلتها فتدفع الشدّة النيكاراغوية إلى أبعد ما تعرف الدار حمله.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'عاد الاستثمار الخاص عام 1994. وكانت إعادة البناء تدريجية ومقصودة — فقد فهمت الإدارة الجديدة أن هوية العلامة تُستعاد بجودة المنتج لا بالسرد التاريخي. وأعلنت «أنتانيو 1970»، وهي خلطة صُمِّمت لاستعادة تركيبة إنتاج 1970 من تبغ نيكاراغوي معتَّق ستّ سنوات، عن الولادة الجديدة. أما «دارك كوروخو» التي تلتها فتدفع الشدّة النيكاراغوية إلى أبعد ما تعرف الدار حمله.', 'في عام 1994 اشترت Tabacos Puros de Nicaragua S.A.، المملوكة للدكتور Alejandro Martínez Cuenca، شركة Nicaragua Cigar Co.؛ وتتخذ الشركة اسم Joya de Nicaragua عام 2009. وأعادت Antaño 1970، وهي خلطة حنينية لعام 2001، إطلاق العلامة؛ وتبعتها Cabinetta Serie وAntaño Dark Corojo بين 2009 و2011 (بحسب الدار). ثم يأتي إصداران بمناسبة الذكرى: Cuatro Cinco بمناسبة السنة الخامسة والأربعين، 4 500 سيجار عام 2013 (Cigar Coop، 15 أكتوبر 2013)، وCinco Décadas بمناسبة السنة الخمسين، عام 2018.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Joya de Nicaragua';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('En 2025, la maison a roulé un Black Swan. Le nom n''est pas le sien : Black Swan appartient à CigarPage, un détaillant américain, qui en a fait une série dont chaque édition est confiée à une manufacture différente et bâtie sur un lot de tabac particulier trouvé chez elle. Quatre éditions, quatre maisons, trois pays — Oliva au Nicaragua en 2023, Rocky Patel au Honduras en janvier 2024, E.P. Carrillo en République dominicaine, et celle-ci. Les quatre ont leur fiche dans cet atlas.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'En 2025, la maison a roulé un Black Swan. Le nom n''est pas le sien : Black Swan appartient à CigarPage, un détaillant américain, qui en a fait une série dont chaque édition est confiée à une manufacture différente et bâtie sur un lot de tabac particulier trouvé chez elle. Quatre éditions, quatre maisons, trois pays — Oliva au Nicaragua en 2023, Rocky Patel au Honduras en janvier 2024, E.P. Carrillo en République dominicaine, et celle-ci. Les quatre ont leur fiche dans cet atlas.', 'Aux États-Unis, Drew Estate a distribué Joya de 2008 à fin 2025 ; depuis le 1er janvier 2026, Joya assure elle-même sa distribution, et un partenariat avec Quesada Cigars, annoncé en décembre 2025, doit réunir les deux familles dans une structure commune.'), `history`),
  `history_en` = IF(LOCATE(CAST('In 2025 the house rolled a Black Swan. The name is not its own: Black Swan belongs to CigarPage, an American retailer, which made of it a series whose every edition is entrusted to a different factory and built on a particular lot of tobacco found there. Four editions, four houses, three countries — Oliva in Nicaragua in 2023, Rocky Patel in Honduras in January 2024, E.P. Carrillo in the Dominican Republic, and this one. All four have their entry in this atlas.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'In 2025 the house rolled a Black Swan. The name is not its own: Black Swan belongs to CigarPage, an American retailer, which made of it a series whose every edition is entrusted to a different factory and built on a particular lot of tobacco found there. Four editions, four houses, three countries — Oliva in Nicaragua in 2023, Rocky Patel in Honduras in January 2024, E.P. Carrillo in the Dominican Republic, and this one. All four have their entry in this atlas.', 'In the United States, Drew Estate distributed Joya from 2008 to the end of 2025; since 1 January 2026, Joya handles its own distribution, and a partnership with Quesada Cigars, announced in December 2025, is due to bring the two families together in a joint structure.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('En 2025 la casa lió un Black Swan. El nombre no es suyo: Black Swan pertenece a CigarPage, un minorista estadounidense, que hizo de él una serie cuya cada edición se confía a una manufactura distinta y se construye sobre un lote de tabaco particular hallado en ella. Cuatro ediciones, cuatro casas, tres países: Oliva en Nicaragua en 2023, Rocky Patel en Honduras en enero de 2024, E.P. Carrillo en la República Dominicana, y esta. Las cuatro tienen su ficha en este atlas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'En 2025 la casa lió un Black Swan. El nombre no es suyo: Black Swan pertenece a CigarPage, un minorista estadounidense, que hizo de él una serie cuya cada edición se confía a una manufactura distinta y se construye sobre un lote de tabaco particular hallado en ella. Cuatro ediciones, cuatro casas, tres países: Oliva en Nicaragua en 2023, Rocky Patel en Honduras en enero de 2024, E.P. Carrillo en la República Dominicana, y esta. Las cuatro tienen su ficha en este atlas.', 'En Estados Unidos, Drew Estate distribuyó Joya de 2008 a finales de 2025; desde el 1 de enero de 2026, Joya se encarga ella misma de su distribución, y una asociación con Quesada Cigars, anunciada en diciembre de 2025, debe reunir a las dos familias en una estructura común.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('2025 rollte das Haus eine Black Swan. Der Name gehört ihm nicht: Black Swan gehört CigarPage, einem amerikanischen Händler, der daraus eine Serie machte, deren jede Ausgabe einer anderen Fabrik anvertraut und auf eine dort gefundene besondere Tabakpartie gebaut wird. Vier Ausgaben, vier Häuser, drei Länder — Oliva in Nicaragua 2023, Rocky Patel in Honduras im Januar 2024, E.P. Carrillo in der Dominikanischen Republik, und diese. Alle vier haben in diesem Atlas ihren Eintrag.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, '2025 rollte das Haus eine Black Swan. Der Name gehört ihm nicht: Black Swan gehört CigarPage, einem amerikanischen Händler, der daraus eine Serie machte, deren jede Ausgabe einer anderen Fabrik anvertraut und auf eine dort gefundene besondere Tabakpartie gebaut wird. Vier Ausgaben, vier Häuser, drei Länder — Oliva in Nicaragua 2023, Rocky Patel in Honduras im Januar 2024, E.P. Carrillo in der Dominikanischen Republik, und diese. Alle vier haben in diesem Atlas ihren Eintrag.', 'In den USA vertrieb Drew Estate Joya von 2008 bis Ende 2025; seit dem 1. Januar 2026 übernimmt Joya den Vertrieb selbst, und eine im Dezember 2025 angekündigte Partnerschaft mit Quesada Cigars soll die beiden Familien in einer gemeinsamen Struktur zusammenführen.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('2025 年，这家卷制了一支 Black Swan。这个名字不属于它：Black Swan 归美国零售商 CigarPage 所有，后者把它做成一个系列，每一版都交给不同的工厂，并建立在该厂找到的某一批特定烟叶之上。四版、四家公司、三个国家——2023 年 Oliva 在尼加拉瓜，2024 年 1 月 Rocky Patel 在洪都拉斯，E.P. Carrillo 在多米尼加共和国，以及这一版。四家在本图集中都有条目。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '2025 年，这家卷制了一支 Black Swan。这个名字不属于它：Black Swan 归美国零售商 CigarPage 所有，后者把它做成一个系列，每一版都交给不同的工厂，并建立在该厂找到的某一批特定烟叶之上。四版、四家公司、三个国家——2023 年 Oliva 在尼加拉瓜，2024 年 1 月 Rocky Patel 在洪都拉斯，E.P. Carrillo 在多米尼加共和国，以及这一版。四家在本图集中都有条目。', '在美国，Drew Estate 从2008年到2025年底负责分销 Joya；自2026年1月1日起，Joya 自行负责分销，而2025年12月宣布的与 Quesada Cigars 的合作，将把两个家族并入一个共同的架构。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('في عام 2025 لفّت الدار سيجار «بلاك سوان». والاسم ليس اسمها: فـ«بلاك سوان» ملك لـ«سيغار بيدج»، وهو بائع تجزئة أمريكيّ، جعل منه سلسلة تُسنَد كلّ طبعة فيها إلى مصنع مختلف، وتُبنى على دفعة تبغ خاصّة وُجدت عنده. أربع طبعات، وأربع دور، وثلاثة بلدان — «أوليفا» في نيكاراغوا عام 2023، و«روكي باتيل» في هندوراس في يناير 2024، و«إي. بي. كاريّو» في الجمهورية الدومينيكية، وهذه. وللأربع بطاقاتها في هذا الأطلس.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'في عام 2025 لفّت الدار سيجار «بلاك سوان». والاسم ليس اسمها: فـ«بلاك سوان» ملك لـ«سيغار بيدج»، وهو بائع تجزئة أمريكيّ، جعل منه سلسلة تُسنَد كلّ طبعة فيها إلى مصنع مختلف، وتُبنى على دفعة تبغ خاصّة وُجدت عنده. أربع طبعات، وأربع دور، وثلاثة بلدان — «أوليفا» في نيكاراغوا عام 2023، و«روكي باتيل» في هندوراس في يناير 2024، و«إي. بي. كاريّو» في الجمهورية الدومينيكية، وهذه. وللأربع بطاقاتها في هذا الأطلس.', 'في الولايات المتحدة وزّعت Drew Estate سيجار Joya من 2008 حتى نهاية 2025؛ ومنذ 1 يناير 2026 تتولى Joya توزيعه بنفسها، ومن المقرر أن تجمع شراكة مع Quesada Cigars أُعلن عنها في ديسمبر 2025 العائلتين في هيكل مشترك.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Joya de Nicaragua';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Celle de Joya de Nicaragua porte une cape criollo d''Équateur de semence cubaine sur une sous-cape habano nicaraguayenne et une tripe longue de Jalapa et d''Estelí. Elle n''entre pas dans la gamme de la maison : c''est une commande, en quantité limitée, vendue par un seul détaillant. L''atlas l''écrit ici parce que la main qui roule compte autant que le nom sur la bague, et qu''ici les deux ne sont pas de la même maison.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Celle de Joya de Nicaragua porte une cape criollo d''Équateur de semence cubaine sur une sous-cape habano nicaraguayenne et une tripe longue de Jalapa et d''Estelí. Elle n''entre pas dans la gamme de la maison : c''est une commande, en quantité limitée, vendue par un seul détaillant. L''atlas l''écrit ici parce que la main qui roule compte autant que le nom sur la bague, et qu''ici les deux ne sont pas de la même maison.', 'Joya roule aussi, sans la posséder, la marque Bentley, celle de Bentley Tobacco, entreprise de la famille Schuster que Cigar Coop fait remonter à 1878, comme fabricant de pipes. Le White a une cape Connecticut Shade, le Green une cape rosado d''Équateur, tous deux sur sous-cape et tripe nicaraguayennes. Bentley Tobacco a fait son premier PCA en 2025, avec une division américaine lancée fin 2024.'), `history`),
  `history_en` = IF(LOCATE(CAST('Joya de Nicaragua''s carries an Ecuadorian Criollo wrapper of Cuban seed over a Nicaraguan Habano binder and long filler from Jalapa and Estelí. It does not belong to the house''s range: it is a commission, in limited quantity, sold by a single retailer. The atlas writes it here because the hand that rolls counts as much as the name on the band, and here the two are not the same house.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Joya de Nicaragua''s carries an Ecuadorian Criollo wrapper of Cuban seed over a Nicaraguan Habano binder and long filler from Jalapa and Estelí. It does not belong to the house''s range: it is a commission, in limited quantity, sold by a single retailer. The atlas writes it here because the hand that rolls counts as much as the name on the band, and here the two are not the same house.', 'Joya also rolls, without owning it, the Bentley brand, that of Bentley Tobacco, a company of the Schuster family which Cigar Coop traces back to 1878, as a pipe maker. The White has a Connecticut Shade wrapper, the Green an Ecuadorian rosado wrapper, both over a Nicaraguan binder and filler. Bentley Tobacco made its first PCA in 2025, with an American division launched at the end of 2024.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La de Joya de Nicaragua lleva una capa criollo de Ecuador de semilla cubana sobre un capote habano nicaragüense y tripa larga de Jalapa y Estelí. No entra en la gama de la casa: es un encargo, en cantidad limitada, vendido por un solo minorista. El atlas lo escribe aquí porque la mano que lía cuenta tanto como el nombre de la vitola, y aquí ambos no son de la misma casa.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La de Joya de Nicaragua lleva una capa criollo de Ecuador de semilla cubana sobre un capote habano nicaragüense y tripa larga de Jalapa y Estelí. No entra en la gama de la casa: es un encargo, en cantidad limitada, vendido por un solo minorista. El atlas lo escribe aquí porque la mano que lía cuenta tanto como el nombre de la vitola, y aquí ambos no son de la misma casa.', 'Joya también lía, sin poseerla, la marca Bentley, la de Bentley Tobacco, empresa de la familia Schuster que Cigar Coop hace remontar a 1878, como fabricante de pipas. El White lleva capa Connecticut Shade, el Green capa rosado de Ecuador, ambos sobre capote y tripa nicaragüenses. Bentley Tobacco hizo su primer PCA en 2025, con una división estadounidense lanzada a finales de 2024.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die von Joya de Nicaragua trägt ein ecuadorianisches Criollo-Deckblatt kubanischer Saat über einem nicaraguanischen Habano-Umblatt und Langeinlage aus Jalapa und Estelí. Sie gehört nicht zur Linie des Hauses: Sie ist ein Auftrag, in begrenzter Menge, von einem einzigen Händler verkauft. Der Atlas schreibt es hier, weil die rollende Hand ebenso zählt wie der Name auf dem Ring — und hier sind beide nicht dasselbe Haus.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die von Joya de Nicaragua trägt ein ecuadorianisches Criollo-Deckblatt kubanischer Saat über einem nicaraguanischen Habano-Umblatt und Langeinlage aus Jalapa und Estelí. Sie gehört nicht zur Linie des Hauses: Sie ist ein Auftrag, in begrenzter Menge, von einem einzigen Händler verkauft. Der Atlas schreibt es hier, weil die rollende Hand ebenso zählt wie der Name auf dem Ring — und hier sind beide nicht dasselbe Haus.', 'Joya rollt auch die Marke Bentley, ohne sie zu besitzen, die von Bentley Tobacco, einem Unternehmen der Familie Schuster, das Cigar Coop auf 1878 zurückführt, als Pfeifenhersteller. Der White hat ein Deckblatt Connecticut Shade, der Green ein Deckblatt rosado aus Ecuador, beide über nicaraguanischem Umblatt und nicaraguanischer Einlage. Bentley Tobacco nahm 2025 zum ersten Mal an der PCA teil, mit einer Ende 2024 gestarteten amerikanischen Division.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Joya de Nicaragua 这一版用古巴种的厄瓜多尔 Criollo 茄衣，配尼加拉瓜 Habano 茄套，芯叶为来自 Jalapa 与埃斯特利的长芯。它不属于这家的常规产品线：这是一份订制，数量有限，只由一家零售商销售。本图集把它写在这里，是因为卷制的手与茄标上的名字同样重要——而在这里，两者并非同一家。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Joya de Nicaragua 这一版用古巴种的厄瓜多尔 Criollo 茄衣，配尼加拉瓜 Habano 茄套，芯叶为来自 Jalapa 与埃斯特利的长芯。它不属于这家的常规产品线：这是一份订制，数量有限，只由一家零售商销售。本图集把它写在这里，是因为卷制的手与茄标上的名字同样重要——而在这里，两者并非同一家。', 'Joya 还代为卷制 Bentley 品牌的雪茄，但并不拥有该品牌；它属于 Bentley Tobacco，这是 Schuster 家族的企业，据 Cigar Coop，其渊源可追溯至1878年，当时是烟斗制造商。White 采用 Connecticut Shade 茄衣，Green 采用厄瓜多尔 rosado 茄衣，两者的茄套与茄芯均为尼加拉瓜所产。Bentley Tobacco 于2025年首次参加 PCA，其美国分部于2024年底推出。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أمّا طبعة «خويا دي نيكاراغوا» فتحمل غلاف كريّو إكوادوريًّا من بذرة كوبية، فوق رابط هابانو نيكاراغويّ وحشوة طويلة من خالابا وإستيلي. وهي لا تدخل في سلسلة الدار: إنّها طلبيّة، بكمّية محدودة، يبيعها بائع واحد. ويكتبها الأطلس هنا لأنّ اليد التي تلفّ تزن ما يزنه الاسم على الحلقة، والاثنان هنا ليسا من دارٍ واحدة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أمّا طبعة «خويا دي نيكاراغوا» فتحمل غلاف كريّو إكوادوريًّا من بذرة كوبية، فوق رابط هابانو نيكاراغويّ وحشوة طويلة من خالابا وإستيلي. وهي لا تدخل في سلسلة الدار: إنّها طلبيّة، بكمّية محدودة، يبيعها بائع واحد. ويكتبها الأطلس هنا لأنّ اليد التي تلفّ تزن ما يزنه الاسم على الحلقة، والاثنان هنا ليسا من دارٍ واحدة.', 'وتلفّ Joya أيضًا، دون أن تملكها، علامة Bentley، وهي علامة Bentley Tobacco، شركة تعود إلى عائلة Schuster تُرجِع Cigar Coop أصولها إلى 1878، بوصفها صانعة غلايين. يحمل White غلافًا خارجيًّا Connecticut Shade، ويحمل Green غلافًا خارجيًّا rosado من الإكوادور، وكلاهما فوق رابط وحشوة نيكاراغويين. وقد شاركت Bentley Tobacco في PCA لأول مرة عام 2025، مع قسم أمريكي أُطلق في نهاية 2024.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Joya de Nicaragua';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('

Bentley est un autre nom que la maison roule sans le posséder. C''est la marque de Bentley Tobacco, entreprise de la famille Schuster dont Cigar Coop fait remonter les origines à 1878, comme fabricant de pipes. Joya de Nicaragua en roule les cigares : le White, à cape Connecticut Shade, et le Green, à cape rosado d''Équateur, tous deux sur sous-cape et tripe nicaraguayennes. Bentley Tobacco a fait en 2025 son premier PCA, avec une division américaine nouvellement lancée ; en octobre 2026, un détaillant liste encore les deux éditions.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, '

Bentley est un autre nom que la maison roule sans le posséder. C''est la marque de Bentley Tobacco, entreprise de la famille Schuster dont Cigar Coop fait remonter les origines à 1878, comme fabricant de pipes. Joya de Nicaragua en roule les cigares : le White, à cape Connecticut Shade, et le Green, à cape rosado d''Équateur, tous deux sur sous-cape et tripe nicaraguayennes. Bentley Tobacco a fait en 2025 son premier PCA, avec une division américaine nouvellement lancée ; en octobre 2026, un détaillant liste encore les deux éditions.', ''), `history`),
  `history_en` = IF(LOCATE(CAST('

Bentley is another name that the company rolls without owning it. It is the brand of Bentley Tobacco, a company of the Schuster family whose origins Cigar Coop traces back to 1878, as a pipe maker. Joya de Nicaragua rolls the brand''s cigars: the White, with a Connecticut Shade wrapper, and the Green, with an Ecuadorian rosado wrapper, both over a Nicaraguan binder and filler. Bentley Tobacco made its first PCA in 2025, with a newly launched American division; in October 2026, a retailer still lists both editions.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, '

Bentley is another name that the company rolls without owning it. It is the brand of Bentley Tobacco, a company of the Schuster family whose origins Cigar Coop traces back to 1878, as a pipe maker. Joya de Nicaragua rolls the brand''s cigars: the White, with a Connecticut Shade wrapper, and the Green, with an Ecuadorian rosado wrapper, both over a Nicaraguan binder and filler. Bentley Tobacco made its first PCA in 2025, with a newly launched American division; in October 2026, a retailer still lists both editions.', ''), `history_en`),
  `history_es` = IF(LOCATE(CAST('

Bentley es otro nombre que la casa enrolla sin poseerlo. Es la marca de Bentley Tobacco, empresa de la familia Schuster cuyos orígenes Cigar Coop hace remontar a 1878, como fabricante de pipas. Joya de Nicaragua enrolla los puros de la marca: el White, con capa Connecticut Shade, y el Green, con capa rosado de Ecuador, ambos sobre capote y tripa nicaragüenses. Bentley Tobacco hizo en 2025 su primer PCA, con una división estadounidense recién lanzada; en octubre de 2026, un minorista todavía lista las dos ediciones.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '

Bentley es otro nombre que la casa enrolla sin poseerlo. Es la marca de Bentley Tobacco, empresa de la familia Schuster cuyos orígenes Cigar Coop hace remontar a 1878, como fabricante de pipas. Joya de Nicaragua enrolla los puros de la marca: el White, con capa Connecticut Shade, y el Green, con capa rosado de Ecuador, ambos sobre capote y tripa nicaragüenses. Bentley Tobacco hizo en 2025 su primer PCA, con una división estadounidense recién lanzada; en octubre de 2026, un minorista todavía lista las dos ediciones.', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST('

Bentley ist ein weiterer Name, den das Haus rollt, ohne ihn zu besitzen. Es ist die Marke von Bentley Tobacco, einem Unternehmen der Familie Schuster, dessen Ursprünge Cigar Coop auf 1878 zurückführt, als Pfeifenhersteller. Joya de Nicaragua rollt die Zigarren der Marke: den White mit Deckblatt Connecticut Shade und den Green mit Deckblatt rosado aus Ecuador, beide über einem nicaraguanischen Umblatt und einer nicaraguanischen Einlage. Bentley Tobacco nahm 2025 zum ersten Mal an der PCA teil, mit einer neu gestarteten amerikanischen Division; im Oktober 2026 führt ein Einzelhändler weiterhin beide Editionen auf.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, '

Bentley ist ein weiterer Name, den das Haus rollt, ohne ihn zu besitzen. Es ist die Marke von Bentley Tobacco, einem Unternehmen der Familie Schuster, dessen Ursprünge Cigar Coop auf 1878 zurückführt, als Pfeifenhersteller. Joya de Nicaragua rollt die Zigarren der Marke: den White mit Deckblatt Connecticut Shade und den Green mit Deckblatt rosado aus Ecuador, beide über einem nicaraguanischen Umblatt und einer nicaraguanischen Einlage. Bentley Tobacco nahm 2025 zum ersten Mal an der PCA teil, mit einer neu gestarteten amerikanischen Division; im Oktober 2026 führt ein Einzelhändler weiterhin beide Editionen auf.', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('

Bentley是该公司代为卷制而并不拥有的另一个名称。它是Bentley Tobacco的品牌，这是一家Schuster家族的企业，据Cigar Coop，其渊源可追溯至1878年，当时是一家烟斗制造商。Joya de Nicaragua为该品牌卷制雪茄：White采用Connecticut Shade茄衣，Green采用厄瓜多尔rosado茄衣，两者的茄套与茄芯均为尼加拉瓜所产。Bentley Tobacco于2025年首次参加PCA，并有一个新近推出的美国分部；2026年十月，仍有一家零售商列出这两个版本。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '

Bentley是该公司代为卷制而并不拥有的另一个名称。它是Bentley Tobacco的品牌，这是一家Schuster家族的企业，据Cigar Coop，其渊源可追溯至1878年，当时是一家烟斗制造商。Joya de Nicaragua为该品牌卷制雪茄：White采用Connecticut Shade茄衣，Green采用厄瓜多尔rosado茄衣，两者的茄套与茄芯均为尼加拉瓜所产。Bentley Tobacco于2025年首次参加PCA，并有一个新近推出的美国分部；2026年十月，仍有一家零售商列出这两个版本。', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('

Bentley اسم آخر تلفّ الشركة سيجاره دون أن تملكه. وهو علامة Bentley Tobacco، شركة تعود إلى عائلة Schuster تُرجِع Cigar Coop أصولها إلى 1878، بوصفها صانعة غلايين. وتلفّ Joya de Nicaragua سيجارات العلامة: White بغلاف خارجي Connecticut Shade، وGreen بغلاف خارجي rosado من الإكوادور، وكلاهما فوق رابط وحشوة نيكاراغويين. وقد شاركت Bentley Tobacco في 2025 في PCA لأول مرة، مع قسم أمريكي أُطلق حديثًا؛ وفي أكتوبر 2026 ما زال تاجر تجزئة يدرج الإصدارين.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '

Bentley اسم آخر تلفّ الشركة سيجاره دون أن تملكه. وهو علامة Bentley Tobacco، شركة تعود إلى عائلة Schuster تُرجِع Cigar Coop أصولها إلى 1878، بوصفها صانعة غلايين. وتلفّ Joya de Nicaragua سيجارات العلامة: White بغلاف خارجي Connecticut Shade، وGreen بغلاف خارجي rosado من الإكوادور، وكلاهما فوق رابط وحشوة نيكاراغويين. وقد شاركت Bentley Tobacco في 2025 في PCA لأول مرة، مع قسم أمريكي أُطلق حديثًا؛ وفي أكتوبر 2026 ما زال تاجر تجزئة يدرج الإصدارين.', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Joya de Nicaragua';

UPDATE `brands` SET
  `limited_eds` = '["Joya de Nicaragua Cuatro Cinco (45 ans, 2013)","Joya de Nicaragua Cinco Décadas (50 ans, 2018)","Joya de Nicaragua Antaño CT Gran Cónsul (2025)"]',
  `factory` = 'Joya de Nicaragua S.A., Estelí, Nicaragua — fabrique ouverte en 1968',
  `gamme` = '[{"name":"Antaño 1970","color":"#1C0A00","force":"Full","story":"Assemblage nostalgique mis au point par Alejandro Martínez Cuenca et lancé en 2001, que la maison range parmi les cigares corsés. C''est la ligne qui a relancé la marque.","vitolas":["Gran Consul","Churchill","Robusto","Torpedo","Corona Gorda"],"wrapper":"Nicaragua"},{"name":"Cabinetta","color":"#A0522D","force":"Mild","story":"Lancée sous le nom de Cabinetta Serie entre 2009 et 2011, rebaptisée Joya Cabinetta en 2016. Cape bicolore : Connecticut Shade d''Équateur et criollo nicaraguayen vers la tête, sur sous-cape et tripe du Nicaragua. Cigar Coop la décrit comme légère, sans force agressive.","vitolas":["Robusto","Toro","Torpedo"],"wrapper":"Équateur + criollo Nicaragua"}]',
  `gamme_en` = '[{"name":"Antaño 1970","color":"#1C0A00","force":"Full","story":"A nostalgic blend devised by Alejandro Martínez Cuenca and launched in 2001, which the house classes among full-bodied cigars. It is the line that relaunched the brand.","vitolas":["Gran Consul","Churchill","Robusto","Torpedo","Corona Gorda"],"wrapper":"Nicaragua"},{"name":"Cabinetta","color":"#A0522D","force":"Mild","story":"Launched as Cabinetta Serie between 2009 and 2011, renamed Joya Cabinetta in 2016. Two-tone wrapper: Ecuadorian Connecticut Shade and Nicaraguan criollo towards the head, over a Nicaraguan binder and filler. Cigar Coop describes it as light, with no aggressive strength.","vitolas":["Robusto","Toro","Torpedo"],"wrapper":"Ecuador + Nicaraguan criollo"}]',
  `gamme_es` = '[{"name":"Antaño 1970","color":"#1C0A00","force":"Full","story":"Liga nostálgica ideada por Alejandro Martínez Cuenca y lanzada en 2001, que la casa clasifica entre los puros fuertes. Es la línea que relanzó la marca.","vitolas":["Gran Consul","Churchill","Robusto","Torpedo","Corona Gorda"],"wrapper":"Nicaragua"},{"name":"Cabinetta","color":"#A0522D","force":"Mild","story":"Lanzada con el nombre de Cabinetta Serie entre 2009 y 2011, rebautizada Joya Cabinetta en 2016. Capa bicolor: Connecticut Shade de Ecuador y criollo nicaragüense hacia la cabeza, sobre capote y tripa de Nicaragua. Cigar Coop la describe como ligera, sin fuerza agresiva.","vitolas":["Robusto","Toro","Torpedo"],"wrapper":"Ecuador + criollo de Nicaragua"}]',
  `gamme_de` = '[{"name":"Antaño 1970","color":"#1C0A00","force":"Full","story":"Nostalgische Mischung, von Alejandro Martínez Cuenca entwickelt und 2001 eingeführt, die das Haus zu den kräftigen Zigarren zählt. Es ist die Linie, die die Marke neu belebt hat.","vitolas":["Gran Consul","Churchill","Robusto","Torpedo","Corona Gorda"],"wrapper":"Nicaragua"},{"name":"Cabinetta","color":"#A0522D","force":"Mild","story":"Unter dem Namen Cabinetta Serie zwischen 2009 und 2011 eingeführt, 2016 in Joya Cabinetta umbenannt. Zweifarbiges Deckblatt: Connecticut Shade aus Ecuador und nicaraguanischer Criollo zum Kopf hin, über Umblatt und Einlage aus Nicaragua. Cigar Coop beschreibt sie als leicht, ohne aggressive Kraft.","vitolas":["Robusto","Toro","Torpedo"],"wrapper":"Ecuador + Criollo Nicaragua"}]',
  `gamme_zh` = '[{"name":"Antaño 1970","color":"#1C0A00","force":"Full","story":"由 Alejandro Martínez Cuenca 调配、2001年推出的怀旧配方，这家公司将其归入浓郁雪茄之列。正是这个系列让品牌重新振兴。","vitolas":["Gran Consul","Churchill","Robusto","Torpedo","Corona Gorda"],"wrapper":"尼加拉瓜"},{"name":"Cabinetta","color":"#A0522D","force":"Mild","story":"于2009年至2011年间以 Cabinetta Serie 之名推出，2016年更名为 Joya Cabinetta。双色茄衣：厄瓜多尔 Connecticut Shade 与尼加拉瓜 criollo 靠近头部，包在尼加拉瓜的茄套与茄芯之上。据 Cigar Coop 的描述，它偏淡，并无咄咄逼人的劲道。","vitolas":["Robusto","Toro","Torpedo"],"wrapper":"厄瓜多尔 + 尼加拉瓜 criollo"}]',
  `gamme_ar` = '[{"name":"Antaño 1970","color":"#1C0A00","force":"Full","story":"خلطة حنينية ابتكرها Alejandro Martínez Cuenca وأُطلقت عام 2001، وتصنّفها الدار ضمن السيجار القويّ الجسم. وهي السلسلة التي أعادت إطلاق العلامة.","vitolas":["Gran Consul","Churchill","Robusto","Torpedo","Corona Gorda"],"wrapper":"نيكاراغوا"},{"name":"Cabinetta","color":"#A0522D","force":"Mild","story":"أُطلقت باسم Cabinetta Serie بين 2009 و2011، وأُعيدت تسميتها Joya Cabinetta عام 2016. غلاف ثنائي اللون: Connecticut Shade من الإكوادور وcriollo نيكاراغوي قرب الرأس، فوق رابط وحشوة من نيكاراغوا. وتصفها Cigar Coop بأنها خفيفة، بلا قوة عدوانية.","vitolas":["Robusto","Toro","Torpedo"],"wrapper":"إكوادور + criollo نيكاراغوا"}]',
  `celebrities` = '[{"name":"La Maison-Blanche","anecdote":"Selon la maison, Joya de Nicaragua fut le cigare officiel de la Maison-Blanche : Somoza l''aurait appris de Nixon, entre 1971 et 1974. La presse du métier date cette désignation de 1971. Aucune préférence personnelle d''un président n''est attestée."}]',
  `celebrities_en` = '[{"name":"The White House","anecdote":"According to the house, Joya de Nicaragua was the official cigar of the White House: Somoza is said to have learned this from Nixon, between 1971 and 1974. The trade press dates this designation to 1971. No personal preference of any president is attested."}]',
  `celebrities_es` = '[{"name":"La Casa Blanca","anecdote":"Según la casa, Joya de Nicaragua fue el puro oficial de la Casa Blanca: Somoza lo habría sabido por Nixon, entre 1971 y 1974. La prensa del sector sitúa esta designación en 1971. No se acredita ninguna preferencia personal de un presidente."}]',
  `celebrities_de` = '[{"name":"Das Weiße Haus","anecdote":"Laut dem Haus war Joya de Nicaragua die offizielle Zigarre des Weißen Hauses: Somoza habe es von Nixon erfahren, zwischen 1971 und 1974. Die Fachpresse datiert diese Bezeichnung auf 1971. Eine persönliche Vorliebe eines Präsidenten ist nicht belegt."}]',
  `celebrities_zh` = '[{"name":"白宫","anecdote":"据公司所述，Joya de Nicaragua 曾是白宫的官方雪茄：Somoza 据说是从 Nixon 那里得知的，时间在1971年至1974年间。行业媒体将这一指定的时间定在1971年。没有任何一位总统的个人偏好有据可查。"}]',
  `celebrities_ar` = '[{"name":"البيت الأبيض","anecdote":"بحسب الدار، كانت Joya de Nicaragua السيجار الرسمي للبيت الأبيض: ويقال إن Somoza علم بذلك من Nixon، بين 1971 و1974. وتؤرّخ صحافة المهنة هذه التسمية بعام 1971. ولا يثبت أي تفضيل شخصي لأي رئيس."}]',
  `pairings` = '[{"type":"Rhum","name":"Flor de Caña 12 ans","notes":"Un rhum nicaraguayen pour un cigare nicaraguayen : l''accord de pays."},{"type":"Café","name":"Café du Nicaragua (Matagalpa)","notes":"Un café de montagne nicaraguayen, à la rondeur fruitée, qui se prête à un cigare corsé."}]',
  `pairings_en` = '[{"type":"Rum","name":"Flor de Caña 12 years","notes":"A Nicaraguan rum for a Nicaraguan cigar: a pairing from the same country."},{"type":"Coffee","name":"Nicaraguan coffee (Matagalpa)","notes":"A Nicaraguan mountain coffee with a fruity roundness, well suited to a full-bodied cigar."}]',
  `pairings_es` = '[{"type":"Ron","name":"Flor de Caña 12 años","notes":"Un ron nicaragüense para un puro nicaragüense: el maridaje de país."},{"type":"Café","name":"Café de Nicaragua (Matagalpa)","notes":"Un café de montaña nicaragüense, de redondez afrutada, que va bien con un puro fuerte."}]',
  `pairings_de` = '[{"type":"Rum","name":"Flor de Caña 12 Jahre","notes":"Ein nicaraguanischer Rum zu einer nicaraguanischen Zigarre: die Verbindung aus demselben Land."},{"type":"Kaffee","name":"Kaffee aus Nicaragua (Matagalpa)","notes":"Ein nicaraguanischer Bergkaffee von fruchtiger Rundheit, der zu einer kräftigen Zigarre passt."}]',
  `pairings_zh` = '[{"type":"朗姆酒","name":"Flor de Caña 12年","notes":"尼加拉瓜朗姆酒配尼加拉瓜雪茄：同一国度的搭配。"},{"type":"咖啡","name":"尼加拉瓜咖啡（Matagalpa）","notes":"尼加拉瓜的高山咖啡，圆润带果味，适合搭配浓郁的雪茄。"}]',
  `pairings_ar` = '[{"type":"الروم","name":"Flor de Caña 12 سنة","notes":"روم نيكاراغوي لسيجار نيكاراغوي: توافق من البلد نفسه."},{"type":"القهوة","name":"قهوة من نيكاراغوا (Matagalpa)","notes":"قهوة جبلية نيكاراغوية ذات استدارة فاكهية، تناسب سيجارًا قويّ الجسم."}]',
  `mentions` = '["Bentley"]',
  `source` = IF(LOCATE(CAST('stogiephile.blog et cigarpage.com (édition Black Swan de 2025 UNIQUEMENT) — le reste de la fiche est antérieur et n''a pas de source enregistrée ; ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'stogiephile.blog et cigarpage.com (édition Black Swan de 2025 UNIQUEMENT) — le reste de la fiche est antérieur et n''a pas de source enregistrée ; ', ''), `source`),
  `source` = IF(LOCATE(CAST('; cigarsdirect.com « Bentley Green Edition Churchill » (octobre 2026 : cape rosado d''Équateur, sous-cape et tripe de la vallée de Jalapa, en stock)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, '; cigarsdirect.com « Bentley Green Edition Churchill » (octobre 2026 : cape rosado d''Équateur, sous-cape et tripe de la vallée de Jalapa, en stock)', ''), `source`),
  `source` = IF(LOCATE(CAST('joyacigars.com « The Original Nicaraguan Cigar » (chronologi' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'joyacigars.com « The Original Nicaraguan Cigar » (chronologie : Nicaragua Cigar Co. fondée le 29 février 1968 à Estelí par Bermejo et Camacho ; Somoza et la Maison-Blanche 1971-1974 ; usine détruite en 1978 ; 1994 Tabacos Puros de Nicaragua / Martínez Cuenca ; Antaño 1970 en 2001 ; Cabinetta et Dark Corojo 2009-2011) ; cigaraficionado.com « A Half Century of Joya » (2018 : Somoza prend le contrôle, vente de la marque à Oppenheimer, nationalisation, Antaño 2001) ; drewestate.prezly.com « Joya de Nicaragua Celebrates its 50th Anniversary » (28 février 2018 : première fabrique de cigares premium roulés à la main du pays, 1968, Estelí) ; cigar-coop.com « Joya de Nicaragua Cuatro Cinco » (15 octobre 2013 : 45 ans, 4 500 cigares) ; blindmanspuff.com « Joya de Nicaragua Introduces Cinco Décadas » (2018) ; cigar-coop.com « Joya de Nicaragua Cabinetta Serie rebranded as Joya Cabinetta » (24 juillet 2016 : cape, force Mild) ; cigardojo.com « Joya de Nicaragua to end U.S. distribution partnership with Drew Estate » (septembre 2025 : fin au 1er janvier 2026) ; cigarinspector.com (13 décembre 2025, titre vu : partenariat Quesada, SAG)')),
  `updated_at` = NOW()
 WHERE `name` = 'Joya de Nicaragua';

-- ── La Flor Dominicana ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('José « Jochy » Blanco a fondé La Flor Dominicana à Santiago, en République dominicaine, en 1996, avec une ligne dont il n''a pas dévié : faire ce que les autres ne font pas. Dans un métier qui privilégie souvent l''incrément — le léger ajustement d''un assemblage établi, le format familier sous une nouvelle cape —, Blanco a bâti sa réputation sur l''expérimentation véritable et sur des décisions de production que la plupart des fabricants refuseraient pour des raisons pratiques.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'José « Jochy » Blanco a fondé La Flor Dominicana à Santiago, en République dominicaine, en 1996, avec une ligne dont il n''a pas dévié : faire ce que les autres ne font pas. Dans un métier qui privilégie souvent l''incrément — le léger ajustement d''un assemblage établi, le format familier sous une nouvelle cape —, Blanco a bâti sa réputation sur l''expérimentation véritable et sur des décisions de production que la plupart des fabricants refuseraient pour des raisons pratiques.', 'La Flor Dominicana est l''œuvre de Litto Gómez, ancien bijoutier de Miami, et de sa femme Ines Lorenzo. D''après la presse du métier, le couple entre dans le cigare en 1994 avec la marque Los Libertadores, dans un petit atelier de Villa González à quatre postes de roulage. En 1996, à la suite d''un différend, Litto Gómez et Ines Lorenzo reprennent l''entreprise, sans la marque Los Libertadores, et les cigares sont rebaptisés La Flor Dominicana. Selon Wikipédia, les premiers cigares sont produits à Santiago en 1996 ; la fabrique est aujourd''hui à Tamboril (état d''octobre 2026, cette seule source).'), `history`),
  `history_en` = IF(LOCATE(CAST('José ''Jochy'' Blanco established La Flor Dominicana in Santiago, Dominican Republic in 1996 with a remit he has maintained consistently since: do what others won''t. In an industry that often rewards the incremental — the slight adjustment to an established blend, the familiar format in a new wrapper — Blanco built his reputation on genuine experimentation and the willingness to make production decisions that most manufacturers would reject on practical grounds.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'José ''Jochy'' Blanco established La Flor Dominicana in Santiago, Dominican Republic in 1996 with a remit he has maintained consistently since: do what others won''t. In an industry that often rewards the incremental — the slight adjustment to an established blend, the familiar format in a new wrapper — Blanco built his reputation on genuine experimentation and the willingness to make production decisions that most manufacturers would reject on practical grounds.', 'La Flor Dominicana is the work of Litto Gómez, a former Miami jeweller, and his wife Ines Lorenzo. According to the trade press, the couple entered the cigar business in 1994 with the Los Libertadores brand, in a small workshop in Villa González with four rolling stations. In 1996, following a dispute, Litto Gómez and Ines Lorenzo took over the business, without the Los Libertadores brand, and the cigars were renamed La Flor Dominicana. According to Wikipedia, the first cigars were produced in Santiago in 1996; the factory is now in Tamboril (as of October 2026, this source alone).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('José «Jochy» Blanco fundó La Flor Dominicana en Santiago, en República Dominicana, en 1996, con una línea de la que no se ha apartado: hacer lo que los demás no hacen. En un oficio que suele preferir el incremento —el leve ajuste de una ligada establecida, el formato familiar bajo una capa nueva—, Blanco levantó su reputación sobre la experimentación verdadera y sobre decisiones de producción que la mayoría de los fabricantes rechazarían por razones prácticas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'José «Jochy» Blanco fundó La Flor Dominicana en Santiago, en República Dominicana, en 1996, con una línea de la que no se ha apartado: hacer lo que los demás no hacen. En un oficio que suele preferir el incremento —el leve ajuste de una ligada establecida, el formato familiar bajo una capa nueva—, Blanco levantó su reputación sobre la experimentación verdadera y sobre decisiones de producción que la mayoría de los fabricantes rechazarían por razones prácticas.', 'La Flor Dominicana es obra de Litto Gómez, antiguo joyero de Miami, y de su esposa Ines Lorenzo. Según la prensa del sector, la pareja entra en el mundo del puro en 1994 con la marca Los Libertadores, en un pequeño taller de Villa González con cuatro puestos de torcido. En 1996, a raíz de una disputa, Litto Gómez e Ines Lorenzo se hacen cargo de la empresa, sin la marca Los Libertadores, y los puros pasan a llamarse La Flor Dominicana. Según Wikipedia, los primeros puros se producen en Santiago en 1996; la fábrica está hoy en Tamboril (estado de octubre de 2026, solo esta fuente).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('José «Jochy» Blanco gründete La Flor Dominicana 1996 in Santiago in der Dominikanischen Republik, mit einer Linie, von der er nicht abgewichen ist: zu tun, was die anderen nicht tun. In einem Fach, das oft den kleinen Schritt bevorzugt — die leichte Anpassung einer eingeführten Mischung, das vertraute Format unter einem neuen Deckblatt —, hat Blanco seinen Ruf auf echtem Versuch aufgebaut und auf Produktionsentscheidungen, die die meisten Hersteller aus praktischen Gründen ablehnen würden.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'José «Jochy» Blanco gründete La Flor Dominicana 1996 in Santiago in der Dominikanischen Republik, mit einer Linie, von der er nicht abgewichen ist: zu tun, was die anderen nicht tun. In einem Fach, das oft den kleinen Schritt bevorzugt — die leichte Anpassung einer eingeführten Mischung, das vertraute Format unter einem neuen Deckblatt —, hat Blanco seinen Ruf auf echtem Versuch aufgebaut und auf Produktionsentscheidungen, die die meisten Hersteller aus praktischen Gründen ablehnen würden.', 'La Flor Dominicana ist das Werk von Litto Gómez, einem früheren Juwelier aus Miami, und seiner Frau Ines Lorenzo. Laut der Fachpresse steigt das Paar 1994 mit der Marke Los Libertadores ins Zigarrengeschäft ein, in einer kleinen Werkstatt in Villa González mit vier Rollplätzen. 1996 übernehmen Litto Gómez und Ines Lorenzo nach einem Streit den Betrieb, ohne die Marke Los Libertadores, und die Zigarren werden in La Flor Dominicana umbenannt. Laut Wikipedia werden die ersten Zigarren 1996 in Santiago hergestellt; die Fabrik steht heute in Tamboril (Stand Oktober 2026, nur diese eine Quelle).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('1996年，何塞·「霍奇」·布兰科在多米尼加共和国的圣地亚哥创办了拉弗洛尔·多米尼加纳，秉持的路线始终没变：做别人不做的事。在一个往往偏爱小步推进的行当里——把成熟配方稍作调整，把熟悉的规格换一张茄衣——布兰科靠真正的试验，以及多数厂商出于现实考虑会拒绝的生产决定，立起了自己的名声。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '1996年，何塞·「霍奇」·布兰科在多米尼加共和国的圣地亚哥创办了拉弗洛尔·多米尼加纳，秉持的路线始终没变：做别人不做的事。在一个往往偏爱小步推进的行当里——把成熟配方稍作调整，把熟悉的规格换一张茄衣——布兰科靠真正的试验，以及多数厂商出于现实考虑会拒绝的生产决定，立起了自己的名声。', 'La Flor Dominicana 出自 Litto Gómez 与其妻子 Ines Lorenzo 之手，前者曾是 Miami 的珠宝商。据行业媒体报道，这对夫妇于1994年带着 Los Libertadores 品牌踏入雪茄行业，在 Villa González 的一间小作坊里，只有四个卷制工位。1996年，因一场纠纷，Litto Gómez 与 Ines Lorenzo 接手了这家企业，但不带 Los Libertadores 品牌，雪茄随之改名为 La Flor Dominicana。据维基百科，首批雪茄于1996年在 Santiago 生产；工厂如今设在 Tamboril（截至2026年10月的情况，仅此一个来源）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أسّس خوسيه «خوتشي» بلانكو دار «لا فلور دومينيكانا» في سانتياغو بالجمهورية الدومينيكية عام 1996، على خطّ لم يحد عنه: أن يفعل ما لا يفعله الآخرون. ففي مهنة تفضّل غالبًا الخطوة الصغيرة — تعديل طفيف على خلطة راسخة، أو قياس مألوف تحت غلاف جديد — بنى بلانكو سمعته على التجريب الحقيقي وعلى قرارات إنتاج يرفضها معظم الصنّاع لأسباب عملية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أسّس خوسيه «خوتشي» بلانكو دار «لا فلور دومينيكانا» في سانتياغو بالجمهورية الدومينيكية عام 1996، على خطّ لم يحد عنه: أن يفعل ما لا يفعله الآخرون. ففي مهنة تفضّل غالبًا الخطوة الصغيرة — تعديل طفيف على خلطة راسخة، أو قياس مألوف تحت غلاف جديد — بنى بلانكو سمعته على التجريب الحقيقي وعلى قرارات إنتاج يرفضها معظم الصنّاع لأسباب عملية.', 'La Flor Dominicana من صنع Litto Gómez، وهو صائغ سابق في Miami، وزوجته Ines Lorenzo. وبحسب صحافة المهنة، دخل الزوجان عالم السيجار عام 1994 بعلامة Los Libertadores، في ورشة صغيرة في Villa González فيها أربعة مواقع للّف. وفي عام 1996، إثر خلاف، تولّى Litto Gómez وInes Lorenzo الشركة دون علامة Los Libertadores، وأُعيدت تسمية السيجار إلى La Flor Dominicana. وبحسب ويكيبيديا، أُنتجت أولى السيجارات في Santiago عام 1996؛ والمصنع اليوم في Tamboril (الوضع في أكتوبر 2026، وهذا المصدر وحده).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'La Flor Dominicana';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le Double Ligero — un double torpedo de 75 × 184 mm — en est l''expression la plus nette. Le seul défi technique est considérable : le format exige un moule de dimensions si particulières que La Flor Dominicana l''a fait fabriquer pour elle seule. L''expérience qu''il produit — trois heures au minimum, cinq phases aromatiques distinctes, du cèdre léger au premier tiers jusqu''à la terre profonde et au chocolat noir dans la dernière demi-heure — tient autant de l''épreuve d''endurance que du plaisir.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le Double Ligero — un double torpedo de 75 × 184 mm — en est l''expression la plus nette. Le seul défi technique est considérable : le format exige un moule de dimensions si particulières que La Flor Dominicana l''a fait fabriquer pour elle seule. L''expérience qu''il produit — trois heures au minimum, cinq phases aromatiques distinctes, du cèdre léger au premier tiers jusqu''à la terre profonde et au chocolat noir dans la dernière demi-heure — tient autant de l''épreuve d''endurance que du plaisir.', 'Le Chisel, figurado à tête en coin, sort en 2003 selon la presse du métier : l''idée serait venue à Litto Gómez en route vers la fabrique, la forme a demandé dix mois de mise au point et il a demandé à ses rouleurs de la reproduire. Il se décline dans la ligne Double Ligero, que la maison décrit comme enveloppée de feuilles sombres Sumatra d''Équateur cultivées au soleil, sur une tripe et une sous-cape dominicaines issues de la propriété.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Double Ligero format — a Double Torpedo measuring 75 x 184mm — is the clearest expression of this philosophy. The engineering challenge alone is formidable: the format requires a mold of such specific dimensions that La Flor Dominicana commissioned it exclusively. No other factory possesses the equipment to produce it at scale. The smoking experience it creates — three hours minimum, five distinct aromatic phases that range from light cedar in the first third to deep earth and dark chocolate in the final half-hour — is as much an endurance test as a pleasure.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Double Ligero format — a Double Torpedo measuring 75 x 184mm — is the clearest expression of this philosophy. The engineering challenge alone is formidable: the format requires a mold of such specific dimensions that La Flor Dominicana commissioned it exclusively. No other factory possesses the equipment to produce it at scale. The smoking experience it creates — three hours minimum, five distinct aromatic phases that range from light cedar in the first third to deep earth and dark chocolate in the final half-hour — is as much an endurance test as a pleasure.', 'The Chisel, a figurado with a wedge-shaped head, came out in 2003 according to the trade press: the idea is said to have come to Litto Gómez on his way to the factory, the shape took ten months to perfect, and he asked his rollers to reproduce it. It comes in the Double Ligero line, which the house describes as wrapped in dark, sun-grown Ecuadorian Sumatra leaves over a Dominican filler and binder from the estate.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El Double Ligero —un doble torpedo de 75 × 184 mm— es su expresión más nítida. El solo desafío técnico es considerable: el formato exige un molde de dimensiones tan particulares que La Flor Dominicana lo mandó fabricar para ella sola. La experiencia que produce —tres horas como mínimo, cinco fases aromáticas distintas, del cedro ligero en el primer tercio hasta la tierra profunda y el chocolate negro en la última media hora— tiene tanto de prueba de resistencia como de placer.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El Double Ligero —un doble torpedo de 75 × 184 mm— es su expresión más nítida. El solo desafío técnico es considerable: el formato exige un molde de dimensiones tan particulares que La Flor Dominicana lo mandó fabricar para ella sola. La experiencia que produce —tres horas como mínimo, cinco fases aromáticas distintas, del cedro ligero en el primer tercio hasta la tierra profunda y el chocolate negro en la última media hora— tiene tanto de prueba de resistencia como de placer.', 'El Chisel, figurado de cabeza en cuña, sale en 2003 según la prensa del sector: la idea le habría surgido a Litto Gómez de camino a la fábrica, la forma exigió diez meses de puesta a punto y él pidió a sus torcedores que la reprodujeran. Se declina en la línea Double Ligero, que la casa describe como envuelta en hojas oscuras de Sumatra de Ecuador cultivadas al sol, sobre una tripa y una capote dominicanas procedentes de la propiedad.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der Double Ligero — ein Doppel-Torpedo von 75 × 184 mm — ist dafür der klarste Ausdruck. Schon die technische Aufgabe ist beträchtlich: Das Format verlangt eine Form von so eigenen Maßen, dass La Flor Dominicana sie für sich allein anfertigen ließ. Das Erlebnis, das daraus folgt — mindestens drei Stunden, fünf deutlich getrennte aromatische Phasen, von leichter Zeder im ersten Drittel bis zu tiefer Erde und Zartbitterschokolade in der letzten halben Stunde —, hat ebenso viel von einer Ausdauerprüfung wie vom Genuss.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der Double Ligero — ein Doppel-Torpedo von 75 × 184 mm — ist dafür der klarste Ausdruck. Schon die technische Aufgabe ist beträchtlich: Das Format verlangt eine Form von so eigenen Maßen, dass La Flor Dominicana sie für sich allein anfertigen ließ. Das Erlebnis, das daraus folgt — mindestens drei Stunden, fünf deutlich getrennte aromatische Phasen, von leichter Zeder im ersten Drittel bis zu tiefer Erde und Zartbitterschokolade in der letzten halben Stunde —, hat ebenso viel von einer Ausdauerprüfung wie vom Genuss.', 'Der Chisel, ein Figurado mit keilförmigem Kopf, kommt laut Fachpresse 2003 heraus: Die Idee soll Litto Gómez auf dem Weg zur Fabrik gekommen sein, die Form brauchte zehn Monate Entwicklung, und er bat seine Zigarrenroller, sie nachzubauen. Er wird in der Linie Double Ligero angeboten, die das Haus als umhüllt von dunklen, in der Sonne gezogenen Sumatra-Blättern aus Ecuador beschreibt, über Einlage und Umblatt aus dominikanischem Tabak vom Anwesen des Hauses.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('双利加罗——一支 75 × 184 毫米的双鱼雷——是这条路线最清晰的表达。单是技术上的难处就已可观：这个规格所需的模具尺寸如此特别，以致拉弗洛尔·多米尼加纳专门为自己订制了一副。它带来的体验——至少三小时，五个分明的香气阶段，从第一段的淡雪松到最后半小时的深沉泥土与黑巧克力——既是享受，也是耐力的考验。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '双利加罗——一支 75 × 184 毫米的双鱼雷——是这条路线最清晰的表达。单是技术上的难处就已可观：这个规格所需的模具尺寸如此特别，以致拉弗洛尔·多米尼加纳专门为自己订制了一副。它带来的体验——至少三小时，五个分明的香气阶段，从第一段的淡雪松到最后半小时的深沉泥土与黑巧克力——既是享受，也是耐力的考验。', 'Chisel 是一种楔形头的异形雪茄，据行业媒体报道于2003年推出：Litto Gómez 据说是在前往工厂的路上想到了这个主意，这个形状花了十个月调试，他让自己的卷烟工把它复制出来。它收在 Double Ligero 系列之中，厂家将该系列描述为以厄瓜多尔产的深色 Sumatra 烟叶作茄衣，阳光下种植，内里的芯叶与束叶为多米尼加烟叶，来自庄园自家种植。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('«دبل ليغيرو» — تُربيدو مزدوج بقياس 75 × 184 مم — هو أوضح تعبير عن ذلك. فالتحدّي التقني وحده كبير: يتطلّب هذا القياس قالبًا بأبعاد خاصة إلى حدّ دفع الدار إلى صنعه لنفسها وحدها. أما التجربة التي ينتجها — ثلاث ساعات على الأقل، وخمس مراحل عطرية متمايزة، من خشب الأرز الخفيف في الثلث الأول إلى التراب العميق والشوكولاتة الداكنة في نصف الساعة الأخير — ففيها من امتحان القدرة بقدر ما فيها من المتعة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '«دبل ليغيرو» — تُربيدو مزدوج بقياس 75 × 184 مم — هو أوضح تعبير عن ذلك. فالتحدّي التقني وحده كبير: يتطلّب هذا القياس قالبًا بأبعاد خاصة إلى حدّ دفع الدار إلى صنعه لنفسها وحدها. أما التجربة التي ينتجها — ثلاث ساعات على الأقل، وخمس مراحل عطرية متمايزة، من خشب الأرز الخفيف في الثلث الأول إلى التراب العميق والشوكولاتة الداكنة في نصف الساعة الأخير — ففيها من امتحان القدرة بقدر ما فيها من المتعة.', 'يصدر «Chisel»، وهو فيغورادو برأس مائل كالإسفين، عام 2003 بحسب صحافة المهنة: يُقال إن الفكرة خطرت لـ Litto Gómez وهو في طريقه إلى المصنع، وإن الشكل احتاج عشرة شهور من الضبط، وإنه طلب من لافّي السيجار لديه أن يعيدوا صنعه. ويأتي ضمن خط Double Ligero، الذي تصفه الدار بأنه ملفوف بأوراق Sumatra الداكنة من الإكوادور المزروعة تحت الشمس، فوق حشوة وغلاف داخلي دومينيكيين من أرض الدار.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'La Flor Dominicana';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Au-delà de ce format vitrine, les apports techniques de Blanco à la production dominicaine sont substantiels. Il a introduit pour les ligeros dominicains des protocoles de fermentation prolongée que d''autres manufactures de l''île ont adoptés ensuite. Son emploi de tabacs dits « Mystery Ligero » — des feuilles d''origine volontairement non divulguée, ajoutées à plusieurs assemblages pour créer un caractère que l''analyse ne peut pas rattacher à une région connue — relève du génie commercial ou de la philosophie du terroir, selon le point de vue.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Au-delà de ce format vitrine, les apports techniques de Blanco à la production dominicaine sont substantiels. Il a introduit pour les ligeros dominicains des protocoles de fermentation prolongée que d''autres manufactures de l''île ont adoptés ensuite. Son emploi de tabacs dits « Mystery Ligero » — des feuilles d''origine volontairement non divulguée, ajoutées à plusieurs assemblages pour créer un caractère que l''analyse ne peut pas rattacher à une région connue — relève du génie commercial ou de la philosophie du terroir, selon le point de vue.', 'José « Jochi » Blanco, fabricant de cigares, est cité en 2007 par la presse du métier comme partageant avec La Flor Dominicana une ferme de 120 acres ; il n''est pas le fondateur de la maison.'), `history`),
  `history_en` = IF(LOCATE(CAST('Beyond the headline format, Blanco''s technical contributions to Dominican cigar production are substantial. He introduced extended fermentation protocols for Dominican ligero leaves that the island''s other manufacturers later adopted. His sourcing of ''Mystery Ligero'' tobaccos — leaves from undisclosed origins, deliberately unnamed, added to several blends to create a specific character that analytical reviewers cannot fully attribute to known growing regions — is either marketing genius or genuine terroir philosophy depending on your perspective.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Beyond the headline format, Blanco''s technical contributions to Dominican cigar production are substantial. He introduced extended fermentation protocols for Dominican ligero leaves that the island''s other manufacturers later adopted. His sourcing of ''Mystery Ligero'' tobaccos — leaves from undisclosed origins, deliberately unnamed, added to several blends to create a specific character that analytical reviewers cannot fully attribute to known growing regions — is either marketing genius or genuine terroir philosophy depending on your perspective.', 'José ''Jochi'' Blanco, a cigar maker, was cited by the trade press in 2007 as sharing a 120-acre farm with La Flor Dominicana; he is not the founder of the house.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Más allá de ese formato escaparate, las aportaciones técnicas de Blanco a la producción dominicana son sustanciales. Introdujo para los ligeros dominicanos protocolos de fermentación prolongada que otras manufacturas de la isla adoptaron después. Su empleo de tabacos llamados «Mystery Ligero» —hojas de origen deliberadamente no divulgado, añadidas a varias ligadas para crear un carácter que el análisis no puede vincular a ninguna región conocida— es genio comercial o filosofía del terruño, según se mire.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Más allá de ese formato escaparate, las aportaciones técnicas de Blanco a la producción dominicana son sustanciales. Introdujo para los ligeros dominicanos protocolos de fermentación prolongada que otras manufacturas de la isla adoptaron después. Su empleo de tabacos llamados «Mystery Ligero» —hojas de origen deliberadamente no divulgado, añadidas a varias ligadas para crear un carácter que el análisis no puede vincular a ninguna región conocida— es genio comercial o filosofía del terruño, según se mire.', 'José «Jochi» Blanco, fabricante de puros, es citado en 2007 por la prensa del sector como alguien que comparte con La Flor Dominicana una finca de 120 acres; no es el fundador de la casa.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Über dieses Schaufensterformat hinaus sind Blancos technische Beiträge zur dominikanischen Produktion beträchtlich. Er führte für dominikanische Ligeros verlängerte Fermentationsverfahren ein, die andere Manufakturen der Insel später übernahmen. Sein Einsatz von Tabaken, die «Mystery Ligero» heißen — Blätter absichtlich nicht offengelegter Herkunft, mehreren Mischungen beigegeben, um einen Charakter zu schaffen, den die Analyse keiner bekannten Region zuordnen kann —, ist kaufmännischer Einfall oder Terroir-Philosophie, je nach Blickwinkel.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Über dieses Schaufensterformat hinaus sind Blancos technische Beiträge zur dominikanischen Produktion beträchtlich. Er führte für dominikanische Ligeros verlängerte Fermentationsverfahren ein, die andere Manufakturen der Insel später übernahmen. Sein Einsatz von Tabaken, die «Mystery Ligero» heißen — Blätter absichtlich nicht offengelegter Herkunft, mehreren Mischungen beigegeben, um einen Charakter zu schaffen, den die Analyse keiner bekannten Region zuordnen kann —, ist kaufmännischer Einfall oder Terroir-Philosophie, je nach Blickwinkel.', 'José «Jochi» Blanco, Zigarrenhersteller, wird 2007 von der Fachpresse als jemand genannt, der mit La Flor Dominicana eine Farm von 120 Acres teilt; er ist nicht der Gründer des Hauses.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('除了这支橱窗之作，布兰科在技术上对多米尼加生产的贡献同样扎实。他为多米尼加利加罗引入了延长发酵的工序，岛上其他工厂后来纷纷采用。他使用所谓「Mystery Ligero」的烟叶——刻意不公开产地，掺入多副配方，造出一种分析无法归入任何已知产区的性格——究竟是商业上的巧思还是风土的哲学，取决于你站在哪一边。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '除了这支橱窗之作，布兰科在技术上对多米尼加生产的贡献同样扎实。他为多米尼加利加罗引入了延长发酵的工序，岛上其他工厂后来纷纷采用。他使用所谓「Mystery Ligero」的烟叶——刻意不公开产地，掺入多副配方，造出一种分析无法归入任何已知产区的性格——究竟是商业上的巧思还是风土的哲学，取决于你站在哪一边。', 'José「Jochi」Blanco 是一名雪茄制造者，2007年行业媒体称他与 La Flor Dominicana 共用一座120英亩的农场；他并非该品牌的创办人。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وخارج هذا القياس الاستعراضي، إسهامات بلانكو التقنية في الإنتاج الدومينيكي جوهرية. فقد أدخل على الليغيرو الدومينيكي بروتوكولات تخمير مطوَّلة تبنّتها لاحقًا مصانع أخرى في الجزيرة. أما استعماله تبغًا يسمّيه «Mystery Ligero» — أوراق لا يُفصح عن أصلها عمدًا، تُضاف إلى عدة خلطات لتخلق طابعًا لا يستطيع التحليل ردّه إلى منطقة معروفة — فهو نبوغ تجاري أو فلسفة أرض، بحسب زاوية النظر.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وخارج هذا القياس الاستعراضي، إسهامات بلانكو التقنية في الإنتاج الدومينيكي جوهرية. فقد أدخل على الليغيرو الدومينيكي بروتوكولات تخمير مطوَّلة تبنّتها لاحقًا مصانع أخرى في الجزيرة. أما استعماله تبغًا يسمّيه «Mystery Ligero» — أوراق لا يُفصح عن أصلها عمدًا، تُضاف إلى عدة خلطات لتخلق طابعًا لا يستطيع التحليل ردّه إلى منطقة معروفة — فهو نبوغ تجاري أو فلسفة أرض، بحسب زاوية النظر.', 'ذُكر في صحافة المهنة عام 2007 أن José «Jochi» Blanco، صانع السيجار، يتقاسم مع La Flor Dominicana مزرعة مساحتها 120 أكرًا؛ وهو ليس مؤسس الدار.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'La Flor Dominicana';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('

La manufacture de Santiago produit un catalogue qui va du cigare dominicain doux de tous les jours aux expressions extrêmes du Double Ligero. Cette amplitude est inhabituelle pour une maison de cette taille : la plupart des fabricants de niche trouvent leur registre et s''y tiennent. La Flor Dominicana parcourt tout le spectre, et montre que la République dominicaine, poussée comme il faut, produit des tabacs aussi exigeants que ceux du Nicaragua ou du Honduras.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, '

La manufacture de Santiago produit un catalogue qui va du cigare dominicain doux de tous les jours aux expressions extrêmes du Double Ligero. Cette amplitude est inhabituelle pour une maison de cette taille : la plupart des fabricants de niche trouvent leur registre et s''y tiennent. La Flor Dominicana parcourt tout le spectre, et montre que la République dominicaine, poussée comme il faut, produit des tabacs aussi exigeants que ceux du Nicaragua ou du Honduras.', ''), `history`),
  `history_en` = IF(LOCATE(CAST(CONCAT('', CHAR(13), '
', CHAR(13), '
The Santiago factory produces a catalog that ranges from everyday Dominican mild cigars to the extreme expressions of the Double Ligero. Blanco''s range of production is unusual for a house of his size — most boutique manufacturers find their register and stay in it. La Flor Dominicana moves across the entire aromatic spectrum, demonstrating that the Dominican Republic, properly pushed, can produce tobacco experiences as demanding as anything Nicaragua or Honduras offers.') AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, CONCAT('', CHAR(13), '
', CHAR(13), '
The Santiago factory produces a catalog that ranges from everyday Dominican mild cigars to the extreme expressions of the Double Ligero. Blanco''s range of production is unusual for a house of his size — most boutique manufacturers find their register and stay in it. La Flor Dominicana moves across the entire aromatic spectrum, demonstrating that the Dominican Republic, properly pushed, can produce tobacco experiences as demanding as anything Nicaragua or Honduras offers.'), ''), `history_en`),
  `history_es` = IF(LOCATE(CAST('

La manufactura de Santiago produce un catálogo que va del puro dominicano suave de todos los días a las expresiones extremas del Double Ligero. Esa amplitud es inhabitual en una casa de este tamaño: la mayoría de los fabricantes de nicho encuentran su registro y se quedan en él. La Flor Dominicana recorre todo el espectro, y muestra que República Dominicana, empujada como es debido, produce tabacos tan exigentes como los de Nicaragua o de Honduras.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '

La manufactura de Santiago produce un catálogo que va del puro dominicano suave de todos los días a las expresiones extremas del Double Ligero. Esa amplitud es inhabitual en una casa de este tamaño: la mayoría de los fabricantes de nicho encuentran su registro y se quedan en él. La Flor Dominicana recorre todo el espectro, y muestra que República Dominicana, empujada como es debido, produce tabacos tan exigentes como los de Nicaragua o de Honduras.', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST('

Die Manufaktur in Santiago erzeugt einen Katalog, der von der milden dominikanischen Alltagszigarre bis zu den äußersten Ausdrucksformen des Double Ligero reicht. Diese Spannweite ist für ein Haus dieser Größe ungewöhnlich: Die meisten Nischenhersteller finden ihr Register und bleiben darin. La Flor Dominicana durchmisst das ganze Feld und zeigt, dass die Dominikanische Republik, richtig gefordert, Tabake hervorbringt, die ebenso anspruchsvoll sind wie die aus Nicaragua oder Honduras.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, '

Die Manufaktur in Santiago erzeugt einen Katalog, der von der milden dominikanischen Alltagszigarre bis zu den äußersten Ausdrucksformen des Double Ligero reicht. Diese Spannweite ist für ein Haus dieser Größe ungewöhnlich: Die meisten Nischenhersteller finden ihr Register und bleiben darin. La Flor Dominicana durchmisst das ganze Feld und zeigt, dass die Dominikanische Republik, richtig gefordert, Tabake hervorbringt, die ebenso anspruchsvoll sind wie die aus Nicaragua oder Honduras.', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('

圣地亚哥的工厂做出的目录，从日常的柔和多米尼加雪茄一直延伸到双利加罗那样的极端表达。对这个体量的字号来说，这样的幅度并不常见：多数小众厂商找到自己的调性便守在那里。拉弗洛尔·多米尼加纳走遍了整个光谱，并且证明：只要推得够狠，多米尼加共和国也能长出与尼加拉瓜或洪都拉斯同样考验人的烟草。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '

圣地亚哥的工厂做出的目录，从日常的柔和多米尼加雪茄一直延伸到双利加罗那样的极端表达。对这个体量的字号来说，这样的幅度并不常见：多数小众厂商找到自己的调性便守在那里。拉弗洛尔·多米尼加纳走遍了整个光谱，并且证明：只要推得够狠，多米尼加共和国也能长出与尼加拉瓜或洪都拉斯同样考验人的烟草。', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('

ينتج مصنع سانتياغو كتالوغًا يمتدّ من السيجار الدومينيكي اللطيف لكل يوم إلى أقصى تعبيرات «دبل ليغيرو». وهذا المدى غير معتاد لدار بهذا الحجم: فأكثر صنّاع النخبة الصغار يجدون طابعهم ويلزمونه. أما «لا فلور دومينيكانا» فتقطع الطيف كلّه، وتُظهر أن الجمهورية الدومينيكية، إذا دُفعت كما ينبغي، تنتج تبغًا لا يقلّ تطلّبًا عن تبغ نيكاراغوا أو هندوراس.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '

ينتج مصنع سانتياغو كتالوغًا يمتدّ من السيجار الدومينيكي اللطيف لكل يوم إلى أقصى تعبيرات «دبل ليغيرو». وهذا المدى غير معتاد لدار بهذا الحجم: فأكثر صنّاع النخبة الصغار يجدون طابعهم ويلزمونه. أما «لا فلور دومينيكانا» فتقطع الطيف كلّه، وتُظهر أن الجمهورية الدومينيكية، إذا دُفعت كما ينبغي، تنتج تبغًا لا يقلّ تطلّبًا عن تبغ نيكاراغوا أو هندوراس.', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'La Flor Dominicana';

UPDATE `brands` SET
  `limited_eds` = '[]',
  `founded` = '1996 (issue de Los Libertadores, 1994)',
  `factory` = 'Tamboril, République dominicaine (selon Wikipédia, octobre 2026) ; premiers cigares produits à Santiago en 1996',
  `gamme` = '[{"name":"Double Ligero","color":"#8B0000","force":"Full","story":"Ligne emblématique de la maison. Cape Sumatra d''Équateur sombre, cultivée au soleil, sur tripe et sous-cape dominicaines issues de la propriété, en natural et en maduro (dit la maison, laflordominicana.com/double-ligero). Le Chisel, figurado à tête en coin sorti en 2003, en est le format le plus connu.","vitolas":["Chisel","Missile","Torpedo"],"wrapper":"Sumatra d''Équateur"},{"name":"Air Bender","color":"#722F37","force":"Full","story":"Mélange plein corps, dit la maison, de tripe et sous-cape dominicaines issues de la propriété sous une cape Habano, proposé en natural ou en maduro (laflordominicana.com/air-bender).","vitolas":["Robusto","Toro","Chisel","Lancero"],"wrapper":"Habano"},{"name":"Litto Gómez","color":"#8B4513","force":null,"wrapper":"100 % dominicain","vitolas":[],"story":"Ligne éponyme du fondateur, présentée par la maison comme entièrement dominicaine (laflordominicana.com/our-cigars)."}]',
  `gamme_en` = '[{"name":"Double Ligero","color":"#8B0000","force":"Full","story":"The house''s emblematic line. Dark, sun-grown Ecuadorian Sumatra wrapper over Dominican filler and binder from the estate, in natural and in maduro (says the house, laflordominicana.com/double-ligero). The Chisel, a wedge-headed figurado released in 2003, is its best-known format.","vitolas":["Chisel","Missile","Torpedo"],"wrapper":"Ecuadorian Sumatra"},{"name":"Air Bender","color":"#722F37","force":"Full","story":"A full-bodied blend, says the house, of Dominican filler and binder from the estate under a Habano wrapper, offered in natural or maduro (laflordominicana.com/air-bender).","vitolas":["Robusto","Toro","Chisel","Lancero"],"wrapper":"Habano"},{"name":"Litto Gómez","color":"#8B4513","force":null,"wrapper":"100% Dominican","vitolas":[],"story":"The founder''s namesake line, presented by the house as entirely Dominican (laflordominicana.com/our-cigars)."}]',
  `gamme_es` = '[{"name":"Double Ligero","color":"#8B0000","force":"Full","story":"Línea emblemática de la casa. Capa Sumatra de Ecuador oscura, cultivada al sol, sobre tripa y capote dominicanos procedentes de la propiedad, en natural y en maduro (dice la casa, laflordominicana.com/double-ligero). El Chisel, figurado de cabeza en cuña aparecido en 2003, es su formato más conocido.","vitolas":["Chisel","Missile","Torpedo"],"wrapper":"Sumatra de Ecuador"},{"name":"Air Bender","color":"#722F37","force":"Full","story":"Mezcla de cuerpo pleno, dice la casa, de tripa y capote dominicanos procedentes de la propiedad bajo una capa Habano, ofrecida en natural o en maduro (laflordominicana.com/air-bender).","vitolas":["Robusto","Toro","Chisel","Lancero"],"wrapper":"Habano"},{"name":"Litto Gómez","color":"#8B4513","force":null,"wrapper":"100 % dominicano","vitolas":[],"story":"Línea homónima del fundador, presentada por la casa como enteramente dominicana (laflordominicana.com/our-cigars)."}]',
  `gamme_de` = '[{"name":"Double Ligero","color":"#8B0000","force":"Full","story":"Die Vorzeigelinie des Hauses. Dunkles, in der Sonne gezogenes Sumatra-Deckblatt aus Ecuador über Einlage und Umblatt aus dominikanischem Tabak vom Anwesen, als Natural und als Maduro (sagt das Haus, laflordominicana.com/double-ligero). Der Chisel, ein 2003 erschienenes Figurado mit keilförmigem Kopf, ist ihr bekanntestes Format.","vitolas":["Chisel","Missile","Torpedo"],"wrapper":"Sumatra aus Ecuador"},{"name":"Air Bender","color":"#722F37","force":"Full","story":"Eine vollmundige Mischung, sagt das Haus, aus Einlage und Umblatt aus dominikanischem Tabak vom Anwesen unter einem Habano-Deckblatt, erhältlich als Natural oder Maduro (laflordominicana.com/air-bender).","vitolas":["Robusto","Toro","Chisel","Lancero"],"wrapper":"Habano"},{"name":"Litto Gómez","color":"#8B4513","force":null,"wrapper":"100 % dominikanisch","vitolas":[],"story":"Die nach dem Gründer benannte Linie, vom Haus als vollständig dominikanisch dargestellt (laflordominicana.com/our-cigars)."}]',
  `gamme_zh` = '[{"name":"Double Ligero","color":"#8B0000","force":"Full","story":"品牌的标志性系列。深色厄瓜多尔 Sumatra 茄衣，阳光下种植，内裹来自庄园的多米尼加芯叶与束叶，有 natural 与 maduro 两种（厂家自述，laflordominicana.com/double-ligero）。2003年推出的楔形头异形雪茄 Chisel，是该系列广为人知的规格。","vitolas":["Chisel","Missile","Torpedo"],"wrapper":"厄瓜多尔 Sumatra"},{"name":"Air Bender","color":"#722F37","force":"Full","story":"厂家称这是一款浓郁醇厚的混合配方，以来自庄园的多米尼加芯叶与束叶，外覆 Habano 茄衣，有 natural 与 maduro 两种（laflordominicana.com/air-bender）。","vitolas":["Robusto","Toro","Chisel","Lancero"],"wrapper":"Habano"},{"name":"Litto Gómez","color":"#8B4513","force":null,"wrapper":"100% 多米尼加","vitolas":[],"story":"以创办人命名的系列，厂家介绍其完全属于多米尼加（laflordominicana.com/our-cigars）。"}]',
  `gamme_ar` = '[{"name":"Double Ligero","color":"#8B0000","force":"Full","story":"الخط الرمزي للدار. غلاف Sumatra إكوادوري داكن مزروع تحت الشمس، فوق حشوة وغلاف داخلي دومينيكيين من أرض الدار، بدرجتي natural وmaduro (بحسب الدار، laflordominicana.com/double-ligero). و«Chisel»، وهو فيغورادو برأس إسفيني صدر عام 2003، هو القياس المعروف للخط.","vitolas":["Chisel","Missile","Torpedo"],"wrapper":"Sumatra إكوادوري"},{"name":"Air Bender","color":"#722F37","force":"Full","story":"خلطة كاملة الجسم، بحسب الدار، من حشوة وغلاف داخلي دومينيكيين من أرض الدار تحت غلاف Habano، متوافرة بدرجتي natural وmaduro (laflordominicana.com/air-bender).","vitolas":["Robusto","Toro","Chisel","Lancero"],"wrapper":"Habano"},{"name":"Litto Gómez","color":"#8B4513","force":null,"wrapper":"دومينيكي 100 %","vitolas":[],"story":"الخط الذي يحمل اسم المؤسس، وتقدّمه الدار على أنه دومينيكي بالكامل (laflordominicana.com/our-cigars)."}]',
  `celebrities` = '[]',
  `celebrities_en` = '[]',
  `celebrities_es` = '[]',
  `celebrities_de` = '[]',
  `celebrities_zh` = '[]',
  `celebrities_ar` = '[]',
  `pairings` = '[]',
  `pairings_en` = '[]',
  `pairings_es` = '[]',
  `pairings_de` = '[]',
  `pairings_zh` = '[]',
  `pairings_ar` = '[]',
  `source` = IF(LOCATE(CAST('cigaraficionado.com « Litto''s Twist of Fate » et halfwheel.com « Los Libertadores — the original La Flor Dominicana » (Litto Gómez et Ines Lorenzo créent Los Libertadores en 1994 à Villa González, quatre postes de roulage ; reprise et renommage en juin 1996 après un différend avec l''associé) ; en.wikipedia.org' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'cigaraficionado.com « Litto''s Twist of Fate » et halfwheel.com « Los Libertadores — the original La Flor Dominicana » (Litto Gómez et Ines Lorenzo créent Los Libertadores en 1994 à Villa González, quatre postes de roulage ; reprise et renommage en juin 1996 après un différend avec l''associé) ; en.wikipedia.org', 'cigaraficionado.com « Litto''s Twist of Fate » (Los Libertadores 1994, Villa González, quatre postes ; reprise sans la marque en 1996 ; Chisel 2003 ; ferme partagée avec Jochi Blanco) ; halfwheel.com « Los Libertadores — the original La Flor Dominicana » (titre vu en résultat de recherche : reprise et renommage en juin 1996) ; en.wikipedia.org « La Flor Dominicana » (fondateurs Litto Gómez et Ines Lorenzo ; production à Santiago en 1996 ; fabrique à Tamboril) ; laflordominicana.com/double-ligero, /air-bender, /our-cigars (lignes, capes, tripes)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'La Flor Dominicana';

-- ── Avo ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La biographie d''Avo Uvezian échappe aux conventions du genre. Né à Beyrouth en 1926 de parents arméniens rescapés du génocide, il quitta le Liban dans sa vingtaine pour New York, où il devint un pianiste de jazz assez accompli pour rejoindre l''orchestre de tournée de Frank Sinatra. Sa carrière le mena des clubs new-yorkais aux salles de concert européennes, et jusqu''à cette distinction improbable : avoir contribué à « Strangers in the Night », dont la paternité lui est restée disputée toute sa vie.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La biographie d''Avo Uvezian échappe aux conventions du genre. Né à Beyrouth en 1926 de parents arméniens rescapés du génocide, il quitta le Liban dans sa vingtaine pour New York, où il devint un pianiste de jazz assez accompli pour rejoindre l''orchestre de tournée de Frank Sinatra. Sa carrière le mena des clubs new-yorkais aux salles de concert européennes, et jusqu''à cette distinction improbable : avoir contribué à « Strangers in the Night », dont la paternité lui est restée disputée toute sa vie.', 'Avo Uvezian est né à Beyrouth le 22 mars 1926 ; pianiste et compositeur arméno-américain, il est mort à Orlando le 24 mars 2017, à 91 ans (Cigar Dojo, 24 mars 2017). Sa chanson la plus connue reste disputée : Strangers in the Night est créditée à Bert Kaempfert, tandis qu''Uvezian affirmait l''avoir composée et avoir envoyé la mélodie à Kaempfert avant que Sinatra l''enregistre en 1966 (Wikipédia).'), `history`),
  `history_en` = IF(LOCATE(CAST('Avo Uvezian''s biography defies the conventions of the cigar industry''s typical founder narrative. Born in Beirut in 1926 to Armenian parents who had survived the genocide, he left Lebanon in his twenties for New York, where he became a jazz pianist of sufficient accomplishment to join Frank Sinatra''s touring band. His musical career took him through the clubs of New York, the concert halls of Europe, and eventually to the unlikely distinction of having contributed to one of the twentieth century''s most recognizable popular songs — though the credit for ''Strangers in the Night'' remained disputed throughout his life.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Avo Uvezian''s biography defies the conventions of the cigar industry''s typical founder narrative. Born in Beirut in 1926 to Armenian parents who had survived the genocide, he left Lebanon in his twenties for New York, where he became a jazz pianist of sufficient accomplishment to join Frank Sinatra''s touring band. His musical career took him through the clubs of New York, the concert halls of Europe, and eventually to the unlikely distinction of having contributed to one of the twentieth century''s most recognizable popular songs — though the credit for ''Strangers in the Night'' remained disputed throughout his life.', 'Avo Uvezian was born in Beirut on 22 March 1926; an Armenian-American pianist and composer, he died in Orlando on 24 March 2017, aged 91 (Cigar Dojo, 24 March 2017). His best-known song remains disputed: Strangers in the Night is credited to Bert Kaempfert, whereas Uvezian claimed to have composed it and to have sent the melody to Kaempfert before Sinatra recorded it in 1966 (Wikipedia).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La biografía de Avo Uvezian escapa a las convenciones del género. Nacido en Beirut en 1926 de padres armenios supervivientes del genocidio, dejó el Líbano en la veintena rumbo a Nueva York, donde llegó a ser un pianista de jazz lo bastante consumado como para unirse a la orquesta de gira de Frank Sinatra. Su carrera lo llevó de los clubes neoyorquinos a las salas de concierto europeas, y hasta esa distinción improbable: haber contribuido a «Strangers in the Night», cuya paternidad le quedó disputada toda su vida.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La biografía de Avo Uvezian escapa a las convenciones del género. Nacido en Beirut en 1926 de padres armenios supervivientes del genocidio, dejó el Líbano en la veintena rumbo a Nueva York, donde llegó a ser un pianista de jazz lo bastante consumado como para unirse a la orquesta de gira de Frank Sinatra. Su carrera lo llevó de los clubes neoyorquinos a las salas de concierto europeas, y hasta esa distinción improbable: haber contribuido a «Strangers in the Night», cuya paternidad le quedó disputada toda su vida.', 'Avo Uvezian nació en Beirut el 22 de marzo de 1926; pianista y compositor armenio-estadounidense, murió en Orlando el 24 de marzo de 2017, a los 91 años (Cigar Dojo, 24 de marzo de 2017). Su canción más conocida sigue siendo objeto de disputa: Strangers in the Night se atribuye a Bert Kaempfert, mientras que Uvezian afirmaba haberla compuesto y haber enviado la melodía a Kaempfert antes de que Sinatra la grabara en 1966 (Wikipedia).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Lebensgeschichte von Avo Uvezian entzieht sich den Konventionen der Gattung. 1926 in Beirut als Sohn armenischer Eltern geboren, die den Völkermord überlebt hatten, verließ er den Libanon in seinen Zwanzigern Richtung New York, wo er ein Jazzpianist wurde, gut genug, um in Frank Sinatras Tourneeorchester zu spielen. Seine Laufbahn führte ihn von den New Yorker Clubs in europäische Konzertsäle und bis zu jener unwahrscheinlichen Besonderheit: an «Strangers in the Night» mitgewirkt zu haben, dessen Urheberschaft ihm sein Leben lang streitig blieb.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Lebensgeschichte von Avo Uvezian entzieht sich den Konventionen der Gattung. 1926 in Beirut als Sohn armenischer Eltern geboren, die den Völkermord überlebt hatten, verließ er den Libanon in seinen Zwanzigern Richtung New York, wo er ein Jazzpianist wurde, gut genug, um in Frank Sinatras Tourneeorchester zu spielen. Seine Laufbahn führte ihn von den New Yorker Clubs in europäische Konzertsäle und bis zu jener unwahrscheinlichen Besonderheit: an «Strangers in the Night» mitgewirkt zu haben, dessen Urheberschaft ihm sein Leben lang streitig blieb.', 'Avo Uvezian wurde am 22. März 1926 in Beirut geboren; als armenisch-amerikanischer Pianist und Komponist starb er am 24. März 2017 in Orlando im Alter von 91 Jahren (Cigar Dojo, 24. März 2017). Sein bekanntestes Lied bleibt umstritten: Strangers in the Night wird Bert Kaempfert zugeschrieben, während Uvezian behauptete, es komponiert und die Melodie an Kaempfert geschickt zu haben, bevor Sinatra sie 1966 aufnahm (Wikipedia).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('阿沃·乌韦兹扬的生平不合这一体裁的常规。1926年，他生于贝鲁特，父母是从种族灭绝中幸存下来的亚美尼亚人。二十几岁时他离开黎巴嫩去了纽约，成了一名相当出色的爵士钢琴手，出色到能加入弗兰克·辛纳屈的巡演乐队。他的生涯把他从纽约的俱乐部带到欧洲的音乐厅，也带到一项不大可能的名分上：参与了《Strangers in the Night》的创作——而这首曲子的著作权归属，与他争执了一辈子。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '阿沃·乌韦兹扬的生平不合这一体裁的常规。1926年，他生于贝鲁特，父母是从种族灭绝中幸存下来的亚美尼亚人。二十几岁时他离开黎巴嫩去了纽约，成了一名相当出色的爵士钢琴手，出色到能加入弗兰克·辛纳屈的巡演乐队。他的生涯把他从纽约的俱乐部带到欧洲的音乐厅，也带到一项不大可能的名分上：参与了《Strangers in the Night》的创作——而这首曲子的著作权归属，与他争执了一辈子。', 'Avo Uvezian 1926年3月22日生于 Beirut；他是亚美尼亚裔美国钢琴家兼作曲家，2017年3月24日在 Orlando 去世，享年91岁（Cigar Dojo，2017年3月24日）。他广为人知的那首歌至今仍有争议：《Strangers in the Night》署名为 Bert Kaempfert，而 Uvezian 声称自己创作了它，并在 Sinatra 于1966年录制之前把旋律寄给了 Kaempfert（维基百科）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تفلت سيرة آفو أوفيزيان من أعراف هذا النوع من السير. وُلد في بيروت عام 1926 لأبوين أرمنيين نجيا من الإبادة الجماعية، وغادر لبنان في عشرينيّاته إلى نيويورك، حيث صار عازف بيانو جاز بارعًا بما يكفي للانضمام إلى أوركسترا فرانك سيناترا في جولاتها. وقادته مسيرته من نوادي نيويورك إلى قاعات الحفلات الأوروبية، وصولًا إلى ذلك الامتياز غير المتوقَّع: مساهمته في «Strangers in the Night»، التي ظلّت نسبتها إليه موضع نزاع طوال حياته.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تفلت سيرة آفو أوفيزيان من أعراف هذا النوع من السير. وُلد في بيروت عام 1926 لأبوين أرمنيين نجيا من الإبادة الجماعية، وغادر لبنان في عشرينيّاته إلى نيويورك، حيث صار عازف بيانو جاز بارعًا بما يكفي للانضمام إلى أوركسترا فرانك سيناترا في جولاتها. وقادته مسيرته من نوادي نيويورك إلى قاعات الحفلات الأوروبية، وصولًا إلى ذلك الامتياز غير المتوقَّع: مساهمته في «Strangers in the Night»، التي ظلّت نسبتها إليه موضع نزاع طوال حياته.', 'وُلد Avo Uvezian في Beirut يوم 22 مارس 1926؛ عازف بيانو وملحّن أرمني أمريكي، توفي في Orlando يوم 24 مارس 2017 عن 91 عامًا (Cigar Dojo، 24 مارس 2017). وتبقى أغنيته الذائعة موضع خلاف: تُنسب «Strangers in the Night» إلى Bert Kaempfert، بينما كان Uvezian يؤكد أنه ألّفها وأنه أرسل اللحن إلى Kaempfert قبل أن يسجّلها Sinatra عام 1966 (ويكيبيديا).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Avo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Passé la soixantaine, Uvezian menait une vie qui mêlait des concerts épisodiques à un intérêt grandissant pour le cigare. Il fumait à l''ancienne école cubaine, formé par la même culture du tabac havanais que Sinatra et son cercle avaient absorbée dans leurs années new-yorkaises. La République dominicaine, devenue dans les années 1980 l''alternative du cigare premium à Cuba, lui offrait ce qu''il cherchait : une fabrication excellente, et la possibilité de bâtir quelque chose à son nom.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Passé la soixantaine, Uvezian menait une vie qui mêlait des concerts épisodiques à un intérêt grandissant pour le cigare. Il fumait à l''ancienne école cubaine, formé par la même culture du tabac havanais que Sinatra et son cercle avaient absorbée dans leurs années new-yorkaises. La République dominicaine, devenue dans les années 1980 l''alternative du cigare premium à Cuba, lui offrait ce qu''il cherchait : une fabrication excellente, et la possibilité de bâtir quelque chose à son nom.', 'Pour le cigare, il s''est tourné vers Hendrik Kelner, qui avait ouvert Tabacos Dominicanos (Tabadom) en 1984. Selon la presse du métier, la première commande de Kelner pour Avo, 17 000 cigares, date de 1987 et la boutique Davidoff de Madison Avenue vend la marque en 1988 ; la première sortie est datée de 1988. Wikipédia écrit que Davidoff a acquis en 1995 les droits de distribution d''Avo, pour un montant d''environ 10 millions de dollars.'), `history`),
  `history_en` = IF(LOCATE(CAST('By his sixties, Uvezian had settled into a life that combined modest jazz performance with a deepening interest in cigars. He was a smoker of the old Cuban school, educated by the same Havana tobacco culture that Sinatra and his circle had absorbed in their own Manhattan years. The Dominican Republic, which had become the premium cigar world''s alternative to Cuba by the 1980s, offered what Uvezian needed: access to excellent manufacturing and the possibility of building something under his own name.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'By his sixties, Uvezian had settled into a life that combined modest jazz performance with a deepening interest in cigars. He was a smoker of the old Cuban school, educated by the same Havana tobacco culture that Sinatra and his circle had absorbed in their own Manhattan years. The Dominican Republic, which had become the premium cigar world''s alternative to Cuba by the 1980s, offered what Uvezian needed: access to excellent manufacturing and the possibility of building something under his own name.', 'For the cigar, he turned to Hendrik Kelner, who had opened Tabacos Dominicanos (Tabadom) in 1984. According to the trade press, Kelner''s first order for Avo, 17,000 cigars, dates from 1987 and the Davidoff shop on Madison Avenue was selling the brand in 1988; the first release is dated 1988. Wikipedia writes that Davidoff acquired the distribution rights to Avo in 1995, for about 10 million dollars.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Pasados los sesenta, Uvezian llevaba una vida que mezclaba conciertos episódicos con un interés creciente por el puro. Fumaba a la vieja escuela cubana, formado por la misma cultura del tabaco habanero que Sinatra y su círculo habían absorbido en sus años neoyorquinos. La República Dominicana, convertida en los años ochenta en la alternativa del puro premium a Cuba, le ofrecía lo que buscaba: una fabricación excelente y la posibilidad de levantar algo con su nombre.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Pasados los sesenta, Uvezian llevaba una vida que mezclaba conciertos episódicos con un interés creciente por el puro. Fumaba a la vieja escuela cubana, formado por la misma cultura del tabaco habanero que Sinatra y su círculo habían absorbido en sus años neoyorquinos. La República Dominicana, convertida en los años ochenta en la alternativa del puro premium a Cuba, le ofrecía lo que buscaba: una fabricación excelente y la posibilidad de levantar algo con su nombre.', 'Para el puro, se dirigió a Hendrik Kelner, que había abierto Tabacos Dominicanos (Tabadom) en 1984. Según la prensa del sector, el primer pedido de Kelner para Avo, 17 000 puros, data de 1987 y la tienda Davidoff de Madison Avenue vende la marca en 1988; la primera salida se fecha en 1988. Wikipedia escribe que Davidoff adquirió en 1995 los derechos de distribución de Avo, por un importe de unos 10 millones de dólares.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Jenseits der sechzig führte Uvezian ein Leben, das gelegentliche Auftritte mit einem wachsenden Interesse an der Zigarre verband. Er rauchte nach kubanischer alter Schule, geprägt von derselben Havanna-Tabakkultur, die Sinatra und sein Kreis in ihren New Yorker Jahren aufgenommen hatten. Die Dominikanische Republik, in den achtziger Jahren zur Alternative der Premiumzigarre zu Kuba geworden, bot ihm, was er suchte: eine ausgezeichnete Fertigung und die Möglichkeit, etwas unter seinem Namen aufzubauen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Jenseits der sechzig führte Uvezian ein Leben, das gelegentliche Auftritte mit einem wachsenden Interesse an der Zigarre verband. Er rauchte nach kubanischer alter Schule, geprägt von derselben Havanna-Tabakkultur, die Sinatra und sein Kreis in ihren New Yorker Jahren aufgenommen hatten. Die Dominikanische Republik, in den achtziger Jahren zur Alternative der Premiumzigarre zu Kuba geworden, bot ihm, was er suchte: eine ausgezeichnete Fertigung und die Möglichkeit, etwas unter seinem Namen aufzubauen.', 'Für die Zigarre wandte er sich an Hendrik Kelner, der 1984 Tabacos Dominicanos (Tabadom) eröffnet hatte. Laut Fachpresse stammt Kelners erste Bestellung für Avo, 17 000 Zigarren, von 1987, und das Davidoff-Geschäft an der Madison Avenue verkauft die Marke 1988; die erste Veröffentlichung wird auf 1988 datiert. Wikipedia schreibt, Davidoff habe 1995 die Vertriebsrechte an Avo erworben, für einen Betrag von rund 10 Millionen Dollar.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('过了六十岁，乌韦兹扬的日子把零星的演出与日渐加深的雪茄兴趣掺在一起。他抽的是古巴老派的路数，受的是辛纳屈及其圈子在纽约岁月里吸收的那套哈瓦那烟草文化的熏陶。八十年代成为古巴之外高端雪茄替代产地的多米尼加共和国，正好给了他想要的东西：出色的制作，以及用自己的名字建起点什么的可能。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '过了六十岁，乌韦兹扬的日子把零星的演出与日渐加深的雪茄兴趣掺在一起。他抽的是古巴老派的路数，受的是辛纳屈及其圈子在纽约岁月里吸收的那套哈瓦那烟草文化的熏陶。八十年代成为古巴之外高端雪茄替代产地的多米尼加共和国，正好给了他想要的东西：出色的制作，以及用自己的名字建起点什么的可能。', '至于雪茄，他找到了 Hendrik Kelner，后者于1984年开办了 Tabacos Dominicanos（Tabadom）。据行业媒体报道，Kelner 为 Avo 下的首笔订单（17 000 支雪茄）可追溯到1987年，Madison Avenue 上的 Davidoff 门店于1988年销售该品牌；首次推出的时间标为1988年。维基百科写道，Davidoff 于1995年获得 Avo 的经销权，金额约1000万美元。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('بعد الستين، كان أوفيزيان يعيش حياة تمزج حفلات متفرّقة باهتمام متنامٍ بالسيجار. كان يدخّن على المدرسة الكوبية القديمة، متشرّبًا ثقافة تبغ هافانا نفسها التي استوعبها سيناترا ودائرته في سنواتهم النيويوركية. وكانت الجمهورية الدومينيكية، التي صارت في الثمانينيات بديل السيجار الفاخر عن كوبا، تقدّم له ما يبحث عنه: صناعة ممتازة، وإمكان بناء شيء يحمل اسمه.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'بعد الستين، كان أوفيزيان يعيش حياة تمزج حفلات متفرّقة باهتمام متنامٍ بالسيجار. كان يدخّن على المدرسة الكوبية القديمة، متشرّبًا ثقافة تبغ هافانا نفسها التي استوعبها سيناترا ودائرته في سنواتهم النيويوركية. وكانت الجمهورية الدومينيكية، التي صارت في الثمانينيات بديل السيجار الفاخر عن كوبا، تقدّم له ما يبحث عنه: صناعة ممتازة، وإمكان بناء شيء يحمل اسمه.', 'وللسيجار اتجه إلى Hendrik Kelner، الذي كان قد افتتح Tabacos Dominicanos (Tabadom) عام 1984. وبحسب صحافة المهنة، يعود أول طلب قدّمه Kelner لعلامة Avo، وهو 17 000 سيجار، إلى عام 1987، ويبيع متجر Davidoff في Madison Avenue العلامة عام 1988؛ وتُؤرَّخ أولى الإصدارات بعام 1988. وتكتب ويكيبيديا أن Davidoff اشترت عام 1995 حقوق توزيع Avo، بمبلغ يقارب 10 ملايين دولار.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Avo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Son ami Zino Davidoff facilita la rencontre avec la manufacture Tabadom, à Villa González — celle qu''Hendrik Kelner avait fondée en 1984, et où se développait la production dominicaine de Davidoff. Les premiers Avo XO parurent en 1988, immédiatement reconnaissables à une convention de nommage qu''aucun autre fabricant n''employait : les vitoles portaient des noms d''accords de jazz — Intermezzo, Maestoso, Notturno, Impromptu — plutôt que les désignations numériques ou de format en usage dans le métier. C''était une affirmation esthétique, et elle s''avéra commercialement efficace.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Son ami Zino Davidoff facilita la rencontre avec la manufacture Tabadom, à Villa González — celle qu''Hendrik Kelner avait fondée en 1984, et où se développait la production dominicaine de Davidoff. Les premiers Avo XO parurent en 1988, immédiatement reconnaissables à une convention de nommage qu''aucun autre fabricant n''employait : les vitoles portaient des noms d''accords de jazz — Intermezzo, Maestoso, Notturno, Impromptu — plutôt que les désignations numériques ou de format en usage dans le métier. C''était une affirmation esthétique, et elle s''avéra commercialement efficace.', 'Les cigares sont roulés en République dominicaine, dans la fabrique OK Cigars de Tabadom, filiale d''Oettinger Davidoff (presse du métier, 2016 et 2025). En janvier 2015, la marque a resserré son offre en quatre lignes courantes, Classic, Domaine, Heritage et XO ; Signature et Maduro étaient arrêtées. La ligne XO porte des termes musicaux pour noms de vitolas : Notturno, Preludio, Intermezzo, Legato, Maestoso.'), `history`),
  `history_en` = IF(LOCATE(CAST('His friend Zino Davidoff facilitated the introduction to the Tabadom factory in Villa González — the one Hendrik Kelner had founded in 1984, where Davidoff''s Dominican production was being developed. The first Avo XOs appeared in 1988, immediately distinguished by naming conventions that no other cigar manufacturer had employed: the vitolas carried jazz chord names — Intermezzo, Maestoso, Notturno, Impromptu — rather than the numerical or format-based designations that the rest of the industry used. It was a statement of aesthetic identity that proved to be commercially effective.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'His friend Zino Davidoff facilitated the introduction to the Tabadom factory in Villa González — the one Hendrik Kelner had founded in 1984, where Davidoff''s Dominican production was being developed. The first Avo XOs appeared in 1988, immediately distinguished by naming conventions that no other cigar manufacturer had employed: the vitolas carried jazz chord names — Intermezzo, Maestoso, Notturno, Impromptu — rather than the numerical or format-based designations that the rest of the industry used. It was a statement of aesthetic identity that proved to be commercially effective.', 'The cigars are rolled in the Dominican Republic, in the OK Cigars factory of Tabadom, a subsidiary of Oettinger Davidoff (trade press, 2016 and 2025). In January 2015 the brand narrowed its offer to four current lines, Classic, Domaine, Heritage and XO; Signature and Maduro were discontinued. The XO line takes musical terms as its vitola names: Notturno, Preludio, Intermezzo, Legato, Maestoso.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Su amigo Zino Davidoff facilitó el encuentro con la manufactura Tabadom, en Villa González —la que Hendrik Kelner había fundado en 1984, y donde se desarrollaba la producción dominicana de Davidoff. Los primeros Avo XO aparecieron en 1988, inmediatamente reconocibles por una convención de nombres que ningún otro fabricante empleaba: las vitolas llevaban nombres de acordes de jazz —Intermezzo, Maestoso, Notturno, Impromptu— en lugar de las designaciones numéricas o de formato al uso en el oficio. Era una afirmación estética, y resultó comercialmente eficaz.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Su amigo Zino Davidoff facilitó el encuentro con la manufactura Tabadom, en Villa González —la que Hendrik Kelner había fundado en 1984, y donde se desarrollaba la producción dominicana de Davidoff. Los primeros Avo XO aparecieron en 1988, inmediatamente reconocibles por una convención de nombres que ningún otro fabricante empleaba: las vitolas llevaban nombres de acordes de jazz —Intermezzo, Maestoso, Notturno, Impromptu— en lugar de las designaciones numéricas o de formato al uso en el oficio. Era una afirmación estética, y resultó comercialmente eficaz.', 'Los puros se tuercen en República Dominicana, en la fábrica OK Cigars de Tabadom, filial de Oettinger Davidoff (prensa del sector, 2016 y 2025). En enero de 2015, la marca redujo su oferta a cuatro líneas corrientes, Classic, Domaine, Heritage y XO; Signature y Maduro quedaron descatalogadas. La línea XO lleva términos musicales como nombres de vitolas: Notturno, Preludio, Intermezzo, Legato, Maestoso.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Sein Freund Zino Davidoff bahnte die Begegnung mit der Manufaktur Tabadom in Villa González an — jener, die Hendrik Kelner 1984 gegründet hatte und in der Davidoffs dominikanische Produktion entstand. Die ersten Avo XO erschienen 1988, sofort erkennbar an einer Namensordnung, die kein anderer Hersteller verwendete: Die Formate trugen Namen von Jazzakkorden — Intermezzo, Maestoso, Notturno, Impromptu — statt der im Fach üblichen Zahlen- oder Formatbezeichnungen. Das war eine ästhetische Behauptung, und sie erwies sich als kaufmännisch wirksam.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Sein Freund Zino Davidoff bahnte die Begegnung mit der Manufaktur Tabadom in Villa González an — jener, die Hendrik Kelner 1984 gegründet hatte und in der Davidoffs dominikanische Produktion entstand. Die ersten Avo XO erschienen 1988, sofort erkennbar an einer Namensordnung, die kein anderer Hersteller verwendete: Die Formate trugen Namen von Jazzakkorden — Intermezzo, Maestoso, Notturno, Impromptu — statt der im Fach üblichen Zahlen- oder Formatbezeichnungen. Das war eine ästhetische Behauptung, und sie erwies sich als kaufmännisch wirksam.', 'Die Zigarren werden in der Dominikanischen Republik gerollt, in der Fabrik OK Cigars von Tabadom, einer Tochtergesellschaft von Oettinger Davidoff (Fachpresse, 2016 und 2025). Im Januar 2015 hat die Marke ihr Angebot auf vier laufende Linien verschlankt, Classic, Domaine, Heritage und XO; Signature und Maduro wurden eingestellt. Die Linie XO trägt musikalische Begriffe als Vitola-Namen: Notturno, Preludio, Intermezzo, Legato, Maestoso.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('他的朋友齐诺·大卫杜夫促成了他与比亚冈萨雷斯 Tabadom 工厂的相识——那是亨德里克·凯尔纳 1984 年创办的工厂，也正是大卫杜夫多米尼加生产线所在之处。第一批 Avo XO 于1988年问世，一眼可辨，因为它用了别家都不用的命名法：各个规格取的是爵士和弦的名字——Intermezzo、Maestoso、Notturno、Impromptu——而不是行业惯用的编号或形制名称。这是一次美学上的主张，而它在商业上也奏了效。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '他的朋友齐诺·大卫杜夫促成了他与比亚冈萨雷斯 Tabadom 工厂的相识——那是亨德里克·凯尔纳 1984 年创办的工厂，也正是大卫杜夫多米尼加生产线所在之处。第一批 Avo XO 于1988年问世，一眼可辨，因为它用了别家都不用的命名法：各个规格取的是爵士和弦的名字——Intermezzo、Maestoso、Notturno、Impromptu——而不是行业惯用的编号或形制名称。这是一次美学上的主张，而它在商业上也奏了效。', '雪茄在多米尼加共和国卷制，地点是 Tabadom 旗下的 OK Cigars 工厂，Tabadom 是 Oettinger Davidoff 的子公司（行业媒体，2016年与2025年）。2015年1月，该品牌把产品线收窄为四个在售系列：Classic、Domaine、Heritage 与 XO；Signature 与 Maduro 已停产。XO 系列以音乐术语作为规格名称：Notturno、Preludio、Intermezzo、Legato、Maestoso。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('يسّر له صديقه زينو دافيدوف اللقاء بمصنع تابادوم في بيّا غونثاليث — المصنع الذي أسّسه هندريك كيلنر عام 1984، والذي كان يتطوّر فيه إنتاج دافيدوف الدومينيكي. ظهرت أولى سيجارات «آفو إكس أو» عام 1988، وكانت تُعرف فورًا من طريقة تسمية لم يستعملها صانع آخر: فالقياسات تحمل أسماء تآلفات جازية — إنترميتزو، ومايستوزو، ونوتورنو، وإمبرومبتو — بدل التسميات الرقمية أو تسميات الأشكال المتداولة في المهنة. كان ذلك موقفًا جماليًّا، وثبت أنه ناجح تجاريًّا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'يسّر له صديقه زينو دافيدوف اللقاء بمصنع تابادوم في بيّا غونثاليث — المصنع الذي أسّسه هندريك كيلنر عام 1984، والذي كان يتطوّر فيه إنتاج دافيدوف الدومينيكي. ظهرت أولى سيجارات «آفو إكس أو» عام 1988، وكانت تُعرف فورًا من طريقة تسمية لم يستعملها صانع آخر: فالقياسات تحمل أسماء تآلفات جازية — إنترميتزو، ومايستوزو، ونوتورنو، وإمبرومبتو — بدل التسميات الرقمية أو تسميات الأشكال المتداولة في المهنة. كان ذلك موقفًا جماليًّا، وثبت أنه ناجح تجاريًّا.', 'تُلفّ السيجارات في الجمهورية الدومينيكية، في مصنع OK Cigars التابع لـ Tabadom، وهي فرع من Oettinger Davidoff (صحافة المهنة، 2016 و2025). وفي يناير 2015 حصرت العلامة عرضها في أربعة خطوط جارية هي Classic وDomaine وHeritage وXO؛ وتوقّف إنتاج Signature وMaduro. ويحمل خط XO مصطلحات موسيقية أسماءً لقياساته: Notturno وPreludio وIntermezzo وLegato وMaestoso.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Avo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le groupe Davidoff racheta Avo dans les années 1990 et a maintenu la production en République dominicaine dans le même esprit. Avo Uvezian est mort en 2017, à quatre-vingt-neuf ans. La marque continue en hommage, chaque sortie tenant le lien entre le vocabulaire du jazz et les possibilités du tabac dominicain — un lien qu''il avait établi en décidant, à un âge où la plupart des musiciens songent à s''arrêter, de devenir fabricant de cigares.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le groupe Davidoff racheta Avo dans les années 1990 et a maintenu la production en République dominicaine dans le même esprit. Avo Uvezian est mort en 2017, à quatre-vingt-neuf ans. La marque continue en hommage, chaque sortie tenant le lien entre le vocabulaire du jazz et les possibilités du tabac dominicain — un lien qu''il avait établi en décidant, à un âge où la plupart des musiciens songent à s''arrêter, de devenir fabricant de cigares.', 'Davidoff a fêté ses anniversaires par une édition limitée chaque année de 2001 à 2014, puis l''Avo 90th en 2016. En mars 2026, la presse du métier rapportait que la maison prévoyait de marquer le centenaire d''Uvezian au salon PCA d''avril.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Davidoff group acquired Avo during the 1990s and has maintained production in the Dominican Republic under the original ethos. Avo Uvezian died in 2017, at eighty-nine. The brand continues as a tribute, with each release maintaining the connection between jazz''s vocabulary and Dominican tobacco''s possibilities that Uvezian established when he decided, at an age when most musicians are considering retirement, to become a cigar maker instead.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Davidoff group acquired Avo during the 1990s and has maintained production in the Dominican Republic under the original ethos. Avo Uvezian died in 2017, at eighty-nine. The brand continues as a tribute, with each release maintaining the connection between jazz''s vocabulary and Dominican tobacco''s possibilities that Uvezian established when he decided, at an age when most musicians are considering retirement, to become a cigar maker instead.', 'Davidoff marked its anniversaries with a limited edition every year from 2001 to 2014, then the Avo 90th in 2016. In March 2026 the trade press reported that the house planned to mark Uvezian''s centenary at the PCA show in April.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El grupo Davidoff compró Avo en los años noventa y ha mantenido la producción en República Dominicana con el mismo espíritu. Avo Uvezian murió en 2017, a los ochenta y nueve años. La marca continúa como homenaje, y cada salida sostiene el vínculo entre el vocabulario del jazz y las posibilidades del tabaco dominicano —un vínculo que él estableció al decidir, a una edad en que la mayoría de los músicos piensan en parar, hacerse fabricante de puros.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El grupo Davidoff compró Avo en los años noventa y ha mantenido la producción en República Dominicana con el mismo espíritu. Avo Uvezian murió en 2017, a los ochenta y nueve años. La marca continúa como homenaje, y cada salida sostiene el vínculo entre el vocabulario del jazz y las posibilidades del tabaco dominicano —un vínculo que él estableció al decidir, a una edad en que la mayoría de los músicos piensan en parar, hacerse fabricante de puros.', 'Davidoff celebró sus aniversarios con una edición limitada cada año de 2001 a 2014, y luego con el Avo 90th en 2016. En marzo de 2026, la prensa del sector informaba de que la casa preveía marcar el centenario de Uvezian en el salón PCA de abril.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Davidoff-Gruppe kaufte Avo in den neunziger Jahren und hat die Produktion in der Dominikanischen Republik im selben Geist fortgeführt. Avo Uvezian starb 2017 mit neunundachtzig Jahren. Die Marke besteht als Hommage weiter, und jede Neuheit hält die Verbindung zwischen dem Vokabular des Jazz und den Möglichkeiten des dominikanischen Tabaks — eine Verbindung, die er stiftete, als er in einem Alter, in dem die meisten Musiker ans Aufhören denken, beschloss, Zigarrenhersteller zu werden.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Davidoff-Gruppe kaufte Avo in den neunziger Jahren und hat die Produktion in der Dominikanischen Republik im selben Geist fortgeführt. Avo Uvezian starb 2017 mit neunundachtzig Jahren. Die Marke besteht als Hommage weiter, und jede Neuheit hält die Verbindung zwischen dem Vokabular des Jazz und den Möglichkeiten des dominikanischen Tabaks — eine Verbindung, die er stiftete, als er in einem Alter, in dem die meisten Musiker ans Aufhören denken, beschloss, Zigarrenhersteller zu werden.', 'Davidoff feierte seine Jubiläen von 2001 bis 2014 jedes Jahr mit einer limitierten Edition, 2016 dann mit der Avo 90th. Im März 2026 berichtete die Fachpresse, das Haus plane, Uvezians 100. Geburtstag auf der PCA-Messe im April zu begehen.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('九十年代，大卫杜夫集团收购了 Avo，并以同样的精神把生产留在多米尼加共和国。2017年，阿沃·乌韦兹扬去世，享年八十九岁。品牌以致敬的方式延续，每一次新品都维系着爵士词汇与多米尼加烟草可能性之间的那条线——这条线是他亲手系上的：在大多数音乐家考虑收手的年纪，他决定去做一个雪茄制造者。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '九十年代，大卫杜夫集团收购了 Avo，并以同样的精神把生产留在多米尼加共和国。2017年，阿沃·乌韦兹扬去世，享年八十九岁。品牌以致敬的方式延续，每一次新品都维系着爵士词汇与多米尼加烟草可能性之间的那条线——这条线是他亲手系上的：在大多数音乐家考虑收手的年纪，他决定去做一个雪茄制造者。', 'Davidoff 在2001年至2014年间每年推出一款限量版来庆祝其周年，随后在2016年推出 Avo 90th。2026年3月，行业媒体报道称，该厂计划在4月的 PCA 展会上纪念 Uvezian 的百年。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('اشترت مجموعة دافيدوف علامة «آفو» في التسعينيات وأبقت الإنتاج في الجمهورية الدومينيكية بالروح نفسها. تُوفّي آفو أوفيزيان عام 2017 عن تسعة وثمانين عامًا. وتستمر العلامة تحيةً له، إذ يحفظ كل إصدار الصلة بين مفردات الجاز وإمكانات التبغ الدومينيكي — وهي صلة عقدها هو حين قرّر، في سنّ يفكّر فيها معظم الموسيقيين في التوقّف، أن يصير صانع سيجار.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'اشترت مجموعة دافيدوف علامة «آفو» في التسعينيات وأبقت الإنتاج في الجمهورية الدومينيكية بالروح نفسها. تُوفّي آفو أوفيزيان عام 2017 عن تسعة وثمانين عامًا. وتستمر العلامة تحيةً له، إذ يحفظ كل إصدار الصلة بين مفردات الجاز وإمكانات التبغ الدومينيكي — وهي صلة عقدها هو حين قرّر، في سنّ يفكّر فيها معظم الموسيقيين في التوقّف، أن يصير صانع سيجار.', 'احتفلت Davidoff بمناسباتها السنوية بإصدار محدود في كل عام من 2001 إلى 2014، ثم بـ Avo 90th عام 2016. وفي مارس 2026 أفادت صحافة المهنة بأن الدار تعتزم إحياء مئوية Uvezian في معرض PCA في أبريل.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Avo';

UPDATE `brands` SET
  `limited_eds` = '["Avo Classic Covers (volumes 1 à 4, 2015-2016)","Avo 90th (2016)","Avo Improvisation 30 Years (2018)"]',
  `founded` = '1988 — première sortie ; Davidoff dès 1995',
  `factory` = 'OK Cigars, fabrique de Tabadom (Oettinger Davidoff), République dominicaine ; Tabadom est à Villa González selon la presse du métier en 2025',
  `gamme` = '[{"name":"Avo Classic","color":"#C9A96E","force":null,"story":"La ligne d''origine de la marque. En janvier 2015, la presse du métier la donne en cape Ecuadorian Connecticut Seed sur sous-cape et tripe dominicaines. Les vitolas portent des numéros (No. 9, No. 5, No. 2, No. 3, No. 6) ainsi que Robusto et Primides.","vitolas":["No.1","No.2","No.3","No.5","No.9","Robusto","Toro"],"wrapper":"Connecticut Seed équatorien"},{"name":"Avo XO","color":"#8B6914","force":null,"story":"Ligne aux noms de termes musicaux : Notturno (5 x 42), Preludio (6 x 40), Intermezzo (5 x 50), Legato (6 x 54), Maestoso (7 x 48), selon la presse du métier en janvier 2015. Cape Ecuadorian-grown Connecticut Seed sur tripe et sous-cape dominicaines.","vitolas":["Intermezzo","Maestoso","Notturno","Preludio"],"wrapper":"Connecticut Seed équatorien"},{"name":"Avo Heritage","color":"#6B4423","force":null,"wrapper":"Équateur, Special Sun Grown","vitolas":[],"story":"Ligne courante de la relance de janvier 2015, en cape équatorienne Special Sun Grown sur tripe et sous-cape dominicaines (Short Torpedo, Robusto, Toro, Special Toro, Short Robusto)."},{"name":"Avo Domaine","color":"#7A4B2A","force":null,"wrapper":"Équateur, Sun Grown","vitolas":[],"story":"Ligne courante de la relance de janvier 2015, en cape équatorienne Sun Grown de semence Connecticut/cubaine sur tripe et sous-cape dominicaines (Domaine 20, 10, 50 et 70)."}]',
  `gamme_en` = '[{"name":"Avo Classic","color":"#C9A96E","force":null,"story":"The brand''s original line. In January 2015 the trade press gave it as an Ecuadorian Connecticut Seed wrapper over Dominican binder and filler. The vitolas carry numbers (No. 9, No. 5, No. 2, No. 3, No. 6) as well as Robusto and Primides.","vitolas":["No.1","No.2","No.3","No.5","No.9","Robusto","Toro"],"wrapper":"Ecuadorian Connecticut Seed"},{"name":"Avo XO","color":"#8B6914","force":null,"story":"A line named with musical terms: Notturno (5 x 42), Preludio (6 x 40), Intermezzo (5 x 50), Legato (6 x 54), Maestoso (7 x 48), according to the trade press in January 2015. Ecuadorian-grown Connecticut Seed wrapper over Dominican filler and binder.","vitolas":["Intermezzo","Maestoso","Notturno","Preludio"],"wrapper":"Ecuadorian Connecticut Seed"},{"name":"Avo Heritage","color":"#6B4423","force":null,"wrapper":"Ecuador, Special Sun Grown","vitolas":[],"story":"Current line from the January 2015 relaunch, with an Ecuadorian Special Sun Grown wrapper over Dominican filler and binder (Short Torpedo, Robusto, Toro, Special Toro, Short Robusto)."},{"name":"Avo Domaine","color":"#7A4B2A","force":null,"wrapper":"Ecuador, Sun Grown","vitolas":[],"story":"Current line from the January 2015 relaunch, with an Ecuadorian Sun Grown wrapper from Connecticut/Cuban seed over Dominican filler and binder (Domaine 20, 10, 50 and 70)."}]',
  `gamme_es` = '[{"name":"Avo Classic","color":"#C9A96E","force":null,"story":"La línea original de la marca. En enero de 2015, la prensa del sector la da con capa Connecticut Seed de Ecuador sobre capote y tripa dominicanos. Las vitolas llevan números (No. 9, No. 5, No. 2, No. 3, No. 6), además de Robusto y Primides.","vitolas":["No.1","No.2","No.3","No.5","No.9","Robusto","Toro"],"wrapper":"Connecticut Seed de Ecuador"},{"name":"Avo XO","color":"#8B6914","force":null,"story":"Línea con nombres de términos musicales: Notturno (5 x 42), Preludio (6 x 40), Intermezzo (5 x 50), Legato (6 x 54), Maestoso (7 x 48), según la prensa del sector en enero de 2015. Capa Connecticut Seed cultivada en Ecuador sobre tripa y capote dominicanos.","vitolas":["Intermezzo","Maestoso","Notturno","Preludio"],"wrapper":"Connecticut Seed de Ecuador"},{"name":"Avo Heritage","color":"#6B4423","force":null,"wrapper":"Ecuador, Special Sun Grown","vitolas":[],"story":"Línea corriente del relanzamiento de enero de 2015, con capa ecuatoriana Special Sun Grown sobre tripa y capote dominicanos (Short Torpedo, Robusto, Toro, Special Toro, Short Robusto)."},{"name":"Avo Domaine","color":"#7A4B2A","force":null,"wrapper":"Ecuador, Sun Grown","vitolas":[],"story":"Línea corriente del relanzamiento de enero de 2015, con capa ecuatoriana Sun Grown de semilla Connecticut/cubana sobre tripa y capote dominicanos (Domaine 20, 10, 50 y 70)."}]',
  `gamme_de` = '[{"name":"Avo Classic","color":"#C9A96E","force":null,"story":"Die ursprüngliche Linie der Marke. Im Januar 2015 nennt die Fachpresse sie mit Deckblatt Connecticut Seed aus Ecuador über Umblatt und Einlage aus der Dominikanischen Republik. Die Vitolas tragen Nummern (No. 9, No. 5, No. 2, No. 3, No. 6) sowie Robusto und Primides.","vitolas":["No.1","No.2","No.3","No.5","No.9","Robusto","Toro"],"wrapper":"Connecticut Seed aus Ecuador"},{"name":"Avo XO","color":"#8B6914","force":null,"story":"Linie mit Namen aus musikalischen Begriffen: Notturno (5 x 42), Preludio (6 x 40), Intermezzo (5 x 50), Legato (6 x 54), Maestoso (7 x 48), laut Fachpresse im Januar 2015. Deckblatt Connecticut Seed, in Ecuador angebaut, über Einlage und Umblatt aus der Dominikanischen Republik.","vitolas":["Intermezzo","Maestoso","Notturno","Preludio"],"wrapper":"Connecticut Seed aus Ecuador"},{"name":"Avo Heritage","color":"#6B4423","force":null,"wrapper":"Ecuador, Special Sun Grown","vitolas":[],"story":"Laufende Linie der Neuauflage vom Januar 2015, mit ecuadorianischem Deckblatt Special Sun Grown über Einlage und Umblatt aus der Dominikanischen Republik (Short Torpedo, Robusto, Toro, Special Toro, Short Robusto)."},{"name":"Avo Domaine","color":"#7A4B2A","force":null,"wrapper":"Ecuador, Sun Grown","vitolas":[],"story":"Laufende Linie der Neuauflage vom Januar 2015, mit ecuadorianischem Deckblatt Sun Grown aus Connecticut-/kubanischem Saatgut über Einlage und Umblatt aus der Dominikanischen Republik (Domaine 20, 10, 50 und 70)."}]',
  `gamme_zh` = '[{"name":"Avo Classic","color":"#C9A96E","force":null,"story":"品牌的原始系列。2015年1月，行业媒体称其茄衣为厄瓜多尔 Connecticut Seed，内裹多米尼加束叶与芯叶。各规格带有编号（No. 9、No. 5、No. 2、No. 3、No. 6），另有 Robusto 与 Primides。","vitolas":["No.1","No.2","No.3","No.5","No.9","Robusto","Toro"],"wrapper":"厄瓜多尔 Connecticut Seed"},{"name":"Avo XO","color":"#8B6914","force":null,"story":"以音乐术语命名的系列：Notturno（5 x 42）、Preludio（6 x 40）、Intermezzo（5 x 50）、Legato（6 x 54）、Maestoso（7 x 48），依据2015年1月的行业媒体报道。茄衣为厄瓜多尔种植的 Connecticut Seed，内裹多米尼加芯叶与束叶。","vitolas":["Intermezzo","Maestoso","Notturno","Preludio"],"wrapper":"厄瓜多尔 Connecticut Seed"},{"name":"Avo Heritage","color":"#6B4423","force":null,"wrapper":"厄瓜多尔，Special Sun Grown","vitolas":[],"story":"2015年1月重新推出的在售系列，茄衣为厄瓜多尔 Special Sun Grown，内裹多米尼加芯叶与束叶（Short Torpedo、Robusto、Toro、Special Toro、Short Robusto）。"},{"name":"Avo Domaine","color":"#7A4B2A","force":null,"wrapper":"厄瓜多尔，Sun Grown","vitolas":[],"story":"2015年1月重新推出的在售系列，茄衣为厄瓜多尔 Sun Grown，种子为 Connecticut/古巴品种，内裹多米尼加芯叶与束叶（Domaine 20、10、50 与 70）。"}]',
  `gamme_ar` = '[{"name":"Avo Classic","color":"#C9A96E","force":null,"story":"الخط الأصلي للعلامة. وفي يناير 2015 تذكر صحافة المهنة أن غلافه Connecticut Seed إكوادوري فوق غلاف داخلي وحشوة دومينيكيين. وتحمل القياسات أرقامًا (No. 9 وNo. 5 وNo. 2 وNo. 3 وNo. 6) إضافة إلى Robusto وPrimides.","vitolas":["No.1","No.2","No.3","No.5","No.9","Robusto","Toro"],"wrapper":"Connecticut Seed إكوادوري"},{"name":"Avo XO","color":"#8B6914","force":null,"story":"خط بأسماء مصطلحات موسيقية: Notturno (5 x 42) وPreludio (6 x 40) وIntermezzo (5 x 50) وLegato (6 x 54) وMaestoso (7 x 48)، بحسب صحافة المهنة في يناير 2015. غلاف Connecticut Seed مزروع في الإكوادور فوق حشوة وغلاف داخلي دومينيكيين.","vitolas":["Intermezzo","Maestoso","Notturno","Preludio"],"wrapper":"Connecticut Seed إكوادوري"},{"name":"Avo Heritage","color":"#6B4423","force":null,"wrapper":"الإكوادور، Special Sun Grown","vitolas":[],"story":"خط جارٍ من إعادة الإطلاق في يناير 2015، بغلاف إكوادوري Special Sun Grown فوق حشوة وغلاف داخلي دومينيكيين (Short Torpedo وRobusto وToro وSpecial Toro وShort Robusto)."},{"name":"Avo Domaine","color":"#7A4B2A","force":null,"wrapper":"الإكوادور، Sun Grown","vitolas":[],"story":"خط جارٍ من إعادة الإطلاق في يناير 2015، بغلاف إكوادوري Sun Grown من بذور Connecticut/كوبية فوق حشوة وغلاف داخلي دومينيكيين (Domaine 20 و10 و50 و70)."}]',
  `celebrities` = '[{"name":"Avo Uvezian","anecdote":"Pianiste et compositeur né à Beyrouth en 1926, mort en 2017 à 91 ans. Il affirmait avoir composé Strangers in the Night, créditée à Bert Kaempfert (Wikipédia). Armenpress, citant Men''s Journal, raconte qu''il joua en 1966 une mélodie à Sinatra, qui lui fit changer titre et paroles."}]',
  `celebrities_en` = '[{"name":"Avo Uvezian","anecdote":"Pianist and composer born in Beirut in 1926, died in 2017 aged 91. He claimed to have composed Strangers in the Night, which is credited to Bert Kaempfert (Wikipedia). Armenpress, citing Men''s Journal, relates that in 1966 he played a melody to Sinatra, who had him change the title and lyrics."}]',
  `celebrities_es` = '[{"name":"Avo Uvezian","anecdote":"Pianista y compositor nacido en Beirut en 1926, muerto en 2017 a los 91 años. Afirmaba haber compuesto Strangers in the Night, atribuida a Bert Kaempfert (Wikipedia). Armenpress, citando a Men''s Journal, cuenta que en 1966 tocó una melodía a Sinatra, quien le hizo cambiar el título y la letra."}]',
  `celebrities_de` = '[{"name":"Avo Uvezian","anecdote":"Pianist und Komponist, 1926 in Beirut geboren, 2017 mit 91 Jahren gestorben. Er behauptete, Strangers in the Night komponiert zu haben, das Bert Kaempfert zugeschrieben wird (Wikipedia). Armenpress berichtet unter Berufung auf Men''s Journal, er habe 1966 Sinatra eine Melodie vorgespielt, der ihn Titel und Text ändern ließ."}]',
  `celebrities_zh` = '[{"name":"Avo Uvezian","anecdote":"钢琴家兼作曲家，1926年生于 Beirut，2017年去世，享年91岁。他声称自己创作了《Strangers in the Night》，这首歌署名为 Bert Kaempfert（维基百科）。Armenpress 援引 Men''s Journal 的报道称，他在1966年向 Sinatra 弹奏了一段旋律，Sinatra 让他更改了标题和歌词。"}]',
  `celebrities_ar` = '[{"name":"Avo Uvezian","anecdote":"عازف بيانو وملحّن وُلد في Beirut عام 1926 وتوفي عام 2017 عن 91 عامًا. كان يؤكد أنه ألّف «Strangers in the Night»، المنسوبة إلى Bert Kaempfert (ويكيبيديا). وتروي Armenpress، نقلًا عن Men''s Journal، أنه عزف عام 1966 لحنًا أمام Sinatra، فطلب منه هذا الأخير تغيير العنوان والكلمات."}]',
  `pairings` = '[{"type":"Jazz","name":"Miles Davis, Kind of Blue","notes":"Suggestion d''ambiance pour la ligne Classic, sans lien documenté avec la marque."},{"type":"Café","name":"Café dominicain de Barahona","notes":"Suggestion : un café doux accompagne une ligne de corps léger à moyen sans la couvrir."},{"type":"Spiritueux","name":"Cognac jeune","notes":"Suggestion : un cognac souple pour la ligne XO."}]',
  `pairings_en` = '[{"type":"Jazz","name":"Miles Davis, Kind of Blue","notes":"A suggestion for atmosphere with the Classic line, with no documented link to the brand."},{"type":"Coffee","name":"Dominican coffee from Barahona","notes":"A suggestion: a soft coffee accompanies a light- to medium-bodied line without overpowering it."},{"type":"Spirits","name":"Young cognac","notes":"A suggestion: a supple cognac for the XO line."}]',
  `pairings_es` = '[{"type":"Jazz","name":"Miles Davis, Kind of Blue","notes":"Sugerencia de ambiente para la línea Classic, sin vínculo documentado con la marca."},{"type":"Café","name":"Café dominicano de Barahona","notes":"Sugerencia: un café suave acompaña una línea de cuerpo ligero a medio sin taparla."},{"type":"Licores","name":"Coñac joven","notes":"Sugerencia: un coñac suave para la línea XO."}]',
  `pairings_de` = '[{"type":"Jazz","name":"Miles Davis, Kind of Blue","notes":"Stimmungsvorschlag für die Linie Classic, ohne dokumentierte Verbindung zur Marke."},{"type":"Kaffee","name":"Dominikanischer Kaffee aus Barahona","notes":"Vorschlag: Ein milder Kaffee begleitet eine Linie von leichtem bis mittlerem Körper, ohne sie zu überdecken."},{"type":"Spirituosen","name":"Junger Cognac","notes":"Vorschlag: ein geschmeidiger Cognac für die Linie XO."}]',
  `pairings_zh` = '[{"type":"Jazz","name":"Miles Davis, Kind of Blue","notes":"为 Classic 系列营造氛围的建议，与该品牌并无文献可查的关联。"},{"type":"咖啡","name":"Barahona 产多米尼加咖啡","notes":"建议：柔和的咖啡搭配劲道轻至中等的系列，不会盖过它。"},{"type":"烈酒","name":"年轻干邑","notes":"建议：为 XO 系列配一款柔顺的干邑。"}]',
  `pairings_ar` = '[{"type":"Jazz","name":"Miles Davis, Kind of Blue","notes":"اقتراح للأجواء مع خط Classic، دون صلة موثّقة بالعلامة."},{"type":"القهوة","name":"قهوة دومينيكية من Barahona","notes":"اقتراح: قهوة لطيفة ترافق خطًا خفيف القوام إلى متوسطه دون أن تغطي عليه."},{"type":"المسكرات","name":"كونياك فتي","notes":"اقتراح: كونياك سلس لخط XO."}]',
  `source` = IF(LOCATE(CAST(' ; cigarjournal.com (O.K. Cigars, campus Tabadom)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; cigarjournal.com (O.K. Cigars, campus Tabadom)', ''), `source`),
  `source` = IF(LOCATE(CAST('cigardojo.com « Avo Uvezian dies at age 91 » (2017-03-24 : n' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigardojo.com « Avo Uvezian dies at age 91 » (2017-03-24 : né le 22 mars 1926, mort le 24 mars 2017 à 91 ans) ; en.wikipedia.org « Avo Uvezian » (Kaempfert, Davidoff 1995) ; cigar-coop.com « AVO Cigar Unveils Revamped Line » (2015-01-13 : lignes, capes, vitolas) ; cigardojo.com « IPCPR 2016, Avo » (2016-08-10 : OK Cigar Corp, République dominicaine) ; cigaraficionado.com « Kelner — Davidoff''s Tobacco Guru » (Tabadom 1984, commande 1987, Madison Avenue 1988) ; cigaraficionado.com « Cigar Brand Highlight, Avo » (lignes actuelles, Expresivo Honduras)')),
  `updated_at` = NOW()
 WHERE `name` = 'Avo';

-- ── Macanudo ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Les origines de Macanudo sont caribéennes et compliquées. La marque fut fondée en Jamaïque en 1868 sous le nom de Temple Hall, à partir d''un tabac jamaïcain qui offrait quelque chose d''inhabituel sur le marché premium du milieu du XIXe siècle : un profil léger et crémeux, de force minimale et d''accès maximal. Les sols et le climat de l''île donnaient un tabac plus proche du Connecticut Shade que de la Vuelta Abajo cubaine — souple, doux, indulgent pour les fumeurs qui trouvaient exigeante l''intensité des grandes marques de La Havane.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Les origines de Macanudo sont caribéennes et compliquées. La marque fut fondée en Jamaïque en 1868 sous le nom de Temple Hall, à partir d''un tabac jamaïcain qui offrait quelque chose d''inhabituel sur le marché premium du milieu du XIXe siècle : un profil léger et crémeux, de force minimale et d''accès maximal. Les sols et le climat de l''île donnaient un tabac plus proche du Connecticut Shade que de la Vuelta Abajo cubaine — souple, doux, indulgent pour les fumeurs qui trouvaient exigeante l''intensité des grandes marques de La Havane.', 'Macanudo vient de Jamaïque. Selon la presse du métier, c''était une petite marque roulée à la main à la fabrique Temple Hall, à Kingston, pour le marché britannique. En 1968, General Cigar Co. rachète Temple Hall avec la marque, et la presse du métier note que Macanudo est plus ancienne que les 50 ans fêtés en 2018. La date de création de la marque n''est pas établie ; 1968 est l''année du rachat.'), `history`),
  `history_en` = IF(LOCATE(CAST('Macanudo''s origins are Caribbean and distinctly complicated. The brand was founded in Jamaica in 1868 under the name Temple Hall, using Jamaican-grown tobacco that offered something genuinely unusual in the mid-nineteenth century premium market: a light, creamy profile with minimal strength and maximum accessibility. Jamaica''s soils and climate produced a tobacco character that was more like Connecticut shade than Cuban Vuelta Abajo — smooth, gentle, and forgiving for smokers who found the intensity of Havana''s great brands demanding.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Macanudo''s origins are Caribbean and distinctly complicated. The brand was founded in Jamaica in 1868 under the name Temple Hall, using Jamaican-grown tobacco that offered something genuinely unusual in the mid-nineteenth century premium market: a light, creamy profile with minimal strength and maximum accessibility. Jamaica''s soils and climate produced a tobacco character that was more like Connecticut shade than Cuban Vuelta Abajo — smooth, gentle, and forgiving for smokers who found the intensity of Havana''s great brands demanding.', 'Macanudo comes from Jamaica. According to the trade press, it was a small hand-rolled brand made at the Temple Hall factory in Kingston for the British market. In 1968 General Cigar Co. bought Temple Hall together with the brand, and the trade press notes that Macanudo is older than the 50 years celebrated in 2018. The date the brand was created is not established; 1968 is the year of the purchase.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Los orígenes de Macanudo son caribeños y complicados. La marca se fundó en Jamaica en 1868 con el nombre de Temple Hall, a partir de un tabaco jamaicano que ofrecía algo inhabitual en el mercado premium de mediados del siglo XIX: un perfil ligero y cremoso, de fuerza mínima y acceso máximo. Los suelos y el clima de la isla daban un tabaco más cercano al Connecticut Shade que a la Vuelta Abajo cubana —flexible, suave, indulgente con los fumadores que encontraban exigente la intensidad de las grandes marcas de La Habana.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Los orígenes de Macanudo son caribeños y complicados. La marca se fundó en Jamaica en 1868 con el nombre de Temple Hall, a partir de un tabaco jamaicano que ofrecía algo inhabitual en el mercado premium de mediados del siglo XIX: un perfil ligero y cremoso, de fuerza mínima y acceso máximo. Los suelos y el clima de la isla daban un tabaco más cercano al Connecticut Shade que a la Vuelta Abajo cubana —flexible, suave, indulgente con los fumadores que encontraban exigente la intensidad de las grandes marcas de La Habana.', 'Macanudo viene de Jamaica. Según la prensa del sector, era una pequeña marca hecha a mano en la fábrica Temple Hall, en Kingston, para el mercado británico. En 1968, General Cigar Co. compra Temple Hall junto con la marca, y la prensa del sector señala que Macanudo es anterior a los 50 años celebrados en 2018. La fecha de creación de la marca no está establecida; 1968 es el año de la compra.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Ursprünge von Macanudo sind karibisch und verwickelt. Die Marke wurde 1868 in Jamaika unter dem Namen Temple Hall gegründet, aus einem jamaikanischen Tabak, der auf dem Premiummarkt der Mitte des 19. Jahrhunderts etwas Ungewöhnliches bot: ein leichtes, cremiges Profil, von geringster Stärke und größter Zugänglichkeit. Böden und Klima der Insel ergaben einen Tabak, der dem Connecticut Shade näherstand als der kubanischen Vuelta Abajo — geschmeidig, mild, nachsichtig gegenüber Rauchern, denen die Intensität der großen Havanna-Marken zu viel abverlangte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Ursprünge von Macanudo sind karibisch und verwickelt. Die Marke wurde 1868 in Jamaika unter dem Namen Temple Hall gegründet, aus einem jamaikanischen Tabak, der auf dem Premiummarkt der Mitte des 19. Jahrhunderts etwas Ungewöhnliches bot: ein leichtes, cremiges Profil, von geringster Stärke und größter Zugänglichkeit. Böden und Klima der Insel ergaben einen Tabak, der dem Connecticut Shade näherstand als der kubanischen Vuelta Abajo — geschmeidig, mild, nachsichtig gegenüber Rauchern, denen die Intensität der großen Havanna-Marken zu viel abverlangte.', 'Macanudo stammt aus Jamaika. Laut der Fachpresse war es eine kleine, handgerollte Marke, die in der Fabrik Temple Hall in Kingston für den britischen Markt hergestellt wurde. 1968 kaufte General Cigar Co. Temple Hall samt der Marke, und die Fachpresse vermerkt, dass Macanudo älter ist als die 50 Jahre, die 2018 gefeiert wurden. Das Gründungsdatum der Marke ist nicht belegt; 1968 ist das Jahr des Kaufs.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('马卡努多的来历是加勒比式的，也是复杂的。1868年，这个品牌以「圣殿厅」之名创立于牙买加，用的是一种在19世纪中叶高端市场上颇为少见的牙买加烟草：轻盈、奶油质地，力度最小而门槛最低。岛上的土壤与气候，长出的烟草更接近康涅狄格阴植叶，而不是古巴的阿巴霍谷——柔韧、温和，对那些觉得哈瓦那大牌太过强烈的烟客格外宽容。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '马卡努多的来历是加勒比式的，也是复杂的。1868年，这个品牌以「圣殿厅」之名创立于牙买加，用的是一种在19世纪中叶高端市场上颇为少见的牙买加烟草：轻盈、奶油质地，力度最小而门槛最低。岛上的土壤与气候，长出的烟草更接近康涅狄格阴植叶，而不是古巴的阿巴霍谷——柔韧、温和，对那些觉得哈瓦那大牌太过强烈的烟客格外宽容。', 'Macanudo来自牙买加。据行业媒体，它原是一个小型手工卷制品牌，在金斯敦的Temple Hall工厂为英国市场生产。1968年，General Cigar Co.买下Temple Hall及这个品牌，行业媒体指出，Macanudo的历史比2018年庆祝的50周年还要久远。品牌的创立日期并无定论；1968年是收购之年。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أصول ماكانودو كاريبية ومتشابكة. تأسّست العلامة في جامايكا عام 1868 باسم «تمبل هول»، انطلاقًا من تبغ جامايكي كان يقدّم شيئًا غير مألوف في السوق الفاخرة في منتصف القرن التاسع عشر: طابعًا خفيفًا قشديًّا، أدنى قوة وأوسع تناول. فقد كانت تربة الجزيرة ومناخها يعطيان تبغًا أقرب إلى كونيتيكت شيد منه إلى فويلتا أباخو الكوبية — ليّنًا، لطيفًا، متسامحًا مع المدخّنين الذين تُرهقهم شدّة كبريات علامات هافانا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أصول ماكانودو كاريبية ومتشابكة. تأسّست العلامة في جامايكا عام 1868 باسم «تمبل هول»، انطلاقًا من تبغ جامايكي كان يقدّم شيئًا غير مألوف في السوق الفاخرة في منتصف القرن التاسع عشر: طابعًا خفيفًا قشديًّا، أدنى قوة وأوسع تناول. فقد كانت تربة الجزيرة ومناخها يعطيان تبغًا أقرب إلى كونيتيكت شيد منه إلى فويلتا أباخو الكوبية — ليّنًا، لطيفًا، متسامحًا مع المدخّنين الذين تُرهقهم شدّة كبريات علامات هافانا.', 'تنحدر Macanudo من جامايكا. وبحسب صحافة القطاع، كانت علامة صغيرة تُلفّ يدويًا في مصنع Temple Hall في كينغستون للسوق البريطانية. وفي عام 1968 اشترت General Cigar Co. مصنع Temple Hall مع العلامة، وتشير صحافة القطاع إلى أن عمر Macanudo يتجاوز الخمسين عامًا التي احتُفل بها في 2018. لم يثبت تاريخ إنشاء العلامة؛ و1968 هو عام الشراء.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Macanudo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''installation à New York dans les années 1960, sous l''impulsion d''Edgar M. Cullman Sr., transforma une spécialité caribéenne en phénomène américain. Cullman avait compris que le fumeur aisé de l''après-guerre voulait du luxe sans épreuve — un cigare disant le raffinement sans exiger d''expertise ni de tolérance physique. Il repositionna Macanudo autour de capes Connecticut Shade et de tripes dominicaines, effaçant ce que le tabac jamaïcain gardait de terreux, pour un profil de crème pure, de cèdre léger et de force abordable.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''installation à New York dans les années 1960, sous l''impulsion d''Edgar M. Cullman Sr., transforma une spécialité caribéenne en phénomène américain. Cullman avait compris que le fumeur aisé de l''après-guerre voulait du luxe sans épreuve — un cigare disant le raffinement sans exiger d''expertise ni de tolérance physique. Il repositionna Macanudo autour de capes Connecticut Shade et de tripes dominicaines, effaçant ce que le tabac jamaïcain gardait de terreux, pour un profil de crème pure, de cèdre léger et de force abordable.', 'La suite se raconte en deux versions. Wikipédia écrit qu''en 1971 General Cigar lance une marque Macanudo distincte, mise au point sous la direction de Ramón Cifuentes, ancien de Partagás, mais l''article signale lui-même des passages à préciser. La presse du métier, elle, établit que General Cigar ferme Temple Hall en 2000 et transfère toute la production en République dominicaine ; le tabac jamaïcain quitte ensuite l''assemblage. Edgar M. Cullman Sr., qui dirigea General Cigar pendant des décennies, est mort en août 2011 à 93 ans.'), `history`),
  `history_en` = IF(LOCATE(CAST('The migration to New York in the 1960s under Edgar M. Cullman Sr. transformed Macanudo from a Caribbean specialty into an American phenomenon. Cullman understood that the wealthy American smoker of the postwar decades wanted luxury without challenge — a cigar that communicated refinement without demanding expertise or physical tolerance. He repositioned Macanudo around Connecticut shade wrappers and Dominican fillers, eliminating the Jamaican tobacco''s residual earthiness and producing a profile of pure cream, mild cedar, and approachable strength that no other brand was delivering with the same consistency.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The migration to New York in the 1960s under Edgar M. Cullman Sr. transformed Macanudo from a Caribbean specialty into an American phenomenon. Cullman understood that the wealthy American smoker of the postwar decades wanted luxury without challenge — a cigar that communicated refinement without demanding expertise or physical tolerance. He repositioned Macanudo around Connecticut shade wrappers and Dominican fillers, eliminating the Jamaican tobacco''s residual earthiness and producing a profile of pure cream, mild cedar, and approachable strength that no other brand was delivering with the same consistency.', 'The story then continues in two versions. Wikipedia writes that in 1971 General Cigar launched a distinct Macanudo brand, developed under the direction of Ramón Cifuentes, formerly of Partagás, but the article itself flags passages that need clarifying. The trade press, for its part, establishes that General Cigar closed Temple Hall in 2000 and moved all production to the Dominican Republic; Jamaican tobacco then left the blend. Edgar M. Cullman Sr., who ran General Cigar for decades, died in August 2011 aged 93.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La instalación en Nueva York en los años sesenta, por impulso de Edgar M. Cullman Sr., transformó una especialidad caribeña en fenómeno estadounidense. Cullman había comprendido que el fumador acomodado de la posguerra quería lujo sin prueba —un puro que dijera refinamiento sin exigir pericia ni tolerancia física. Reposicionó Macanudo en torno a capas Connecticut Shade y tripas dominicanas, borrando lo que el tabaco jamaicano conservaba de terroso, hacia un perfil de crema pura, de cedro ligero y de fuerza asequible.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La instalación en Nueva York en los años sesenta, por impulso de Edgar M. Cullman Sr., transformó una especialidad caribeña en fenómeno estadounidense. Cullman había comprendido que el fumador acomodado de la posguerra quería lujo sin prueba —un puro que dijera refinamiento sin exigir pericia ni tolerancia física. Reposicionó Macanudo en torno a capas Connecticut Shade y tripas dominicanas, borrando lo que el tabaco jamaicano conservaba de terroso, hacia un perfil de crema pura, de cedro ligero y de fuerza asequible.', 'La continuación se cuenta en dos versiones. Wikipedia escribe que en 1971 General Cigar lanza una marca Macanudo distinta, puesta a punto bajo la dirección de Ramón Cifuentes, procedente de Partagás, pero el propio artículo señala pasajes por precisar. La prensa del sector, por su parte, establece que General Cigar cierra Temple Hall en 2000 y traslada toda la producción a la República Dominicana; el tabaco jamaicano sale después de la ligada. Edgar M. Cullman Sr., que dirigió General Cigar durante décadas, murió en agosto de 2011 a los 93 años.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Ansiedlung in New York in den sechziger Jahren, auf Betreiben von Edgar M. Cullman Sr., machte aus einer karibischen Spezialität ein amerikanisches Phänomen. Cullman hatte begriffen, dass der wohlhabende Raucher der Nachkriegszeit Luxus ohne Prüfung wollte — eine Zigarre, die Verfeinerung ausspricht, ohne Sachkenntnis oder körperliche Duldsamkeit zu verlangen. Er stellte Macanudo auf Connecticut-Shade-Deckblätter und dominikanische Einlagen um und tilgte, was der jamaikanische Tabak an Erdigkeit behielt, hin zu einem Profil aus reiner Sahne, leichter Zeder und erschwinglicher Stärke.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Ansiedlung in New York in den sechziger Jahren, auf Betreiben von Edgar M. Cullman Sr., machte aus einer karibischen Spezialität ein amerikanisches Phänomen. Cullman hatte begriffen, dass der wohlhabende Raucher der Nachkriegszeit Luxus ohne Prüfung wollte — eine Zigarre, die Verfeinerung ausspricht, ohne Sachkenntnis oder körperliche Duldsamkeit zu verlangen. Er stellte Macanudo auf Connecticut-Shade-Deckblätter und dominikanische Einlagen um und tilgte, was der jamaikanische Tabak an Erdigkeit behielt, hin zu einem Profil aus reiner Sahne, leichter Zeder und erschwinglicher Stärke.', 'Der weitere Verlauf wird in zwei Fassungen erzählt. Wikipedia schreibt, 1971 habe General Cigar eine eigenständige Marke Macanudo eingeführt, entwickelt unter der Leitung von Ramón Cifuentes, der zuvor bei Partagás war, doch der Artikel selbst weist auf klärungsbedürftige Passagen hin. Die Fachpresse hingegen hält fest, dass General Cigar Temple Hall im Jahr 2000 schloss und die gesamte Produktion in die Dominikanische Republik verlegte; der jamaikanische Tabak verschwand danach aus der Mischung. Edgar M. Cullman Sr., der General Cigar jahrzehntelang leitete, starb im August 2011 im Alter von 93 Jahren.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('六十年代，在埃德加·M·卡尔曼的推动下迁往纽约，把一门加勒比特产变成了美国现象。卡尔曼看明白了：战后有钱的烟客要的是不必经受考验的奢侈——一支说出精致、却不要求见识与身体耐受力的雪茄。他把马卡努多重新定位在康涅狄格阴植茄衣与多米尼加茄芯上，抹去牙买加烟草残存的泥土气，走向纯粹的奶油、淡雪松与够得着的力度。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '六十年代，在埃德加·M·卡尔曼的推动下迁往纽约，把一门加勒比特产变成了美国现象。卡尔曼看明白了：战后有钱的烟客要的是不必经受考验的奢侈——一支说出精致、却不要求见识与身体耐受力的雪茄。他把马卡努多重新定位在康涅狄格阴植茄衣与多米尼加茄芯上，抹去牙买加烟草残存的泥土气，走向纯粹的奶油、淡雪松与够得着的力度。', '后续有两种说法。维基百科写道，1971年General Cigar推出了一个独立的Macanudo品牌，由出身Partagás的Ramón Cifuentes主持研发，但该条目本身标注有待厘清的段落。行业媒体则确认，General Cigar于2000年关闭Temple Hall，并将全部生产转移到多米尼加共和国；此后牙买加烟草退出了配方。数十年间执掌General Cigar的Edgar M. Cullman Sr.于2011年8月去世，享年93岁。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وقد حوّل الانتقال إلى نيويورك في الستينيات، بدفع من إدغار م. كولمان الأب، اختصاصًا كاريبيًّا إلى ظاهرة أمريكية. كان كولمان قد فهم أنّ المدخّن الميسور في ما بعد الحرب يريد ترفًا بلا امتحان — سيجارًا يقول الرهافة دون أن يطلب خبرة ولا احتمالًا جسديًّا. فأعاد وضع ماكانودو حول أغلفة كونيتيكت شيد وحشوات دومينيكية، ماحيًا ما احتفظ به التبغ الجامايكي من ترابية، نحو طابع من القشدة الصافية وخشب الأرز الخفيف والقوة في المتناول.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وقد حوّل الانتقال إلى نيويورك في الستينيات، بدفع من إدغار م. كولمان الأب، اختصاصًا كاريبيًّا إلى ظاهرة أمريكية. كان كولمان قد فهم أنّ المدخّن الميسور في ما بعد الحرب يريد ترفًا بلا امتحان — سيجارًا يقول الرهافة دون أن يطلب خبرة ولا احتمالًا جسديًّا. فأعاد وضع ماكانودو حول أغلفة كونيتيكت شيد وحشوات دومينيكية، ماحيًا ما احتفظ به التبغ الجامايكي من ترابية، نحو طابع من القشدة الصافية وخشب الأرز الخفيف والقوة في المتناول.', 'تُروى بقية القصة في روايتين. تكتب ويكيبيديا أنّ General Cigar أطلقت عام 1971 علامة Macanudo مستقلة، طُوّرت بإشراف Ramón Cifuentes، القادم من Partagás، لكنّ المقال نفسه يشير إلى مواضع تحتاج إلى توضيح. أمّا صحافة القطاع فتثبت أنّ General Cigar أغلقت Temple Hall عام 2000 ونقلت الإنتاج كله إلى جمهورية الدومينيكان؛ وخرج التبغ الجامايكي بعد ذلك من الخلطة. وتوفي Edgar M. Cullman Sr.، الذي أدار General Cigar عقودًا، في أغسطس 2011 عن 93 عامًا.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Macanudo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La stratégie dépassa toutes les projections. Dans les années 1980 et 1990, chaque kiosque d''aéroport, chaque boutique d''hôtel, chaque bar de restaurant tenant une carte de cigares proposait la Macanudo Café comme choix premium par défaut. Les bagues jaunes étaient devenues un signe de luxe accessible qui traversait les milieux.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La stratégie dépassa toutes les projections. Dans les années 1980 et 1990, chaque kiosque d''aéroport, chaque boutique d''hôtel, chaque bar de restaurant tenant une carte de cigares proposait la Macanudo Café comme choix premium par défaut. Les bagues jaunes étaient devenues un signe de luxe accessible qui traversait les milieux.', 'La Café reste le visage de la marque : cape Connecticut Shade, liant mexicain de San Andrés, tripe mexicaine et dominicaine (piloto cubano), selon la page de la maison (macanudo.com, lue en octobre 2026). La presse du métier la décrit comme le cigare doux auquel le nom Macanudo est associé.'), `history`),
  `history_en` = IF(LOCATE(CAST('The strategy worked beyond any commercial projection. Through the 1980s and into the 1990s, every airport newsstand, every hotel gift shop, every restaurant bar with a cigar program stocked Macanudo Café as the default premium option. The yellow bands became a signal of accessible luxury that crossed demographic lines.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The strategy worked beyond any commercial projection. Through the 1980s and into the 1990s, every airport newsstand, every hotel gift shop, every restaurant bar with a cigar program stocked Macanudo Café as the default premium option. The yellow bands became a signal of accessible luxury that crossed demographic lines.', 'The Café remains the face of the brand: Connecticut Shade wrapper, Mexican San Andrés binder, Mexican and Dominican filler (piloto cubano), according to the house''s page (macanudo.com, read in October 2026). The trade press describes it as the mild cigar with which the Macanudo name is associated.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La estrategia superó todas las previsiones. En los años ochenta y noventa, cada quiosco de aeropuerto, cada tienda de hotel, cada bar de restaurante con carta de puros ofrecía la Macanudo Café como opción premium por defecto. Las anillas amarillas se habían convertido en un signo de lujo accesible que atravesaba los ambientes.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La estrategia superó todas las previsiones. En los años ochenta y noventa, cada quiosco de aeropuerto, cada tienda de hotel, cada bar de restaurante con carta de puros ofrecía la Macanudo Café como opción premium por defecto. Las anillas amarillas se habían convertido en un signo de lujo accesible que atravesaba los ambientes.', 'La Café sigue siendo el rostro de la marca: capa Connecticut Shade, capote mexicano de San Andrés, tripa mexicana y dominicana (piloto cubano), según la página de la casa (macanudo.com, consultada en octubre de 2026). La prensa del sector la describe como el puro suave al que se asocia el nombre Macanudo.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Strategie übertraf alle Erwartungen. In den achtziger und neunziger Jahren bot jeder Flughafenkiosk, jeder Hotelladen, jede Restaurantbar mit Zigarrenkarte die Macanudo Café als selbstverständliche Premiumwahl an. Die gelben Banderolen waren zu einem Zeichen erschwinglichen Luxus geworden, das quer durch die Milieus ging.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Strategie übertraf alle Erwartungen. In den achtziger und neunziger Jahren bot jeder Flughafenkiosk, jeder Hotelladen, jede Restaurantbar mit Zigarrenkarte die Macanudo Café als selbstverständliche Premiumwahl an. Die gelben Banderolen waren zu einem Zeichen erschwinglichen Luxus geworden, das quer durch die Milieus ging.', 'Die Café bleibt das Gesicht der Marke: Deckblatt Connecticut Shade, mexikanisches Umblatt aus San Andrés, Einlage aus mexikanischem und dominikanischem Tabak (piloto cubano), laut der Seite des Hauses (macanudo.com, im Oktober 2026 abgerufen). Die Fachpresse beschreibt sie als die milde Zigarre, mit der der Name Macanudo verbunden wird.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这套策略超出了所有预期。八十与九十年代，凡有雪茄单的机场书报亭、酒店商店、餐厅酒吧，默认的高端选择都是 Macanudo Café。黄色的烟标成了一种跨越圈层的、可及的奢侈符号。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这套策略超出了所有预期。八十与九十年代，凡有雪茄单的机场书报亭、酒店商店、餐厅酒吧，默认的高端选择都是 Macanudo Café。黄色的烟标成了一种跨越圈层的、可及的奢侈符号。', 'Café仍是这个品牌的门面：茄衣为Connecticut Shade，内包叶来自墨西哥的San Andrés，茄芯为墨西哥与多米尼加烟叶（piloto cubano），依据品牌方的页面（macanudo.com，2026年10月查阅）。行业媒体把它描述为与Macanudo这个名字相连的那支柔和雪茄。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تجاوزت الاستراتيجية كل التوقّعات. ففي الثمانينيات والتسعينيات، كان كل كشك مطار، وكل متجر فندق، وكل بار مطعم يحمل قائمة سيجار، يعرض «ماكانودو كافيه» خيارًا فاخرًا بالتلقاء. وصارت الحلقات الصفراء علامة ترف في المتناول تعبر الأوساط كلها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تجاوزت الاستراتيجية كل التوقّعات. ففي الثمانينيات والتسعينيات، كان كل كشك مطار، وكل متجر فندق، وكل بار مطعم يحمل قائمة سيجار، يعرض «ماكانودو كافيه» خيارًا فاخرًا بالتلقاء. وصارت الحلقات الصفراء علامة ترف في المتناول تعبر الأوساط كلها.', 'تبقى Café وجه العلامة: غلاف Connecticut Shade، ورابط مكسيكي من San Andrés، وحشوة مكسيكية ودومينيكية (piloto cubano)، بحسب صفحة الدار (macanudo.com، اطُّلع عليها في أكتوبر 2026). وتصفها صحافة القطاع بأنها السيجار الناعم الذي يقترن به اسم Macanudo.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Macanudo';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('General Cigar, qui a racheté la marque, a reconnu dans les années 2010 que cette position était devenue autant un handicap qu''un atout. Les fumeurs qui avaient grandi avec la Café étaient désormais assez expérimentés pour vouloir plus exigeant. La gamme Inspirado — assemblages nicaraguayens plus corsés sous des capes de style Connecticut modifiées — fut conçue pour retenir ce public tout en attirant l''amateur plus jeune, qui associait Macanudo à la génération de ses parents. Deux âmes cohabitent désormais : la Café pour la tradition, l''Inspirado pour la suite.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'General Cigar, qui a racheté la marque, a reconnu dans les années 2010 que cette position était devenue autant un handicap qu''un atout. Les fumeurs qui avaient grandi avec la Café étaient désormais assez expérimentés pour vouloir plus exigeant. La gamme Inspirado — assemblages nicaraguayens plus corsés sous des capes de style Connecticut modifiées — fut conçue pour retenir ce public tout en attirant l''amateur plus jeune, qui associait Macanudo à la génération de ses parents. Deux âmes cohabitent désormais : la Café pour la tradition, l''Inspirado pour la suite.', 'Inspirado ouvre une autre voie. Lancée en Europe en 2014, la gamme arrive aux États-Unis en 2016 (Cigar Coop, mai 2016) en déclinaisons de couleur d''origines différentes : Orange roulée au Honduras, Black et White en République dominicaine, Red roulée à Estelí (Nicaragua) en 2018, pour les 50 ans de la marque. La maison présente Inspirado comme ses assemblages les plus complexes et intenses. En 2014, STG décrivait General Cigar comme une filiale à 100 % de Scandinavian Tobacco Group.'), `history`),
  `history_en` = IF(LOCATE(CAST('General Cigar, which acquired the brand, recognized by the 2010s that Macanudo''s extraordinary market position had become a liability as much as an asset. Smokers who had grown up with the Café were now experienced enough to want something more demanding. The Inspirado range — using fuller-bodied Nicaraguan blends under modified Connecticut-style wrappers — was designed to retain this audience while attracting the younger enthusiast who associated Macanudo with their parents'' generation rather than their own. The strategy has produced mixed but largely positive results.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'General Cigar, which acquired the brand, recognized by the 2010s that Macanudo''s extraordinary market position had become a liability as much as an asset. Smokers who had grown up with the Café were now experienced enough to want something more demanding. The Inspirado range — using fuller-bodied Nicaraguan blends under modified Connecticut-style wrappers — was designed to retain this audience while attracting the younger enthusiast who associated Macanudo with their parents'' generation rather than their own. The strategy has produced mixed but largely positive results.', 'Inspirado opens another path. Launched in Europe in 2014, the range reached the United States in 2016 (Cigar Coop, May 2016) in colour variants of different origins: Orange rolled in Honduras, Black and White in the Dominican Republic, Red rolled in Estelí (Nicaragua) in 2018, for the brand''s 50th anniversary. The house presents Inspirado as its most complex and intense blends. In 2014, STG described General Cigar as a 100% subsidiary of Scandinavian Tobacco Group.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('General Cigar, que compró la marca, reconoció en los años dos mil diez que esa posición se había vuelto tanto un lastre como una baza. Los fumadores que habían crecido con la Café eran ya bastante experimentados para querer algo más exigente. La gama Inspirado —ligadas nicaragüenses más recias bajo capas de estilo Connecticut modificadas— se concibió para retener a ese público atrayendo a la vez al aficionado más joven, que asociaba Macanudo a la generación de sus padres. Dos almas conviven desde entonces: la Café para la tradición, la Inspirado para lo que sigue.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'General Cigar, que compró la marca, reconoció en los años dos mil diez que esa posición se había vuelto tanto un lastre como una baza. Los fumadores que habían crecido con la Café eran ya bastante experimentados para querer algo más exigente. La gama Inspirado —ligadas nicaragüenses más recias bajo capas de estilo Connecticut modificadas— se concibió para retener a ese público atrayendo a la vez al aficionado más joven, que asociaba Macanudo a la generación de sus padres. Dos almas conviven desde entonces: la Café para la tradición, la Inspirado para lo que sigue.', 'Inspirado abre otro camino. Lanzada en Europa en 2014, la gama llega a Estados Unidos en 2016 (Cigar Coop, mayo de 2016) en variantes de color de orígenes distintos: Orange, torcida en Honduras; Black y White, en la República Dominicana; Red, torcida en Estelí (Nicaragua) en 2018, por los 50 años de la marca. La casa presenta Inspirado como sus ligadas más complejas e intensas. En 2014, STG describía a General Cigar como una filial al 100 % de Scandinavian Tobacco Group.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('General Cigar, das die Marke übernahm, erkannte in den 2010er Jahren, dass diese Stellung ebenso zur Last wie zum Vorteil geworden war. Die Raucher, die mit der Café groß geworden waren, hatten inzwischen genug Erfahrung, um Anspruchsvolleres zu wollen. Die Linie Inspirado — kräftigere nicaraguanische Mischungen unter abgewandelten Deckblättern im Connecticut-Stil — war gedacht, dieses Publikum zu halten und zugleich den jüngeren Liebhaber zu gewinnen, der Macanudo mit der Generation seiner Eltern verband. Seither wohnen zwei Seelen nebeneinander: die Café für die Überlieferung, die Inspirado für das, was folgt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'General Cigar, das die Marke übernahm, erkannte in den 2010er Jahren, dass diese Stellung ebenso zur Last wie zum Vorteil geworden war. Die Raucher, die mit der Café groß geworden waren, hatten inzwischen genug Erfahrung, um Anspruchsvolleres zu wollen. Die Linie Inspirado — kräftigere nicaraguanische Mischungen unter abgewandelten Deckblättern im Connecticut-Stil — war gedacht, dieses Publikum zu halten und zugleich den jüngeren Liebhaber zu gewinnen, der Macanudo mit der Generation seiner Eltern verband. Seither wohnen zwei Seelen nebeneinander: die Café für die Überlieferung, die Inspirado für das, was folgt.', 'Inspirado schlägt einen anderen Weg ein. 2014 in Europa eingeführt, kommt die Linie 2016 in die Vereinigten Staaten (Cigar Coop, Mai 2016), in Farbvarianten unterschiedlicher Herkunft: Orange, gerollt in Honduras, Black und White in der Dominikanischen Republik, Red, gerollt in Estelí (Nicaragua) 2018, zum 50-jährigen Bestehen der Marke. Das Haus stellt Inspirado als seine komplexesten und intensivsten Mischungen vor. 2014 beschrieb STG General Cigar als hundertprozentige Tochter der Scandinavian Tobacco Group.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('买下品牌的 General Cigar 在二〇一〇年代承认，这个位置既是资产也是包袱。当年跟着 Café 长大的烟客，如今已老练到想要更有难度的东西。Inspirado 系列——更结实的尼加拉瓜配方，配上经过改动的康涅狄格风格茄衣——正是为了留住这批人，同时吸引更年轻的爱好者：在后者眼里，马卡努多是父母那一代的东西。从此两个灵魂并存：Café 承接传统，Inspirado 面向之后。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '买下品牌的 General Cigar 在二〇一〇年代承认，这个位置既是资产也是包袱。当年跟着 Café 长大的烟客，如今已老练到想要更有难度的东西。Inspirado 系列——更结实的尼加拉瓜配方，配上经过改动的康涅狄格风格茄衣——正是为了留住这批人，同时吸引更年轻的爱好者：在后者眼里，马卡努多是父母那一代的东西。从此两个灵魂并存：Café 承接传统，Inspirado 面向之后。', 'Inspirado开辟了另一条路。该系列2014年在欧洲推出，2016年进入美国（Cigar Coop，2016年5月），以产地各异的颜色版本面世：Orange在洪都拉斯卷制，Black与White在多米尼加共和国，Red于2018年在尼加拉瓜的Estelí卷制，为纪念品牌50周年。品牌方将Inspirado称为其复杂度与浓烈度均居首的配方。2014年，STG把General Cigar描述为Scandinavian Tobacco Group的全资子公司。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وقد أقرّت «جنرال سيغار»، التي اشترت العلامة، في عشرينيات القرن الحادي والعشرين بأنّ هذا الموقع صار عبئًا بقدر ما هو ورقة رابحة. فالمدخّنون الذين كبروا مع «كافيه» صاروا من الخبرة بحيث يريدون ما هو أكثر تطلّبًا. ومن هنا جاءت تشكيلة «إنسبيرادو» — خلطات نيكاراغوية أمتن تحت أغلفة معدَّلة على الطراز الكونيتيكتي — للإبقاء على هذا الجمهور واجتذاب الهاوي الأصغر سنًّا الذي يربط ماكانودو بجيل والديه. ومنذ ذلك الحين تتعايش روحان: «كافيه» للتقليد، و«إنسبيرادو» لما يأتي بعده.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وقد أقرّت «جنرال سيغار»، التي اشترت العلامة، في عشرينيات القرن الحادي والعشرين بأنّ هذا الموقع صار عبئًا بقدر ما هو ورقة رابحة. فالمدخّنون الذين كبروا مع «كافيه» صاروا من الخبرة بحيث يريدون ما هو أكثر تطلّبًا. ومن هنا جاءت تشكيلة «إنسبيرادو» — خلطات نيكاراغوية أمتن تحت أغلفة معدَّلة على الطراز الكونيتيكتي — للإبقاء على هذا الجمهور واجتذاب الهاوي الأصغر سنًّا الذي يربط ماكانودو بجيل والديه. ومنذ ذلك الحين تتعايش روحان: «كافيه» للتقليد، و«إنسبيرادو» لما يأتي بعده.', 'تفتح Inspirado طريقًا آخر. أُطلقت التشكيلة في أوروبا عام 2014، ووصلت إلى الولايات المتحدة عام 2016 (Cigar Coop، مايو 2016) بإصدارات لونية مختلفة المنشأ: Orange ملفوفة في هندوراس، وBlack وWhite في جمهورية الدومينيكان، وRed ملفوفة في Estelí (نيكاراغوا) عام 2018، في الذكرى الخمسين للعلامة. وتقدّم الدار Inspirado بوصفها أرفع خلطاتها تعقيدًا وشدّة. وفي عام 2014 وصفت STG شركة General Cigar بأنها شركة تابعة مملوكة بالكامل لمجموعة Scandinavian Tobacco Group.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Macanudo';

UPDATE `brands` SET
  `limited_eds` = '["Macanudo Estate Reserve Release No. 1","Macanudo Estate Reserve Release No. 2","Macanudo Estate Reserve Release No. 3","Macanudo Vintage 1997"]',
  `founded` = 'Jamaïque ; repris par General Cigar en 1968',
  `factory` = 'République dominicaine (General Cigar Dominicana, Santiago) pour la Café ; Inspirado Orange au Honduras (HATSA), Inspirado Red à Estelí, Nicaragua (STG Estelí)',
  `gamme` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Mild","story":"Cape Connecticut Shade, liant mexicain de San Andrés, tripe mexicaine et dominicaine (piloto cubano), selon la page de la maison. Moelleuse ; notes sucrées, crémeuses, de noisette et de bois. La maison suggère une brown ale ou un café. Vingt et un formats au catalogue, de Miniatures (3,75 x 24 po) à Prince of Wales (8 x 52 po).","vitolas":["Café","Ascot","Baron de Rothschild","Hampton Court","Hyde Park","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"Inspirado","color":"#8B2500","force":null,"story":"Lancée en Europe en 2014, aux États-Unis en 2016. Déclinaisons de couleur d''origines variées : Orange (Honduras), Black et White (République dominicaine), Red (Estelí, Nicaragua, 2018, cape Habano ligero d''Équateur), puis Green, Jamao, Tercio-Aged et Brazilian Shade selon la maison.","vitolas":["Robusto","Toro","Churchill","Torpedo","White Robusto"],"wrapper":"Selon la déclinaison"},{"name":"Gold Label","color":"#DAA520","force":"Mild","story":"Cape Connecticut Golden Shade issue des premier et deuxième primings (Capa Especial), liant mexicain de San Andrés, tripe mexicaine et dominicaine (piloto cubano). La maison la décrit comme une ligne en édition limitée, moelleuse, aux notes crémeuses et d''amande ; elle suggère un café ou une IPA.","vitolas":["No.1","Corona","Prince of Wales","Robusto","Toro"],"wrapper":"Connecticut Golden Shade"}]',
  `gamme_en` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Mild","story":"Connecticut Shade wrapper, Mexican San Andrés binder, Mexican and Dominican filler (piloto cubano), according to the house''s page. Smooth; sweet, creamy notes, with hazelnut and wood. The house suggests a brown ale or a coffee. Twenty-one formats in the catalogue, from Miniatures (3.75 x 24 in) to Prince of Wales (8 x 52 in).","vitolas":["Café","Ascot","Baron de Rothschild","Hampton Court","Hyde Park","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"Inspirado","color":"#8B2500","force":null,"story":"Launched in Europe in 2014, in the United States in 2016. Colour variants of varied origins: Orange (Honduras), Black and White (Dominican Republic), Red (Estelí, Nicaragua, 2018, Ecuadorian ligero Habano wrapper), then Green, Jamao, Tercio-Aged and Brazilian Shade, according to the house.","vitolas":["Robusto","Toro","Churchill","Torpedo","White Robusto"],"wrapper":"Varies by variant"},{"name":"Gold Label","color":"#DAA520","force":"Mild","story":"Connecticut Golden Shade wrapper from the first and second primings (Capa Especial), Mexican San Andrés binder, Mexican and Dominican filler (piloto cubano). The house describes it as a limited-edition line, smooth, with creamy and almond notes; it suggests a coffee or an IPA.","vitolas":["No.1","Corona","Prince of Wales","Robusto","Toro"],"wrapper":"Connecticut Golden Shade"}]',
  `gamme_es` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Mild","story":"Capa Connecticut Shade, capote mexicano de San Andrés, tripa mexicana y dominicana (piloto cubano), según la página de la casa. Suave; notas dulces, cremosas, de avellana y de madera. La casa sugiere una brown ale o un café. Veintiún formatos en el catálogo, de Miniatures (3,75 x 24 pulg.) a Prince of Wales (8 x 52 pulg.).","vitolas":["Café","Ascot","Baron de Rothschild","Hampton Court","Hyde Park","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"Inspirado","color":"#8B2500","force":null,"story":"Lanzada en Europa en 2014 y en Estados Unidos en 2016. Variantes de color de orígenes diversos: Orange (Honduras), Black y White (República Dominicana), Red (Estelí, Nicaragua, 2018, capa Habano ligero de Ecuador), y luego Green, Jamao, Tercio-Aged y Brazilian Shade, según la casa.","vitolas":["Robusto","Toro","Churchill","Torpedo","White Robusto"],"wrapper":"Según la variante"},{"name":"Gold Label","color":"#DAA520","force":"Mild","story":"Capa Connecticut Golden Shade procedente del primer y segundo priming (Capa Especial), capote mexicano de San Andrés, tripa mexicana y dominicana (piloto cubano). La casa la describe como una línea de edición limitada, suave, con notas cremosas y de almendra; sugiere un café o una IPA.","vitolas":["No.1","Corona","Prince of Wales","Robusto","Toro"],"wrapper":"Connecticut Golden Shade"}]',
  `gamme_de` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Mild","story":"Deckblatt Connecticut Shade, mexikanisches Umblatt aus San Andrés, Einlage aus mexikanischem und dominikanischem Tabak (piloto cubano), laut der Seite des Hauses. Weich; süße, cremige Noten sowie Haselnuss und Holz. Das Haus empfiehlt ein Brown Ale oder einen Kaffee. Einundzwanzig Formate im Katalog, von Miniatures (3,75 x 24 Zoll) bis Prince of Wales (8 x 52 Zoll).","vitolas":["Café","Ascot","Baron de Rothschild","Hampton Court","Hyde Park","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"Inspirado","color":"#8B2500","force":null,"story":"In Europa 2014 eingeführt, in den Vereinigten Staaten 2016. Farbvarianten unterschiedlicher Herkunft: Orange (Honduras), Black und White (Dominikanische Republik), Red (Estelí, Nicaragua, 2018, Deckblatt Habano ligero aus Ecuador), dann Green, Jamao, Tercio-Aged und Brazilian Shade laut dem Haus.","vitolas":["Robusto","Toro","Churchill","Torpedo","White Robusto"],"wrapper":"Je nach Variante"},{"name":"Gold Label","color":"#DAA520","force":"Mild","story":"Deckblatt Connecticut Golden Shade aus dem ersten und zweiten Priming (Capa Especial), mexikanisches Umblatt aus San Andrés, Einlage aus mexikanischem und dominikanischem Tabak (piloto cubano). Das Haus beschreibt sie als limitierte Linie, weich, mit cremigen und Mandelnoten; es empfiehlt einen Kaffee oder ein IPA.","vitolas":["No.1","Corona","Prince of Wales","Robusto","Toro"],"wrapper":"Connecticut Golden Shade"}]',
  `gamme_zh` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Mild","story":"茄衣为Connecticut Shade，内包叶来自墨西哥的San Andrés，茄芯为墨西哥与多米尼加烟叶（piloto cubano），依据品牌方的页面。口感圆润；带有甜香、奶油感、榛子与木质气息。品牌方建议搭配brown ale或咖啡。目录中共有二十一种规格，从Miniatures（3.75 x 24英寸）到Prince of Wales（8 x 52英寸）。","vitolas":["Café","Ascot","Baron de Rothschild","Hampton Court","Hyde Park","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"Inspirado","color":"#8B2500","force":null,"story":"2014年在欧洲推出，2016年进入美国。颜色版本产地各异：Orange（洪都拉斯）、Black与White（多米尼加共和国）、Red（尼加拉瓜Estelí，2018年，厄瓜多尔Habano ligero茄衣），随后据品牌方还有Green、Jamao、Tercio-Aged和Brazilian Shade。","vitolas":["Robusto","Toro","Churchill","Torpedo","White Robusto"],"wrapper":"视版本而定"},{"name":"Gold Label","color":"#DAA520","force":"Mild","story":"茄衣为Connecticut Golden Shade，取自首次与第二次采摘（priming）（Capa Especial），内包叶来自墨西哥的San Andrés，茄芯为墨西哥与多米尼加烟叶（piloto cubano）。品牌方把它描述为限量版系列，口感圆润，带有奶油与杏仁气息；并建议搭配咖啡或IPA。","vitolas":["No.1","Corona","Prince of Wales","Robusto","Toro"],"wrapper":"Connecticut Golden Shade"}]',
  `gamme_ar` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Mild","story":"غلاف Connecticut Shade، ورابط مكسيكي من San Andrés، وحشوة مكسيكية ودومينيكية (piloto cubano)، بحسب صفحة الدار. ناعمة المذاق؛ نفحات حلوة وقشدية ومن البندق والخشب. وتقترح الدار brown ale أو قهوة. واحد وعشرون قياسًا في الكتالوج، من Miniatures (3.75 × 24 بوصة) إلى Prince of Wales (8 × 52 بوصة).","vitolas":["Café","Ascot","Baron de Rothschild","Hampton Court","Hyde Park","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"Inspirado","color":"#8B2500","force":null,"story":"أُطلقت في أوروبا عام 2014 وفي الولايات المتحدة عام 2016. إصدارات لونية متنوعة المنشأ: Orange (هندوراس)، وBlack وWhite (جمهورية الدومينيكان)، وRed (Estelí، نيكاراغوا، 2018، غلاف Habano ligero من الإكوادور)، ثم Green وJamao وTercio-Aged وBrazilian Shade بحسب الدار.","vitolas":["Robusto","Toro","Churchill","Torpedo","White Robusto"],"wrapper":"بحسب الإصدار"},{"name":"Gold Label","color":"#DAA520","force":"Mild","story":"غلاف Connecticut Golden Shade من القطفة الأولى والثانية (priming، Capa Especial)، ورابط مكسيكي من San Andrés، وحشوة مكسيكية ودومينيكية (piloto cubano). تصفها الدار بأنها خط بإصدار محدود، ناعم، بنفحات قشدية ولوزية؛ وتقترح قهوة أو IPA.","vitolas":["No.1","Corona","Prince of Wales","Robusto","Toro"],"wrapper":"Connecticut Golden Shade"}]',
  `celebrities` = '[{"name":"Edgar M. Cullman Sr.","anecdote":"Dirigeant de General Cigar pendant des décennies, mort en août 2011 à 93 ans selon la presse du métier. Les dates exactes de ses fonctions diffèrent d''une source à l''autre."}]',
  `celebrities_en` = '[{"name":"Edgar M. Cullman Sr.","anecdote":"Head of General Cigar for decades; died in August 2011 aged 93, according to the trade press. The exact dates of his tenure differ from one source to another."}]',
  `celebrities_es` = '[{"name":"Edgar M. Cullman Sr.","anecdote":"Dirigente de General Cigar durante décadas, murió en agosto de 2011 a los 93 años según la prensa del sector. Las fechas exactas de sus funciones difieren de una fuente a otra."}]',
  `celebrities_de` = '[{"name":"Edgar M. Cullman Sr.","anecdote":"Jahrzehntelang Leiter von General Cigar, laut der Fachpresse im August 2011 im Alter von 93 Jahren gestorben. Die genauen Daten seiner Amtszeit weichen je nach Quelle voneinander ab."}]',
  `celebrities_zh` = '[{"name":"Edgar M. Cullman Sr.","anecdote":"数十年间执掌General Cigar，据行业媒体，于2011年8月去世，享年93岁。关于他任职的确切年份，各来源说法不一。"}]',
  `celebrities_ar` = '[{"name":"Edgar M. Cullman Sr.","anecdote":"أدار General Cigar عقودًا، وتوفي في أغسطس 2011 عن 93 عامًا بحسب صحافة القطاع. وتختلف التواريخ الدقيقة لتوليه مهامه من مصدر إلى آخر."}]',
  `pairings` = '[{"type":"Café","name":"Café noir","notes":"La maison le suggère pour la Café et pour la Gold Label (macanudo.com, lue en octobre 2026)."},{"type":"Bière","name":"Brown ale","notes":"Suggérée par la maison pour la Café."},{"type":"Bière","name":"IPA","notes":"Suggérée par la maison pour la Gold Label."}]',
  `pairings_en` = '[{"type":"Coffee","name":"Black coffee","notes":"The house suggests it for the Café and for the Gold Label (macanudo.com, read in October 2026)."},{"type":"Beer","name":"Brown ale","notes":"Suggested by the house for the Café."},{"type":"Beer","name":"IPA","notes":"Suggested by the house for the Gold Label."}]',
  `pairings_es` = '[{"type":"Café","name":"Café solo","notes":"La casa lo sugiere para la Café y para la Gold Label (macanudo.com, consultado en octubre de 2026)."},{"type":"Cerveza","name":"Brown ale","notes":"Sugerida por la casa para la Café."},{"type":"Cerveza","name":"IPA","notes":"Sugerida por la casa para la Gold Label."}]',
  `pairings_de` = '[{"type":"Kaffee","name":"Schwarzer Kaffee","notes":"Das Haus empfiehlt ihn zur Café und zur Gold Label (macanudo.com, im Oktober 2026 abgerufen)."},{"type":"Bier","name":"Brown Ale","notes":"Vom Haus zur Café empfohlen."},{"type":"Bier","name":"IPA","notes":"Vom Haus zur Gold Label empfohlen."}]',
  `pairings_zh` = '[{"type":"咖啡","name":"黑咖啡","notes":"品牌方建议搭配Café与Gold Label（macanudo.com，2026年10月查阅）。"},{"type":"啤酒","name":"Brown ale","notes":"品牌方建议搭配Café。"},{"type":"啤酒","name":"IPA","notes":"品牌方建议搭配Gold Label。"}]',
  `pairings_ar` = '[{"type":"القهوة","name":"قهوة سوداء","notes":"تقترحها الدار مع Café ومع Gold Label (macanudo.com، اطُّلع عليه في أكتوبر 2026)."},{"type":"البيرة","name":"Brown ale","notes":"تقترحها الدار مع Café."},{"type":"البيرة","name":"IPA","notes":"تقترحها الدار مع Gold Label."}]',
  `source` = IF(LOCATE(CAST('en.wikipedia.org (Macanudo) ; cigaraficionado.com « Tobacco Man » (General Cigar Dominicana, Santiago)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'en.wikipedia.org (Macanudo) ; cigaraficionado.com « Tobacco Man » (General Cigar Dominicana, Santiago)', 'macanudo.com « Macanudo Café », « Gold Label », « Inspirado », « Macanudo 1968 », Legacy (pages lues en octobre 2026) ; cigaraficionado.com « Macanudo returns to Jamaican roots » (2000 : fermeture de Temple Hall) ; cigaraficionado.com « Macanudo celebrates 50th anniversary with Inspirado Red » (2018 : rachat de 1968) ; cigarjournal.com « Macanudo celebrates its golden anniversary » (2018) ; cigar-coop.com « General Cigar brings Macanudo Inspirado to U.S. market » (2016-05-02) et « Macanudo Inspirado Red coming in March » (2018-02) ; st-group.com communiqué sur les marques Toraño (2014 : General Cigar filiale à 100 % de STG) ; en.wikipedia.org « Macanudo (cigar) » (version 1971, passages à préciser)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Macanudo';

-- ── Zino Platinum ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le nom Zino est indissociable d''une figure humaine : Zino Davidoff lui-même, né à Kiev en 1906, mort à Genève en 1994. Lorsque le groupe Davidoff décida de ressusciter son prénom comme marque à part entière en 2002, il prit un pari sur la force symbolique d''un nom qui avait défini le luxe tabac européen pendant un demi-siècle.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le nom Zino est indissociable d''une figure humaine : Zino Davidoff lui-même, né à Kiev en 1906, mort à Genève en 1994. Lorsque le groupe Davidoff décida de ressusciter son prénom comme marque à part entière en 2002, il prit un pari sur la force symbolique d''un nom qui avait défini le luxe tabac européen pendant un demi-siècle.', 'Le nom Zino est le prénom de Zino Davidoff lui-même. Selon le site de la marque (zino.oettingerdavidoff.com), il lança en 1978, avec le Dr Ernst Schneider, une marque à son prénom ; les premiers cigares furent roulés au Honduras, du temps de l''embargo américain sur Cuba, pour un marché américain qui n''avait plus accès au tabac cubain.'), `history`),
  `history_en` = IF(LOCATE(CAST('The name Zino is inseparable from a human figure: Zino Davidoff himself, born in Kiev in 1906, died in Geneva in 1994. When the Davidoff Group decided to resurrect his first name as a standalone brand in 2002, it bet on the symbolic force of a name that had defined European tobacco luxury for half a century.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The name Zino is inseparable from a human figure: Zino Davidoff himself, born in Kiev in 1906, died in Geneva in 1994. When the Davidoff Group decided to resurrect his first name as a standalone brand in 2002, it bet on the symbolic force of a name that had defined European tobacco luxury for half a century.', 'The name Zino is the first name of Zino Davidoff himself. According to the brand''s website (zino.oettingerdavidoff.com), in 1978, together with Dr Ernst Schneider, he launched a brand named after his first name; the first cigars were rolled in Honduras, at the time of the American embargo on Cuba, for an American market that no longer had access to Cuban tobacco.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El nombre Zino es inseparable de una figura humana: el propio Zino Davidoff, nacido en Kiev en 1906 y fallecido en Ginebra en 1994. Cuando el grupo Davidoff decidió resucitar su nombre de pila como marca autónoma en 2002, apostó por la fuerza simbólica de un nombre que había definido el lujo del tabaco europeo durante medio siglo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El nombre Zino es inseparable de una figura humana: el propio Zino Davidoff, nacido en Kiev en 1906 y fallecido en Ginebra en 1994. Cuando el grupo Davidoff decidió resucitar su nombre de pila como marca autónoma en 2002, apostó por la fuerza simbólica de un nombre que había definido el lujo del tabaco europeo durante medio siglo.', 'El nombre Zino es el nombre de pila del propio Zino Davidoff. Según el sitio de la marca (zino.oettingerdavidoff.com), en 1978 lanzó, con el Dr. Ernst Schneider, una marca con su nombre de pila; los primeros puros se torcieron en Honduras, en tiempos del embargo estadounidense a Cuba, para un mercado estadounidense que ya no tenía acceso al tabaco cubano.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der Name Zino ist untrennbar mit einem Menschen verbunden: mit Zino Davidoff selbst, 1906 in Kiew geboren, 1994 in Genf gestorben. Als die Davidoff-Gruppe 2002 beschloss, seinen Vornamen als eigenständige Marke wiederzubeleben, setzte sie auf die sinnbildliche Kraft eines Namens, der den europäischen Tabakluxus ein halbes Jahrhundert lang bestimmt hatte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der Name Zino ist untrennbar mit einem Menschen verbunden: mit Zino Davidoff selbst, 1906 in Kiew geboren, 1994 in Genf gestorben. Als die Davidoff-Gruppe 2002 beschloss, seinen Vornamen als eigenständige Marke wiederzubeleben, setzte sie auf die sinnbildliche Kraft eines Namens, der den europäischen Tabakluxus ein halbes Jahrhundert lang bestimmt hatte.', 'Der Name Zino ist der Vorname von Zino Davidoff selbst. Laut der Website der Marke (zino.oettingerdavidoff.com) gründete er 1978 gemeinsam mit Dr. Ernst Schneider eine Marke unter seinem Vornamen; die ersten Zigarren wurden in Honduras gerollt, zur Zeit des amerikanischen Embargos gegen Kuba, für einen amerikanischen Markt, der keinen Zugang mehr zu kubanischem Tabak hatte.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Zino 这个名字与一个真实的人密不可分：Zino Davidoff 本人，1906 年生于基辅，1994 年逝于日内瓦。2002 年，Davidoff 集团决定让他的名字复活为一个独立品牌，赌的正是这个名字的象征力量——半个世纪以来，它定义了欧洲的烟草奢华。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Zino 这个名字与一个真实的人密不可分：Zino Davidoff 本人，1906 年生于基辅，1994 年逝于日内瓦。2002 年，Davidoff 集团决定让他的名字复活为一个独立品牌，赌的正是这个名字的象征力量——半个世纪以来，它定义了欧洲的烟草奢华。', 'Zino这个名字就是Zino Davidoff本人的名字。据品牌网站（zino.oettingerdavidoff.com），他于1978年与Ernst Schneider博士一道，推出了一个以自己名字命名的品牌；首批雪茄在洪都拉斯卷制，当时正值美国对古巴实行禁运，面向的是已无法获得古巴烟草的美国市场。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('اسم Zino لا ينفصل عن شخص بعينه: Zino Davidoff نفسه، المولود في كييف عام 1906 والمتوفّى في جنيف عام 1994. وحين قرّرت مجموعة Davidoff عام 2002 أن تبعث اسمه الأول علامةً قائمة بذاتها، راهنت على القوة الرمزية لاسم ظلّ نصف قرن يحدّد معنى الترف التبغي في أوروبا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'اسم Zino لا ينفصل عن شخص بعينه: Zino Davidoff نفسه، المولود في كييف عام 1906 والمتوفّى في جنيف عام 1994. وحين قرّرت مجموعة Davidoff عام 2002 أن تبعث اسمه الأول علامةً قائمة بذاتها، راهنت على القوة الرمزية لاسم ظلّ نصف قرن يحدّد معنى الترف التبغي في أوروبا.', 'اسم Zino هو الاسم الأول لـZino Davidoff نفسه. وبحسب موقع العلامة (zino.oettingerdavidoff.com)، أطلق عام 1978، مع الدكتور Ernst Schneider، علامة تحمل اسمه الأول؛ وكانت أولى السيجارات تُلفّ في هندوراس، في زمن الحظر الأمريكي على كوبا، لسوق أمريكية لم يعد لها منفذ إلى التبغ الكوبي.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Zino Platinum';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La première incarnation de Zino avait été distincte : dans les années 1980, Zino Davidoff créa sous son prénom une gamme de cigares de niche, fabriqués au Honduras, disponibles uniquement dans quelques adresses triées du monde. Ces Zinos originaux avaient une réputation d''excellence artisanale réservée aux initiés. À la mort de Zino Davidoff, la gamme fut graduellement absorbée dans la marque-mère Davidoff.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La première incarnation de Zino avait été distincte : dans les années 1980, Zino Davidoff créa sous son prénom une gamme de cigares de niche, fabriqués au Honduras, disponibles uniquement dans quelques adresses triées du monde. Ces Zinos originaux avaient une réputation d''excellence artisanale réservée aux initiés. À la mort de Zino Davidoff, la gamme fut graduellement absorbée dans la marque-mère Davidoff.', 'Toujours selon la maison, la production passa ensuite par plusieurs régions de culture : la République dominicaine, le Honduras et le Nicaragua.'), `history`),
  `history_en` = IF(LOCATE(CAST('The first incarnation of Zino had been distinct: in the 1980s, Zino Davidoff created under his first name a niche range of cigars, manufactured in Honduras, available only at a handful of carefully selected addresses worldwide. These original Zinos had a reputation for artisanal excellence reserved for insiders. Upon Zino Davidoff''s death, the range was gradually absorbed into the parent Davidoff brand.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The first incarnation of Zino had been distinct: in the 1980s, Zino Davidoff created under his first name a niche range of cigars, manufactured in Honduras, available only at a handful of carefully selected addresses worldwide. These original Zinos had a reputation for artisanal excellence reserved for insiders. Upon Zino Davidoff''s death, the range was gradually absorbed into the parent Davidoff brand.', 'Again according to the house, production then passed through several growing regions: the Dominican Republic, Honduras and Nicaragua.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La primera encarnación de Zino había sido distinta: en los años ochenta, Zino Davidoff creó bajo su nombre de pila una gama de puros de nicho, fabricados en Honduras y disponibles solo en unas pocas direcciones escogidas del mundo. Aquellos Zino originales tenían fama de excelencia artesanal reservada a los iniciados. A la muerte de Zino Davidoff, la gama fue absorbida poco a poco por la marca matriz Davidoff.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La primera encarnación de Zino había sido distinta: en los años ochenta, Zino Davidoff creó bajo su nombre de pila una gama de puros de nicho, fabricados en Honduras y disponibles solo en unas pocas direcciones escogidas del mundo. Aquellos Zino originales tenían fama de excelencia artesanal reservada a los iniciados. A la muerte de Zino Davidoff, la gama fue absorbida poco a poco por la marca matriz Davidoff.', 'Siempre según la casa, la producción pasó después por varias regiones de cultivo: la República Dominicana, Honduras y Nicaragua.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die erste Gestalt von Zino war eine andere gewesen: In den 1980er Jahren schuf Zino Davidoff unter seinem Vornamen eine Nischenlinie von Zigarren, in Honduras gefertigt und nur an einigen wenigen ausgesuchten Adressen der Welt erhältlich. Diese ursprünglichen Zinos galten unter Eingeweihten als Inbegriff handwerklicher Vollendung. Nach dem Tod Zino Davidoffs ging die Linie nach und nach in der Dachmarke Davidoff auf.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die erste Gestalt von Zino war eine andere gewesen: In den 1980er Jahren schuf Zino Davidoff unter seinem Vornamen eine Nischenlinie von Zigarren, in Honduras gefertigt und nur an einigen wenigen ausgesuchten Adressen der Welt erhältlich. Diese ursprünglichen Zinos galten unter Eingeweihten als Inbegriff handwerklicher Vollendung. Nach dem Tod Zino Davidoffs ging die Linie nach und nach in der Dachmarke Davidoff auf.', 'Ebenfalls laut dem Haus durchlief die Produktion danach mehrere Anbauregionen: die Dominikanische Republik, Honduras und Nicaragua.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Zino 的第一次登场是另一副模样：1980 年代，Zino Davidoff 以自己的名字创立了一条小众雪茄线，在洪都拉斯生产，全世界只有寥寥数处精选店铺有售。这些最初的 Zino 在圈内人中享有工艺卓绝的口碑。Zino Davidoff 去世后，该系列逐渐被母品牌 Davidoff 吸收。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Zino 的第一次登场是另一副模样：1980 年代，Zino Davidoff 以自己的名字创立了一条小众雪茄线，在洪都拉斯生产，全世界只有寥寥数处精选店铺有售。这些最初的 Zino 在圈内人中享有工艺卓绝的口碑。Zino Davidoff 去世后，该系列逐渐被母品牌 Davidoff 吸收。', '同样据品牌方，生产随后辗转于多个种植地区：多米尼加共和国、洪都拉斯和尼加拉瓜。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('كان ظهور Zino الأول مختلفاً: ففي الثمانينيات أنشأ Zino Davidoff تحت اسمه الأول تشكيلة سيجار محدودة الانتشار، تُصنع في هندوراس ولا تُباع إلا في عناوين قليلة منتقاة حول العالم. وكانت تلك الـ Zino الأولى تحظى بسمعة إتقان حرفي لا يعرفها إلا الخاصّة. وبعد وفاة Zino Davidoff، ذابت التشكيلة تدريجياً في العلامة الأم Davidoff.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'كان ظهور Zino الأول مختلفاً: ففي الثمانينيات أنشأ Zino Davidoff تحت اسمه الأول تشكيلة سيجار محدودة الانتشار، تُصنع في هندوراس ولا تُباع إلا في عناوين قليلة منتقاة حول العالم. وكانت تلك الـ Zino الأولى تحظى بسمعة إتقان حرفي لا يعرفها إلا الخاصّة. وبعد وفاة Zino Davidoff، ذابت التشكيلة تدريجياً في العلامة الأم Davidoff.', 'وبحسب الدار أيضًا، مرّ الإنتاج بعد ذلك بعدة مناطق زراعة: جمهورية الدومينيكان وهندوراس ونيكاراغوا.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Zino Platinum';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La relance sous le nom Zino Platinum en 2002 chercha à capturer cet héritage de niche. Positionnée délibérément plus haut que le Davidoff standard et plus accessiblement que les éditions limitées, Zino Platinum occupe un espace entre la sophistication suisse du Davidoff et le luxe ultrapremium des collections rares.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La relance sous le nom Zino Platinum en 2002 chercha à capturer cet héritage de niche. Positionnée délibérément plus haut que le Davidoff standard et plus accessiblement que les éditions limitées, Zino Platinum occupe un espace entre la sophistication suisse du Davidoff et le luxe ultrapremium des collections rares.', 'La ligne premium Zino Platinum, avec les séries Crown et Scepter, fut lancée dans le monde en 2003 (site de la marque). Cigar Coop la décrit comme visant le jeune marché né du boom des années 1990. Ses capes sont équatoriennes selon les fiches de la presse du métier et de détaillants ; la Z-Class (mai 2011) associe, selon Cigar Coop, une cape dominicaine, un liant péruvien et une tripe de ligeros nicaraguayens et honduriens. À partir de 2013, une série d''éditions de collection à habillage d''art urbain (New York, Los Angeles, Texas) a prolongé la ligne.'), `history`),
  `history_en` = IF(LOCATE(CAST('The relaunch under the name Zino Platinum in 2002 sought to capture this niche heritage. Positioned deliberately higher than standard Davidoff and more accessibly than limited editions, Zino Platinum occupies a space between the Swiss sophistication of Davidoff and the ultra-premium luxury of rare collections.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The relaunch under the name Zino Platinum in 2002 sought to capture this niche heritage. Positioned deliberately higher than standard Davidoff and more accessibly than limited editions, Zino Platinum occupies a space between the Swiss sophistication of Davidoff and the ultra-premium luxury of rare collections.', 'The premium line Zino Platinum, with the Crown and Scepter series, was launched worldwide in 2003 (brand website). Cigar Coop describes it as aimed at the young market born of the boom of the 1990s. Its wrappers are Ecuadorian according to trade-press and retailer listings; the Z-Class (May 2011) combines, according to Cigar Coop, a Dominican wrapper, a Peruvian binder and a filler of Nicaraguan and Honduran ligeros. From 2013, a series of collector''s editions with urban-art packaging (New York, Los Angeles, Texas) extended the line.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El relanzamiento con el nombre Zino Platinum en 2002 buscó recoger esa herencia de nicho. Situada deliberadamente por encima del Davidoff estándar y de forma más accesible que las ediciones limitadas, Zino Platinum ocupa un espacio entre la sofisticación suiza de Davidoff y el lujo ultrapremium de las colecciones raras.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El relanzamiento con el nombre Zino Platinum en 2002 buscó recoger esa herencia de nicho. Situada deliberadamente por encima del Davidoff estándar y de forma más accesible que las ediciones limitadas, Zino Platinum ocupa un espacio entre la sofisticación suiza de Davidoff y el lujo ultrapremium de las colecciones raras.', 'La línea premium Zino Platinum, con las series Crown y Scepter, se lanzó en todo el mundo en 2003 (sitio de la marca). Cigar Coop la describe como dirigida al joven mercado nacido del auge de los años noventa. Sus capas son ecuatorianas según las fichas de la prensa del sector y de minoristas; la Z-Class (mayo de 2011) asocia, según Cigar Coop, una capa dominicana, una capote peruana y una tripa de ligeros nicaragüenses y hondureños. A partir de 2013, una serie de ediciones de colección con envoltorio de arte urbano (Nueva York, Los Ángeles, Texas) prolongó la línea.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Wiederbelebung unter dem Namen Zino Platinum im Jahr 2002 wollte dieses Nischenerbe einfangen. Bewusst über dem Standard-Davidoff und unterhalb der limitierten Editionen angesiedelt, besetzt Zino Platinum einen Platz zwischen der schweizerischen Feinheit Davidoffs und dem Ultrapremium-Luxus der seltenen Kollektionen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Wiederbelebung unter dem Namen Zino Platinum im Jahr 2002 wollte dieses Nischenerbe einfangen. Bewusst über dem Standard-Davidoff und unterhalb der limitierten Editionen angesiedelt, besetzt Zino Platinum einen Platz zwischen der schweizerischen Feinheit Davidoffs und dem Ultrapremium-Luxus der seltenen Kollektionen.', 'Die Premiumlinie Zino Platinum mit den Serien Crown und Scepter wurde 2003 weltweit eingeführt (Website der Marke). Cigar Coop beschreibt sie als auf den jungen Markt gerichtet, der aus dem Boom der 1990er-Jahre hervorging. Ihre Deckblätter sind laut den Produktseiten der Fachpresse und von Händlern ecuadorianisch; die Z-Class (Mai 2011) verbindet laut Cigar Coop ein dominikanisches Deckblatt, ein peruanisches Umblatt und eine Einlage aus nicaraguanischen und honduranischen Ligeros. Ab 2013 setzte eine Reihe von Sammlereditionen mit Street-Art-Aufmachung (New York, Los Angeles, Texas) die Linie fort.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('2002 年以 Zino Platinum 之名重启，正是想承接这份小众遗产。它被刻意置于标准 Davidoff 之上、限量版之下，占据了瑞士式 Davidoff 精致与稀有藏品超高端奢华之间的位置。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '2002 年以 Zino Platinum 之名重启，正是想承接这份小众遗产。它被刻意置于标准 Davidoff 之上、限量版之下，占据了瑞士式 Davidoff 精致与稀有藏品超高端奢华之间的位置。', '高端系列Zino Platinum包含Crown与Scepter两个系列，2003年在全球推出（品牌网站）。Cigar Coop称其面向由1990年代热潮催生的年轻市场。据行业媒体和零售商的资料页，其茄衣产自厄瓜多尔；Z-Class（2011年5月）据Cigar Coop所述，搭配多米尼加茄衣、秘鲁内包叶，以及尼加拉瓜与洪都拉斯ligero烟叶组成的茄芯。自2013年起，一系列采用城市艺术外观设计的收藏版（纽约、洛杉矶、德克萨斯）延展了这条产品线。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وسعى الإطلاق الجديد باسم Zino Platinum عام 2002 إلى استعادة هذا الإرث الخاص. وإذ وُضعت عمداً فوق Davidoff القياسية وفي متناول أوسع من الإصدارات المحدودة، تشغل Zino Platinum مساحة بين الرهافة السويسرية لـ Davidoff وترف المجموعات النادرة فائق الفخامة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وسعى الإطلاق الجديد باسم Zino Platinum عام 2002 إلى استعادة هذا الإرث الخاص. وإذ وُضعت عمداً فوق Davidoff القياسية وفي متناول أوسع من الإصدارات المحدودة، تشغل Zino Platinum مساحة بين الرهافة السويسرية لـ Davidoff وترف المجموعات النادرة فائق الفخامة.', 'أُطلق خط Zino Platinum الفاخر، بسلسلتيه Crown وScepter، في العالم عام 2003 (موقع العلامة). ويصفه Cigar Coop بأنه موجَّه إلى السوق الشابة التي وُلدت من طفرة التسعينيات. وأغلفته إكوادورية بحسب بطاقات صحافة القطاع وتجّار التجزئة؛ أما Z-Class (مايو 2011) فتجمع، بحسب Cigar Coop، غلافًا دومينيكيًا ورابطًا بيروفيًا وحشوة من ligeros نيكاراغوية وهندوراسية. ومنذ عام 2013 مدّدت الخط سلسلة من إصدارات المقتنيات بتغليف من فنّ الشارع (نيويورك ولوس أنجلوس وتكساس).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Zino Platinum';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La gamme hondurienne — utilisant les tabacs de la vallée Jamastran — développe un profil distinctement non-nicaraguayen : plus floral, plus herbacé, avec une minéralité volcanique que les amateurs de Davidoff reconnaissent comme parentale. C''est la promesse implicite de Zino Platinum : l''ADN Davidoff dans un vêtement hondurien plus sombre et plus direct.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La gamme hondurienne — utilisant les tabacs de la vallée Jamastran — développe un profil distinctement non-nicaraguayen : plus floral, plus herbacé, avec une minéralité volcanique que les amateurs de Davidoff reconnaissent comme parentale. C''est la promesse implicite de Zino Platinum : l''ADN Davidoff dans un vêtement hondurien plus sombre et plus direct.', 'La marque Zino a été relancée en 2021 sur un assemblage nicaraguayen. En octobre 2026, la maison présente une nouvelle ligne Honduras, avec du tabac de Jamastrán et de Copán et une bande rouge (la ligne Nicaragua porte une bande or) ; elle écrit qu''elle revient ainsi là où tout a commencé en 1978. La cape des deux lignes vient d''Équateur.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Honduran range — using tobaccos from the Jamastran valley — develops a distinctly non-Nicaraguan profile: more floral, more herbaceous, with a volcanic minerality that Davidoff enthusiasts recognize as familial. This is Zino Platinum''s implicit promise: Davidoff DNA in a darker, more direct Honduran garment.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Honduran range — using tobaccos from the Jamastran valley — develops a distinctly non-Nicaraguan profile: more floral, more herbaceous, with a volcanic minerality that Davidoff enthusiasts recognize as familial. This is Zino Platinum''s implicit promise: Davidoff DNA in a darker, more direct Honduran garment.', 'The Zino brand was relaunched in 2021 on a Nicaraguan blend. In October 2026 the house presents a new Honduras line, with tobacco from Jamastrán and Copán and a red band (the Nicaragua line carries a gold band); it writes that it is thus returning to where everything began in 1978. The wrapper of both lines comes from Ecuador.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La gama hondureña —con tabacos del valle de Jamastran— despliega un perfil claramente no nicaragüense: más floral, más herbáceo, con una mineralidad volcánica que los aficionados a Davidoff reconocen como familiar. Esa es la promesa implícita de Zino Platinum: el ADN Davidoff con un ropaje hondureño más oscuro y más directo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La gama hondureña —con tabacos del valle de Jamastran— despliega un perfil claramente no nicaragüense: más floral, más herbáceo, con una mineralidad volcánica que los aficionados a Davidoff reconocen como familiar. Esa es la promesa implícita de Zino Platinum: el ADN Davidoff con un ropaje hondureño más oscuro y más directo.', 'La marca Zino se relanzó en 2021 sobre una ligada nicaragüense. En octubre de 2026, la casa presenta una nueva línea Honduras, con tabaco de Jamastrán y de Copán y una anilla roja (la línea Nicaragua lleva una anilla dorada); escribe que vuelve así adonde todo empezó en 1978. La capa de las dos líneas procede de Ecuador.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die honduranische Linie — aus den Tabaken des Jamastran-Tals — entwickelt ein ausgesprochen unnicaraguanisches Profil: blumiger, krautiger, mit einer vulkanischen Mineralität, die Davidoff-Liebhaber als verwandt wiedererkennen. Das ist das stille Versprechen von Zino Platinum: die Davidoff-DNA in einem dunkleren, unmittelbareren honduranischen Gewand.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die honduranische Linie — aus den Tabaken des Jamastran-Tals — entwickelt ein ausgesprochen unnicaraguanisches Profil: blumiger, krautiger, mit einer vulkanischen Mineralität, die Davidoff-Liebhaber als verwandt wiedererkennen. Das ist das stille Versprechen von Zino Platinum: die Davidoff-DNA in einem dunkleren, unmittelbareren honduranischen Gewand.', 'Die Marke Zino wurde 2021 auf Basis einer nicaraguanischen Mischung neu aufgelegt. Im Oktober 2026 stellt das Haus eine neue Linie Honduras vor, mit Tabak aus Jamastrán und Copán und einer roten Banderole (die Linie Nicaragua trägt eine goldene Banderole); es schreibt, es kehre damit dorthin zurück, wo 1978 alles begann. Das Deckblatt beider Linien stammt aus Ecuador.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这条洪都拉斯产品线取用 Jamastran 谷地的烟叶，呈现出明显不属于尼加拉瓜的风格：更花香、更草本，还有一份火山矿物感，Davidoff 的爱好者一尝便知其血缘。这正是 Zino Platinum 的隐含承诺：Davidoff 的基因，披着更深沉、更直接的洪都拉斯外衣。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这条洪都拉斯产品线取用 Jamastran 谷地的烟叶，呈现出明显不属于尼加拉瓜的风格：更花香、更草本，还有一份火山矿物感，Davidoff 的爱好者一尝便知其血缘。这正是 Zino Platinum 的隐含承诺：Davidoff 的基因，披着更深沉、更直接的洪都拉斯外衣。', 'Zino品牌于2021年以尼加拉瓜配方重新推出。2026年10月，品牌方介绍了新的Honduras系列，使用Jamastrán与Copán的烟叶，配红色烟标（Nicaragua系列则是金色烟标）；品牌方写道，这样就回到了1978年一切开始的地方。两个系列的茄衣均来自厄瓜多尔。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أما التشكيلة الهندوراسية — القائمة على تبغ وادي Jamastran — فتطوّر طابعاً غير نيكاراغوي بوضوح: أكثر زهرية وعشبية، مع معدنية بركانية يتعرّف عليها هواة Davidoff بوصفها قرابة عائلية. وهذا هو وعد Zino Platinum الضمني: حمض Davidoff النووي في ثوب هندوراسي أغمق وأكثر مباشرة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أما التشكيلة الهندوراسية — القائمة على تبغ وادي Jamastran — فتطوّر طابعاً غير نيكاراغوي بوضوح: أكثر زهرية وعشبية، مع معدنية بركانية يتعرّف عليها هواة Davidoff بوصفها قرابة عائلية. وهذا هو وعد Zino Platinum الضمني: حمض Davidoff النووي في ثوب هندوراسي أغمق وأكثر مباشرة.', 'أُعيد إطلاق علامة Zino عام 2021 على خلطة نيكاراغوية. وفي أكتوبر 2026 تقدّم الدار خطًا جديدًا هو Honduras، بتبغ من Jamastrán وCopán وحلقة حمراء (يحمل خط Nicaragua حلقة ذهبية)؛ وتكتب أنها تعود بذلك إلى حيث بدأ كل شيء عام 1978. وغلاف الخطين من الإكوادور.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Zino Platinum';

UPDATE `brands` SET
  `limited_eds` = '["Zino Platinum The Make of New York (2013)","Zino Platinum The Make of Los Angeles (2014)","Zino Platinum The Make of Texas (2014)","Zino Platinum Crown Series Limited Edition 2020"]',
  `founded` = '1978 (marque Zino) ; Zino Platinum depuis 2003',
  `factory` = 'Fabrique de Zino Platinum non nommée par la maison ; pays de roulage non établi. Ligne Zino Honduras (2026) : tabac de Jamastrán et Copán, selon la maison.',
  `gamme` = '[{"name":"Zino Platinum Crown","color":"#8B6914","story":"Première série de la ligne Platinum, lancée en 2003 avec la Scepter. Cape équatorienne de type Connecticut shade selon les fiches de la presse du métier ; l''assemblage exact varie selon les pages et la maison ne le détaille pas sur la page lue.","wrapper":"Équateur (Connecticut shade)","force":null},{"name":"Zino Platinum Scepter","color":"#5C3317","story":"Seconde série de la ligne Platinum, lancée en 2003 avec la Crown. La presse du métier et des détaillants indiquent une cape équatorienne, un liant Connecticut et une tripe dominicaine et péruvienne ; ces détails ne viennent pas d''une page de la maison.","wrapper":"Équateur (Connecticut shade)","force":null},{"name":"Zino Platinum Z-Class","color":"#2C1A0E","story":"Sortie en mai 2011. Selon Cigar Coop (22 mai 2011) : cape dominicaine, liant péruvien Pelo de Oro Visus, tripe de ligeros de Jalapa, d''Estelí (graines cubaines) et de San Vicente. Ce n''est donc pas un Corojo hondurien.","wrapper":"République dominicaine","force":null}]',
  `gamme_en` = '[{"name":"Zino Platinum Crown","color":"#8B6914","story":"First series of the Platinum line, launched in 2003 together with the Scepter. Ecuadorian wrapper of the Connecticut shade type according to trade-press listings; the exact blend varies from page to page and the house does not detail it on the page read.","wrapper":"Ecuador (Connecticut shade)","force":null},{"name":"Zino Platinum Scepter","color":"#5C3317","story":"Second series of the Platinum line, launched in 2003 together with the Crown. The trade press and retailers report an Ecuadorian wrapper, a Connecticut binder and a Dominican and Peruvian filler; these details do not come from a page of the house.","wrapper":"Ecuador (Connecticut shade)","force":null},{"name":"Zino Platinum Z-Class","color":"#2C1A0E","story":"Released in May 2011. According to Cigar Coop (22 May 2011): Dominican wrapper, Peruvian Pelo de Oro Visus binder, filler of ligeros from Jalapa, Estelí (Cuban seed) and San Vicente. It is therefore not a Honduran Corojo.","wrapper":"Dominican Republic","force":null}]',
  `gamme_es` = '[{"name":"Zino Platinum Crown","color":"#8B6914","story":"Primera serie de la línea Platinum, lanzada en 2003 junto con la Scepter. Capa ecuatoriana de tipo Connecticut shade según las fichas de la prensa del sector; la ligada exacta varía según las páginas y la casa no la detalla en la página consultada.","wrapper":"Ecuador (Connecticut shade)","force":null},{"name":"Zino Platinum Scepter","color":"#5C3317","story":"Segunda serie de la línea Platinum, lanzada en 2003 junto con la Crown. La prensa del sector y los minoristas indican una capa ecuatoriana, una capote Connecticut y una tripa dominicana y peruana; estos detalles no proceden de ninguna página de la casa.","wrapper":"Ecuador (Connecticut shade)","force":null},{"name":"Zino Platinum Z-Class","color":"#2C1A0E","story":"Salida en mayo de 2011. Según Cigar Coop (22 de mayo de 2011): capa dominicana, capote peruano Pelo de Oro Visus, tripa de ligeros de Jalapa, de Estelí (semillas cubanas) y de San Vicente. Por tanto, no es un Corojo hondureño.","wrapper":"República Dominicana","force":null}]',
  `gamme_de` = '[{"name":"Zino Platinum Crown","color":"#8B6914","story":"Erste Serie der Linie Platinum, 2003 zusammen mit der Scepter eingeführt. Ecuadorianisches Deckblatt vom Typ Connecticut shade laut den Produktseiten der Fachpresse; die genaue Mischung variiert je nach Seite, und das Haus nennt sie auf der gelesenen Seite nicht im Einzelnen.","wrapper":"Ecuador (Connecticut shade)","force":null},{"name":"Zino Platinum Scepter","color":"#5C3317","story":"Zweite Serie der Linie Platinum, 2003 zusammen mit der Crown eingeführt. Fachpresse und Händler nennen ein ecuadorianisches Deckblatt, ein Umblatt aus Connecticut und eine dominikanische und peruanische Einlage; diese Angaben stammen nicht von einer Seite des Hauses.","wrapper":"Ecuador (Connecticut shade)","force":null},{"name":"Zino Platinum Z-Class","color":"#2C1A0E","story":"Im Mai 2011 erschienen. Laut Cigar Coop (22. Mai 2011): dominikanisches Deckblatt, peruanisches Umblatt Pelo de Oro Visus, Einlage aus Ligeros aus Jalapa, Estelí (kubanisches Saatgut) und San Vicente. Es ist also kein honduranischer Corojo.","wrapper":"Dominikanische Republik","force":null}]',
  `gamme_zh` = '[{"name":"Zino Platinum Crown","color":"#8B6914","story":"Platinum系列的首个系列，2003年与Scepter一同推出。据行业媒体的资料页，茄衣为厄瓜多尔产的Connecticut shade类型；具体配方因页面而异，品牌方在所查阅的页面上也未详述。","wrapper":"厄瓜多尔（Connecticut shade）","force":null},{"name":"Zino Platinum Scepter","color":"#5C3317","story":"Platinum系列的第二个系列，2003年与Crown一同推出。行业媒体和零售商指出，茄衣为厄瓜多尔产，内包叶为Connecticut，茄芯为多米尼加与秘鲁烟叶；这些细节并非来自品牌方的页面。","wrapper":"厄瓜多尔（Connecticut shade）","force":null},{"name":"Zino Platinum Z-Class","color":"#2C1A0E","story":"2011年5月推出。据Cigar Coop（2011年5月22日）：茄衣为多米尼加产，内包叶为秘鲁的Pelo de Oro Visus，茄芯为来自Jalapa、Estelí（古巴种子）和San Vicente的ligero。因此它不是洪都拉斯的Corojo。","wrapper":"多米尼加共和国","force":null}]',
  `gamme_ar` = '[{"name":"Zino Platinum Crown","color":"#8B6914","story":"أول سلسلة في خط Platinum، أُطلقت عام 2003 مع Scepter. غلاف إكوادوري من نوع Connecticut shade بحسب بطاقات صحافة القطاع؛ وتختلف الخلطة الدقيقة من صفحة إلى أخرى، ولا تفصّلها الدار في الصفحة التي اطُّلع عليها.","wrapper":"الإكوادور (Connecticut shade)","force":null},{"name":"Zino Platinum Scepter","color":"#5C3317","story":"ثاني سلسلة في خط Platinum، أُطلقت عام 2003 مع Crown. تذكر صحافة القطاع وتجّار التجزئة غلافًا إكوادوريًا ورابطًا من Connecticut وحشوة دومينيكية وبيروفية؛ وهذه التفاصيل لا تأتي من صفحة للدار.","wrapper":"الإكوادور (Connecticut shade)","force":null},{"name":"Zino Platinum Z-Class","color":"#2C1A0E","story":"صدرت في مايو 2011. بحسب Cigar Coop (22 مايو 2011): غلاف دومينيكي، ورابط بيروفي Pelo de Oro Visus، وحشوة من ligeros من Jalapa ومن Estelí (بذور كوبية) ومن San Vicente. فهي إذن ليست Corojo هندوراسية.","wrapper":"جمهورية الدومينيكان","force":null}]',
  `pairings` = '[{"type":"Spiritueux","name":"Armagnac","notes":"Suggestion de dégustation, sans source : un armagnac âgé peut accompagner un cigare de corps moyen."},{"type":"Vin","name":"Riesling d''Alsace","notes":"Suggestion de dégustation, sans source : un riesling sec offre un contraste vif avec un cigare doux."}]',
  `pairings_en` = '[{"type":"Spirits","name":"Armagnac","notes":"Tasting suggestion, unsourced: an aged Armagnac can accompany a medium-bodied cigar."},{"type":"Wine","name":"Alsace Riesling","notes":"Tasting suggestion, unsourced: a dry Riesling offers a lively contrast with a mild cigar."}]',
  `pairings_es` = '[{"type":"Destilado","name":"Armagnac","notes":"Sugerencia de cata, sin fuente: un armagnac añejo puede acompañar a un puro de cuerpo medio."},{"type":"Vino","name":"Riesling de Alsacia","notes":"Sugerencia de cata, sin fuente: un riesling seco ofrece un contraste vivo con un puro suave."}]',
  `pairings_de` = '[{"type":"Spirituose","name":"Armagnac","notes":"Verkostungsvorschlag ohne Quelle: Ein gereifter Armagnac kann eine Zigarre mittlerer Stärke begleiten."},{"type":"Wein","name":"Elsässer Riesling","notes":"Verkostungsvorschlag ohne Quelle: Ein trockener Riesling bietet einen lebhaften Kontrast zu einer milden Zigarre."}]',
  `pairings_zh` = '[{"type":"烈酒","name":"雅文邑","notes":"品鉴建议，无来源：陈年雅文邑可以搭配中等浓度的雪茄。"},{"type":"葡萄酒","name":"阿尔萨斯雷司令","notes":"品鉴建议，无来源：干型雷司令与柔和的雪茄形成鲜明对比。"}]',
  `pairings_ar` = '[{"type":"مشروب روحي","name":"أرماناك","notes":"اقتراح تذوّق بلا مصدر: يمكن أن يرافق أرماناك معتّق سيجارًا متوسط القوام."},{"type":"نبيذ","name":"ريسلينغ ألزاس","notes":"اقتراح تذوّق بلا مصدر: يقدّم ريسلينغ جاف تباينًا حيًّا مع سيجار ناعم."}]',
  `source` = IF(LOCATE(CAST('us.davidoffgeneva.com et premiumcigars.org (Zino relancée par Davidoff of Geneva USA en 2002, Zino Platinum Crown la même année, Scepter en 2003 ; collaboration avec Peter Arnell et Steve Stout sous Reto Cina)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'us.davidoffgeneva.com et premiumcigars.org (Zino relancée par Davidoff of Geneva USA en 2002, Zino Platinum Crown la même année, Scepter en 2003 ; collaboration avec Peter Arnell et Steve Stout sous Reto Cina)', 'zino.oettingerdavidoff.com « The idea behind Zino » (page lue en octobre 2026 : 1978 Zino Davidoff et Dr Ernst Schneider, Honduras ; 2003 lancement de Zino Platinum Crown et Scepter ; 2021 relance nicaraguayenne ; ligne Honduras 2026 ; cape d''Équateur) ; cigar-coop.com « Cigar Review: Zino Platinum Z-Class » (2011-05-22 : cape dominicaine, liant péruvien) ; cigar-coop.com « Zino Platinum - The Make of Texas Collector''s Edition » (2014-11-16 : cape équatorienne, liant et tripe dominicains ; Make of New York 2013, LA 2014) ; cigaraficionado.com fiches de dégustation des séries Crown et Scepter (résultats de recherche : cape Équateur, tripe dominicaine et péruvienne ; pages non lues, 403)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Zino Platinum';

-- ── Excalibur ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Excalibur est une marque née d''un empêchement juridique, et non d''une intention de style. Villazon & Co., la maison de Tampa que dirigeait Frank Llaneza, avait racheté à Fernando Palicio, après la nationalisation cubaine de 1959, les lignes Punch, Hoyo de Monterrey et Belinda. Elle pouvait les vendre aux États-Unis ; elle ne pouvait pas se servir du nom Hoyo de Monterrey partout ailleurs. « Comme nous ne pouvons pas utiliser Hoyo de Monterrey, nous avons développé une marque appelée Excalibur, que nous vendons en Allemagne et en Angleterre », expliquait Dan Blumenthal, alors président de Villazon, dans un entretien que Cigar Advisor cite encore. Le nom du roi Arthur n''est donc pas une trouvaille de publicitaire : c''est un contournement de marque.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Excalibur est une marque née d''un empêchement juridique, et non d''une intention de style. Villazon & Co., la maison de Tampa que dirigeait Frank Llaneza, avait racheté à Fernando Palicio, après la nationalisation cubaine de 1959, les lignes Punch, Hoyo de Monterrey et Belinda. Elle pouvait les vendre aux États-Unis ; elle ne pouvait pas se servir du nom Hoyo de Monterrey partout ailleurs. « Comme nous ne pouvons pas utiliser Hoyo de Monterrey, nous avons développé une marque appelée Excalibur, que nous vendons en Allemagne et en Angleterre », expliquait Dan Blumenthal, alors président de Villazon, dans un entretien que Cigar Advisor cite encore. Le nom du roi Arthur n''est donc pas une trouvaille de publicitaire : c''est un contournement de marque.', 'Excalibur est une ligne non cubaine de la famille Hoyo de Monterrey. Elle a été créée par Villazon & Co., la maison de Tampa que dirigeait Frank Llaneza, selon la presse du métier (juin 2022) : à l''origine, une version des Hoyo en cape Connecticut shade, roulée au Honduras. Villazon faisait alors les Punch et Hoyo de Monterrey non cubains, dont elle tenait les droits américains, hérités des lignes que Fernando Palicio avait cédées à la famille Villazon après la nationalisation cubaine de 1959 (Wikipédia, page à source unique). Les pages lues ne disent rien de l''origine du nom Excalibur.'), `history`),
  `history_en` = IF(LOCATE(CAST('Excalibur was born of a trademark obstacle, not of a stylistic intention. Villazon & Co., the Tampa house run by Frank Llaneza, had bought from Fernando Palicio, after the Cuban nationalisation of 1959, the Punch, Hoyo de Monterrey and Belinda lines. It could sell them in the United States; it could not use the Hoyo de Monterrey name everywhere else. "Because we can''t use Hoyo de Monterrey, we developed a brand called Excalibur, which we sell in Germany and England," explained Dan Blumenthal, then chairman of Villazon, in an interview Cigar Advisor still quotes. King Arthur''s sword, then, is not an advertising find: it is a way around a trademark.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Excalibur was born of a trademark obstacle, not of a stylistic intention. Villazon & Co., the Tampa house run by Frank Llaneza, had bought from Fernando Palicio, after the Cuban nationalisation of 1959, the Punch, Hoyo de Monterrey and Belinda lines. It could sell them in the United States; it could not use the Hoyo de Monterrey name everywhere else. "Because we can''t use Hoyo de Monterrey, we developed a brand called Excalibur, which we sell in Germany and England," explained Dan Blumenthal, then chairman of Villazon, in an interview Cigar Advisor still quotes. King Arthur''s sword, then, is not an advertising find: it is a way around a trademark.', 'Excalibur is a non-Cuban line from the Hoyo de Monterrey family. According to the trade press (June 2022), it was created by Villazon & Co., the Tampa house run by Frank Llaneza: originally a version of the Hoyo in a Connecticut shade wrapper, rolled in Honduras. Villazon was then making the non-Cuban Punch and Hoyo de Monterrey, whose American rights it held, inherited from the lines that Fernando Palicio had sold to the Villazon family after the Cuban nationalisation of 1959 (Wikipedia, a single-source page). The pages read say nothing about the origin of the name Excalibur.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Excalibur nació de un impedimento de marca, no de una intención de estilo. Villazon & Co., la casa de Tampa dirigida por Frank Llaneza, había comprado a Fernando Palicio, tras la nacionalización cubana de 1959, las líneas Punch, Hoyo de Monterrey y Belinda. Podía venderlas en Estados Unidos; no podía usar el nombre Hoyo de Monterrey en el resto del mundo. «Como no podemos usar Hoyo de Monterrey, desarrollamos una marca llamada Excalibur, que vendemos en Alemania e Inglaterra», explicaba Dan Blumenthal, entonces presidente de Villazon, en una entrevista que Cigar Advisor sigue citando. La espada del rey Arturo no es, pues, un hallazgo publicitario: es un rodeo legal.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Excalibur nació de un impedimento de marca, no de una intención de estilo. Villazon & Co., la casa de Tampa dirigida por Frank Llaneza, había comprado a Fernando Palicio, tras la nacionalización cubana de 1959, las líneas Punch, Hoyo de Monterrey y Belinda. Podía venderlas en Estados Unidos; no podía usar el nombre Hoyo de Monterrey en el resto del mundo. «Como no podemos usar Hoyo de Monterrey, desarrollamos una marca llamada Excalibur, que vendemos en Alemania e Inglaterra», explicaba Dan Blumenthal, entonces presidente de Villazon, en una entrevista que Cigar Advisor sigue citando. La espada del rey Arturo no es, pues, un hallazgo publicitario: es un rodeo legal.', 'Excalibur es una línea no cubana de la familia Hoyo de Monterrey. Fue creada por Villazon & Co., la casa de Tampa dirigida por Frank Llaneza, según la prensa del sector (junio de 2022): en origen, una versión de los Hoyo con capa Connecticut shade, liada en Honduras. Villazon fabricaba entonces los Punch y Hoyo de Monterrey no cubanos, cuyos derechos estadounidenses poseía, heredados de las líneas que Fernando Palicio había cedido a la familia Villazon tras la nacionalización cubana de 1959 (Wikipedia, página de fuente única). Las páginas consultadas no dicen nada del origen del nombre Excalibur.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Excalibur entstand aus einem markenrechtlichen Hindernis, nicht aus einer stilistischen Absicht. Villazon & Co., das von Frank Llaneza geführte Haus aus Tampa, hatte Fernando Palicio nach der kubanischen Verstaatlichung von 1959 die Linien Punch, Hoyo de Monterrey und Belinda abgekauft. Verkaufen durfte es sie in den Vereinigten Staaten; den Namen Hoyo de Monterrey überall sonst zu führen, war ihm verwehrt. „Da wir Hoyo de Monterrey nicht verwenden können, haben wir eine Marke namens Excalibur entwickelt, die wir in Deutschland und England verkaufen", erklärte Dan Blumenthal, damals Vorsitzender von Villazon, in einem Interview, das Cigar Advisor bis heute zitiert. Das Schwert von König Artus ist also kein Werbeeinfall, sondern ein Umweg um ein Markenrecht.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Excalibur entstand aus einem markenrechtlichen Hindernis, nicht aus einer stilistischen Absicht. Villazon & Co., das von Frank Llaneza geführte Haus aus Tampa, hatte Fernando Palicio nach der kubanischen Verstaatlichung von 1959 die Linien Punch, Hoyo de Monterrey und Belinda abgekauft. Verkaufen durfte es sie in den Vereinigten Staaten; den Namen Hoyo de Monterrey überall sonst zu führen, war ihm verwehrt. „Da wir Hoyo de Monterrey nicht verwenden können, haben wir eine Marke namens Excalibur entwickelt, die wir in Deutschland und England verkaufen", erklärte Dan Blumenthal, damals Vorsitzender von Villazon, in einem Interview, das Cigar Advisor bis heute zitiert. Das Schwert von König Artus ist also kein Werbeeinfall, sondern ein Umweg um ein Markenrecht.', 'Excalibur ist eine nichtkubanische Linie aus der Familie Hoyo de Monterrey. Sie wurde laut Fachpresse (Juni 2022) von Villazon & Co. geschaffen, dem von Frank Llaneza geführten Haus aus Tampa: ursprünglich eine Version der Hoyo mit Deckblatt Connecticut Shade, gerollt in Honduras. Villazon stellte damals die nichtkubanischen Punch und Hoyo de Monterrey her, deren amerikanische Rechte es hielt; sie stammten aus den Linien, die Fernando Palicio nach der kubanischen Verstaatlichung von 1959 an die Familie Villazon abgetreten hatte (Wikipedia, Seite mit nur einer Quelle). Die gelesenen Seiten sagen nichts über den Ursprung des Namens Excalibur.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Excalibur（王者之剑）的诞生源于一个商标障碍，而非风格构想。由弗兰克·利亚内萨执掌的坦帕老号 Villazon & Co.，在1959年古巴国有化之后，从费尔南多·帕利西奥手中买下了 Punch、Hoyo de Monterrey 与 Belinda 三个系列。它可以在美国销售这些牌子，却无法在其他地方使用 Hoyo de Monterrey 之名。「因为我们不能用 Hoyo de Monterrey，所以我们开发了一个叫 Excalibur 的牌子，在德国和英国销售。」时任 Villazon 董事长的丹·布卢门塔尔如此解释——这段话至今仍被 Cigar Advisor 引用。可见亚瑟王之剑并非广告灵感，而是一条绕开商标的路。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Excalibur（王者之剑）的诞生源于一个商标障碍，而非风格构想。由弗兰克·利亚内萨执掌的坦帕老号 Villazon & Co.，在1959年古巴国有化之后，从费尔南多·帕利西奥手中买下了 Punch、Hoyo de Monterrey 与 Belinda 三个系列。它可以在美国销售这些牌子，却无法在其他地方使用 Hoyo de Monterrey 之名。「因为我们不能用 Hoyo de Monterrey，所以我们开发了一个叫 Excalibur 的牌子，在德国和英国销售。」时任 Villazon 董事长的丹·布卢门塔尔如此解释——这段话至今仍被 Cigar Advisor 引用。可见亚瑟王之剑并非广告灵感，而是一条绕开商标的路。', 'Excalibur 是 Hoyo de Monterrey 家族中的一个非古巴系列。据行业媒体（2022年6月）报道，它由坦帕的 Villazon & Co. 创立，该公司由 Frank Llaneza 执掌；起初是 Hoyo 的一个版本，采用 Connecticut shade 茄衣，在洪都拉斯卷制。当时 Villazon 生产非古巴的 Punch 与 Hoyo de Monterrey，并持有其美国权利；这些权利承自 Fernando Palicio 在1959年古巴国有化之后转让给 Villazon 家族的系列（Wikipedia，该页仅有单一来源）。所读页面均未提及 Excalibur 这一名称的由来。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وُلدت إكسكاليبر من عائق يتعلق بالعلامة التجارية، لا من نيّة أسلوبية. فقد اشترت شركة فيّازون (Villazon & Co.)، وهي دار من تامبا كان يديرها فرانك يانيسا، من فرناندو باليسيو، بعد التأميم الكوبي سنة 1959، خطوط بونتش وأويو دي مونتيري وبليندا. كان بوسعها بيعها في الولايات المتحدة، لكن لم يكن بوسعها استعمال اسم أويو دي مونتيري في سائر البلدان. قال دان بلومنتال، رئيس فيّازون آنذاك، في حديث ما زالت مجلة Cigar Advisor تنقله: «بما أننا لا نستطيع استعمال أويو دي مونتيري، طوّرنا علامة اسمها إكسكاليبر نبيعها في ألمانيا وإنجلترا». فسيف الملك آرثر إذن ليس ابتكارًا إعلانيًا، بل التفافًا على حقّ علامة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وُلدت إكسكاليبر من عائق يتعلق بالعلامة التجارية، لا من نيّة أسلوبية. فقد اشترت شركة فيّازون (Villazon & Co.)، وهي دار من تامبا كان يديرها فرانك يانيسا، من فرناندو باليسيو، بعد التأميم الكوبي سنة 1959، خطوط بونتش وأويو دي مونتيري وبليندا. كان بوسعها بيعها في الولايات المتحدة، لكن لم يكن بوسعها استعمال اسم أويو دي مونتيري في سائر البلدان. قال دان بلومنتال، رئيس فيّازون آنذاك، في حديث ما زالت مجلة Cigar Advisor تنقله: «بما أننا لا نستطيع استعمال أويو دي مونتيري، طوّرنا علامة اسمها إكسكاليبر نبيعها في ألمانيا وإنجلترا». فسيف الملك آرثر إذن ليس ابتكارًا إعلانيًا، بل التفافًا على حقّ علامة.', 'Excalibur خط غير كوبي من عائلة Hoyo de Monterrey. أنشأته شركة Villazon & Co.، الدار التي في تامبا بإدارة Frank Llaneza، بحسب الصحافة المتخصصة (حزيران/يونيو 2022): كان في الأصل نسخة من Hoyo بغلاف Connecticut shade، تُلَفّ في هندوراس. وكانت Villazon تصنع آنذاك Punch وHoyo de Monterrey غير الكوبيين، وهي تملك حقوقهما الأمريكية، موروثة عن الخطوط التي تنازل عنها Fernando Palicio لعائلة Villazon بعد التأميم الكوبي سنة 1959 (Wikipedia، صفحة بمصدر واحد). والصفحات المقروءة لا تقول شيئًا عن أصل اسم Excalibur.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Excalibur';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Llaneza avait découvert le Honduras en 1960, deux ans avant l''embargo, et Villazon y transféra sa production roulée à la main au cours de la décennie, ne gardant à Tampa qu''un atelier réduit. C''est de là que vient le profil de la ligne : les tabacs de la vallée de Jamastrán, terreux, boisés, francs à la combustion, dans un registre plus rond que puissant.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Llaneza avait découvert le Honduras en 1960, deux ans avant l''embargo, et Villazon y transféra sa production roulée à la main au cours de la décennie, ne gardant à Tampa qu''un atelier réduit. C''est de là que vient le profil de la ligne : les tabacs de la vallée de Jamastrán, terreux, boisés, francs à la combustion, dans un registre plus rond que puissant.', 'Frank Llaneza, mort en 2010, dit avoir visité le Honduras pour la première fois en 1960, deux ans avant l''embargo, quand l''industrie y était déjà en développement ; la presse du métier le compte parmi les premiers à y faire des cigares premium.'), `history`),
  `history_en` = IF(LOCATE(CAST('Llaneza had discovered Honduras in 1960, two years before the embargo, and Villazon moved its hand-rolled production there during that decade, keeping only a reduced workshop in Tampa. That is where the line''s profile comes from: the tobaccos of the Jamastrán valley, earthy, woody, clean-burning, in a register more round than powerful.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Llaneza had discovered Honduras in 1960, two years before the embargo, and Villazon moved its hand-rolled production there during that decade, keeping only a reduced workshop in Tampa. That is where the line''s profile comes from: the tobaccos of the Jamastrán valley, earthy, woody, clean-burning, in a register more round than powerful.', 'Frank Llaneza, who died in 2010, says he first visited Honduras in 1960, two years before the embargo, when the industry there was already developing; the trade press counts him among the first to make premium cigars there.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Llaneza había descubierto Honduras en 1960, dos años antes del embargo, y Villazon trasladó allí su producción hecha a mano a lo largo de esa década, conservando en Tampa solo un taller reducido. De ahí viene el perfil de la línea: los tabacos del valle de Jamastrán, terrosos, amaderados, de combustión franca, en un registro más redondo que potente.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Llaneza había descubierto Honduras en 1960, dos años antes del embargo, y Villazon trasladó allí su producción hecha a mano a lo largo de esa década, conservando en Tampa solo un taller reducido. De ahí viene el perfil de la línea: los tabacos del valle de Jamastrán, terrosos, amaderados, de combustión franca, en un registro más redondo que potente.', 'Frank Llaneza, fallecido en 2010, dice haber visitado Honduras por primera vez en 1960, dos años antes del embargo, cuando la industria ya se estaba desarrollando allí; la prensa del sector lo cuenta entre los primeros en hacer puros premium en ese país.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Llaneza hatte Honduras 1960 entdeckt, zwei Jahre vor dem Embargo, und Villazon verlagerte seine handgerollte Produktion im Lauf des Jahrzehnts dorthin; in Tampa blieb nur eine kleine Werkstatt. Daher stammt das Profil der Linie: die Tabake des Jamastrán-Tals, erdig, holzig, mit sauberem Abbrand, eher rund als kraftvoll.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Llaneza hatte Honduras 1960 entdeckt, zwei Jahre vor dem Embargo, und Villazon verlagerte seine handgerollte Produktion im Lauf des Jahrzehnts dorthin; in Tampa blieb nur eine kleine Werkstatt. Daher stammt das Profil der Linie: die Tabake des Jamastrán-Tals, erdig, holzig, mit sauberem Abbrand, eher rund als kraftvoll.', 'Frank Llaneza, der 2010 starb, sagt, er habe Honduras 1960 zum ersten Mal besucht, zwei Jahre vor dem Embargo, als die Industrie dort schon im Aufbau war; die Fachpresse zählt ihn zu den Ersten, die dort Premiumzigarren herstellten.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('利亚内萨1960年初识洪都拉斯，比禁运早两年；Villazon 在那十年间将手工卷制迁往当地，坦帕只留下一个小作坊。系列的风味由此而来：哈马斯特兰河谷的烟叶，土气、木质、燃烧干净，圆润多于强劲。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '利亚内萨1960年初识洪都拉斯，比禁运早两年；Villazon 在那十年间将手工卷制迁往当地，坦帕只留下一个小作坊。系列的风味由此而来：哈马斯特兰河谷的烟叶，土气、木质、燃烧干净，圆润多于强劲。', 'Frank Llaneza 于2010年去世。他自称1960年首次到访洪都拉斯，比禁运早两年，当时当地的产业已在发展；行业媒体将他列为在当地制作高端雪茄的首批人物之一。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('كان يانيسا قد اكتشف هندوراس سنة 1960، أي قبل الحصار بعامين، ونقلت فيّازون إليها إنتاجها الملفوف يدويًا خلال ذلك العقد، ولم تُبقِ في تامبا سوى ورشة مصغّرة. من هناك يأتي طابع الخط: تبغ وادي خاماستران، ترابيّ، خشبيّ، صافي الاحتراق، في سجلّ مستدير أكثر منه قويًّا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'كان يانيسا قد اكتشف هندوراس سنة 1960، أي قبل الحصار بعامين، ونقلت فيّازون إليها إنتاجها الملفوف يدويًا خلال ذلك العقد، ولم تُبقِ في تامبا سوى ورشة مصغّرة. من هناك يأتي طابع الخط: تبغ وادي خاماستران، ترابيّ، خشبيّ، صافي الاحتراق، في سجلّ مستدير أكثر منه قويًّا.', 'يقول Frank Llaneza، الذي توفي سنة 2010، إنه زار هندوراس أول مرة سنة 1960، قبل الحصار بعامين، حين كانت الصناعة هناك في طور النمو أصلًا؛ وتعدّه الصحافة المتخصصة من أوائل من صنعوا السيجار الفاخر فيها.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Excalibur';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La date de naissance n''est pas établie de la même façon par tout le monde, et cette fiche le dit plutôt que de choisir en silence. Cigar Aficionado, en mai 2021, disait la ligne quadragénaire cette année-là — donc 1981. Cigar Advisor date de 1992 son lancement comme ligne Hoyo de Monterrey, ce qui se comprend si l''on distingue la marque européenne de son arrivée sous l''enseigne Hoyo aux États-Unis. Des détaillants évoquent les années 1970. L''atlas retient 1981, sur la source la plus précise.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La date de naissance n''est pas établie de la même façon par tout le monde, et cette fiche le dit plutôt que de choisir en silence. Cigar Aficionado, en mai 2021, disait la ligne quadragénaire cette année-là — donc 1981. Cigar Advisor date de 1992 son lancement comme ligne Hoyo de Monterrey, ce qui se comprend si l''on distingue la marque européenne de son arrivée sous l''enseigne Hoyo aux États-Unis. Des détaillants évoquent les années 1970. L''atlas retient 1981, sur la source la plus précise.', 'La date de naissance diverge selon les pages. En mai 2021, la presse du métier annonçait les 40 ans de la marque « cette année » : cela mène à 1981, mais aucune année de fondation n''y est écrite. Un test de Cigar Coop (février 2012) et des détaillants situent l''introduction d''Excalibur dans les années 1970. La page de la marque déposée n''a pas pu être lue (403). La ligne Dark Knight est sortie de la gamme 1066 en 2010 selon Cigar Coop.'), `history`),
  `history_en` = IF(LOCATE(CAST('The founding date is not established the same way by everyone, and this entry says so rather than choosing in silence. Cigar Aficionado, in May 2021, called the line forty years old that year — so 1981. Cigar Advisor dates its launch as a Hoyo de Monterrey line to 1992, which makes sense if one separates the European brand from its arrival under the Hoyo name in the United States. Retailers mention the 1970s. The atlas keeps 1981, on the most precise source.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The founding date is not established the same way by everyone, and this entry says so rather than choosing in silence. Cigar Aficionado, in May 2021, called the line forty years old that year — so 1981. Cigar Advisor dates its launch as a Hoyo de Monterrey line to 1992, which makes sense if one separates the European brand from its arrival under the Hoyo name in the United States. Retailers mention the 1970s. The atlas keeps 1981, on the most precise source.', 'The date of birth differs from page to page. In May 2021, the trade press announced the brand''s 40th anniversary “this year”: that leads to 1981, but no founding year is written there. A Cigar Coop test (February 2012) and retailers place Excalibur''s introduction in the 1970s. The registered-trademark page could not be read (403). The Dark Knight line came out of the 1066 range in 2010 according to Cigar Coop.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La fecha de nacimiento no está establecida igual por todos, y esta ficha lo dice en lugar de elegir en silencio. Cigar Aficionado, en mayo de 2021, daba la línea por cuarentona ese año — es decir, 1981. Cigar Advisor fecha en 1992 su lanzamiento como línea Hoyo de Monterrey, lo que se entiende si se distingue la marca europea de su llegada bajo el nombre Hoyo en Estados Unidos. Algunos minoristas hablan de los años setenta. El atlas retiene 1981, por ser la fuente más precisa.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La fecha de nacimiento no está establecida igual por todos, y esta ficha lo dice en lugar de elegir en silencio. Cigar Aficionado, en mayo de 2021, daba la línea por cuarentona ese año — es decir, 1981. Cigar Advisor fecha en 1992 su lanzamiento como línea Hoyo de Monterrey, lo que se entiende si se distingue la marca europea de su llegada bajo el nombre Hoyo en Estados Unidos. Algunos minoristas hablan de los años setenta. El atlas retiene 1981, por ser la fuente más precisa.', 'La fecha de nacimiento diverge según las páginas. En mayo de 2021, la prensa del sector anunciaba los 40 años de la marca «este año»: eso lleva a 1981, pero allí no figura ningún año de fundación. Una prueba de Cigar Coop (febrero de 2012) y algunos minoristas sitúan la introducción de Excalibur en los años setenta. La página de la marca registrada no pudo leerse (403). La línea Dark Knight salió de la gama 1066 en 2010, según Cigar Coop.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Gründungsjahr wird nicht von allen gleich angegeben, und dieser Eintrag sagt das, statt stillschweigend zu wählen. Cigar Aficionado nannte die Linie im Mai 2021 vierzigjährig — also 1981. Cigar Advisor datiert ihren Start als Hoyo-de-Monterrey-Linie auf 1992, was sich erklärt, wenn man die europäische Marke von ihrer Ankunft unter dem Hoyo-Namen in den USA unterscheidet. Händler sprechen von den 1970er-Jahren. Der Atlas hält an 1981 fest, nach der genauesten Quelle.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Gründungsjahr wird nicht von allen gleich angegeben, und dieser Eintrag sagt das, statt stillschweigend zu wählen. Cigar Aficionado nannte die Linie im Mai 2021 vierzigjährig — also 1981. Cigar Advisor datiert ihren Start als Hoyo-de-Monterrey-Linie auf 1992, was sich erklärt, wenn man die europäische Marke von ihrer Ankunft unter dem Hoyo-Namen in den USA unterscheidet. Händler sprechen von den 1970er-Jahren. Der Atlas hält an 1981 fest, nach der genauesten Quelle.', 'Das Geburtsdatum weicht je nach Seite voneinander ab. Im Mai 2021 kündigte die Fachpresse die 40 Jahre der Marke „in diesem Jahr“ an: Das führt zu 1981, doch ein Gründungsjahr steht dort nicht. Ein Test von Cigar Coop (Februar 2012) und Händler verorten die Einführung von Excalibur in den 1970er-Jahren. Die Seite der eingetragenen Marke konnte nicht gelesen werden (403). Die Linie Dark Knight ging 2010 laut Cigar Coop aus der Reihe 1066 hervor.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('创立年份并非人人一致，本词条选择说明分歧，而不是默默择一。《雪茄爱好者》2021年5月称该系列当年「四十岁」，即1981年。Cigar Advisor 则将其作为 Hoyo de Monterrey 系列的推出定在1992年——若把欧洲的牌子与它在美国以 Hoyo 之名登场区分开来，这就说得通。零售商则提到1970年代。本图集采信最精确的来源，取1981年。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '创立年份并非人人一致，本词条选择说明分歧，而不是默默择一。《雪茄爱好者》2021年5月称该系列当年「四十岁」，即1981年。Cigar Advisor 则将其作为 Hoyo de Monterrey 系列的推出定在1992年——若把欧洲的牌子与它在美国以 Hoyo 之名登场区分开来，这就说得通。零售商则提到1970年代。本图集采信最精确的来源，取1981年。', '出生日期各页说法不一。2021年5月，行业媒体称该品牌「今年」迎来40周年：由此推得1981年，但那里并未写明创立年份。Cigar Coop 的一篇测评（2012年2月）和零售商则把 Excalibur 的推出定在1970年代。注册商标页面无法读取（403）。据 Cigar Coop，Dark Knight 系列于2010年自 1066 系列推出。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('سنة النشأة ليست مقرَّرة على نحو واحد عند الجميع، وهذه البطاقة تقول ذلك بدل أن تختار في صمت. فمجلة Cigar Aficionado وصفت الخط في أيار/مايو 2021 بأنه بلغ الأربعين تلك السنة، أي 1981. أما Cigar Advisor فتؤرّخ إطلاقه كخط تابع لأويو دي مونتيري بسنة 1992، وهو ما يُفهم إذا فُرِّق بين العلامة الأوروبية وبين وصولها إلى الولايات المتحدة تحت اسم أويو. ويذكر بائعون سبعينيات القرن الماضي. ويأخذ الأطلس بسنة 1981، اعتمادًا على أدقّ المصادر.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'سنة النشأة ليست مقرَّرة على نحو واحد عند الجميع، وهذه البطاقة تقول ذلك بدل أن تختار في صمت. فمجلة Cigar Aficionado وصفت الخط في أيار/مايو 2021 بأنه بلغ الأربعين تلك السنة، أي 1981. أما Cigar Advisor فتؤرّخ إطلاقه كخط تابع لأويو دي مونتيري بسنة 1992، وهو ما يُفهم إذا فُرِّق بين العلامة الأوروبية وبين وصولها إلى الولايات المتحدة تحت اسم أويو. ويذكر بائعون سبعينيات القرن الماضي. ويأخذ الأطلس بسنة 1981، اعتمادًا على أدقّ المصادر.', 'يختلف تاريخ الميلاد بحسب الصفحات. ففي أيار/مايو 2021 أعلنت الصحافة المتخصصة بلوغ العلامة الأربعين «هذه السنة»: وهذا يقود إلى 1981، لكن لا تُذكر هناك سنة تأسيس. ويضع اختبارٌ من Cigar Coop (شباط/فبراير 2012) وبعض البائعين طرح Excalibur في سبعينيات القرن الماضي. أما صفحة العلامة المسجلة فتعذّرت قراءتها (403). وخرج خط Dark Knight من مجموعة 1066 سنة 2010 بحسب Cigar Coop.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Excalibur';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('En 1997, Llaneza et son associé vendirent Villazon à General Cigar pour 81,4 millions de dollars. Excalibur appartient depuis à cet ensemble, aujourd''hui filiale du Scandinavian Tobacco Group, et se fabrique à la HATSA de Danlí — la fabrique où furent roulés pendant des décennies El Rey del Mundo, Hoyo de Monterrey et Punch.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'En 1997, Llaneza et son associé vendirent Villazon à General Cigar pour 81,4 millions de dollars. Excalibur appartient depuis à cet ensemble, aujourd''hui filiale du Scandinavian Tobacco Group, et se fabrique à la HATSA de Danlí — la fabrique où furent roulés pendant des décennies El Rey del Mundo, Hoyo de Monterrey et Punch.', 'La vente de Villazon à General Cigar est datée de 1997 par la presse du métier (obituaire de Dan Blumenthal, 2011) et de 1996 par un entretien de Llaneza paru en 1999, qui donne 91 millions de dollars ; les deux versions ne se tranchent pas ici. Excalibur appartient depuis à General Cigar, filiale du Scandinavian Tobacco Group, qui fabrique tous les Hoyo de Monterrey non cubains. En mai 2021, la presse du métier place la fabrication à la HATSA de Danlí ; Cigar Coop (2012) écrivait Cofradía. En 2022, Dion Giolito (Illusione) et STG ont sorti une édition limitée Excalibur roulée au Nicaragua.'), `history`),
  `history_en` = IF(LOCATE(CAST('In 1997, Llaneza and his partner sold Villazon to General Cigar for 81.4 million dollars. Excalibur has belonged to that group ever since — today a subsidiary of Scandinavian Tobacco Group — and is made at the HATSA factory in Danlí, where El Rey del Mundo, Hoyo de Monterrey and Punch were rolled for decades.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'In 1997, Llaneza and his partner sold Villazon to General Cigar for 81.4 million dollars. Excalibur has belonged to that group ever since — today a subsidiary of Scandinavian Tobacco Group — and is made at the HATSA factory in Danlí, where El Rey del Mundo, Hoyo de Monterrey and Punch were rolled for decades.', 'The sale of Villazon to General Cigar is dated 1997 by the trade press (Dan Blumenthal''s obituary, 2011) and 1996 by a Llaneza interview published in 1999, which gives 91 million dollars; the two versions cannot be settled here. Excalibur has belonged since then to General Cigar, a subsidiary of Scandinavian Tobacco Group, which makes all the non-Cuban Hoyo de Monterrey. In May 2021, the trade press places manufacture at the HATSA in Danlí; Cigar Coop (2012) wrote Cofradía. In 2022, Dion Giolito (Illusione) and STG released a limited-edition Excalibur rolled in Nicaragua.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('En 1997, Llaneza y su socio vendieron Villazon a General Cigar por 81,4 millones de dólares. Excalibur pertenece desde entonces a ese conjunto, hoy filial del Scandinavian Tobacco Group, y se fabrica en la HATSA de Danlí, la fábrica donde se liaron durante décadas El Rey del Mundo, Hoyo de Monterrey y Punch.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'En 1997, Llaneza y su socio vendieron Villazon a General Cigar por 81,4 millones de dólares. Excalibur pertenece desde entonces a ese conjunto, hoy filial del Scandinavian Tobacco Group, y se fabrica en la HATSA de Danlí, la fábrica donde se liaron durante décadas El Rey del Mundo, Hoyo de Monterrey y Punch.', 'La venta de Villazon a General Cigar se fecha en 1997 según la prensa del sector (obituario de Dan Blumenthal, 2011) y en 1996 según una entrevista a Llaneza publicada en 1999, que da 91 millones de dólares; aquí no se puede zanjar entre las dos versiones. Excalibur pertenece desde entonces a General Cigar, filial del Scandinavian Tobacco Group, que fabrica todos los Hoyo de Monterrey no cubanos. En mayo de 2021, la prensa del sector sitúa la fabricación en la HATSA de Danlí; Cigar Coop (2012) escribía Cofradía. En 2022, Dion Giolito (Illusione) y STG sacaron una edición limitada de Excalibur liada en Nicaragua.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('1997 verkauften Llaneza und sein Partner Villazon für 81,4 Millionen Dollar an General Cigar. Seither gehört Excalibur zu dieser Gruppe, heute eine Tochter der Scandinavian Tobacco Group, und wird in der HATSA in Danlí gefertigt — jener Fabrik, in der jahrzehntelang El Rey del Mundo, Hoyo de Monterrey und Punch gerollt wurden.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, '1997 verkauften Llaneza und sein Partner Villazon für 81,4 Millionen Dollar an General Cigar. Seither gehört Excalibur zu dieser Gruppe, heute eine Tochter der Scandinavian Tobacco Group, und wird in der HATSA in Danlí gefertigt — jener Fabrik, in der jahrzehntelang El Rey del Mundo, Hoyo de Monterrey und Punch gerollt wurden.', 'Den Verkauf von Villazon an General Cigar datiert die Fachpresse auf 1997 (Nachruf auf Dan Blumenthal, 2011), ein 1999 erschienenes Interview mit Llaneza auf 1996; es nennt 91 Millionen Dollar. Die beiden Fassungen lassen sich hier nicht entscheiden. Excalibur gehört seither zu General Cigar, einer Tochter der Scandinavian Tobacco Group, die alle nichtkubanischen Hoyo de Monterrey herstellt. Im Mai 2021 verlegt die Fachpresse die Fertigung in die HATSA in Danlí; Cigar Coop (2012) schrieb Cofradía. 2022 brachten Dion Giolito (Illusione) und STG eine limitierte Excalibur-Edition heraus, die in Nicaragua gerollt wurde.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('1997年，利亚内萨与合伙人以8140万美元将 Villazon 售予 General Cigar。此后 Excalibur 一直属于该集团——今日为斯堪的纳维亚烟草集团的子公司——在丹利的 HATSA 厂制造；那正是数十年间卷制 El Rey del Mundo、Hoyo de Monterrey 与 Punch 的厂房。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '1997年，利亚内萨与合伙人以8140万美元将 Villazon 售予 General Cigar。此后 Excalibur 一直属于该集团——今日为斯堪的纳维亚烟草集团的子公司——在丹利的 HATSA 厂制造；那正是数十年间卷制 El Rey del Mundo、Hoyo de Monterrey 与 Punch 的厂房。', '关于 Villazon 售予 General Cigar 的时间，行业媒体（Dan Blumenthal 的讣告，2011年）定为1997年，Llaneza 1999年发表的一篇访谈则定为1996年，并给出9100万美元；两种说法在此无法定夺。此后 Excalibur 归 General Cigar 所有，后者是 Scandinavian Tobacco Group 的子公司，生产所有非古巴的 Hoyo de Monterrey。2021年5月，行业媒体把制造地点放在 Danlí 的 HATSA；Cigar Coop（2012年）写的则是 Cofradía。2022年，Dion Giolito（Illusione）与 STG 推出了一款在尼加拉瓜卷制的 Excalibur 限量版。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وفي 1997 باع يانيسا وشريكه فيّازون إلى جنرال سيغار بمبلغ 81,4 مليون دولار. ومنذ ذلك الحين تنتمي إكسكاليبر إلى تلك المجموعة، وهي اليوم تابعة لمجموعة التبغ الإسكندنافية، وتُصنع في مصنع HATSA بمدينة دانلي — المصنع الذي لُفّت فيه عقودًا طويلة سجائر إل ري ديل موندو وأويو دي مونتيري وبونتش.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وفي 1997 باع يانيسا وشريكه فيّازون إلى جنرال سيغار بمبلغ 81,4 مليون دولار. ومنذ ذلك الحين تنتمي إكسكاليبر إلى تلك المجموعة، وهي اليوم تابعة لمجموعة التبغ الإسكندنافية، وتُصنع في مصنع HATSA بمدينة دانلي — المصنع الذي لُفّت فيه عقودًا طويلة سجائر إل ري ديل موندو وأويو دي مونتيري وبونتش.', 'تؤرّخ الصحافة المتخصصة بيع Villazon إلى General Cigar بسنة 1997 (نعي Dan Blumenthal، 2011)، وتؤرّخه مقابلة مع Llaneza نُشرت سنة 1999 بسنة 1996 وتذكر 91 مليون دولار؛ ولا يُفصل بين الروايتين هنا. وتنتمي Excalibur منذ ذلك الحين إلى General Cigar، التابعة لمجموعة Scandinavian Tobacco Group، التي تصنع جميع سيجار Hoyo de Monterrey غير الكوبي. وفي أيار/مايو 2021 تضع الصحافة المتخصصة التصنيع في HATSA بمدينة Danlí؛ وكتبت Cigar Coop (2012) Cofradía. وفي 2022 أصدر Dion Giolito (Illusione) وSTG طبعة محدودة من Excalibur لُفّت في نيكاراغوا.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Excalibur';

UPDATE `brands` SET
  `limited_eds` = '["Excalibur Illusione (2022)"]',
  `founded` = 'Années 1970 ou 1981 (sources divergentes)',
  `factory` = 'HATSA (Honduras American Tabaco S.A.), Danlí, Honduras — General Cigar, filiale du Scandinavian Tobacco Group (presse du métier, 2021)',
  `gamme` = '[{"name":"Excalibur No. I","color":"#5C3317","story":"Le grand format de la ligne ; en Excalibur Black, il mesure 7¼ × 54 pouces (presse du métier, mai 2021). La ligne d''origine est en cape Connecticut shade.","wrapper":"Connecticut shade","force":null},{"name":"Excalibur Robusto","color":"#7A4520","story":"Le Robusto, 5 × 50 pouces dans la ligne Black (presse du métier, mai 2021) ; la ligne d''origine est en cape Connecticut shade.","wrapper":"Connecticut shade","force":null},{"name":"Excalibur Dark Knight","color":"#2C1A0E","story":"Cape Connecticut Broadleaf maduro (Stogie Review, 2007 ; Cigar Coop, 2012), et non San Andrés. Sortie de la gamme 1066 en 2010 selon Cigar Coop, avec quatre formats dont un Dark Knight I de 5,75 × 54 pouces.","wrapper":"Connecticut Broadleaf maduro","force":null},{"name":"Excalibur Black","color":"#1F1A17","force":"Medium","wrapper":"Connecticut broadleaf","vitolas":[],"story":"Lancée en juin 2021 pour les 40 ans de la marque : cape Connecticut broadleaf, liant Sumatra d''Équateur, tripe hondurienne et nicaraguayenne, présentée comme medium et plus corsée que le mélange de base. Robusto 5 × 50, Toro 6 × 52, No. 1 7¼ × 54 pouces."}]',
  `gamme_en` = '[{"name":"Excalibur No. I","color":"#5C3317","story":"The line''s large format; in Excalibur Black it measures 7¼ × 54 inches (trade press, May 2021). The original line has a Connecticut shade wrapper.","wrapper":"Connecticut shade","force":null},{"name":"Excalibur Robusto","color":"#7A4520","story":"The Robusto, 5 × 50 inches in the Black line (trade press, May 2021); the original line has a Connecticut shade wrapper.","wrapper":"Connecticut shade","force":null},{"name":"Excalibur Dark Knight","color":"#2C1A0E","story":"Connecticut Broadleaf maduro wrapper (Stogie Review, 2007; Cigar Coop, 2012), not San Andrés. Released from the 1066 range in 2010 according to Cigar Coop, with four formats including a Dark Knight I of 5.75 × 54 inches.","wrapper":"Connecticut Broadleaf maduro","force":null},{"name":"Excalibur Black","color":"#1F1A17","force":"Medium","wrapper":"Connecticut broadleaf","vitolas":[],"story":"Launched in June 2021 for the brand''s 40th anniversary: Connecticut broadleaf wrapper, Ecuadorian Sumatra binder, Honduran and Nicaraguan filler, presented as medium and fuller-bodied than the base blend. Robusto 5 × 50, Toro 6 × 52, No. 1 7¼ × 54 inches."}]',
  `gamme_es` = '[{"name":"Excalibur No. I","color":"#5C3317","story":"El gran formato de la línea; en Excalibur Black mide 7¼ × 54 pulgadas (prensa del sector, mayo de 2021). La línea original lleva capa Connecticut shade.","wrapper":"Connecticut shade","force":null},{"name":"Excalibur Robusto","color":"#7A4520","story":"El Robusto, 5 × 50 pulgadas en la línea Black (prensa del sector, mayo de 2021); la línea original lleva capa Connecticut shade.","wrapper":"Connecticut shade","force":null},{"name":"Excalibur Dark Knight","color":"#2C1A0E","story":"Capa Connecticut Broadleaf maduro (Stogie Review, 2007; Cigar Coop, 2012), y no San Andrés. Salió de la gama 1066 en 2010 según Cigar Coop, con cuatro formatos, entre ellos un Dark Knight I de 5,75 × 54 pulgadas.","wrapper":"Connecticut Broadleaf maduro","force":null},{"name":"Excalibur Black","color":"#1F1A17","force":"Medium","wrapper":"Connecticut broadleaf","vitolas":[],"story":"Lanzada en junio de 2021 por los 40 años de la marca: capa Connecticut broadleaf, capote Sumatra de Ecuador, tripa hondureña y nicaragüense, presentada como media y más potente que la mezcla base. Robusto 5 × 50, Toro 6 × 52, No. 1 7¼ × 54 pulgadas."}]',
  `gamme_de` = '[{"name":"Excalibur No. I","color":"#5C3317","story":"Das große Format der Linie; in der Excalibur Black misst es 7¼ × 54 Zoll (Fachpresse, Mai 2021). Die ursprüngliche Linie hat ein Deckblatt Connecticut Shade.","wrapper":"Connecticut Shade","force":null},{"name":"Excalibur Robusto","color":"#7A4520","story":"Der Robusto, 5 × 50 Zoll in der Linie Black (Fachpresse, Mai 2021); die ursprüngliche Linie hat ein Deckblatt Connecticut Shade.","wrapper":"Connecticut Shade","force":null},{"name":"Excalibur Dark Knight","color":"#2C1A0E","story":"Deckblatt Connecticut Broadleaf Maduro (Stogie Review, 2007; Cigar Coop, 2012), und nicht San Andrés. Laut Cigar Coop 2010 aus der Reihe 1066 hervorgegangen, mit vier Formaten, darunter ein Dark Knight I von 5,75 × 54 Zoll.","wrapper":"Connecticut Broadleaf Maduro","force":null},{"name":"Excalibur Black","color":"#1F1A17","force":"Medium","wrapper":"Connecticut Broadleaf","vitolas":[],"story":"Im Juni 2021 zum 40-jährigen Bestehen der Marke eingeführt: Deckblatt Connecticut Broadleaf, Umblatt Sumatra aus Ecuador, Einlage aus Honduras und Nicaragua; sie wird als mittelkräftig und kräftiger als die Basismischung vorgestellt. Robusto 5 × 50, Toro 6 × 52, No. 1 7¼ × 54 Zoll."}]',
  `gamme_zh` = '[{"name":"Excalibur No. I","color":"#5C3317","story":"该系列的大尺寸规格；在 Excalibur Black 中为 7¼ × 54 英寸（行业媒体，2021年5月）。原版系列采用 Connecticut shade 茄衣。","wrapper":"Connecticut shade","force":null},{"name":"Excalibur Robusto","color":"#7A4520","story":"Robusto，在 Black 系列中为 5 × 50 英寸（行业媒体，2021年5月）；原版系列采用 Connecticut shade 茄衣。","wrapper":"Connecticut shade","force":null},{"name":"Excalibur Dark Knight","color":"#2C1A0E","story":"Connecticut Broadleaf maduro 茄衣（Stogie Review，2007年；Cigar Coop，2012年），而非 San Andrés。据 Cigar Coop，2010年自 1066 系列推出，共有四种规格，其中一款 Dark Knight I 为 5.75 × 54 英寸。","wrapper":"Connecticut Broadleaf maduro","force":null},{"name":"Excalibur Black","color":"#1F1A17","force":"Medium","wrapper":"Connecticut broadleaf","vitolas":[],"story":"2021年6月为纪念品牌40周年而推出：Connecticut broadleaf 茄衣，厄瓜多尔 Sumatra 茄套，洪都拉斯与尼加拉瓜茄芯，被定位为中等浓度，且比基础配方更浓郁。Robusto 5 × 50，Toro 6 × 52，No. 1 7¼ × 54 英寸。"}]',
  `gamme_ar` = '[{"name":"Excalibur No. I","color":"#5C3317","story":"الحجم الكبير في الخط؛ وفي Excalibur Black يبلغ 7¼ × 54 بوصة (الصحافة المتخصصة، أيار/مايو 2021). والخط الأصلي بغلاف Connecticut shade.","wrapper":"Connecticut shade","force":null},{"name":"Excalibur Robusto","color":"#7A4520","story":"Robusto، بقياس 5 × 50 بوصة في خط Black (الصحافة المتخصصة، أيار/مايو 2021)؛ والخط الأصلي بغلاف Connecticut shade.","wrapper":"Connecticut shade","force":null},{"name":"Excalibur Dark Knight","color":"#2C1A0E","story":"غلاف Connecticut Broadleaf maduro (Stogie Review، 2007؛ Cigar Coop، 2012)، لا San Andrés. خرج من مجموعة 1066 سنة 2010 بحسب Cigar Coop، بأربعة أحجام منها Dark Knight I بقياس 5,75 × 54 بوصة.","wrapper":"Connecticut Broadleaf maduro","force":null},{"name":"Excalibur Black","color":"#1F1A17","force":"Medium","wrapper":"Connecticut broadleaf","vitolas":[],"story":"أُطلق في حزيران/يونيو 2021 بمناسبة مرور 40 سنة على العلامة: غلاف Connecticut broadleaf، وغلاف داخلي Sumatra من الإكوادور، وحشوة هندوراسية ونيكاراغوية، ويُقدَّم على أنه متوسط وأشدّ قوةً من الخلطة الأساسية. Robusto 5 × 50 وToro 6 × 52 وNo. 1 7¼ × 54 بوصة."}]',
  `celebrities` = '[{"name":"Frank Llaneza","anecdote":"Président de Villazon & Co., qui faisait les Punch et Hoyo de Monterrey non cubains ; la presse du métier le compte parmi les premiers à avoir fait des cigares premium au Honduras. Il dit y être venu pour la première fois en 1960. Mort en 2010, il avait récemment créé pour Altadis U.S.A. les Siglo et Frank Llaneza 1961, roulés au Nicaragua."}]',
  `celebrities_en` = '[{"name":"Frank Llaneza","anecdote":"President of Villazon & Co., which made the non-Cuban Punch and Hoyo de Monterrey; the trade press counts him among the first to have made premium cigars in Honduras. He says he first went there in 1960. He died in 2010, having recently created for Altadis U.S.A. the Siglo and Frank Llaneza 1961, rolled in Nicaragua."}]',
  `celebrities_es` = '[{"name":"Frank Llaneza","anecdote":"Presidente de Villazon & Co., que hacía los Punch y Hoyo de Monterrey no cubanos; la prensa del sector lo cuenta entre los primeros en haber hecho puros premium en Honduras. Dice haber ido allí por primera vez en 1960. Fallecido en 2010, había creado hacía poco para Altadis U.S.A. los Siglo y Frank Llaneza 1961, liados en Nicaragua."}]',
  `celebrities_de` = '[{"name":"Frank Llaneza","anecdote":"Präsident von Villazon & Co., das die nichtkubanischen Punch und Hoyo de Monterrey herstellte; die Fachpresse zählt ihn zu den Ersten, die in Honduras Premiumzigarren gemacht haben. Er sagt, er sei 1960 zum ersten Mal dorthin gekommen. Er starb 2010; kurz zuvor hatte er für Altadis U.S.A. die Siglo und Frank Llaneza 1961 geschaffen, in Nicaragua gerollt."}]',
  `celebrities_zh` = '[{"name":"Frank Llaneza","anecdote":"Villazon & Co. 的总裁，该公司生产非古巴的 Punch 与 Hoyo de Monterrey；行业媒体将他列为在洪都拉斯制作高端雪茄的首批人物之一。他自称1960年首次前往当地。他于2010年去世，不久前刚为 Altadis U.S.A. 创制了 Siglo 与 Frank Llaneza 1961，均在尼加拉瓜卷制。"}]',
  `celebrities_ar` = '[{"name":"Frank Llaneza","anecdote":"رئيس Villazon & Co. التي كانت تصنع Punch وHoyo de Monterrey غير الكوبيين؛ وتعدّه الصحافة المتخصصة من أوائل من صنعوا السيجار الفاخر في هندوراس. ويقول إنه ذهب إليها أول مرة سنة 1960. وقد توفي سنة 2010، وكان قد أنشأ حديثًا لحساب Altadis U.S.A. سيجار Siglo وFrank Llaneza 1961، يُلفّان في نيكاراغوا."}]',
  `pairings` = '[]',
  `pairings_en` = '[]',
  `pairings_es` = '[]',
  `pairings_de` = '[]',
  `pairings_zh` = '[]',
  `pairings_ar` = '[]',
  `source` = IF(LOCATE(CAST('cigaraficionado.com « Hoyo Excalibur Celebrates 40 Years » (mai 2021 : « turns 40 this year », donc 1981 ; fabriquée à la HATSA de Danlí par General Cigar, filiale du Scandinavian Tobacco Group) et « Frank Llaneza: 1920—2010 » (Villazon vendue à General Cigar en 1997 pour 81,4 M$) ; famous-smoke.com / Cigar Advisor pour la citation de Dan Blumenthal et la date de 1992 comme ligne Hoyo ; en.wikipedia.org « Hoyo de Monterrey » pour le rachat des lignes Palicio' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'cigaraficionado.com « Hoyo Excalibur Celebrates 40 Years » (mai 2021 : « turns 40 this year », donc 1981 ; fabriquée à la HATSA de Danlí par General Cigar, filiale du Scandinavian Tobacco Group) et « Frank Llaneza: 1920—2010 » (Villazon vendue à General Cigar en 1997 pour 81,4 M$) ; famous-smoke.com / Cigar Advisor pour la citation de Dan Blumenthal et la date de 1992 comme ligne Hoyo ; en.wikipedia.org « Hoyo de Monterrey » pour le rachat des lignes Palicio', ''), `source`),
  `source` = IF(LOCATE(CAST('cigaraficionado.com « Hoyo Excalibur Celebrates 40 Years wit' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigaraficionado.com « Hoyo Excalibur Celebrates 40 Years with Excalibur Black » (13 mai 2021 : marque qui « turns 40 in 2021 », HATSA de Danlí, General Cigar / STG, Black en trois formats) ; « Dion Giolito and STG collaborate on Excalibur Illusione » (9 juin 2022 : Villazon a créé la marque, rachetée par General Cigar ; édition limitée roulée chez Aganorsa Leaf) ; « Daniel Blumenthal dies at 94 » (22 août 2011 : vente de Punch et Hoyo à General Cigar en 1997) ; « Cigar Profiles : Frank Llaneza of Villazon » (numéro janv.-févr. 1999 : filiale depuis 1996, 91 M$, Honduras en 1960) ; « Frank Llaneza: 1920—2010 » (19 mars 2010 : premier à faire des premium au Honduras, Siglo et Frank Llaneza 1961 au Nicaragua) ; cigar-coop.com « Cigar Review: Hoyo de Monterrey Excalibur Dark Knight » (26 février 2012 : années 1970, Dark Knight séparé de la 1066 en 2010, cape Connecticut Broadleaf, fabrique à Cofradía) ; stogiereview.com « Excalibur 1066 Dark Knight » (26 mars 2007 : cape Connecticut Broadleaf maduro) ; en.wikipedia.org « Hoyo de Monterrey » (Palicio cède ses lignes à la famille Villazon ; page à source unique)')),
  `updated_at` = NOW()
 WHERE `name` = 'Excalibur';

-- ── Santa Damiana ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Santa Damiana incarne une proposition rare dans l''industrie du cigare premium : la douceur comme valeur absolue, sans concession à la mode de la puissance qui domine le marché depuis les années 1990. Fondée en 1993 à La Romana, la marque fut créée par Hendrik Kelner — l''assembleur de la Tabacalera de García — pour une clientèle cherchant l''élégance sans intensité.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Santa Damiana incarne une proposition rare dans l''industrie du cigare premium : la douceur comme valeur absolue, sans concession à la mode de la puissance qui domine le marché depuis les années 1990. Fondée en 1993 à La Romana, la marque fut créée par Hendrik Kelner — l''assembleur de la Tabacalera de García — pour une clientèle cherchant l''élégance sans intensité.', 'Santa Damiana est une marque dominicaine de cigares roulés à la main, produits à la Tabacalera de García, à La Romana. Selon cigarworld.de (octobre 2026), sa percée date de 1992 avec son premier cigare. Des détaillants (timecigar.com) la disent héritée de Cuba, sans année ni fabrique cubaine.'), `history`),
  `history_en` = IF(LOCATE(CAST('Santa Damiana embodies a rare proposition in the premium cigar industry: softness as an absolute value, without concession to the power trend that has dominated the market since the 1990s. Founded in 1993 in La Romana, the brand was created by Hendrik Kelner — the legendary blender of Tabacalera de García — for a clientele seeking elegance without intensity.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Santa Damiana embodies a rare proposition in the premium cigar industry: softness as an absolute value, without concession to the power trend that has dominated the market since the 1990s. Founded in 1993 in La Romana, the brand was created by Hendrik Kelner — the legendary blender of Tabacalera de García — for a clientele seeking elegance without intensity.', 'Santa Damiana is a Dominican brand of hand-rolled cigars, produced at the Tabacalera de García in La Romana. According to cigarworld.de (October 2026), its breakthrough dates from 1992 with its first cigar. Retailers (timecigar.com) say it is inherited from Cuba, with no year and no Cuban factory given.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Santa Damiana encarna una propuesta poco frecuente en la industria del puro premium: la suavidad como valor absoluto, sin concesiones a la moda de la potencia que domina el mercado desde los años noventa. Nacida en 1993 en La Romana, la marca fue creada por Hendrik Kelner —el legendario maestro ligador de la Tabacalera de García— para un público que buscaba elegancia sin intensidad.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Santa Damiana encarna una propuesta poco frecuente en la industria del puro premium: la suavidad como valor absoluto, sin concesiones a la moda de la potencia que domina el mercado desde los años noventa. Nacida en 1993 en La Romana, la marca fue creada por Hendrik Kelner —el legendario maestro ligador de la Tabacalera de García— para un público que buscaba elegancia sin intensidad.', 'Santa Damiana es una marca dominicana de puros liados a mano, producidos en la Tabacalera de García, en La Romana. Según cigarworld.de (octubre de 2026), su despegue data de 1992 con su primer puro. Algunos minoristas (timecigar.com) la dicen heredada de Cuba, sin año ni fábrica cubana.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Santa Damiana verkörpert ein seltenes Angebot in der Premium-Zigarrenbranche: Milde als absoluter Wert, ohne Zugeständnis an die Kraftmode, die den Markt seit den 1990er Jahren beherrscht. Die 1993 in La Romana gegründete Marke wurde von Hendrik Kelner — dem legendären Blender der Tabacalera de García — für eine Kundschaft geschaffen, die Eleganz ohne Intensität sucht.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Santa Damiana verkörpert ein seltenes Angebot in der Premium-Zigarrenbranche: Milde als absoluter Wert, ohne Zugeständnis an die Kraftmode, die den Markt seit den 1990er Jahren beherrscht. Die 1993 in La Romana gegründete Marke wurde von Hendrik Kelner — dem legendären Blender der Tabacalera de García — für eine Kundschaft geschaffen, die Eleganz ohne Intensität sucht.', 'Santa Damiana ist eine dominikanische Marke handgerollter Zigarren, hergestellt in der Tabacalera de García in La Romana. Laut cigarworld.de (Oktober 2026) stammt ihr Durchbruch von 1992 mit ihrer ersten Zigarre. Händler (timecigar.com) bezeichnen sie als von Kuba geerbt, ohne Jahr und ohne kubanische Fabrik.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('在高端雪茄行业里，Santa Damiana 代表着一种少见的主张：把柔和当作绝对价值，绝不迎合自 1990 年代以来主导市场的强度潮流。品牌 1993 年创立于 La Romana，由 Tabacalera de García 的传奇调配师 Hendrik Kelner 为追求优雅而非强度的顾客而创。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '在高端雪茄行业里，Santa Damiana 代表着一种少见的主张：把柔和当作绝对价值，绝不迎合自 1990 年代以来主导市场的强度潮流。品牌 1993 年创立于 La Romana，由 Tabacalera de García 的传奇调配师 Hendrik Kelner 为追求优雅而非强度的顾客而创。', 'Santa Damiana 是一个多米尼加手工卷制雪茄品牌，在 La Romana 的 Tabacalera de García 生产。据 cigarworld.de（2026年10月），其突破始于1992年，凭借的是首支雪茄。零售商（timecigar.com）称它承自古巴，但未给出年份，也未提及古巴的工厂。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تجسّد Santa Damiana طرحاً نادراً في صناعة السيجار الفاخر: النعومة قيمةً مطلقة، دون أي تنازل لموضة القوة التي تسيطر على السوق منذ التسعينيات. تأسّست العلامة عام 1993 في La Romana على يد Hendrik Kelner — خبير الخلطات الأسطوري في Tabacalera de García — لزبائن يبحثون عن الأناقة دون شدّة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تجسّد Santa Damiana طرحاً نادراً في صناعة السيجار الفاخر: النعومة قيمةً مطلقة، دون أي تنازل لموضة القوة التي تسيطر على السوق منذ التسعينيات. تأسّست العلامة عام 1993 في La Romana على يد Hendrik Kelner — خبير الخلطات الأسطوري في Tabacalera de García — لزبائن يبحثون عن الأناقة دون شدّة.', 'Santa Damiana علامة دومينيكية للسيجار الملفوف يدويًا، تُنتج في Tabacalera de García بمدينة La Romana. وبحسب cigarworld.de (تشرين الأول/أكتوبر 2026)، يعود بروزها إلى سنة 1992 مع أول سيجار لها. ويقول بائعون (timecigar.com) إنها موروثة من كوبا، دون ذكر سنة ولا مصنع كوبي.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Santa Damiana';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La philosophie Santa Damiana est explicitement anti-mode. Alors que les années 2000 virent une course généralisée vers les assemblages plus forts, plus nicaraguayens, plus maduro, la marque maintint sa position de référence dans le registre doux à moyen : cape Connecticut Shade, assemblage dominicain équilibré, force légère à médium.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La philosophie Santa Damiana est explicitement anti-mode. Alors que les années 2000 virent une course généralisée vers les assemblages plus forts, plus nicaraguayens, plus maduro, la marque maintint sa position de référence dans le registre doux à moyen : cape Connecticut Shade, assemblage dominicain équilibré, force légère à médium.', 'Les détaillants la présentent dans un registre doux à moyen, avec une cape Connecticut blonde et une liaison dominicaine (timecigar.com, zigarrenversand.ch, octobre 2026). Cigarworld.de décrit aujourd''hui deux séries, dont la Classic, et des formats variés.'), `history`),
  `history_en` = IF(LOCATE(CAST('Santa Damiana''s philosophy is explicitly anti-trend. While the 2000s saw a generalized race toward stronger, more Nicaraguan, more maduro blends, the brand maintained its reference position in the soft-medium register: Connecticut Shade wrapper, balanced Dominican blend, light to medium strength.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Santa Damiana''s philosophy is explicitly anti-trend. While the 2000s saw a generalized race toward stronger, more Nicaraguan, more maduro blends, the brand maintained its reference position in the soft-medium register: Connecticut Shade wrapper, balanced Dominican blend, light to medium strength.', 'Retailers present it in a mild to medium register, with a blond Connecticut wrapper and a Dominican binder (timecigar.com, zigarrenversand.ch, October 2026). Cigarworld.de now describes two series, including the Classic, and a variety of formats.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La filosofía de Santa Damiana es explícitamente contraria a la moda. Mientras los años dos mil vieron una carrera generalizada hacia ligadas más fuertes, más nicaragüenses, más maduro, la marca mantuvo su posición de referente en el registro suave-medio: capa Connecticut Shade, ligada dominicana equilibrada, fuerza de ligera a media.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La filosofía de Santa Damiana es explícitamente contraria a la moda. Mientras los años dos mil vieron una carrera generalizada hacia ligadas más fuertes, más nicaragüenses, más maduro, la marca mantuvo su posición de referente en el registro suave-medio: capa Connecticut Shade, ligada dominicana equilibrada, fuerza de ligera a media.', 'Los minoristas la presentan en un registro suave a medio, con capa Connecticut rubia y capote dominicano (timecigar.com, zigarrenversand.ch, octubre de 2026). Cigarworld.de describe hoy dos series, entre ellas la Classic, y formatos variados.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Philosophie von Santa Damiana ist ausdrücklich gegen die Mode gerichtet. Während die 2000er Jahre einen allgemeinen Wettlauf zu stärkeren, stärker nicaraguanisch geprägten, dunkleren Maduro-Mischungen erlebten, behauptete die Marke ihren Rang im mild-mittleren Register: Connecticut-Shade-Deckblatt, ausgewogene dominikanische Mischung, leichte bis mittlere Stärke.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Philosophie von Santa Damiana ist ausdrücklich gegen die Mode gerichtet. Während die 2000er Jahre einen allgemeinen Wettlauf zu stärkeren, stärker nicaraguanisch geprägten, dunkleren Maduro-Mischungen erlebten, behauptete die Marke ihren Rang im mild-mittleren Register: Connecticut-Shade-Deckblatt, ausgewogene dominikanische Mischung, leichte bis mittlere Stärke.', 'Händler präsentieren sie im milden bis mittleren Bereich, mit blondem Connecticut-Deckblatt und dominikanischem Umblatt (timecigar.com, zigarrenversand.ch, Oktober 2026). Cigarworld.de beschreibt heute zwei Serien, darunter die Classic, und unterschiedliche Formate.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Santa Damiana 的理念明确反潮流。2000 年代业界普遍竞相追逐更浓、更尼加拉瓜化、更 Maduro 的配方，它却守住了柔和至中度这一区间的标杆位置：Connecticut Shade 茄衣、均衡的多米尼加配方、轻至中度的强度。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Santa Damiana 的理念明确反潮流。2000 年代业界普遍竞相追逐更浓、更尼加拉瓜化、更 Maduro 的配方，它却守住了柔和至中度这一区间的标杆位置：Connecticut Shade 茄衣、均衡的多米尼加配方、轻至中度的强度。', '零售商把它归在柔和至中等的区间，配浅色 Connecticut 茄衣与多米尼加茄套（timecigar.com；zigarrenversand.ch；2026年10月）。如今 cigarworld.de 介绍了两个系列，其中包括 Classic，规格多样。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('فلسفة Santa Damiana معادية للموضة صراحةً. فبينما شهدت الألفية سباقاً عاماً نحو خلطات أقوى وأكثر نيكاراغوية وأشدّ ميلاً إلى الـ Maduro، حافظت العلامة على موقعها المرجعي في المستوى الناعم–المتوسط: غلاف Connecticut Shade، وخلطة دومينيكية متوازنة، وقوة خفيفة إلى متوسطة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'فلسفة Santa Damiana معادية للموضة صراحةً. فبينما شهدت الألفية سباقاً عاماً نحو خلطات أقوى وأكثر نيكاراغوية وأشدّ ميلاً إلى الـ Maduro، حافظت العلامة على موقعها المرجعي في المستوى الناعم–المتوسط: غلاف Connecticut Shade، وخلطة دومينيكية متوازنة، وقوة خفيفة إلى متوسطة.', 'يعرضها البائعون في مستوى ناعم إلى متوسط، بغلاف Connecticut أشقر وغلاف داخلي دومينيكي (timecigar.com وzigarrenversand.ch، تشرين الأول/أكتوبر 2026). ويصف cigarworld.de اليوم سلسلتين، منهما Classic، وأحجامًا متنوعة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Santa Damiana';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Ce conservatisme apparent cache une sophistication réelle. Comme Kelner lui-même l''a dit publiquement : "Construire un cigare intéressant sans puissance est techniquement plus difficile que d''assembler une bombe aromatique. Avec la puissance, on peut cacher beaucoup d''erreurs." La constance de Santa Damiana sur trois décennies valide cette affirmation.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Ce conservatisme apparent cache une sophistication réelle. Comme Kelner lui-même l''a dit publiquement : "Construire un cigare intéressant sans puissance est techniquement plus difficile que d''assembler une bombe aromatique. Avec la puissance, on peut cacher beaucoup d''erreurs." La constance de Santa Damiana sur trois décennies valide cette affirmation.', 'La Tabacalera de García est, selon la presse du métier (2019), le cœur de la production de Tabacalera USA, filiale américaine d''Imperial Brands, qui a repris Altadis en 2007.'), `history`),
  `history_en` = IF(LOCATE(CAST('This apparent conservatism conceals real sophistication. As Kelner himself has stated publicly: "Building an interesting cigar without power is technically more difficult than assembling an aromatic bomb. With power, you can hide many mistakes." Santa Damiana''s consistency over three decades validates this claim.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'This apparent conservatism conceals real sophistication. As Kelner himself has stated publicly: "Building an interesting cigar without power is technically more difficult than assembling an aromatic bomb. With power, you can hide many mistakes." Santa Damiana''s consistency over three decades validates this claim.', 'The Tabacalera de García is, according to the trade press (2019), the heart of the production of Tabacalera USA, the American subsidiary of Imperial Brands, which took over Altadis in 2007.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Ese conservadurismo aparente esconde una sofisticación real. Como el propio Kelner ha dicho públicamente: "Construir un puro interesante sin potencia es técnicamente más difícil que montar una bomba aromática. Con la potencia se pueden esconder muchos errores." La constancia de Santa Damiana a lo largo de tres décadas valida esa afirmación.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Ese conservadurismo aparente esconde una sofisticación real. Como el propio Kelner ha dicho públicamente: "Construir un puro interesante sin potencia es técnicamente más difícil que montar una bomba aromática. Con la potencia se pueden esconder muchos errores." La constancia de Santa Damiana a lo largo de tres décadas valida esa afirmación.', 'La Tabacalera de García es, según la prensa del sector (2019), el corazón de la producción de Tabacalera USA, filial estadounidense de Imperial Brands, que adquirió Altadis en 2007.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Dieser scheinbare Konservatismus verbirgt eine echte Raffinesse. Kelner selbst hat es öffentlich gesagt: „Eine interessante Zigarre ohne Kraft zu bauen ist technisch schwieriger, als eine Aromabombe zusammenzustellen. Mit Kraft lassen sich viele Fehler verbergen.“ Die Beständigkeit von Santa Damiana über drei Jahrzehnte bestätigt diesen Satz.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Dieser scheinbare Konservatismus verbirgt eine echte Raffinesse. Kelner selbst hat es öffentlich gesagt: „Eine interessante Zigarre ohne Kraft zu bauen ist technisch schwieriger, als eine Aromabombe zusammenzustellen. Mit Kraft lassen sich viele Fehler verbergen.“ Die Beständigkeit von Santa Damiana über drei Jahrzehnte bestätigt diesen Satz.', 'Die Tabacalera de García ist laut Fachpresse (2019) das Herz der Produktion von Tabacalera USA, der US-Tochter von Imperial Brands, die 2007 Altadis übernommen hat.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这份看似保守的坚持，藏着真正的功力。正如 Kelner 本人公开所说：「不靠强度造出一支有趣的雪茄，技术上比调配一枚香气炸弹更难。有了强度，很多错误都能藏起来。」Santa Damiana 三十年的一贯水准，印证了这句话。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这份看似保守的坚持，藏着真正的功力。正如 Kelner 本人公开所说：「不靠强度造出一支有趣的雪茄，技术上比调配一枚香气炸弹更难。有了强度，很多错误都能藏起来。」Santa Damiana 三十年的一贯水准，印证了这句话。', '据行业媒体（2019年），Tabacalera de García 是 Tabacalera USA 生产的核心；Tabacalera USA 是 Imperial Brands 的美国子公司，后者于2007年接手 Altadis。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وهذه المحافظة الظاهرية تخفي رهافة حقيقية. وكما قال Kelner نفسه علناً: «صناعة سيجار مثير للاهتمام بلا قوة أصعب تقنياً من تركيب قنبلة عطرية. فمع القوة يمكن إخفاء أخطاء كثيرة.» وثبات Santa Damiana على مدى ثلاثة عقود يصدّق هذا القول.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وهذه المحافظة الظاهرية تخفي رهافة حقيقية. وكما قال Kelner نفسه علناً: «صناعة سيجار مثير للاهتمام بلا قوة أصعب تقنياً من تركيب قنبلة عطرية. فمع القوة يمكن إخفاء أخطاء كثيرة.» وثبات Santa Damiana على مدى ثلاثة عقود يصدّق هذا القول.', 'بحسب الصحافة المتخصصة (2019)، تُعدّ Tabacalera de García قلب إنتاج Tabacalera USA، الشركة التابعة الأمريكية لمجموعة Imperial Brands التي استحوذت على Altadis سنة 2007.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Santa Damiana';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Les amateurs de golf ont particulièrement adopté Santa Damiana : léger pour les 18 trous, construit pour le plein air, prix accessible pour une consommation quotidienne. Cette association avec le golf premium américain et européen a donné à la marque une visibilité dans les country clubs qui dépasse largement sa présence dans les cigar bars traditionnels.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Les amateurs de golf ont particulièrement adopté Santa Damiana : léger pour les 18 trous, construit pour le plein air, prix accessible pour une consommation quotidienne. Cette association avec le golf premium américain et européen a donné à la marque une visibilité dans les country clubs qui dépasse largement sa présence dans les cigar bars traditionnels.', 'Cigarworld.de décrit une cape Connecticut sur une marque proposée en deux séries et en cigarillos.'), `history`),
  `history_en` = IF(LOCATE(CAST('Golf enthusiasts have particularly adopted Santa Damiana: light for 18 holes, built for the outdoors, accessible pricing for daily consumption. This association with American and European premium golf has given the brand visibility in country clubs that far exceeds its presence in traditional cigar bars.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Golf enthusiasts have particularly adopted Santa Damiana: light for 18 holes, built for the outdoors, accessible pricing for daily consumption. This association with American and European premium golf has given the brand visibility in country clubs that far exceeds its presence in traditional cigar bars.', 'Cigarworld.de describes a Connecticut wrapper on a brand offered in two series and in cigarillos.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Los aficionados al golf han adoptado especialmente Santa Damiana: ligero para los 18 hoyos, pensado para el aire libre, de precio asequible para un consumo diario. Esa asociación con el golf premium estadounidense y europeo ha dado a la marca una visibilidad en los country clubs que supera con mucho su presencia en los cigar bars tradicionales.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Los aficionados al golf han adoptado especialmente Santa Damiana: ligero para los 18 hoyos, pensado para el aire libre, de precio asequible para un consumo diario. Esa asociación con el golf premium estadounidense y europeo ha dado a la marca una visibilidad en los country clubs que supera con mucho su presencia en los cigar bars tradicionales.', 'Cigarworld.de describe una capa Connecticut en una marca ofrecida en dos series y en cigarillos.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Besonders Golfspieler haben Santa Damiana angenommen: leicht für die 18 Löcher, für die frische Luft gemacht, im Preis für den täglichen Genuss erschwinglich. Diese Verbindung mit dem amerikanischen und europäischen Premiumgolf hat der Marke in den Countryclubs eine Sichtbarkeit verschafft, die ihre Präsenz in den klassischen Zigarrenbars weit übertrifft.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Besonders Golfspieler haben Santa Damiana angenommen: leicht für die 18 Löcher, für die frische Luft gemacht, im Preis für den täglichen Genuss erschwinglich. Diese Verbindung mit dem amerikanischen und europäischen Premiumgolf hat der Marke in den Countryclubs eine Sichtbarkeit verschafft, die ihre Präsenz in den klassischen Zigarrenbars weit übertrifft.', 'Cigarworld.de beschreibt ein Connecticut-Deckblatt bei einer Marke, die in zwei Serien und als Zigarillos angeboten wird.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('高尔夫爱好者尤其钟爱 Santa Damiana：打完 18 洞不觉负担，为户外而生，价格也适合日常消费。它与美欧高端高尔夫的这层关联，使品牌在乡村俱乐部中的曝光度，远远超过它在传统雪茄吧里的存在感。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '高尔夫爱好者尤其钟爱 Santa Damiana：打完 18 洞不觉负担，为户外而生，价格也适合日常消费。它与美欧高端高尔夫的这层关联，使品牌在乡村俱乐部中的曝光度，远远超过它在传统雪茄吧里的存在感。', 'cigarworld.de 介绍这一品牌采用 Connecticut 茄衣，提供两个系列以及小雪茄。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وقد تبنّى هواة الغولف Santa Damiana على وجه الخصوص: خفيف يرافق الحفر الثمانية عشر، مصنوع للهواء الطلق، وسعره في متناول الاستهلاك اليومي. وقد منح هذا الارتباط بغولف النخبة في أمريكا وأوروبا العلامةَ حضوراً في نوادي الريف يفوق كثيراً حضورها في بارات السيجار التقليدية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وقد تبنّى هواة الغولف Santa Damiana على وجه الخصوص: خفيف يرافق الحفر الثمانية عشر، مصنوع للهواء الطلق، وسعره في متناول الاستهلاك اليومي. وقد منح هذا الارتباط بغولف النخبة في أمريكا وأوروبا العلامةَ حضوراً في نوادي الريف يفوق كثيراً حضورها في بارات السيجار التقليدية.', 'يصف cigarworld.de غلاف Connecticut على علامة تُعرض في سلسلتين وبصيغة سيجاريلو.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Santa Damiana';

