  `limited_eds` = '["Santa Damiana 30 Aniversario"]',
  `founded` = '1992 selon cigarworld.de — La Romana (RD)',
  `factory` = 'Tabacalera de García, La Romana, République dominicaine (dit cigarworld.de, octobre 2026)',
  `gamme` = '[{"name":"Santa Damiana Classic","color":"#D4A96A","story":"Série principale selon cigarworld.de (octobre 2026) : cape Connecticut, liaison dominicaine, roulée à la Tabacalera de García. Des détaillants la décrivent douce à moyenne.","wrapper":"Connecticut","force":"Mild-Medium"}]',
  `gamme_en` = '[{"name":"Santa Damiana Classic","color":"#D4A96A","story":"Main series according to cigarworld.de (October 2026): Connecticut wrapper, Dominican binder, rolled at the Tabacalera de García. Retailers describe it as mild to medium.","wrapper":"Connecticut","force":"Mild-Medium"}]',
