  `gamme_de` = '[{"name":"Santa Damiana Classic","color":"#D4A96A","story":"Hauptserie laut cigarworld.de (Oktober 2026): Connecticut-Deckblatt, dominikanisches Umblatt, gerollt in der Tabacalera de García. Händler beschreiben sie als mild bis mittelkräftig.","wrapper":"Connecticut","force":"Mild-Medium"}]',
  `gamme_zh` = '[{"name":"Santa Damiana Classic","color":"#D4A96A","story":"主打系列（据 cigarworld.de，2026年10月）：Connecticut 茄衣，多米尼加茄套，在 Tabacalera de García 卷制。零售商称其柔和至中等。","wrapper":"Connecticut","force":"Mild-Medium"}]',
  `gamme_ar` = '[{"name":"Santa Damiana Classic","color":"#D4A96A","story":"السلسلة الرئيسية بحسب cigarworld.de (تشرين الأول/أكتوبر 2026): غلاف Connecticut وغلاف داخلي دومينيكي، تُلَفّ في Tabacalera de García. ويصفها بائعون بأنها ناعمة إلى متوسطة.","wrapper":"Connecticut","force":"Mild-Medium"}]',
  `celebrities` = '[]',
  `celebrities_en` = '[]',
  `celebrities_es` = '[]',
  `celebrities_de` = '[]',
  `celebrities_zh` = '[]',
  `celebrities_ar` = '[]',
  `pairings` = '[]',
  `pairings_en` = '[]',
  `pairings_es` = '[]',
  `pairings_de` = '[]',
  `pairings_zh` = '[]',
  `pairings_ar` = '[]',
  `source` = IF(LOCATE(CAST('cigarjournal.com et cigarworld.de (relancée en 1993 à la Tabacalera de García ; le nom vient d''une plantation cubaine du XIXᵉ siècle)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'cigarjournal.com et cigarworld.de (relancée en 1993 à la Tabacalera de García ; le nom vient d''une plantation cubaine du XIXᵉ siècle)', 'cigarworld.de « Santa Damiana: Buy Cigars and Cigarillos » (octobre 2026 : Tabacalera de García, percée en 1992, deux séries, Connecticut) ; timecigar.com « Santa Damiana Cigar » (octobre 2026 : héritée de Cuba, cape Connecticut blonde) ; cigaraficionado.com « 50 years a factory » (mai/juin 2019 : Tabacalera de García, Tabacalera USA, Imperial Brands)'), `source`),
  `source` = IF(LOCATE(CAST('cigarinspector.com « Santa Damiana 30 Aniversario » (titre v' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigarinspector.com « Santa Damiana 30 Aniversario » (titre vu en résultat de recherche, non lu : édition pour les 30 ans de la marque)')),
  `updated_at` = NOW()
 WHERE `name` = 'Santa Damiana';

-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` WHEN 'pairings' THEN b.`pairings` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'Camacho' hote, 'celebrities' champ
        UNION ALL SELECT 'Camacho' hote, 'gamme' champ
        UNION ALL SELECT 'Camacho' hote, 'history' champ
        UNION ALL SELECT 'Joya de Nicaragua' hote, 'celebrities' champ
        UNION ALL SELECT 'Joya de Nicaragua' hote, 'gamme' champ
        UNION ALL SELECT 'Joya de Nicaragua' hote, 'history' champ
        UNION ALL SELECT 'Joya de Nicaragua' hote, 'pairings' champ
        UNION ALL SELECT 'La Flor Dominicana' hote, 'celebrities' champ
        UNION ALL SELECT 'La Flor Dominicana' hote, 'gamme' champ
        UNION ALL SELECT 'La Flor Dominicana' hote, 'history' champ
        UNION ALL SELECT 'La Flor Dominicana' hote, 'pairings' champ
        UNION ALL SELECT 'Avo' hote, 'celebrities' champ
        UNION ALL SELECT 'Avo' hote, 'gamme' champ
        UNION ALL SELECT 'Avo' hote, 'history' champ
        UNION ALL SELECT 'Avo' hote, 'pairings' champ
        UNION ALL SELECT 'Macanudo' hote, 'celebrities' champ
        UNION ALL SELECT 'Macanudo' hote, 'gamme' champ
        UNION ALL SELECT 'Macanudo' hote, 'history' champ
        UNION ALL SELECT 'Macanudo' hote, 'pairings' champ
        UNION ALL SELECT 'Zino Platinum' hote, 'gamme' champ
        UNION ALL SELECT 'Zino Platinum' hote, 'history' champ
        UNION ALL SELECT 'Zino Platinum' hote, 'pairings' champ
        UNION ALL SELECT 'Excalibur' hote, 'celebrities' champ
        UNION ALL SELECT 'Excalibur' hote, 'gamme' champ
        UNION ALL SELECT 'Excalibur' hote, 'history' champ
        UNION ALL SELECT 'Excalibur' hote, 'pairings' champ
        UNION ALL SELECT 'Santa Damiana' hote, 'celebrities' champ
        UNION ALL SELECT 'Santa Damiana' hote, 'gamme' champ
        UNION ALL SELECT 'Santa Damiana' hote, 'history' champ
        UNION ALL SELECT 'Santa Damiana' hote, 'pairings' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

