-- ── Contrôle : chaque ligne doit valoir 1 ──
SELECT 'Camacho' AS hote, 'fr' AS lang, 'limited_eds : Camacho Triple Maduro' AS quoi, (JSON_CONTAINS(`limited_eds`, '"Camacho Triple Maduro"')) AS ok FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'fr', 'limited_eds : Camacho Diploma', (JSON_CONTAINS(`limited_eds`, '"Camacho Diploma"')) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'fr', 'limited_eds : Camacho Liberty Series', (JSON_CONTAINS(`limited_eds`, '"Camacho Liberty Series"')) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'fr', 'founded', (CAST(`founded` AS BINARY) = CAST('1961, Miami (Simon Camacho)' AS BINARY)) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Diadema Cigars de Honduras, Danlí, Honduras (Oettinger Davidoff) ; American Barrel-Aged roulée en Rép. dominicaine' AS BINARY)) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Camacho est une marque fondée en 1961 par Simon Camacho, exilé cubain, à Miami, selon le communiqué d''Oettinger Davidoff du 13 octobre 2008 ; l''introduction de Wikipédia donne 1962. Simon Camacho meurt en 1990. La famille Eiroa, elle aussi issue de l''exil cubain et menée par Julio Eiroa, reprend la marque par sa société Caribe Imported Cigars : en 1994 selon le communiqué Davidoff, vers 1995 selon d''autres sources. La fabrication, jusque-là au Nicaragua, passe alors au Honduras, où les Eiroa possèdent des plantations.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La famille Camacho cultivait le corojo dans la Vuelta Abajo cubaine depuis des générations — non pas n''importe quel tabac, mais précisément cette variété dont les feuilles fournissent les capes qui ont donné aux grands havanes leur signature visuelle et aromatique. Sombre, huileuse, d''une texture régulière, elle donnait au cigare son aspect et son parfum reconnaissables entre tous. La cultiver était un métier à part, et les Camacho comptaient parmi ceux qui le maîtrisaient le mieux.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Camacho is a brand founded in 1961 in Miami by Simon Camacho, a Cuban exile, according to Oettinger Davidoff''s press release of 13 October 2008; the introduction to Wikipedia gives 1962. Simon Camacho died in 1990. The Eiroa family, also from the Cuban exile and led by Julio Eiroa, took over the brand through its company Caribe Imported Cigars: in 1994 according to the Davidoff press release, around 1995 according to other sources. Production, until then in Nicaragua, then moved to Honduras, where the Eiroas own plantations.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The Camacho family grew corojo tobacco in Cuba''s Vuelta Abajo region for generations — not any tobacco, but specifically the corojo varietal whose leaves provide the wrappers that gave Havana''s great cigars their visual and aromatic signature. Dark, oily, consistently textured, it gave Havana''s cigars their recognisable look and scent. Growing it was a specialized craft, and the Camachos were among its most accomplished practitioners.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Camacho es una marca fundada en 1961 en Miami por Simon Camacho, exiliado cubano, según el comunicado de Oettinger Davidoff del 13 de octubre de 2008; la introducción de Wikipedia da 1962. Simon Camacho muere en 1990. La familia Eiroa, también procedente del exilio cubano y dirigida por Julio Eiroa, retoma la marca a través de su empresa Caribe Imported Cigars: en 1994 según el comunicado de Davidoff, hacia 1995 según otras fuentes. La fabricación, hasta entonces en Nicaragua, pasa entonces a Honduras, donde los Eiroa poseen plantaciones.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La familia Camacho cultivaba el corojo en la Vuelta Abajo cubana desde hacía generaciones —no un tabaco cualquiera, sino precisamente esa variedad cuyas hojas dan las capas que confirieron a los grandes habanos su firma visual y aromática. Oscura, aceitosa, de textura regular, daba al puro su aspecto y su perfume reconocibles entre todos. Cultivarla era un oficio aparte, y los Camacho estaban entre quienes mejor lo dominaban.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Camacho ist eine Marke, die 1961 von Simon Camacho, einem kubanischen Exilanten, in Miami gegründet wurde, laut der Mitteilung von Oettinger Davidoff vom 13. Oktober 2008; die Einleitung von Wikipedia nennt 1962. Simon Camacho stirbt 1990. Die Familie Eiroa, ebenfalls aus dem kubanischen Exil stammend und von Julio Eiroa geführt, übernimmt die Marke über ihre Firma Caribe Imported Cigars: 1994 laut der Davidoff-Mitteilung, um 1995 laut anderen Quellen. Die Fertigung, bis dahin in Nicaragua, wechselt dann nach Honduras, wo die Eiroas Plantagen besitzen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Familie Camacho baute in der kubanischen Vuelta Abajo seit Generationen Corojo an — nicht irgendeinen Tabak, sondern eben jene Sorte, deren Blätter die Deckblätter liefern, die den großen Havannas ihre sichtbare und aromatische Handschrift gaben. Dunkel, ölig, von gleichmäßiger Textur, gab sie der Zigarre ihr unverwechselbares Aussehen und ihren Duft. Sie anzubauen war ein eigenes Handwerk, und die Camachos gehörten zu denen, die es am besten beherrschten.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Camacho 是一个品牌，据 Oettinger Davidoff 2008年10月13日的公告，由古巴流亡者 Simon Camacho 于1961年在迈阿密创立；维基百科的导言写作1962年。Simon Camacho 于1990年去世。同样出身古巴流亡者、由 Julio Eiroa 领导的 Eiroa 家族，通过其公司 Caribe Imported Cigars 接手该品牌：据 Davidoff 公告在1994年，据其他来源约在1995年。此前在尼加拉瓜的生产此时转到洪都拉斯，Eiroa 家在那里拥有种植园。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('卡马乔家族在古巴阿巴霍谷种植科罗霍已有数代人——不是随便什么烟草，而恰恰是那个品种：它的叶子提供的茄衣，赋予了伟大哈瓦那雪茄在外观与香气上的签名。颜色深、油润、质地匀整，它让雪茄有了一望即知的外形与气味。种它是一门单独的手艺，而卡马乔家是掌握得最好的那几家之一。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Camacho علامة أسّسها عام 1961 في ميامي Simon Camacho، المنفيّ الكوبي، بحسب بيان Oettinger Davidoff الصادر في 13 أكتوبر 2008؛ أما مقدّمة Wikipedia فتذكر 1962. وتوفي Simon Camacho عام 1990. وتتسلّم عائلة Eiroa، وهي أيضًا من المنفى الكوبي ويقودها Julio Eiroa، العلامة عبر شركتها Caribe Imported Cigars: عام 1994 بحسب بيان Davidoff، وحوالى 1995 بحسب مصادر أخرى. وكان التصنيع حتى ذلك الحين في نيكاراغوا، فانتقل حينئذٍ إلى هندوراس، حيث تملك عائلة Eiroa مزارع.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('كانت عائلة كاماتشو تزرع الكوروخو في فويلتا أباخو الكوبية منذ أجيال — لا أيّ تبغ، بل تحديدًا ذلك الصنف الذي تعطي أوراقه الأغلفة التي منحت الهافانا الكبرى توقيعها البصري والعطري. داكنة، زيتية، متساوية الملمس، كانت تمنح السيجار مظهره ورائحته اللذين يُعرفان من بين الجميع. وكانت زراعتها حرفةً قائمة بذاتها، وكان آل كاماتشو من أتقن الناس لها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Le tabac emblématique de la maison est le corojo cultivé dans la vallée de Jamastrán, au Honduras. Selon BespokeUnit, la graine de corojo est attribuée au Cubain Diego Rodriguez, dans les années 1940, puis replantée à Jamastrán après la nationalisation de l''industrie cubaine ; Camacho a ensuite cultivé ses propres graines. La ligne Camacho Corojo est faite de tabacs honduriens ; sa version BXP y ajoute du filler broadleaf de Pennsylvanie, selon la presse du métier en 2017.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La révolution cubaine referma ce chapitre en 1959. Le départ de Simon Camacho fut celui d''un homme emportant son identité professionnelle sous forme de semences — littéralement, s''agissant des plants de corojo dont il transporta la génétique jusqu''à Miami, puis au Honduras. La vallée de Jamastran, dans le département d''Olancho, se révéla le site le plus prometteur : sols volcaniques, altitude et régime d''humidité que les tabacologues jugeaient capables de porter une culture de corojo.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The house''s emblematic tobacco is the corojo grown in the Jamastrán valley in Honduras. According to BespokeUnit, the corojo seed is attributed to the Cuban Diego Rodriguez in the 1940s, and was then replanted in Jamastrán after the nationalisation of the Cuban industry; Camacho went on to grow its own seeds. The Camacho Corojo line is made of Honduran tobaccos; its BXP version adds Pennsylvania broadleaf filler, according to the trade press in 2017.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The Cuban revolution ended that chapter in 1959. Simon Camacho''s departure from Havana was the departure of a man carrying his professional identity in seed form — literally, in the case of the corojo plants whose genetics he transported first to Miami and eventually to Honduras. The Jamastran Valley in Honduras'' Olancho Department proved to be the most promising available site: volcanic soils, altitude, and humidity patterns that experienced tobacologists recognized as potentially capable of supporting corojo cultivation.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('El tabaco emblemático de la casa es el corojo cultivado en el valle de Jamastrán, en Honduras. Según BespokeUnit, la semilla de corojo se atribuye al cubano Diego Rodriguez, en los años cuarenta, y después se replantó en Jamastrán tras la nacionalización de la industria cubana; Camacho cultivó luego sus propias semillas. La línea Camacho Corojo está hecha de tabacos hondureños; su versión BXP añade tripa broadleaf de Pensilvania, según la prensa del sector en 2017.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La revolución cubana cerró ese capítulo en 1959. La partida de Simon Camacho fue la de un hombre que se llevaba su identidad profesional en forma de semillas —literalmente, tratándose de las plantas de corojo cuya genética transportó hasta Miami, y después a Honduras. El valle de Jamastrán, en el departamento de Olancho, resultó el emplazamiento más prometedor: suelos volcánicos, altitud y régimen de humedad que los tabacólogos juzgaban capaces de sostener un cultivo de corojo.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Der Signaturtabak des Hauses ist der Corojo, der im Tal von Jamastrán in Honduras angebaut wird. Laut BespokeUnit wird die Corojo-Saat dem Kubaner Diego Rodriguez in den 1940er Jahren zugeschrieben und wurde nach der Verstaatlichung der kubanischen Industrie in Jamastrán neu ausgesät; Camacho zog danach eigene Samen. Die Linie Camacho Corojo besteht aus honduranischen Tabaken; ihre BXP-Version ergänzt Einlage Broadleaf aus Pennsylvania, laut Fachpresse 2017.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die kubanische Revolution schloss dieses Kapitel 1959. Der Weggang von Simon Camacho war der eines Mannes, der seine berufliche Identität in Form von Saatgut mitnahm — buchstäblich, wenn es um die Corojo-Pflanzen geht, deren Erbgut er bis nach Miami und dann nach Honduras trug. Das Tal von Jamastrán im Departement Olancho erwies sich als der aussichtsreichste Ort: vulkanische Böden, Höhenlage und ein Feuchteregime, dem Tabakfachleute zutrauten, einen Corojo-Anbau zu tragen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('这家公司的标志性烟草是种在洪都拉斯哈马斯特兰谷地的科罗霍。据 BespokeUnit，科罗霍种子归于古巴人 Diego Rodriguez 名下，时间在1940年代，古巴烟草工业国有化后又在哈马斯特兰重新种下；Camacho 随后种植自己的种子。Camacho Corojo 系列由洪都拉斯烟叶制成；据行业媒体2017年的报道，其 BXP 版本另加宾夕法尼亚 broadleaf 芯叶。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('1959年，古巴革命合上了这一章。西蒙·卡马乔的离开，是一个人把职业身份以种子的形式带走——就科罗霍烟株而言，这是字面意义上的：他把它们的遗传带到了迈阿密，再带到洪都拉斯。奥兰乔省的哈马斯特兰谷地被证明是最有希望的落点：火山土壤、海拔，以及烟草学者认为足以支撑科罗霍种植的湿度条件。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('التبغ الرمزي للدار هو الكوروخو المزروع في وادي خاماستران في هندوراس. وبحسب BespokeUnit تُنسب بذرة الكوروخو إلى الكوبي Diego Rodriguez في أربعينيات القرن العشرين، ثم أعيدت زراعتها في خاماستران بعد تأميم الصناعة الكوبية؛ ثم زرعت Camacho بذورها الخاصة. وسلسلة Camacho Corojo مصنوعة من تبغ هندوراسي؛ وتضيف نسخة BXP منها حشوة Broadleaf من بنسلفانيا، بحسب صحافة المهنة عام 2017.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('أغلقت الثورة الكوبية هذا الفصل عام 1959. وكان رحيل سيمون كاماتشو رحيل رجل يحمل هويته المهنية على هيئة بذور — حرفيًّا، إذ حمل جينات شتلات الكوروخو إلى ميامي ثم إلى هندوراس. وتبيّن أن وادي خاماستران، في محافظة أولانتشو، هو الموقع الأكثر وعدًا: تربة بركانية، وارتفاع، ونظام رطوبة رأى فيه خبراء التبغ ما يحتمل زراعة الكوروخو.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Le corojo hondurien que la famille développa au fil des décennies n''est pas la même plante que le cubain. Le terroir diffère réellement — composition du sol, eau, milieu microbien des salles de fermentation. Il en est sorti une variété qui partage les caractéristiques visuelles et la tenue de l''originale cubaine tout en développant son propre profil : plus corsé, plus dominé par le poivre, avec une terre que le sol hondurien apporte et non le cubain.

' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
