UNION ALL SELECT 'Camacho', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Le rachat par le groupe Davidoff en 2008 apporta les moyens de fabrication et de distribution qui firent passer Camacho du statut de manufacture spécialisée à celui de marque internationale. Le repositionnement autour de « Cigars Gone Loud » était un calcul commercial, mais il n''était pas faux : Camacho occupe un registre d''intensité et de franchise qu''aucune autre grande marque du portefeuille Davidoff n''adresse. Les boîtes noires, les noms de gammes — Corojo, BXP, American Barrel-Aged —, toute l''esthétique d''agressivité assumée décrivent honnêtement les cigares : ce ne sont pas des exercices de subtilité.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Camacho joined the Oettinger Davidoff group on 1 October 2008; the terms were not published. At the announcement, Christian Eiroa remained chairman and the 561 employees (534 in Honduras, 27 in the United States) were retained. According to the trade press, the group bought the brand and the Danlí factory, with the Eiroas keeping their plantations according to Wikipedia. Since January 2017, the cigars have been rolled in Danlí at the Diadema Cigars de Honduras factory. In 2015 the brand added the American Barrel-Aged, rolled in the Dominican Republic, and in 2017 the box-pressed (BXP) versions of its Connecticut, Corojo and Ecuador lines.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The Davidoff group''s acquisition in 2008 provided the manufacturing and distribution resources that allowed Camacho''s transition from specialist manufacturer to international brand. The repositioning around the ''Cigars Gone Loud'' identity was commercially calculated but not inaccurate — Camacho occupies a specific register of intensity and directness that no other major brand in the Davidoff portfolio addresses. The packaging design, the range names, the overall aesthetic of deliberate aggression describe the cigars honestly: these are not subtlety exercises.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Camacho'
UNION ALL SELECT 'Camacho', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Camacho se incorporó al grupo Oettinger Davidoff el 1 de octubre de 2008; no se publicaron las condiciones. En el anuncio, Christian Eiroa seguía como presidente y se conservaban los 561 empleados (534 en Honduras, 27 en Estados Unidos). Según la prensa del sector, el grupo compró la marca y la fábrica de Danlí, y los Eiroa conservan sus plantaciones según Wikipedia. Desde enero de 2017, los puros se lían en Danlí, en la fábrica Diadema Cigars de Honduras. La marca añadió en 2015 el American Barrel-Aged, liado en la República Dominicana, y en 2017 las versiones box-pressed (BXP) de sus líneas Connecticut, Corojo y Ecuador.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
