UNION ALL SELECT 'Camacho', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Camacho trat am 1. Oktober 2008 der Gruppe Oettinger Davidoff bei; die Bedingungen wurden nicht veröffentlicht. Bei der Bekanntgabe blieb Christian Eiroa Präsident, und die 561 Beschäftigten (534 in Honduras, 27 in den USA) wurden übernommen. Laut Fachpresse kaufte die Gruppe die Marke und die Fabrik in Danlí, wobei die Eiroas laut Wikipedia ihre Plantagen behielten. Seit Januar 2017 werden die Zigarren in Danlí in der Fabrik Diadema Cigars de Honduras gerollt. 2015 ergänzte die Marke die American Barrel-Aged, gerollt in der Dominikanischen Republik, und 2017 die Versionen box-pressed (BXP) ihrer Linien Connecticut, Corojo und Ecuador.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Camacho'
