UNION ALL SELECT 'Joya de Nicaragua', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Joya de Nicaragua se dit la première fabrique du pays à rouler des cigares premium à la main. Selon la maison, Nicaragua Cigar Co. est fondée le 29 février 1968 à Estelí par J.F. Bermejo et Simón Camacho, deux planteurs, après un projet pilote de tabac de type havane (1965) qui avait désigné Estelí et Condega comme les meilleures terres. Somoza n''est donc pas le fondateur : la maison écrit qu''il apprit de Nixon que Joya était le cigare officiel de la Maison-Blanche et que Bermejo lui vendit alors, sous pression politique, une part de l''entreprise (1971-1974). La presse du métier raconte une version plus dure : Somoza prit le contrôle aux propriétaires d''origine, déplaça la production vers une fabrique plus grande, puis vendit la marque à Oppenheimer & Co. avant de fuir en 1979.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('L''histoire de Joya de Nicaragua contient une ironie que ses propres historiens relèvent avec gourmandise : la marque fut créée par le gouvernement que la plupart des administrations américaines de l''époque soutenaient. Anastasio Somoza, dont Washington appuyait le régime comme rempart à l''influence communiste en Amérique centrale, fonda Joya de Nicaragua en 1968 comme entreprise d''État destinée à développer l''industrie du tabac à l''exportation.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Joya de Nicaragua calls itself the first factory in the country to roll premium cigars by hand. According to the house, Nicaragua Cigar Co. was founded on 29 February 1968 in Estelí by J.F. Bermejo and Simón Camacho, two planters, after a pilot project for Havana-type tobacco (1965) that had named Estelí and Condega as the best lands. Somoza was therefore not the founder: the house writes that he learned from Nixon that Joya was the official cigar of the White House and that Bermejo then sold him, under political pressure, a share of the company (1971-1974). The trade press tells a harsher version: Somoza took control from the original owners, moved production to a larger factory, then sold the brand to Oppenheimer & Co. before fleeing in 1979.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The origin story of Joya de Nicaragua contains an irony that the company''s historians note with evident relish: the country''s best-known cigar brand was created by the government most American administrations of the era were supporting. Anastasio Somoza, whose regime Washington backed as a bulwark against communist influence in Central America, founded Joya de Nicaragua in 1968 as a state enterprise intended to develop the country''s tobacco industry for export.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Joya de Nicaragua se presenta como la primera fábrica del país en liar puros premium a mano. Según la casa, Nicaragua Cigar Co. se fundó el 29 de febrero de 1968 en Estelí por J.F. Bermejo y Simón Camacho, dos plantadores, tras un proyecto piloto de tabaco de tipo habano (1965) que había señalado Estelí y Condega como las mejores tierras. Somoza no es, pues, el fundador: la casa escribe que se enteró por Nixon de que Joya era el puro oficial de la Casa Blanca y que Bermejo le vendió entonces, bajo presión política, una parte de la empresa (1971-1974). La prensa del sector cuenta una versión más dura: Somoza tomó el control a los propietarios originales, trasladó la producción a una fábrica más grande y luego vendió la marca a Oppenheimer & Co. antes de huir en 1979.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La historia de Joya de Nicaragua contiene una ironía que sus propios historiadores señalan con gusto: la marca fue creada por el gobierno que la mayoría de las administraciones estadounidenses de la época sostenían. Anastasio Somoza, cuyo régimen Washington apoyaba como muro de contención frente a la influencia comunista en Centroamérica, fundó Joya de Nicaragua en 1968 como empresa de Estado destinada a desarrollar la industria del tabaco para la exportación.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Joya de Nicaragua bezeichnet sich als die erste Fabrik des Landes, die Premiumzigarren von Hand rollte. Laut dem Haus wurde Nicaragua Cigar Co. am 29. Februar 1968 in Estelí von J.F. Bermejo und Simón Camacho, zwei Pflanzern, gegründet, nach einem Pilotprojekt für Tabak vom Havanna-Typ (1965), das Estelí und Condega als die besten Böden benannt hatte. Somoza ist also nicht der Gründer: Das Haus schreibt, er habe von Nixon erfahren, dass Joya die offizielle Zigarre des Weißen Hauses sei, und Bermejo habe ihm daraufhin unter politischem Druck einen Anteil an dem Unternehmen verkauft (1971-1974). Die Fachpresse erzählt eine härtere Version: Somoza übernahm die Kontrolle von den ursprünglichen Eigentümern, verlegte die Produktion in eine größere Fabrik und verkaufte die Marke dann an Oppenheimer & Co., bevor er 1979 floh.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Geschichte von Joya de Nicaragua enthält eine Ironie, die ihre eigenen Chronisten mit Genuss hervorheben: Die Marke wurde von der Regierung geschaffen, die die meisten amerikanischen Kabinette jener Zeit stützten. Anastasio Somoza, dessen Regime Washington als Bollwerk gegen den kommunistischen Einfluss in Mittelamerika unterstützte, gründete Joya de Nicaragua 1968 als Staatsunternehmen zur Entwicklung der Tabakindustrie für die Ausfuhr.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Joya de Nicaragua 自称是该国首家手工卷制高端雪茄的工厂。据公司所述，Nicaragua Cigar Co. 于1968年2月29日在埃斯特利由两位种植者 J.F. Bermejo 与 Simón Camacho 创立，此前1965年一项哈瓦那型烟草的试点项目，已把埃斯特利与孔德加指为上佳的土地。因此 Somoza 并非创始人：公司写道，他从 Nixon 那里得知 Joya 是白宫的官方雪茄，于是 Bermejo 在政治压力下向他出让了公司的一部分股份（1971-1974年）。行业媒体讲述的是更严酷的版本：Somoza 从原所有者手中夺取控制权，把生产转到一家更大的工厂，随后将品牌卖给 Oppenheimer & Co.，并在1979年出逃。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('华雅·德尼加拉瓜的历史里有一处反讽，连它自己的记述者都乐于点出：这个品牌是由当时多数美国政府所支持的那个政权创办的。华盛顿把阿纳斯塔西奥·索摩查的政权当作中美洲抵挡共产主义影响的屏障加以支持；1968年，索摩查创办华雅·德尼加拉瓜，作为一家旨在发展出口烟草工业的国营企业。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تقول Joya de Nicaragua عن نفسها إنها أول مصنع في البلاد لفَّ السيجار الفاخر باليد. وبحسب الدار، تأسست Nicaragua Cigar Co. في 29 فبراير 1968 في إستيلي على يد J.F. Bermejo وSimón Camacho، وهما مزارعان، بعد مشروع تجريبي لتبغ من طراز هافانا (1965) عيّن إستيلي وكوندغا بوصفهما الأراضي المُثلى. فـSomoza إذن ليس المؤسس: تكتب الدار أنه علم من Nixon أن Joya هو السيجار الرسمي للبيت الأبيض، وأن Bermejo باع له حينئذٍ، تحت ضغط سياسي، حصة من الشركة (1971-1974). وتروي صحافة المهنة رواية أشدّ قسوةً: استولى Somoza على السيطرة من الملّاك الأصليين، ونقل الإنتاج إلى مصنع أوسع، ثم باع العلامة إلى Oppenheimer & Co. قبل أن يفرّ عام 1979.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('يحمل تاريخ «خويا دي نيكاراغوا» مفارقةً يبرزها مؤرّخوها أنفسهم باستمتاع: فقد أنشأت العلامةَ الحكومةُ التي كانت تدعمها معظم الإدارات الأمريكية في ذلك الوقت. فقد أسّس أناستاسيو سوموزا، الذي كانت واشنطن تسند نظامه بوصفه حاجزًا أمام النفوذ الشيوعي في أمريكا الوسطى، «خويا دي نيكاراغوا» عام 1968 شركةً حكومية غايتها تطوير صناعة التبغ للتصدير.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Le moment était bien choisi. La culture américaine du cigare entrait à la fin des années 1960 dans une phase d''expansion et de montée en gamme, et l''embargo contre Cuba avait créé une demande d''alternatives que les centres de production existants — République dominicaine, Honduras — ne pouvaient pas entièrement satisfaire. Le tabac nicaraguayen des vallées de Jalapa et d''Estelí offrait un profil distinct : plus terreux et plus poivré que le dominicain, avec une intensité que les dégustateurs expérimentés reconnaissaient comme une autre expression du tabac du Nouveau Monde.

' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST(CONCAT('The timing was excellent. American cigar culture in the late 1960s was entering a period of expansion and premiumization, and the US trade embargo against Cuba had created demand for alternatives to Havana that the existing production centers — the Dominican Republic, Honduras — could not fully satisfy. Nicaraguan tobacco from the Jalapa and Jalapa Valleys offered a distinct flavor profile: earthier and more peppery than Dominican, with a specific intensity that experienced tasters recognized as a different expression of New World tobacco.', CHAR(13), '
', CHAR(13), '
') AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
