UNION ALL SELECT 'Joya de Nicaragua', 'ar', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('في عام 2025 لفّت الدار سيجار «بلاك سوان». والاسم ليس اسمها: فـ«بلاك سوان» ملك لـ«سيغار بيدج»، وهو بائع تجزئة أمريكيّ، جعل منه سلسلة تُسنَد كلّ طبعة فيها إلى مصنع مختلف، وتُبنى على دفعة تبغ خاصّة وُجدت عنده. أربع طبعات، وأربع دور، وثلاثة بلدان — «أوليفا» في نيكاراغوا عام 2023، و«روكي باتيل» في هندوراس في يناير 2024، و«إي. بي. كاريّو» في الجمهورية الدومينيكية، وهذه. وللأربع بطاقاتها في هذا الأطلس.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
UNION ALL SELECT 'Joya de Nicaragua', 'fr', 'histoire 7 (nouveau texte)', (LOCATE(CAST('Joya roule aussi, sans la posséder, la marque Bentley, celle de Bentley Tobacco, entreprise de la famille Schuster que Cigar Coop fait remonter à 1878, comme fabricant de pipes. Le White a une cape Connecticut Shade, le Green une cape rosado d''Équateur, tous deux sur sous-cape et tripe nicaraguayennes. Bentley Tobacco a fait son premier PCA en 2025, avec une division américaine lancée fin 2024.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
