UNION ALL SELECT 'Joya de Nicaragua', 'es', 'histoire 7 (ancien texte parti)', (LOCATE(CAST('La de Joya de Nicaragua lleva una capa criollo de Ecuador de semilla cubana sobre un capote habano nicaragüense y tripa larga de Jalapa y Estelí. No entra en la gama de la casa: es un encargo, en cantidad limitada, vendido por un solo minorista. El atlas lo escribe aquí porque la mano que lía cuenta tanto como el nombre de la vitola, y aquí ambos no son de la misma casa.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Joya de Nicaragua'
