UNION ALL SELECT 'La Flor Dominicana', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Tamboril, République dominicaine (selon Wikipédia, octobre 2026) ; premiers cigares produits à Santiago en 1996' AS BINARY)) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La Flor Dominicana est l''œuvre de Litto Gómez, ancien bijoutier de Miami, et de sa femme Ines Lorenzo. D''après la presse du métier, le couple entre dans le cigare en 1994 avec la marque Los Libertadores, dans un petit atelier de Villa González à quatre postes de roulage. En 1996, à la suite d''un différend, Litto Gómez et Ines Lorenzo reprennent l''entreprise, sans la marque Los Libertadores, et les cigares sont rebaptisés La Flor Dominicana. Selon Wikipédia, les premiers cigares sont produits à Santiago en 1996 ; la fabrique est aujourd''hui à Tamboril (état d''octobre 2026, cette seule source).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('José « Jochy » Blanco a fondé La Flor Dominicana à Santiago, en République dominicaine, en 1996, avec une ligne dont il n''a pas dévié : faire ce que les autres ne font pas. Dans un métier qui privilégie souvent l''incrément — le léger ajustement d''un assemblage établi, le format familier sous une nouvelle cape —, Blanco a bâti sa réputation sur l''expérimentation véritable et sur des décisions de production que la plupart des fabricants refuseraient pour des raisons pratiques.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La Flor Dominicana is the work of Litto Gómez, a former Miami jeweller, and his wife Ines Lorenzo. According to the trade press, the couple entered the cigar business in 1994 with the Los Libertadores brand, in a small workshop in Villa González with four rolling stations. In 1996, following a dispute, Litto Gómez and Ines Lorenzo took over the business, without the Los Libertadores brand, and the cigars were renamed La Flor Dominicana. According to Wikipedia, the first cigars were produced in Santiago in 1996; the factory is now in Tamboril (as of October 2026, this source alone).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('José ''Jochy'' Blanco established La Flor Dominicana in Santiago, Dominican Republic in 1996 with a remit he has maintained consistently since: do what others won''t. In an industry that often rewards the incremental — the slight adjustment to an established blend, the familiar format in a new wrapper — Blanco built his reputation on genuine experimentation and the willingness to make production decisions that most manufacturers would reject on practical grounds.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La Flor Dominicana es obra de Litto Gómez, antiguo joyero de Miami, y de su esposa Ines Lorenzo. Según la prensa del sector, la pareja entra en el mundo del puro en 1994 con la marca Los Libertadores, en un pequeño taller de Villa González con cuatro puestos de torcido. En 1996, a raíz de una disputa, Litto Gómez e Ines Lorenzo se hacen cargo de la empresa, sin la marca Los Libertadores, y los puros pasan a llamarse La Flor Dominicana. Según Wikipedia, los primeros puros se producen en Santiago en 1996; la fábrica está hoy en Tamboril (estado de octubre de 2026, solo esta fuente).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('José «Jochy» Blanco fundó La Flor Dominicana en Santiago, en República Dominicana, en 1996, con una línea de la que no se ha apartado: hacer lo que los demás no hacen. En un oficio que suele preferir el incremento —el leve ajuste de una ligada establecida, el formato familiar bajo una capa nueva—, Blanco levantó su reputación sobre la experimentación verdadera y sobre decisiones de producción que la mayoría de los fabricantes rechazarían por razones prácticas.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La Flor Dominicana ist das Werk von Litto Gómez, einem früheren Juwelier aus Miami, und seiner Frau Ines Lorenzo. Laut der Fachpresse steigt das Paar 1994 mit der Marke Los Libertadores ins Zigarrengeschäft ein, in einer kleinen Werkstatt in Villa González mit vier Rollplätzen. 1996 übernehmen Litto Gómez und Ines Lorenzo nach einem Streit den Betrieb, ohne die Marke Los Libertadores, und die Zigarren werden in La Flor Dominicana umbenannt. Laut Wikipedia werden die ersten Zigarren 1996 in Santiago hergestellt; die Fabrik steht heute in Tamboril (Stand Oktober 2026, nur diese eine Quelle).' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('José «Jochy» Blanco gründete La Flor Dominicana 1996 in Santiago in der Dominikanischen Republik, mit einer Linie, von der er nicht abgewichen ist: zu tun, was die anderen nicht tun. In einem Fach, das oft den kleinen Schritt bevorzugt — die leichte Anpassung einer eingeführten Mischung, das vertraute Format unter einem neuen Deckblatt —, hat Blanco seinen Ruf auf echtem Versuch aufgebaut und auf Produktionsentscheidungen, die die meisten Hersteller aus praktischen Gründen ablehnen würden.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La Flor Dominicana 出自 Litto Gómez 与其妻子 Ines Lorenzo 之手，前者曾是 Miami 的珠宝商。据行业媒体报道，这对夫妇于1994年带着 Los Libertadores 品牌踏入雪茄行业，在 Villa González 的一间小作坊里，只有四个卷制工位。1996年，因一场纠纷，Litto Gómez 与 Ines Lorenzo 接手了这家企业，但不带 Los Libertadores 品牌，雪茄随之改名为 La Flor Dominicana。据维基百科，首批雪茄于1996年在 Santiago 生产；工厂如今设在 Tamboril（截至2026年10月的情况，仅此一个来源）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('1996年，何塞·「霍奇」·布兰科在多米尼加共和国的圣地亚哥创办了拉弗洛尔·多米尼加纳，秉持的路线始终没变：做别人不做的事。在一个往往偏爱小步推进的行当里——把成熟配方稍作调整，把熟悉的规格换一张茄衣——布兰科靠真正的试验，以及多数厂商出于现实考虑会拒绝的生产决定，立起了自己的名声。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La Flor Dominicana من صنع Litto Gómez، وهو صائغ سابق في Miami، وزوجته Ines Lorenzo. وبحسب صحافة المهنة، دخل الزوجان عالم السيجار عام 1994 بعلامة Los Libertadores، في ورشة صغيرة في Villa González فيها أربعة مواقع للّف. وفي عام 1996، إثر خلاف، تولّى Litto Gómez وInes Lorenzo الشركة دون علامة Los Libertadores، وأُعيدت تسمية السيجار إلى La Flor Dominicana. وبحسب ويكيبيديا، أُنتجت أولى السيجارات في Santiago عام 1996؛ والمصنع اليوم في Tamboril (الوضع في أكتوبر 2026، وهذا المصدر وحده).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('أسّس خوسيه «خوتشي» بلانكو دار «لا فلور دومينيكانا» في سانتياغو بالجمهورية الدومينيكية عام 1996، على خطّ لم يحد عنه: أن يفعل ما لا يفعله الآخرون. ففي مهنة تفضّل غالبًا الخطوة الصغيرة — تعديل طفيف على خلطة راسخة، أو قياس مألوف تحت غلاف جديد — بنى بلانكو سمعته على التجريب الحقيقي وعلى قرارات إنتاج يرفضها معظم الصنّاع لأسباب عملية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Le Chisel, figurado à tête en coin, sort en 2003 selon la presse du métier : l''idée serait venue à Litto Gómez en route vers la fabrique, la forme a demandé dix mois de mise au point et il a demandé à ses rouleurs de la reproduire. Il se décline dans la ligne Double Ligero, que la maison décrit comme enveloppée de feuilles sombres Sumatra d''Équateur cultivées au soleil, sur une tripe et une sous-cape dominicaines issues de la propriété.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Le Double Ligero — un double torpedo de 75 × 184 mm — en est l''expression la plus nette. Le seul défi technique est considérable : le format exige un moule de dimensions si particulières que La Flor Dominicana l''a fait fabriquer pour elle seule. L''expérience qu''il produit — trois heures au minimum, cinq phases aromatiques distinctes, du cèdre léger au premier tiers jusqu''à la terre profonde et au chocolat noir dans la dernière demi-heure — tient autant de l''épreuve d''endurance que du plaisir.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The Chisel, a figurado with a wedge-shaped head, came out in 2003 according to the trade press: the idea is said to have come to Litto Gómez on his way to the factory, the shape took ten months to perfect, and he asked his rollers to reproduce it. It comes in the Double Ligero line, which the house describes as wrapped in dark, sun-grown Ecuadorian Sumatra leaves over a Dominican filler and binder from the estate.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The Double Ligero format — a Double Torpedo measuring 75 x 184mm — is the clearest expression of this philosophy. The engineering challenge alone is formidable: the format requires a mold of such specific dimensions that La Flor Dominicana commissioned it exclusively. No other factory possesses the equipment to produce it at scale. The smoking experience it creates — three hours minimum, five distinct aromatic phases that range from light cedar in the first third to deep earth and dark chocolate in the final half-hour — is as much an endurance test as a pleasure.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('El Chisel, figurado de cabeza en cuña, sale en 2003 según la prensa del sector: la idea le habría surgido a Litto Gómez de camino a la fábrica, la forma exigió diez meses de puesta a punto y él pidió a sus torcedores que la reprodujeran. Se declina en la línea Double Ligero, que la casa describe como envuelta en hojas oscuras de Sumatra de Ecuador cultivadas al sol, sobre una tripa y una capote dominicanas procedentes de la propiedad.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('El Double Ligero —un doble torpedo de 75 × 184 mm— es su expresión más nítida. El solo desafío técnico es considerable: el formato exige un molde de dimensiones tan particulares que La Flor Dominicana lo mandó fabricar para ella sola. La experiencia que produce —tres horas como mínimo, cinco fases aromáticas distintas, del cedro ligero en el primer tercio hasta la tierra profunda y el chocolate negro en la última media hora— tiene tanto de prueba de resistencia como de placer.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Der Chisel, ein Figurado mit keilförmigem Kopf, kommt laut Fachpresse 2003 heraus: Die Idee soll Litto Gómez auf dem Weg zur Fabrik gekommen sein, die Form brauchte zehn Monate Entwicklung, und er bat seine Zigarrenroller, sie nachzubauen. Er wird in der Linie Double Ligero angeboten, die das Haus als umhüllt von dunklen, in der Sonne gezogenen Sumatra-Blättern aus Ecuador beschreibt, über Einlage und Umblatt aus dominikanischem Tabak vom Anwesen des Hauses.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Der Double Ligero — ein Doppel-Torpedo von 75 × 184 mm — ist dafür der klarste Ausdruck. Schon die technische Aufgabe ist beträchtlich: Das Format verlangt eine Form von so eigenen Maßen, dass La Flor Dominicana sie für sich allein anfertigen ließ. Das Erlebnis, das daraus folgt — mindestens drei Stunden, fünf deutlich getrennte aromatische Phasen, von leichter Zeder im ersten Drittel bis zu tiefer Erde und Zartbitterschokolade in der letzten halben Stunde —, hat ebenso viel von einer Ausdauerprüfung wie vom Genuss.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Chisel 是一种楔形头的异形雪茄，据行业媒体报道于2003年推出：Litto Gómez 据说是在前往工厂的路上想到了这个主意，这个形状花了十个月调试，他让自己的卷烟工把它复制出来。它收在 Double Ligero 系列之中，厂家将该系列描述为以厄瓜多尔产的深色 Sumatra 烟叶作茄衣，阳光下种植，内里的芯叶与束叶为多米尼加烟叶，来自庄园自家种植。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('双利加罗——一支 75 × 184 毫米的双鱼雷——是这条路线最清晰的表达。单是技术上的难处就已可观：这个规格所需的模具尺寸如此特别，以致拉弗洛尔·多米尼加纳专门为自己订制了一副。它带来的体验——至少三小时，五个分明的香气阶段，从第一段的淡雪松到最后半小时的深沉泥土与黑巧克力——既是享受，也是耐力的考验。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('يصدر «Chisel»، وهو فيغورادو برأس مائل كالإسفين، عام 2003 بحسب صحافة المهنة: يُقال إن الفكرة خطرت لـ Litto Gómez وهو في طريقه إلى المصنع، وإن الشكل احتاج عشرة شهور من الضبط، وإنه طلب من لافّي السيجار لديه أن يعيدوا صنعه. ويأتي ضمن خط Double Ligero، الذي تصفه الدار بأنه ملفوف بأوراق Sumatra الداكنة من الإكوادور المزروعة تحت الشمس، فوق حشوة وغلاف داخلي دومينيكيين من أرض الدار.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('«دبل ليغيرو» — تُربيدو مزدوج بقياس 75 × 184 مم — هو أوضح تعبير عن ذلك. فالتحدّي التقني وحده كبير: يتطلّب هذا القياس قالبًا بأبعاد خاصة إلى حدّ دفع الدار إلى صنعه لنفسها وحدها. أما التجربة التي ينتجها — ثلاث ساعات على الأقل، وخمس مراحل عطرية متمايزة، من خشب الأرز الخفيف في الثلث الأول إلى التراب العميق والشوكولاتة الداكنة في نصف الساعة الأخير — ففيها من امتحان القدرة بقدر ما فيها من المتعة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('José « Jochi » Blanco, fabricant de cigares, est cité en 2007 par la presse du métier comme partageant avec La Flor Dominicana une ferme de 120 acres ; il n''est pas le fondateur de la maison.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Au-delà de ce format vitrine, les apports techniques de Blanco à la production dominicaine sont substantiels. Il a introduit pour les ligeros dominicains des protocoles de fermentation prolongée que d''autres manufactures de l''île ont adoptés ensuite. Son emploi de tabacs dits « Mystery Ligero » — des feuilles d''origine volontairement non divulguée, ajoutées à plusieurs assemblages pour créer un caractère que l''analyse ne peut pas rattacher à une région connue — relève du génie commercial ou de la philosophie du terroir, selon le point de vue.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('José ''Jochi'' Blanco, a cigar maker, was cited by the trade press in 2007 as sharing a 120-acre farm with La Flor Dominicana; he is not the founder of the house.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Beyond the headline format, Blanco''s technical contributions to Dominican cigar production are substantial. He introduced extended fermentation protocols for Dominican ligero leaves that the island''s other manufacturers later adopted. His sourcing of ''Mystery Ligero'' tobaccos — leaves from undisclosed origins, deliberately unnamed, added to several blends to create a specific character that analytical reviewers cannot fully attribute to known growing regions — is either marketing genius or genuine terroir philosophy depending on your perspective.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('José «Jochi» Blanco, fabricante de puros, es citado en 2007 por la prensa del sector como alguien que comparte con La Flor Dominicana una finca de 120 acres; no es el fundador de la casa.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Más allá de ese formato escaparate, las aportaciones técnicas de Blanco a la producción dominicana son sustanciales. Introdujo para los ligeros dominicanos protocolos de fermentación prolongada que otras manufacturas de la isla adoptaron después. Su empleo de tabacos llamados «Mystery Ligero» —hojas de origen deliberadamente no divulgado, añadidas a varias ligadas para crear un carácter que el análisis no puede vincular a ninguna región conocida— es genio comercial o filosofía del terruño, según se mire.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('José «Jochi» Blanco, Zigarrenhersteller, wird 2007 von der Fachpresse als jemand genannt, der mit La Flor Dominicana eine Farm von 120 Acres teilt; er ist nicht der Gründer des Hauses.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Über dieses Schaufensterformat hinaus sind Blancos technische Beiträge zur dominikanischen Produktion beträchtlich. Er führte für dominikanische Ligeros verlängerte Fermentationsverfahren ein, die andere Manufakturen der Insel später übernahmen. Sein Einsatz von Tabaken, die «Mystery Ligero» heißen — Blätter absichtlich nicht offengelegter Herkunft, mehreren Mischungen beigegeben, um einen Charakter zu schaffen, den die Analyse keiner bekannten Region zuordnen kann —, ist kaufmännischer Einfall oder Terroir-Philosophie, je nach Blickwinkel.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('José「Jochi」Blanco 是一名雪茄制造者，2007年行业媒体称他与 La Flor Dominicana 共用一座120英亩的农场；他并非该品牌的创办人。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('除了这支橱窗之作，布兰科在技术上对多米尼加生产的贡献同样扎实。他为多米尼加利加罗引入了延长发酵的工序，岛上其他工厂后来纷纷采用。他使用所谓「Mystery Ligero」的烟叶——刻意不公开产地，掺入多副配方，造出一种分析无法归入任何已知产区的性格——究竟是商业上的巧思还是风土的哲学，取决于你站在哪一边。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('ذُكر في صحافة المهنة عام 2007 أن José «Jochi» Blanco، صانع السيجار، يتقاسم مع La Flor Dominicana مزرعة مساحتها 120 أكرًا؛ وهو ليس مؤسس الدار.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وخارج هذا القياس الاستعراضي، إسهامات بلانكو التقنية في الإنتاج الدومينيكي جوهرية. فقد أدخل على الليغيرو الدومينيكي بروتوكولات تخمير مطوَّلة تبنّتها لاحقًا مصانع أخرى في الجزيرة. أما استعماله تبغًا يسمّيه «Mystery Ligero» — أوراق لا يُفصح عن أصلها عمدًا، تُضاف إلى عدة خلطات لتخلق طابعًا لا يستطيع التحليل ردّه إلى منطقة معروفة — فهو نبوغ تجاري أو فلسفة أرض، بحسب زاوية النظر.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor Dominicana'
UNION ALL SELECT 'La Flor Dominicana', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('

