UNION ALL SELECT 'Avo', 'fr', 'limited_eds : Avo Improvisation 30 Years (2018)', (JSON_CONTAINS(`limited_eds`, '"Avo Improvisation 30 Years (2018)"')) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'fr', 'founded', (CAST(`founded` AS BINARY) = CAST('1988 — première sortie ; Davidoff dès 1995' AS BINARY)) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('OK Cigars, fabrique de Tabadom (Oettinger Davidoff), République dominicaine ; Tabadom est à Villa González selon la presse du métier en 2025' AS BINARY)) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Avo Uvezian est né à Beyrouth le 22 mars 1926 ; pianiste et compositeur arméno-américain, il est mort à Orlando le 24 mars 2017, à 91 ans (Cigar Dojo, 24 mars 2017). Sa chanson la plus connue reste disputée : Strangers in the Night est créditée à Bert Kaempfert, tandis qu''Uvezian affirmait l''avoir composée et avoir envoyé la mélodie à Kaempfert avant que Sinatra l''enregistre en 1966 (Wikipédia).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La biographie d''Avo Uvezian échappe aux conventions du genre. Né à Beyrouth en 1926 de parents arméniens rescapés du génocide, il quitta le Liban dans sa vingtaine pour New York, où il devint un pianiste de jazz assez accompli pour rejoindre l''orchestre de tournée de Frank Sinatra. Sa carrière le mena des clubs new-yorkais aux salles de concert européennes, et jusqu''à cette distinction improbable : avoir contribué à « Strangers in the Night », dont la paternité lui est restée disputée toute sa vie.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Avo Uvezian was born in Beirut on 22 March 1926; an Armenian-American pianist and composer, he died in Orlando on 24 March 2017, aged 91 (Cigar Dojo, 24 March 2017). His best-known song remains disputed: Strangers in the Night is credited to Bert Kaempfert, whereas Uvezian claimed to have composed it and to have sent the melody to Kaempfert before Sinatra recorded it in 1966 (Wikipedia).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Avo Uvezian''s biography defies the conventions of the cigar industry''s typical founder narrative. Born in Beirut in 1926 to Armenian parents who had survived the genocide, he left Lebanon in his twenties for New York, where he became a jazz pianist of sufficient accomplishment to join Frank Sinatra''s touring band. His musical career took him through the clubs of New York, the concert halls of Europe, and eventually to the unlikely distinction of having contributed to one of the twentieth century''s most recognizable popular songs — though the credit for ''Strangers in the Night'' remained disputed throughout his life.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Avo Uvezian nació en Beirut el 22 de marzo de 1926; pianista y compositor armenio-estadounidense, murió en Orlando el 24 de marzo de 2017, a los 91 años (Cigar Dojo, 24 de marzo de 2017). Su canción más conocida sigue siendo objeto de disputa: Strangers in the Night se atribuye a Bert Kaempfert, mientras que Uvezian afirmaba haberla compuesto y haber enviado la melodía a Kaempfert antes de que Sinatra la grabara en 1966 (Wikipedia).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La biografía de Avo Uvezian escapa a las convenciones del género. Nacido en Beirut en 1926 de padres armenios supervivientes del genocidio, dejó el Líbano en la veintena rumbo a Nueva York, donde llegó a ser un pianista de jazz lo bastante consumado como para unirse a la orquesta de gira de Frank Sinatra. Su carrera lo llevó de los clubes neoyorquinos a las salas de concierto europeas, y hasta esa distinción improbable: haber contribuido a «Strangers in the Night», cuya paternidad le quedó disputada toda su vida.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Avo Uvezian wurde am 22. März 1926 in Beirut geboren; als armenisch-amerikanischer Pianist und Komponist starb er am 24. März 2017 in Orlando im Alter von 91 Jahren (Cigar Dojo, 24. März 2017). Sein bekanntestes Lied bleibt umstritten: Strangers in the Night wird Bert Kaempfert zugeschrieben, während Uvezian behauptete, es komponiert und die Melodie an Kaempfert geschickt zu haben, bevor Sinatra sie 1966 aufnahm (Wikipedia).' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Lebensgeschichte von Avo Uvezian entzieht sich den Konventionen der Gattung. 1926 in Beirut als Sohn armenischer Eltern geboren, die den Völkermord überlebt hatten, verließ er den Libanon in seinen Zwanzigern Richtung New York, wo er ein Jazzpianist wurde, gut genug, um in Frank Sinatras Tourneeorchester zu spielen. Seine Laufbahn führte ihn von den New Yorker Clubs in europäische Konzertsäle und bis zu jener unwahrscheinlichen Besonderheit: an «Strangers in the Night» mitgewirkt zu haben, dessen Urheberschaft ihm sein Leben lang streitig blieb.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Avo Uvezian 1926年3月22日生于 Beirut；他是亚美尼亚裔美国钢琴家兼作曲家，2017年3月24日在 Orlando 去世，享年91岁（Cigar Dojo，2017年3月24日）。他广为人知的那首歌至今仍有争议：《Strangers in the Night》署名为 Bert Kaempfert，而 Uvezian 声称自己创作了它，并在 Sinatra 于1966年录制之前把旋律寄给了 Kaempfert（维基百科）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('阿沃·乌韦兹扬的生平不合这一体裁的常规。1926年，他生于贝鲁特，父母是从种族灭绝中幸存下来的亚美尼亚人。二十几岁时他离开黎巴嫩去了纽约，成了一名相当出色的爵士钢琴手，出色到能加入弗兰克·辛纳屈的巡演乐队。他的生涯把他从纽约的俱乐部带到欧洲的音乐厅，也带到一项不大可能的名分上：参与了《Strangers in the Night》的创作——而这首曲子的著作权归属，与他争执了一辈子。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('وُلد Avo Uvezian في Beirut يوم 22 مارس 1926؛ عازف بيانو وملحّن أرمني أمريكي، توفي في Orlando يوم 24 مارس 2017 عن 91 عامًا (Cigar Dojo، 24 مارس 2017). وتبقى أغنيته الذائعة موضع خلاف: تُنسب «Strangers in the Night» إلى Bert Kaempfert، بينما كان Uvezian يؤكد أنه ألّفها وأنه أرسل اللحن إلى Kaempfert قبل أن يسجّلها Sinatra عام 1966 (ويكيبيديا).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('تفلت سيرة آفو أوفيزيان من أعراف هذا النوع من السير. وُلد في بيروت عام 1926 لأبوين أرمنيين نجيا من الإبادة الجماعية، وغادر لبنان في عشرينيّاته إلى نيويورك، حيث صار عازف بيانو جاز بارعًا بما يكفي للانضمام إلى أوركسترا فرانك سيناترا في جولاتها. وقادته مسيرته من نوادي نيويورك إلى قاعات الحفلات الأوروبية، وصولًا إلى ذلك الامتياز غير المتوقَّع: مساهمته في «Strangers in the Night»، التي ظلّت نسبتها إليه موضع نزاع طوال حياته.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Pour le cigare, il s''est tourné vers Hendrik Kelner, qui avait ouvert Tabacos Dominicanos (Tabadom) en 1984. Selon la presse du métier, la première commande de Kelner pour Avo, 17 000 cigares, date de 1987 et la boutique Davidoff de Madison Avenue vend la marque en 1988 ; la première sortie est datée de 1988. Wikipédia écrit que Davidoff a acquis en 1995 les droits de distribution d''Avo, pour un montant d''environ 10 millions de dollars.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Passé la soixantaine, Uvezian menait une vie qui mêlait des concerts épisodiques à un intérêt grandissant pour le cigare. Il fumait à l''ancienne école cubaine, formé par la même culture du tabac havanais que Sinatra et son cercle avaient absorbée dans leurs années new-yorkaises. La République dominicaine, devenue dans les années 1980 l''alternative du cigare premium à Cuba, lui offrait ce qu''il cherchait : une fabrication excellente, et la possibilité de bâtir quelque chose à son nom.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('For the cigar, he turned to Hendrik Kelner, who had opened Tabacos Dominicanos (Tabadom) in 1984. According to the trade press, Kelner''s first order for Avo, 17,000 cigars, dates from 1987 and the Davidoff shop on Madison Avenue was selling the brand in 1988; the first release is dated 1988. Wikipedia writes that Davidoff acquired the distribution rights to Avo in 1995, for about 10 million dollars.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('By his sixties, Uvezian had settled into a life that combined modest jazz performance with a deepening interest in cigars. He was a smoker of the old Cuban school, educated by the same Havana tobacco culture that Sinatra and his circle had absorbed in their own Manhattan years. The Dominican Republic, which had become the premium cigar world''s alternative to Cuba by the 1980s, offered what Uvezian needed: access to excellent manufacturing and the possibility of building something under his own name.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Para el puro, se dirigió a Hendrik Kelner, que había abierto Tabacos Dominicanos (Tabadom) en 1984. Según la prensa del sector, el primer pedido de Kelner para Avo, 17 000 puros, data de 1987 y la tienda Davidoff de Madison Avenue vende la marca en 1988; la primera salida se fecha en 1988. Wikipedia escribe que Davidoff adquirió en 1995 los derechos de distribución de Avo, por un importe de unos 10 millones de dólares.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Pasados los sesenta, Uvezian llevaba una vida que mezclaba conciertos episódicos con un interés creciente por el puro. Fumaba a la vieja escuela cubana, formado por la misma cultura del tabaco habanero que Sinatra y su círculo habían absorbido en sus años neoyorquinos. La República Dominicana, convertida en los años ochenta en la alternativa del puro premium a Cuba, le ofrecía lo que buscaba: una fabricación excelente y la posibilidad de levantar algo con su nombre.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Für die Zigarre wandte er sich an Hendrik Kelner, der 1984 Tabacos Dominicanos (Tabadom) eröffnet hatte. Laut Fachpresse stammt Kelners erste Bestellung für Avo, 17 000 Zigarren, von 1987, und das Davidoff-Geschäft an der Madison Avenue verkauft die Marke 1988; die erste Veröffentlichung wird auf 1988 datiert. Wikipedia schreibt, Davidoff habe 1995 die Vertriebsrechte an Avo erworben, für einen Betrag von rund 10 Millionen Dollar.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Jenseits der sechzig führte Uvezian ein Leben, das gelegentliche Auftritte mit einem wachsenden Interesse an der Zigarre verband. Er rauchte nach kubanischer alter Schule, geprägt von derselben Havanna-Tabakkultur, die Sinatra und sein Kreis in ihren New Yorker Jahren aufgenommen hatten. Die Dominikanische Republik, in den achtziger Jahren zur Alternative der Premiumzigarre zu Kuba geworden, bot ihm, was er suchte: eine ausgezeichnete Fertigung und die Möglichkeit, etwas unter seinem Namen aufzubauen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('至于雪茄，他找到了 Hendrik Kelner，后者于1984年开办了 Tabacos Dominicanos（Tabadom）。据行业媒体报道，Kelner 为 Avo 下的首笔订单（17 000 支雪茄）可追溯到1987年，Madison Avenue 上的 Davidoff 门店于1988年销售该品牌；首次推出的时间标为1988年。维基百科写道，Davidoff 于1995年获得 Avo 的经销权，金额约1000万美元。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('过了六十岁，乌韦兹扬的日子把零星的演出与日渐加深的雪茄兴趣掺在一起。他抽的是古巴老派的路数，受的是辛纳屈及其圈子在纽约岁月里吸收的那套哈瓦那烟草文化的熏陶。八十年代成为古巴之外高端雪茄替代产地的多米尼加共和国，正好给了他想要的东西：出色的制作，以及用自己的名字建起点什么的可能。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('وللسيجار اتجه إلى Hendrik Kelner، الذي كان قد افتتح Tabacos Dominicanos (Tabadom) عام 1984. وبحسب صحافة المهنة، يعود أول طلب قدّمه Kelner لعلامة Avo، وهو 17 000 سيجار، إلى عام 1987، ويبيع متجر Davidoff في Madison Avenue العلامة عام 1988؛ وتُؤرَّخ أولى الإصدارات بعام 1988. وتكتب ويكيبيديا أن Davidoff اشترت عام 1995 حقوق توزيع Avo، بمبلغ يقارب 10 ملايين دولار.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('بعد الستين، كان أوفيزيان يعيش حياة تمزج حفلات متفرّقة باهتمام متنامٍ بالسيجار. كان يدخّن على المدرسة الكوبية القديمة، متشرّبًا ثقافة تبغ هافانا نفسها التي استوعبها سيناترا ودائرته في سنواتهم النيويوركية. وكانت الجمهورية الدومينيكية، التي صارت في الثمانينيات بديل السيجار الفاخر عن كوبا، تقدّم له ما يبحث عنه: صناعة ممتازة، وإمكان بناء شيء يحمل اسمه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Les cigares sont roulés en République dominicaine, dans la fabrique OK Cigars de Tabadom, filiale d''Oettinger Davidoff (presse du métier, 2016 et 2025). En janvier 2015, la marque a resserré son offre en quatre lignes courantes, Classic, Domaine, Heritage et XO ; Signature et Maduro étaient arrêtées. La ligne XO porte des termes musicaux pour noms de vitolas : Notturno, Preludio, Intermezzo, Legato, Maestoso.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Son ami Zino Davidoff facilita la rencontre avec la manufacture Tabadom, à Villa González — celle qu''Hendrik Kelner avait fondée en 1984, et où se développait la production dominicaine de Davidoff. Les premiers Avo XO parurent en 1988, immédiatement reconnaissables à une convention de nommage qu''aucun autre fabricant n''employait : les vitoles portaient des noms d''accords de jazz — Intermezzo, Maestoso, Notturno, Impromptu — plutôt que les désignations numériques ou de format en usage dans le métier. C''était une affirmation esthétique, et elle s''avéra commercialement efficace.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('The cigars are rolled in the Dominican Republic, in the OK Cigars factory of Tabadom, a subsidiary of Oettinger Davidoff (trade press, 2016 and 2025). In January 2015 the brand narrowed its offer to four current lines, Classic, Domaine, Heritage and XO; Signature and Maduro were discontinued. The XO line takes musical terms as its vitola names: Notturno, Preludio, Intermezzo, Legato, Maestoso.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('His friend Zino Davidoff facilitated the introduction to the Tabadom factory in Villa González — the one Hendrik Kelner had founded in 1984, where Davidoff''s Dominican production was being developed. The first Avo XOs appeared in 1988, immediately distinguished by naming conventions that no other cigar manufacturer had employed: the vitolas carried jazz chord names — Intermezzo, Maestoso, Notturno, Impromptu — rather than the numerical or format-based designations that the rest of the industry used. It was a statement of aesthetic identity that proved to be commercially effective.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Los puros se tuercen en República Dominicana, en la fábrica OK Cigars de Tabadom, filial de Oettinger Davidoff (prensa del sector, 2016 y 2025). En enero de 2015, la marca redujo su oferta a cuatro líneas corrientes, Classic, Domaine, Heritage y XO; Signature y Maduro quedaron descatalogadas. La línea XO lleva términos musicales como nombres de vitolas: Notturno, Preludio, Intermezzo, Legato, Maestoso.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Su amigo Zino Davidoff facilitó el encuentro con la manufactura Tabadom, en Villa González —la que Hendrik Kelner había fundado en 1984, y donde se desarrollaba la producción dominicana de Davidoff. Los primeros Avo XO aparecieron en 1988, inmediatamente reconocibles por una convención de nombres que ningún otro fabricante empleaba: las vitolas llevaban nombres de acordes de jazz —Intermezzo, Maestoso, Notturno, Impromptu— en lugar de las designaciones numéricas o de formato al uso en el oficio. Era una afirmación estética, y resultó comercialmente eficaz.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Die Zigarren werden in der Dominikanischen Republik gerollt, in der Fabrik OK Cigars von Tabadom, einer Tochtergesellschaft von Oettinger Davidoff (Fachpresse, 2016 und 2025). Im Januar 2015 hat die Marke ihr Angebot auf vier laufende Linien verschlankt, Classic, Domaine, Heritage und XO; Signature und Maduro wurden eingestellt. Die Linie XO trägt musikalische Begriffe als Vitola-Namen: Notturno, Preludio, Intermezzo, Legato, Maestoso.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Sein Freund Zino Davidoff bahnte die Begegnung mit der Manufaktur Tabadom in Villa González an — jener, die Hendrik Kelner 1984 gegründet hatte und in der Davidoffs dominikanische Produktion entstand. Die ersten Avo XO erschienen 1988, sofort erkennbar an einer Namensordnung, die kein anderer Hersteller verwendete: Die Formate trugen Namen von Jazzakkorden — Intermezzo, Maestoso, Notturno, Impromptu — statt der im Fach üblichen Zahlen- oder Formatbezeichnungen. Das war eine ästhetische Behauptung, und sie erwies sich als kaufmännisch wirksam.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('雪茄在多米尼加共和国卷制，地点是 Tabadom 旗下的 OK Cigars 工厂，Tabadom 是 Oettinger Davidoff 的子公司（行业媒体，2016年与2025年）。2015年1月，该品牌把产品线收窄为四个在售系列：Classic、Domaine、Heritage 与 XO；Signature 与 Maduro 已停产。XO 系列以音乐术语作为规格名称：Notturno、Preludio、Intermezzo、Legato、Maestoso。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('他的朋友齐诺·大卫杜夫促成了他与比亚冈萨雷斯 Tabadom 工厂的相识——那是亨德里克·凯尔纳 1984 年创办的工厂，也正是大卫杜夫多米尼加生产线所在之处。第一批 Avo XO 于1988年问世，一眼可辨，因为它用了别家都不用的命名法：各个规格取的是爵士和弦的名字——Intermezzo、Maestoso、Notturno、Impromptu——而不是行业惯用的编号或形制名称。这是一次美学上的主张，而它在商业上也奏了效。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('تُلفّ السيجارات في الجمهورية الدومينيكية، في مصنع OK Cigars التابع لـ Tabadom، وهي فرع من Oettinger Davidoff (صحافة المهنة، 2016 و2025). وفي يناير 2015 حصرت العلامة عرضها في أربعة خطوط جارية هي Classic وDomaine وHeritage وXO؛ وتوقّف إنتاج Signature وMaduro. ويحمل خط XO مصطلحات موسيقية أسماءً لقياساته: Notturno وPreludio وIntermezzo وLegato وMaestoso.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('يسّر له صديقه زينو دافيدوف اللقاء بمصنع تابادوم في بيّا غونثاليث — المصنع الذي أسّسه هندريك كيلنر عام 1984، والذي كان يتطوّر فيه إنتاج دافيدوف الدومينيكي. ظهرت أولى سيجارات «آفو إكس أو» عام 1988، وكانت تُعرف فورًا من طريقة تسمية لم يستعملها صانع آخر: فالقياسات تحمل أسماء تآلفات جازية — إنترميتزو، ومايستوزو، ونوتورنو، وإمبرومبتو — بدل التسميات الرقمية أو تسميات الأشكال المتداولة في المهنة. كان ذلك موقفًا جماليًّا، وثبت أنه ناجح تجاريًّا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Davidoff a fêté ses anniversaires par une édition limitée chaque année de 2001 à 2014, puis l''Avo 90th en 2016. En mars 2026, la presse du métier rapportait que la maison prévoyait de marquer le centenaire d''Uvezian au salon PCA d''avril.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
UNION ALL SELECT 'Avo', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Le groupe Davidoff racheta Avo dans les années 1990 et a maintenu la production en République dominicaine dans le même esprit. Avo Uvezian est mort en 2017, à quatre-vingt-neuf ans. La marque continue en hommage, chaque sortie tenant le lien entre le vocabulaire du jazz et les possibilités du tabac dominicain — un lien qu''il avait établi en décidant, à un âge où la plupart des musiciens songent à s''arrêter, de devenir fabricant de cigares.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
