UNION ALL SELECT 'Avo', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The Davidoff group acquired Avo during the 1990s and has maintained production in the Dominican Republic under the original ethos. Avo Uvezian died in 2017, at eighty-nine. The brand continues as a tribute, with each release maintaining the connection between jazz''s vocabulary and Dominican tobacco''s possibilities that Uvezian established when he decided, at an age when most musicians are considering retirement, to become a cigar maker instead.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Avo'
