UNION ALL SELECT 'Avo', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('احتفلت Davidoff بمناسباتها السنوية بإصدار محدود في كل عام من 2001 إلى 2014، ثم بـ Avo 90th عام 2016. وفي مارس 2026 أفادت صحافة المهنة بأن الدار تعتزم إحياء مئوية Uvezian في معرض PCA في أبريل.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Avo'
