UNION ALL SELECT 'Macanudo', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Macanudo vient de Jamaïque. Selon la presse du métier, c''était une petite marque roulée à la main à la fabrique Temple Hall, à Kingston, pour le marché britannique. En 1968, General Cigar Co. rachète Temple Hall avec la marque, et la presse du métier note que Macanudo est plus ancienne que les 50 ans fêtés en 2018. La date de création de la marque n''est pas établie ; 1968 est l''année du rachat.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Les origines de Macanudo sont caribéennes et compliquées. La marque fut fondée en Jamaïque en 1868 sous le nom de Temple Hall, à partir d''un tabac jamaïcain qui offrait quelque chose d''inhabituel sur le marché premium du milieu du XIXe siècle : un profil léger et crémeux, de force minimale et d''accès maximal. Les sols et le climat de l''île donnaient un tabac plus proche du Connecticut Shade que de la Vuelta Abajo cubaine — souple, doux, indulgent pour les fumeurs qui trouvaient exigeante l''intensité des grandes marques de La Havane.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Macanudo comes from Jamaica. According to the trade press, it was a small hand-rolled brand made at the Temple Hall factory in Kingston for the British market. In 1968 General Cigar Co. bought Temple Hall together with the brand, and the trade press notes that Macanudo is older than the 50 years celebrated in 2018. The date the brand was created is not established; 1968 is the year of the purchase.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Macanudo''s origins are Caribbean and distinctly complicated. The brand was founded in Jamaica in 1868 under the name Temple Hall, using Jamaican-grown tobacco that offered something genuinely unusual in the mid-nineteenth century premium market: a light, creamy profile with minimal strength and maximum accessibility. Jamaica''s soils and climate produced a tobacco character that was more like Connecticut shade than Cuban Vuelta Abajo — smooth, gentle, and forgiving for smokers who found the intensity of Havana''s great brands demanding.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Macanudo viene de Jamaica. Según la prensa del sector, era una pequeña marca hecha a mano en la fábrica Temple Hall, en Kingston, para el mercado británico. En 1968, General Cigar Co. compra Temple Hall junto con la marca, y la prensa del sector señala que Macanudo es anterior a los 50 años celebrados en 2018. La fecha de creación de la marca no está establecida; 1968 es el año de la compra.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Los orígenes de Macanudo son caribeños y complicados. La marca se fundó en Jamaica en 1868 con el nombre de Temple Hall, a partir de un tabaco jamaicano que ofrecía algo inhabitual en el mercado premium de mediados del siglo XIX: un perfil ligero y cremoso, de fuerza mínima y acceso máximo. Los suelos y el clima de la isla daban un tabaco más cercano al Connecticut Shade que a la Vuelta Abajo cubana —flexible, suave, indulgente con los fumadores que encontraban exigente la intensidad de las grandes marcas de La Habana.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Macanudo stammt aus Jamaika. Laut der Fachpresse war es eine kleine, handgerollte Marke, die in der Fabrik Temple Hall in Kingston für den britischen Markt hergestellt wurde. 1968 kaufte General Cigar Co. Temple Hall samt der Marke, und die Fachpresse vermerkt, dass Macanudo älter ist als die 50 Jahre, die 2018 gefeiert wurden. Das Gründungsdatum der Marke ist nicht belegt; 1968 ist das Jahr des Kaufs.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Ursprünge von Macanudo sind karibisch und verwickelt. Die Marke wurde 1868 in Jamaika unter dem Namen Temple Hall gegründet, aus einem jamaikanischen Tabak, der auf dem Premiummarkt der Mitte des 19. Jahrhunderts etwas Ungewöhnliches bot: ein leichtes, cremiges Profil, von geringster Stärke und größter Zugänglichkeit. Böden und Klima der Insel ergaben einen Tabak, der dem Connecticut Shade näherstand als der kubanischen Vuelta Abajo — geschmeidig, mild, nachsichtig gegenüber Rauchern, denen die Intensität der großen Havanna-Marken zu viel abverlangte.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Macanudo来自牙买加。据行业媒体，它原是一个小型手工卷制品牌，在金斯敦的Temple Hall工厂为英国市场生产。1968年，General Cigar Co.买下Temple Hall及这个品牌，行业媒体指出，Macanudo的历史比2018年庆祝的50周年还要久远。品牌的创立日期并无定论；1968年是收购之年。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('马卡努多的来历是加勒比式的，也是复杂的。1868年，这个品牌以「圣殿厅」之名创立于牙买加，用的是一种在19世纪中叶高端市场上颇为少见的牙买加烟草：轻盈、奶油质地，力度最小而门槛最低。岛上的土壤与气候，长出的烟草更接近康涅狄格阴植叶，而不是古巴的阿巴霍谷——柔韧、温和，对那些觉得哈瓦那大牌太过强烈的烟客格外宽容。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تنحدر Macanudo من جامايكا. وبحسب صحافة القطاع، كانت علامة صغيرة تُلفّ يدويًا في مصنع Temple Hall في كينغستون للسوق البريطانية. وفي عام 1968 اشترت General Cigar Co. مصنع Temple Hall مع العلامة، وتشير صحافة القطاع إلى أن عمر Macanudo يتجاوز الخمسين عامًا التي احتُفل بها في 2018. لم يثبت تاريخ إنشاء العلامة؛ و1968 هو عام الشراء.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('أصول ماكانودو كاريبية ومتشابكة. تأسّست العلامة في جامايكا عام 1868 باسم «تمبل هول»، انطلاقًا من تبغ جامايكي كان يقدّم شيئًا غير مألوف في السوق الفاخرة في منتصف القرن التاسع عشر: طابعًا خفيفًا قشديًّا، أدنى قوة وأوسع تناول. فقد كانت تربة الجزيرة ومناخها يعطيان تبغًا أقرب إلى كونيتيكت شيد منه إلى فويلتا أباخو الكوبية — ليّنًا، لطيفًا، متسامحًا مع المدخّنين الذين تُرهقهم شدّة كبريات علامات هافانا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La suite se raconte en deux versions. Wikipédia écrit qu''en 1971 General Cigar lance une marque Macanudo distincte, mise au point sous la direction de Ramón Cifuentes, ancien de Partagás, mais l''article signale lui-même des passages à préciser. La presse du métier, elle, établit que General Cigar ferme Temple Hall en 2000 et transfère toute la production en République dominicaine ; le tabac jamaïcain quitte ensuite l''assemblage. Edgar M. Cullman Sr., qui dirigea General Cigar pendant des décennies, est mort en août 2011 à 93 ans.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('L''installation à New York dans les années 1960, sous l''impulsion d''Edgar M. Cullman Sr., transforma une spécialité caribéenne en phénomène américain. Cullman avait compris que le fumeur aisé de l''après-guerre voulait du luxe sans épreuve — un cigare disant le raffinement sans exiger d''expertise ni de tolérance physique. Il repositionna Macanudo autour de capes Connecticut Shade et de tripes dominicaines, effaçant ce que le tabac jamaïcain gardait de terreux, pour un profil de crème pure, de cèdre léger et de force abordable.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The story then continues in two versions. Wikipedia writes that in 1971 General Cigar launched a distinct Macanudo brand, developed under the direction of Ramón Cifuentes, formerly of Partagás, but the article itself flags passages that need clarifying. The trade press, for its part, establishes that General Cigar closed Temple Hall in 2000 and moved all production to the Dominican Republic; Jamaican tobacco then left the blend. Edgar M. Cullman Sr., who ran General Cigar for decades, died in August 2011 aged 93.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The migration to New York in the 1960s under Edgar M. Cullman Sr. transformed Macanudo from a Caribbean specialty into an American phenomenon. Cullman understood that the wealthy American smoker of the postwar decades wanted luxury without challenge — a cigar that communicated refinement without demanding expertise or physical tolerance. He repositioned Macanudo around Connecticut shade wrappers and Dominican fillers, eliminating the Jamaican tobacco''s residual earthiness and producing a profile of pure cream, mild cedar, and approachable strength that no other brand was delivering with the same consistency.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La continuación se cuenta en dos versiones. Wikipedia escribe que en 1971 General Cigar lanza una marca Macanudo distinta, puesta a punto bajo la dirección de Ramón Cifuentes, procedente de Partagás, pero el propio artículo señala pasajes por precisar. La prensa del sector, por su parte, establece que General Cigar cierra Temple Hall en 2000 y traslada toda la producción a la República Dominicana; el tabaco jamaicano sale después de la ligada. Edgar M. Cullman Sr., que dirigió General Cigar durante décadas, murió en agosto de 2011 a los 93 años.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La instalación en Nueva York en los años sesenta, por impulso de Edgar M. Cullman Sr., transformó una especialidad caribeña en fenómeno estadounidense. Cullman había comprendido que el fumador acomodado de la posguerra quería lujo sin prueba —un puro que dijera refinamiento sin exigir pericia ni tolerancia física. Reposicionó Macanudo en torno a capas Connecticut Shade y tripas dominicanas, borrando lo que el tabaco jamaicano conservaba de terroso, hacia un perfil de crema pura, de cedro ligero y de fuerza asequible.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Der weitere Verlauf wird in zwei Fassungen erzählt. Wikipedia schreibt, 1971 habe General Cigar eine eigenständige Marke Macanudo eingeführt, entwickelt unter der Leitung von Ramón Cifuentes, der zuvor bei Partagás war, doch der Artikel selbst weist auf klärungsbedürftige Passagen hin. Die Fachpresse hingegen hält fest, dass General Cigar Temple Hall im Jahr 2000 schloss und die gesamte Produktion in die Dominikanische Republik verlegte; der jamaikanische Tabak verschwand danach aus der Mischung. Edgar M. Cullman Sr., der General Cigar jahrzehntelang leitete, starb im August 2011 im Alter von 93 Jahren.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die Ansiedlung in New York in den sechziger Jahren, auf Betreiben von Edgar M. Cullman Sr., machte aus einer karibischen Spezialität ein amerikanisches Phänomen. Cullman hatte begriffen, dass der wohlhabende Raucher der Nachkriegszeit Luxus ohne Prüfung wollte — eine Zigarre, die Verfeinerung ausspricht, ohne Sachkenntnis oder körperliche Duldsamkeit zu verlangen. Er stellte Macanudo auf Connecticut-Shade-Deckblätter und dominikanische Einlagen um und tilgte, was der jamaikanische Tabak an Erdigkeit behielt, hin zu einem Profil aus reiner Sahne, leichter Zeder und erschwinglicher Stärke.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('后续有两种说法。维基百科写道，1971年General Cigar推出了一个独立的Macanudo品牌，由出身Partagás的Ramón Cifuentes主持研发，但该条目本身标注有待厘清的段落。行业媒体则确认，General Cigar于2000年关闭Temple Hall，并将全部生产转移到多米尼加共和国；此后牙买加烟草退出了配方。数十年间执掌General Cigar的Edgar M. Cullman Sr.于2011年8月去世，享年93岁。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('六十年代，在埃德加·M·卡尔曼的推动下迁往纽约，把一门加勒比特产变成了美国现象。卡尔曼看明白了：战后有钱的烟客要的是不必经受考验的奢侈——一支说出精致、却不要求见识与身体耐受力的雪茄。他把马卡努多重新定位在康涅狄格阴植茄衣与多米尼加茄芯上，抹去牙买加烟草残存的泥土气，走向纯粹的奶油、淡雪松与够得着的力度。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تُروى بقية القصة في روايتين. تكتب ويكيبيديا أنّ General Cigar أطلقت عام 1971 علامة Macanudo مستقلة، طُوّرت بإشراف Ramón Cifuentes، القادم من Partagás، لكنّ المقال نفسه يشير إلى مواضع تحتاج إلى توضيح. أمّا صحافة القطاع فتثبت أنّ General Cigar أغلقت Temple Hall عام 2000 ونقلت الإنتاج كله إلى جمهورية الدومينيكان؛ وخرج التبغ الجامايكي بعد ذلك من الخلطة. وتوفي Edgar M. Cullman Sr.، الذي أدار General Cigar عقودًا، في أغسطس 2011 عن 93 عامًا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('وقد حوّل الانتقال إلى نيويورك في الستينيات، بدفع من إدغار م. كولمان الأب، اختصاصًا كاريبيًّا إلى ظاهرة أمريكية. كان كولمان قد فهم أنّ المدخّن الميسور في ما بعد الحرب يريد ترفًا بلا امتحان — سيجارًا يقول الرهافة دون أن يطلب خبرة ولا احتمالًا جسديًّا. فأعاد وضع ماكانودو حول أغلفة كونيتيكت شيد وحشوات دومينيكية، ماحيًا ما احتفظ به التبغ الجامايكي من ترابية، نحو طابع من القشدة الصافية وخشب الأرز الخفيف والقوة في المتناول.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('La Café reste le visage de la marque : cape Connecticut Shade, liant mexicain de San Andrés, tripe mexicaine et dominicaine (piloto cubano), selon la page de la maison (macanudo.com, lue en octobre 2026). La presse du métier la décrit comme le cigare doux auquel le nom Macanudo est associé.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La stratégie dépassa toutes les projections. Dans les années 1980 et 1990, chaque kiosque d''aéroport, chaque boutique d''hôtel, chaque bar de restaurant tenant une carte de cigares proposait la Macanudo Café comme choix premium par défaut. Les bagues jaunes étaient devenues un signe de luxe accessible qui traversait les milieux.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('The Café remains the face of the brand: Connecticut Shade wrapper, Mexican San Andrés binder, Mexican and Dominican filler (piloto cubano), according to the house''s page (macanudo.com, read in October 2026). The trade press describes it as the mild cigar with which the Macanudo name is associated.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The strategy worked beyond any commercial projection. Through the 1980s and into the 1990s, every airport newsstand, every hotel gift shop, every restaurant bar with a cigar program stocked Macanudo Café as the default premium option. The yellow bands became a signal of accessible luxury that crossed demographic lines.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('La Café sigue siendo el rostro de la marca: capa Connecticut Shade, capote mexicano de San Andrés, tripa mexicana y dominicana (piloto cubano), según la página de la casa (macanudo.com, consultada en octubre de 2026). La prensa del sector la describe como el puro suave al que se asocia el nombre Macanudo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La estrategia superó todas las previsiones. En los años ochenta y noventa, cada quiosco de aeropuerto, cada tienda de hotel, cada bar de restaurante con carta de puros ofrecía la Macanudo Café como opción premium por defecto. Las anillas amarillas se habían convertido en un signo de lujo accesible que atravesaba los ambientes.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Die Café bleibt das Gesicht der Marke: Deckblatt Connecticut Shade, mexikanisches Umblatt aus San Andrés, Einlage aus mexikanischem und dominikanischem Tabak (piloto cubano), laut der Seite des Hauses (macanudo.com, im Oktober 2026 abgerufen). Die Fachpresse beschreibt sie als die milde Zigarre, mit der der Name Macanudo verbunden wird.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Die Strategie übertraf alle Erwartungen. In den achtziger und neunziger Jahren bot jeder Flughafenkiosk, jeder Hotelladen, jede Restaurantbar mit Zigarrenkarte die Macanudo Café als selbstverständliche Premiumwahl an. Die gelben Banderolen waren zu einem Zeichen erschwinglichen Luxus geworden, das quer durch die Milieus ging.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Café仍是这个品牌的门面：茄衣为Connecticut Shade，内包叶来自墨西哥的San Andrés，茄芯为墨西哥与多米尼加烟叶（piloto cubano），依据品牌方的页面（macanudo.com，2026年10月查阅）。行业媒体把它描述为与Macanudo这个名字相连的那支柔和雪茄。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('这套策略超出了所有预期。八十与九十年代，凡有雪茄单的机场书报亭、酒店商店、餐厅酒吧，默认的高端选择都是 Macanudo Café。黄色的烟标成了一种跨越圈层的、可及的奢侈符号。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('تبقى Café وجه العلامة: غلاف Connecticut Shade، ورابط مكسيكي من San Andrés، وحشوة مكسيكية ودومينيكية (piloto cubano)، بحسب صفحة الدار (macanudo.com، اطُّلع عليها في أكتوبر 2026). وتصفها صحافة القطاع بأنها السيجار الناعم الذي يقترن به اسم Macanudo.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('تجاوزت الاستراتيجية كل التوقّعات. ففي الثمانينيات والتسعينيات، كان كل كشك مطار، وكل متجر فندق، وكل بار مطعم يحمل قائمة سيجار، يعرض «ماكانودو كافيه» خيارًا فاخرًا بالتلقاء. وصارت الحلقات الصفراء علامة ترف في المتناول تعبر الأوساط كلها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Inspirado ouvre une autre voie. Lancée en Europe en 2014, la gamme arrive aux États-Unis en 2016 (Cigar Coop, mai 2016) en déclinaisons de couleur d''origines différentes : Orange roulée au Honduras, Black et White en République dominicaine, Red roulée à Estelí (Nicaragua) en 2018, pour les 50 ans de la marque. La maison présente Inspirado comme ses assemblages les plus complexes et intenses. En 2014, STG décrivait General Cigar comme une filiale à 100 % de Scandinavian Tobacco Group.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('General Cigar, qui a racheté la marque, a reconnu dans les années 2010 que cette position était devenue autant un handicap qu''un atout. Les fumeurs qui avaient grandi avec la Café étaient désormais assez expérimentés pour vouloir plus exigeant. La gamme Inspirado — assemblages nicaraguayens plus corsés sous des capes de style Connecticut modifiées — fut conçue pour retenir ce public tout en attirant l''amateur plus jeune, qui associait Macanudo à la génération de ses parents. Deux âmes cohabitent désormais : la Café pour la tradition, l''Inspirado pour la suite.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Inspirado opens another path. Launched in Europe in 2014, the range reached the United States in 2016 (Cigar Coop, May 2016) in colour variants of different origins: Orange rolled in Honduras, Black and White in the Dominican Republic, Red rolled in Estelí (Nicaragua) in 2018, for the brand''s 50th anniversary. The house presents Inspirado as its most complex and intense blends. In 2014, STG described General Cigar as a 100% subsidiary of Scandinavian Tobacco Group.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('General Cigar, which acquired the brand, recognized by the 2010s that Macanudo''s extraordinary market position had become a liability as much as an asset. Smokers who had grown up with the Café were now experienced enough to want something more demanding. The Inspirado range — using fuller-bodied Nicaraguan blends under modified Connecticut-style wrappers — was designed to retain this audience while attracting the younger enthusiast who associated Macanudo with their parents'' generation rather than their own. The strategy has produced mixed but largely positive results.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Inspirado abre otro camino. Lanzada en Europa en 2014, la gama llega a Estados Unidos en 2016 (Cigar Coop, mayo de 2016) en variantes de color de orígenes distintos: Orange, torcida en Honduras; Black y White, en la República Dominicana; Red, torcida en Estelí (Nicaragua) en 2018, por los 50 años de la marca. La casa presenta Inspirado como sus ligadas más complejas e intensas. En 2014, STG describía a General Cigar como una filial al 100 % de Scandinavian Tobacco Group.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('General Cigar, que compró la marca, reconoció en los años dos mil diez que esa posición se había vuelto tanto un lastre como una baza. Los fumadores que habían crecido con la Café eran ya bastante experimentados para querer algo más exigente. La gama Inspirado —ligadas nicaragüenses más recias bajo capas de estilo Connecticut modificadas— se concibió para retener a ese público atrayendo a la vez al aficionado más joven, que asociaba Macanudo a la generación de sus padres. Dos almas conviven desde entonces: la Café para la tradición, la Inspirado para lo que sigue.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Inspirado schlägt einen anderen Weg ein. 2014 in Europa eingeführt, kommt die Linie 2016 in die Vereinigten Staaten (Cigar Coop, Mai 2016), in Farbvarianten unterschiedlicher Herkunft: Orange, gerollt in Honduras, Black und White in der Dominikanischen Republik, Red, gerollt in Estelí (Nicaragua) 2018, zum 50-jährigen Bestehen der Marke. Das Haus stellt Inspirado als seine komplexesten und intensivsten Mischungen vor. 2014 beschrieb STG General Cigar als hundertprozentige Tochter der Scandinavian Tobacco Group.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('General Cigar, das die Marke übernahm, erkannte in den 2010er Jahren, dass diese Stellung ebenso zur Last wie zum Vorteil geworden war. Die Raucher, die mit der Café groß geworden waren, hatten inzwischen genug Erfahrung, um Anspruchsvolleres zu wollen. Die Linie Inspirado — kräftigere nicaraguanische Mischungen unter abgewandelten Deckblättern im Connecticut-Stil — war gedacht, dieses Publikum zu halten und zugleich den jüngeren Liebhaber zu gewinnen, der Macanudo mit der Generation seiner Eltern verband. Seither wohnen zwei Seelen nebeneinander: die Café für die Überlieferung, die Inspirado für das, was folgt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Inspirado开辟了另一条路。该系列2014年在欧洲推出，2016年进入美国（Cigar Coop，2016年5月），以产地各异的颜色版本面世：Orange在洪都拉斯卷制，Black与White在多米尼加共和国，Red于2018年在尼加拉瓜的Estelí卷制，为纪念品牌50周年。品牌方将Inspirado称为其复杂度与浓烈度均居首的配方。2014年，STG把General Cigar描述为Scandinavian Tobacco Group的全资子公司。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Macanudo'
UNION ALL SELECT 'Macanudo', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('买下品牌的 General Cigar 在二〇一〇年代承认，这个位置既是资产也是包袱。当年跟着 Café 长大的烟客，如今已老练到想要更有难度的东西。Inspirado 系列——更结实的尼加拉瓜配方，配上经过改动的康涅狄格风格茄衣——正是为了留住这批人，同时吸引更年轻的爱好者：在后者眼里，马卡努多是父母那一代的东西。从此两个灵魂并存：Café 承接传统，Inspirado 面向之后。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Macanudo'
