UNION ALL SELECT 'Zino Platinum', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The name Zino is inseparable from a human figure: Zino Davidoff himself, born in Kiev in 1906, died in Geneva in 1994. When the Davidoff Group decided to resurrect his first name as a standalone brand in 2002, it bet on the symbolic force of a name that had defined European tobacco luxury for half a century.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('El nombre Zino es el nombre de pila del propio Zino Davidoff. Según el sitio de la marca (zino.oettingerdavidoff.com), en 1978 lanzó, con el Dr. Ernst Schneider, una marca con su nombre de pila; los primeros puros se torcieron en Honduras, en tiempos del embargo estadounidense a Cuba, para un mercado estadounidense que ya no tenía acceso al tabaco cubano.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('El nombre Zino es inseparable de una figura humana: el propio Zino Davidoff, nacido en Kiev en 1906 y fallecido en Ginebra en 1994. Cuando el grupo Davidoff decidió resucitar su nombre de pila como marca autónoma en 2002, apostó por la fuerza simbólica de un nombre que había definido el lujo del tabaco europeo durante medio siglo.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Der Name Zino ist der Vorname von Zino Davidoff selbst. Laut der Website der Marke (zino.oettingerdavidoff.com) gründete er 1978 gemeinsam mit Dr. Ernst Schneider eine Marke unter seinem Vornamen; die ersten Zigarren wurden in Honduras gerollt, zur Zeit des amerikanischen Embargos gegen Kuba, für einen amerikanischen Markt, der keinen Zugang mehr zu kubanischem Tabak hatte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Der Name Zino ist untrennbar mit einem Menschen verbunden: mit Zino Davidoff selbst, 1906 in Kiew geboren, 1994 in Genf gestorben. Als die Davidoff-Gruppe 2002 beschloss, seinen Vornamen als eigenständige Marke wiederzubeleben, setzte sie auf die sinnbildliche Kraft eines Namens, der den europäischen Tabakluxus ein halbes Jahrhundert lang bestimmt hatte.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Zino这个名字就是Zino Davidoff本人的名字。据品牌网站（zino.oettingerdavidoff.com），他于1978年与Ernst Schneider博士一道，推出了一个以自己名字命名的品牌；首批雪茄在洪都拉斯卷制，当时正值美国对古巴实行禁运，面向的是已无法获得古巴烟草的美国市场。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Zino 这个名字与一个真实的人密不可分：Zino Davidoff 本人，1906 年生于基辅，1994 年逝于日内瓦。2002 年，Davidoff 集团决定让他的名字复活为一个独立品牌，赌的正是这个名字的象征力量——半个世纪以来，它定义了欧洲的烟草奢华。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('اسم Zino هو الاسم الأول لـZino Davidoff نفسه. وبحسب موقع العلامة (zino.oettingerdavidoff.com)، أطلق عام 1978، مع الدكتور Ernst Schneider، علامة تحمل اسمه الأول؛ وكانت أولى السيجارات تُلفّ في هندوراس، في زمن الحظر الأمريكي على كوبا، لسوق أمريكية لم يعد لها منفذ إلى التبغ الكوبي.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('اسم Zino لا ينفصل عن شخص بعينه: Zino Davidoff نفسه، المولود في كييف عام 1906 والمتوفّى في جنيف عام 1994. وحين قرّرت مجموعة Davidoff عام 2002 أن تبعث اسمه الأول علامةً قائمة بذاتها، راهنت على القوة الرمزية لاسم ظلّ نصف قرن يحدّد معنى الترف التبغي في أوروبا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Toujours selon la maison, la production passa ensuite par plusieurs régions de culture : la République dominicaine, le Honduras et le Nicaragua.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La première incarnation de Zino avait été distincte : dans les années 1980, Zino Davidoff créa sous son prénom une gamme de cigares de niche, fabriqués au Honduras, disponibles uniquement dans quelques adresses triées du monde. Ces Zinos originaux avaient une réputation d''excellence artisanale réservée aux initiés. À la mort de Zino Davidoff, la gamme fut graduellement absorbée dans la marque-mère Davidoff.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Again according to the house, production then passed through several growing regions: the Dominican Republic, Honduras and Nicaragua.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The first incarnation of Zino had been distinct: in the 1980s, Zino Davidoff created under his first name a niche range of cigars, manufactured in Honduras, available only at a handful of carefully selected addresses worldwide. These original Zinos had a reputation for artisanal excellence reserved for insiders. Upon Zino Davidoff''s death, the range was gradually absorbed into the parent Davidoff brand.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Siempre según la casa, la producción pasó después por varias regiones de cultivo: la República Dominicana, Honduras y Nicaragua.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La primera encarnación de Zino había sido distinta: en los años ochenta, Zino Davidoff creó bajo su nombre de pila una gama de puros de nicho, fabricados en Honduras y disponibles solo en unas pocas direcciones escogidas del mundo. Aquellos Zino originales tenían fama de excelencia artesanal reservada a los iniciados. A la muerte de Zino Davidoff, la gama fue absorbida poco a poco por la marca matriz Davidoff.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Ebenfalls laut dem Haus durchlief die Produktion danach mehrere Anbauregionen: die Dominikanische Republik, Honduras und Nicaragua.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die erste Gestalt von Zino war eine andere gewesen: In den 1980er Jahren schuf Zino Davidoff unter seinem Vornamen eine Nischenlinie von Zigarren, in Honduras gefertigt und nur an einigen wenigen ausgesuchten Adressen der Welt erhältlich. Diese ursprünglichen Zinos galten unter Eingeweihten als Inbegriff handwerklicher Vollendung. Nach dem Tod Zino Davidoffs ging die Linie nach und nach in der Dachmarke Davidoff auf.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('同样据品牌方，生产随后辗转于多个种植地区：多米尼加共和国、洪都拉斯和尼加拉瓜。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Zino Platinum'
UNION ALL SELECT 'Zino Platinum', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Zino 的第一次登场是另一副模样：1980 年代，Zino Davidoff 以自己的名字创立了一条小众雪茄线，在洪都拉斯生产，全世界只有寥寥数处精选店铺有售。这些最初的 Zino 在圈内人中享有工艺卓绝的口碑。Zino Davidoff 去世后，该系列逐渐被母品牌 Davidoff 吸收。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Zino Platinum'
