UNION ALL SELECT 'Excalibur', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Excalibur est une ligne non cubaine de la famille Hoyo de Monterrey. Elle a été créée par Villazon & Co., la maison de Tampa que dirigeait Frank Llaneza, selon la presse du métier (juin 2022) : à l''origine, une version des Hoyo en cape Connecticut shade, roulée au Honduras. Villazon faisait alors les Punch et Hoyo de Monterrey non cubains, dont elle tenait les droits américains, hérités des lignes que Fernando Palicio avait cédées à la famille Villazon après la nationalisation cubaine de 1959 (Wikipédia, page à source unique). Les pages lues ne disent rien de l''origine du nom Excalibur.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Excalibur est une marque née d''un empêchement juridique, et non d''une intention de style. Villazon & Co., la maison de Tampa que dirigeait Frank Llaneza, avait racheté à Fernando Palicio, après la nationalisation cubaine de 1959, les lignes Punch, Hoyo de Monterrey et Belinda. Elle pouvait les vendre aux États-Unis ; elle ne pouvait pas se servir du nom Hoyo de Monterrey partout ailleurs. « Comme nous ne pouvons pas utiliser Hoyo de Monterrey, nous avons développé une marque appelée Excalibur, que nous vendons en Allemagne et en Angleterre », expliquait Dan Blumenthal, alors président de Villazon, dans un entretien que Cigar Advisor cite encore. Le nom du roi Arthur n''est donc pas une trouvaille de publicitaire : c''est un contournement de marque.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Excalibur is a non-Cuban line from the Hoyo de Monterrey family. According to the trade press (June 2022), it was created by Villazon & Co., the Tampa house run by Frank Llaneza: originally a version of the Hoyo in a Connecticut shade wrapper, rolled in Honduras. Villazon was then making the non-Cuban Punch and Hoyo de Monterrey, whose American rights it held, inherited from the lines that Fernando Palicio had sold to the Villazon family after the Cuban nationalisation of 1959 (Wikipedia, a single-source page). The pages read say nothing about the origin of the name Excalibur.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Excalibur was born of a trademark obstacle, not of a stylistic intention. Villazon & Co., the Tampa house run by Frank Llaneza, had bought from Fernando Palicio, after the Cuban nationalisation of 1959, the Punch, Hoyo de Monterrey and Belinda lines. It could sell them in the United States; it could not use the Hoyo de Monterrey name everywhere else. "Because we can''t use Hoyo de Monterrey, we developed a brand called Excalibur, which we sell in Germany and England," explained Dan Blumenthal, then chairman of Villazon, in an interview Cigar Advisor still quotes. King Arthur''s sword, then, is not an advertising find: it is a way around a trademark.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Excalibur es una línea no cubana de la familia Hoyo de Monterrey. Fue creada por Villazon & Co., la casa de Tampa dirigida por Frank Llaneza, según la prensa del sector (junio de 2022): en origen, una versión de los Hoyo con capa Connecticut shade, liada en Honduras. Villazon fabricaba entonces los Punch y Hoyo de Monterrey no cubanos, cuyos derechos estadounidenses poseía, heredados de las líneas que Fernando Palicio había cedido a la familia Villazon tras la nacionalización cubana de 1959 (Wikipedia, página de fuente única). Las páginas consultadas no dicen nada del origen del nombre Excalibur.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Excalibur nació de un impedimento de marca, no de una intención de estilo. Villazon & Co., la casa de Tampa dirigida por Frank Llaneza, había comprado a Fernando Palicio, tras la nacionalización cubana de 1959, las líneas Punch, Hoyo de Monterrey y Belinda. Podía venderlas en Estados Unidos; no podía usar el nombre Hoyo de Monterrey en el resto del mundo. «Como no podemos usar Hoyo de Monterrey, desarrollamos una marca llamada Excalibur, que vendemos en Alemania e Inglaterra», explicaba Dan Blumenthal, entonces presidente de Villazon, en una entrevista que Cigar Advisor sigue citando. La espada del rey Arturo no es, pues, un hallazgo publicitario: es un rodeo legal.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Excalibur ist eine nichtkubanische Linie aus der Familie Hoyo de Monterrey. Sie wurde laut Fachpresse (Juni 2022) von Villazon & Co. geschaffen, dem von Frank Llaneza geführten Haus aus Tampa: ursprünglich eine Version der Hoyo mit Deckblatt Connecticut Shade, gerollt in Honduras. Villazon stellte damals die nichtkubanischen Punch und Hoyo de Monterrey her, deren amerikanische Rechte es hielt; sie stammten aus den Linien, die Fernando Palicio nach der kubanischen Verstaatlichung von 1959 an die Familie Villazon abgetreten hatte (Wikipedia, Seite mit nur einer Quelle). Die gelesenen Seiten sagen nichts über den Ursprung des Namens Excalibur.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Excalibur entstand aus einem markenrechtlichen Hindernis, nicht aus einer stilistischen Absicht. Villazon & Co., das von Frank Llaneza geführte Haus aus Tampa, hatte Fernando Palicio nach der kubanischen Verstaatlichung von 1959 die Linien Punch, Hoyo de Monterrey und Belinda abgekauft. Verkaufen durfte es sie in den Vereinigten Staaten; den Namen Hoyo de Monterrey überall sonst zu führen, war ihm verwehrt. „Da wir Hoyo de Monterrey nicht verwenden können, haben wir eine Marke namens Excalibur entwickelt, die wir in Deutschland und England verkaufen", erklärte Dan Blumenthal, damals Vorsitzender von Villazon, in einem Interview, das Cigar Advisor bis heute zitiert. Das Schwert von König Artus ist also kein Werbeeinfall, sondern ein Umweg um ein Markenrecht.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Excalibur 是 Hoyo de Monterrey 家族中的一个非古巴系列。据行业媒体（2022年6月）报道，它由坦帕的 Villazon & Co. 创立，该公司由 Frank Llaneza 执掌；起初是 Hoyo 的一个版本，采用 Connecticut shade 茄衣，在洪都拉斯卷制。当时 Villazon 生产非古巴的 Punch 与 Hoyo de Monterrey，并持有其美国权利；这些权利承自 Fernando Palicio 在1959年古巴国有化之后转让给 Villazon 家族的系列（Wikipedia，该页仅有单一来源）。所读页面均未提及 Excalibur 这一名称的由来。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Excalibur（王者之剑）的诞生源于一个商标障碍，而非风格构想。由弗兰克·利亚内萨执掌的坦帕老号 Villazon & Co.，在1959年古巴国有化之后，从费尔南多·帕利西奥手中买下了 Punch、Hoyo de Monterrey 与 Belinda 三个系列。它可以在美国销售这些牌子，却无法在其他地方使用 Hoyo de Monterrey 之名。「因为我们不能用 Hoyo de Monterrey，所以我们开发了一个叫 Excalibur 的牌子，在德国和英国销售。」时任 Villazon 董事长的丹·布卢门塔尔如此解释——这段话至今仍被 Cigar Advisor 引用。可见亚瑟王之剑并非广告灵感，而是一条绕开商标的路。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Excalibur خط غير كوبي من عائلة Hoyo de Monterrey. أنشأته شركة Villazon & Co.، الدار التي في تامبا بإدارة Frank Llaneza، بحسب الصحافة المتخصصة (حزيران/يونيو 2022): كان في الأصل نسخة من Hoyo بغلاف Connecticut shade، تُلَفّ في هندوراس. وكانت Villazon تصنع آنذاك Punch وHoyo de Monterrey غير الكوبيين، وهي تملك حقوقهما الأمريكية، موروثة عن الخطوط التي تنازل عنها Fernando Palicio لعائلة Villazon بعد التأميم الكوبي سنة 1959 (Wikipedia، صفحة بمصدر واحد). والصفحات المقروءة لا تقول شيئًا عن أصل اسم Excalibur.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('وُلدت إكسكاليبر من عائق يتعلق بالعلامة التجارية، لا من نيّة أسلوبية. فقد اشترت شركة فيّازون (Villazon & Co.)، وهي دار من تامبا كان يديرها فرانك يانيسا، من فرناندو باليسيو، بعد التأميم الكوبي سنة 1959، خطوط بونتش وأويو دي مونتيري وبليندا. كان بوسعها بيعها في الولايات المتحدة، لكن لم يكن بوسعها استعمال اسم أويو دي مونتيري في سائر البلدان. قال دان بلومنتال، رئيس فيّازون آنذاك، في حديث ما زالت مجلة Cigar Advisor تنقله: «بما أننا لا نستطيع استعمال أويو دي مونتيري، طوّرنا علامة اسمها إكسكاليبر نبيعها في ألمانيا وإنجلترا». فسيف الملك آرثر إذن ليس ابتكارًا إعلانيًا، بل التفافًا على حقّ علامة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Frank Llaneza, mort en 2010, dit avoir visité le Honduras pour la première fois en 1960, deux ans avant l''embargo, quand l''industrie y était déjà en développement ; la presse du métier le compte parmi les premiers à y faire des cigares premium.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Llaneza avait découvert le Honduras en 1960, deux ans avant l''embargo, et Villazon y transféra sa production roulée à la main au cours de la décennie, ne gardant à Tampa qu''un atelier réduit. C''est de là que vient le profil de la ligne : les tabacs de la vallée de Jamastrán, terreux, boisés, francs à la combustion, dans un registre plus rond que puissant.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Frank Llaneza, who died in 2010, says he first visited Honduras in 1960, two years before the embargo, when the industry there was already developing; the trade press counts him among the first to make premium cigars there.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Llaneza had discovered Honduras in 1960, two years before the embargo, and Villazon moved its hand-rolled production there during that decade, keeping only a reduced workshop in Tampa. That is where the line''s profile comes from: the tobaccos of the Jamastrán valley, earthy, woody, clean-burning, in a register more round than powerful.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Frank Llaneza, fallecido en 2010, dice haber visitado Honduras por primera vez en 1960, dos años antes del embargo, cuando la industria ya se estaba desarrollando allí; la prensa del sector lo cuenta entre los primeros en hacer puros premium en ese país.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Llaneza había descubierto Honduras en 1960, dos años antes del embargo, y Villazon trasladó allí su producción hecha a mano a lo largo de esa década, conservando en Tampa solo un taller reducido. De ahí viene el perfil de la línea: los tabacos del valle de Jamastrán, terrosos, amaderados, de combustión franca, en un registro más redondo que potente.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Frank Llaneza, der 2010 starb, sagt, er habe Honduras 1960 zum ersten Mal besucht, zwei Jahre vor dem Embargo, als die Industrie dort schon im Aufbau war; die Fachpresse zählt ihn zu den Ersten, die dort Premiumzigarren herstellten.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Llaneza hatte Honduras 1960 entdeckt, zwei Jahre vor dem Embargo, und Villazon verlagerte seine handgerollte Produktion im Lauf des Jahrzehnts dorthin; in Tampa blieb nur eine kleine Werkstatt. Daher stammt das Profil der Linie: die Tabake des Jamastrán-Tals, erdig, holzig, mit sauberem Abbrand, eher rund als kraftvoll.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Frank Llaneza 于2010年去世。他自称1960年首次到访洪都拉斯，比禁运早两年，当时当地的产业已在发展；行业媒体将他列为在当地制作高端雪茄的首批人物之一。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('利亚内萨1960年初识洪都拉斯，比禁运早两年；Villazon 在那十年间将手工卷制迁往当地，坦帕只留下一个小作坊。系列的风味由此而来：哈马斯特兰河谷的烟叶，土气、木质、燃烧干净，圆润多于强劲。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('يقول Frank Llaneza، الذي توفي سنة 2010، إنه زار هندوراس أول مرة سنة 1960، قبل الحصار بعامين، حين كانت الصناعة هناك في طور النمو أصلًا؛ وتعدّه الصحافة المتخصصة من أوائل من صنعوا السيجار الفاخر فيها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('كان يانيسا قد اكتشف هندوراس سنة 1960، أي قبل الحصار بعامين، ونقلت فيّازون إليها إنتاجها الملفوف يدويًا خلال ذلك العقد، ولم تُبقِ في تامبا سوى ورشة مصغّرة. من هناك يأتي طابع الخط: تبغ وادي خاماستران، ترابيّ، خشبيّ، صافي الاحتراق، في سجلّ مستدير أكثر منه قويًّا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('La date de naissance diverge selon les pages. En mai 2021, la presse du métier annonçait les 40 ans de la marque « cette année » : cela mène à 1981, mais aucune année de fondation n''y est écrite. Un test de Cigar Coop (février 2012) et des détaillants situent l''introduction d''Excalibur dans les années 1970. La page de la marque déposée n''a pas pu être lue (403). La ligne Dark Knight est sortie de la gamme 1066 en 2010 selon Cigar Coop.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La date de naissance n''est pas établie de la même façon par tout le monde, et cette fiche le dit plutôt que de choisir en silence. Cigar Aficionado, en mai 2021, disait la ligne quadragénaire cette année-là — donc 1981. Cigar Advisor date de 1992 son lancement comme ligne Hoyo de Monterrey, ce qui se comprend si l''on distingue la marque européenne de son arrivée sous l''enseigne Hoyo aux États-Unis. Des détaillants évoquent les années 1970. L''atlas retient 1981, sur la source la plus précise.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('The date of birth differs from page to page. In May 2021, the trade press announced the brand''s 40th anniversary “this year”: that leads to 1981, but no founding year is written there. A Cigar Coop test (February 2012) and retailers place Excalibur''s introduction in the 1970s. The registered-trademark page could not be read (403). The Dark Knight line came out of the 1066 range in 2010 according to Cigar Coop.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The founding date is not established the same way by everyone, and this entry says so rather than choosing in silence. Cigar Aficionado, in May 2021, called the line forty years old that year — so 1981. Cigar Advisor dates its launch as a Hoyo de Monterrey line to 1992, which makes sense if one separates the European brand from its arrival under the Hoyo name in the United States. Retailers mention the 1970s. The atlas keeps 1981, on the most precise source.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('La fecha de nacimiento diverge según las páginas. En mayo de 2021, la prensa del sector anunciaba los 40 años de la marca «este año»: eso lleva a 1981, pero allí no figura ningún año de fundación. Una prueba de Cigar Coop (febrero de 2012) y algunos minoristas sitúan la introducción de Excalibur en los años setenta. La página de la marca registrada no pudo leerse (403). La línea Dark Knight salió de la gama 1066 en 2010, según Cigar Coop.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La fecha de nacimiento no está establecida igual por todos, y esta ficha lo dice en lugar de elegir en silencio. Cigar Aficionado, en mayo de 2021, daba la línea por cuarentona ese año — es decir, 1981. Cigar Advisor fecha en 1992 su lanzamiento como línea Hoyo de Monterrey, lo que se entiende si se distingue la marca europea de su llegada bajo el nombre Hoyo en Estados Unidos. Algunos minoristas hablan de los años setenta. El atlas retiene 1981, por ser la fuente más precisa.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Das Geburtsdatum weicht je nach Seite voneinander ab. Im Mai 2021 kündigte die Fachpresse die 40 Jahre der Marke „in diesem Jahr“ an: Das führt zu 1981, doch ein Gründungsjahr steht dort nicht. Ein Test von Cigar Coop (Februar 2012) und Händler verorten die Einführung von Excalibur in den 1970er-Jahren. Die Seite der eingetragenen Marke konnte nicht gelesen werden (403). Die Linie Dark Knight ging 2010 laut Cigar Coop aus der Reihe 1066 hervor.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Das Gründungsjahr wird nicht von allen gleich angegeben, und dieser Eintrag sagt das, statt stillschweigend zu wählen. Cigar Aficionado nannte die Linie im Mai 2021 vierzigjährig — also 1981. Cigar Advisor datiert ihren Start als Hoyo-de-Monterrey-Linie auf 1992, was sich erklärt, wenn man die europäische Marke von ihrer Ankunft unter dem Hoyo-Namen in den USA unterscheidet. Händler sprechen von den 1970er-Jahren. Der Atlas hält an 1981 fest, nach der genauesten Quelle.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('出生日期各页说法不一。2021年5月，行业媒体称该品牌「今年」迎来40周年：由此推得1981年，但那里并未写明创立年份。Cigar Coop 的一篇测评（2012年2月）和零售商则把 Excalibur 的推出定在1970年代。注册商标页面无法读取（403）。据 Cigar Coop，Dark Knight 系列于2010年自 1066 系列推出。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('创立年份并非人人一致，本词条选择说明分歧，而不是默默择一。《雪茄爱好者》2021年5月称该系列当年「四十岁」，即1981年。Cigar Advisor 则将其作为 Hoyo de Monterrey 系列的推出定在1992年——若把欧洲的牌子与它在美国以 Hoyo 之名登场区分开来，这就说得通。零售商则提到1970年代。本图集采信最精确的来源，取1981年。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('يختلف تاريخ الميلاد بحسب الصفحات. ففي أيار/مايو 2021 أعلنت الصحافة المتخصصة بلوغ العلامة الأربعين «هذه السنة»: وهذا يقود إلى 1981، لكن لا تُذكر هناك سنة تأسيس. ويضع اختبارٌ من Cigar Coop (شباط/فبراير 2012) وبعض البائعين طرح Excalibur في سبعينيات القرن الماضي. أما صفحة العلامة المسجلة فتعذّرت قراءتها (403). وخرج خط Dark Knight من مجموعة 1066 سنة 2010 بحسب Cigar Coop.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('سنة النشأة ليست مقرَّرة على نحو واحد عند الجميع، وهذه البطاقة تقول ذلك بدل أن تختار في صمت. فمجلة Cigar Aficionado وصفت الخط في أيار/مايو 2021 بأنه بلغ الأربعين تلك السنة، أي 1981. أما Cigar Advisor فتؤرّخ إطلاقه كخط تابع لأويو دي مونتيري بسنة 1992، وهو ما يُفهم إذا فُرِّق بين العلامة الأوروبية وبين وصولها إلى الولايات المتحدة تحت اسم أويو. ويذكر بائعون سبعينيات القرن الماضي. ويأخذ الأطلس بسنة 1981، اعتمادًا على أدقّ المصادر.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('La vente de Villazon à General Cigar est datée de 1997 par la presse du métier (obituaire de Dan Blumenthal, 2011) et de 1996 par un entretien de Llaneza paru en 1999, qui donne 91 millions de dollars ; les deux versions ne se tranchent pas ici. Excalibur appartient depuis à General Cigar, filiale du Scandinavian Tobacco Group, qui fabrique tous les Hoyo de Monterrey non cubains. En mai 2021, la presse du métier place la fabrication à la HATSA de Danlí ; Cigar Coop (2012) écrivait Cofradía. En 2022, Dion Giolito (Illusione) et STG ont sorti une édition limitée Excalibur roulée au Nicaragua.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('En 1997, Llaneza et son associé vendirent Villazon à General Cigar pour 81,4 millions de dollars. Excalibur appartient depuis à cet ensemble, aujourd''hui filiale du Scandinavian Tobacco Group, et se fabrique à la HATSA de Danlí — la fabrique où furent roulés pendant des décennies El Rey del Mundo, Hoyo de Monterrey et Punch.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('The sale of Villazon to General Cigar is dated 1997 by the trade press (Dan Blumenthal''s obituary, 2011) and 1996 by a Llaneza interview published in 1999, which gives 91 million dollars; the two versions cannot be settled here. Excalibur has belonged since then to General Cigar, a subsidiary of Scandinavian Tobacco Group, which makes all the non-Cuban Hoyo de Monterrey. In May 2021, the trade press places manufacture at the HATSA in Danlí; Cigar Coop (2012) wrote Cofradía. In 2022, Dion Giolito (Illusione) and STG released a limited-edition Excalibur rolled in Nicaragua.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('In 1997, Llaneza and his partner sold Villazon to General Cigar for 81.4 million dollars. Excalibur has belonged to that group ever since — today a subsidiary of Scandinavian Tobacco Group — and is made at the HATSA factory in Danlí, where El Rey del Mundo, Hoyo de Monterrey and Punch were rolled for decades.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('La venta de Villazon a General Cigar se fecha en 1997 según la prensa del sector (obituario de Dan Blumenthal, 2011) y en 1996 según una entrevista a Llaneza publicada en 1999, que da 91 millones de dólares; aquí no se puede zanjar entre las dos versiones. Excalibur pertenece desde entonces a General Cigar, filial del Scandinavian Tobacco Group, que fabrica todos los Hoyo de Monterrey no cubanos. En mayo de 2021, la prensa del sector sitúa la fabricación en la HATSA de Danlí; Cigar Coop (2012) escribía Cofradía. En 2022, Dion Giolito (Illusione) y STG sacaron una edición limitada de Excalibur liada en Nicaragua.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('En 1997, Llaneza y su socio vendieron Villazon a General Cigar por 81,4 millones de dólares. Excalibur pertenece desde entonces a ese conjunto, hoy filial del Scandinavian Tobacco Group, y se fabrica en la HATSA de Danlí, la fábrica donde se liaron durante décadas El Rey del Mundo, Hoyo de Monterrey y Punch.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Den Verkauf von Villazon an General Cigar datiert die Fachpresse auf 1997 (Nachruf auf Dan Blumenthal, 2011), ein 1999 erschienenes Interview mit Llaneza auf 1996; es nennt 91 Millionen Dollar. Die beiden Fassungen lassen sich hier nicht entscheiden. Excalibur gehört seither zu General Cigar, einer Tochter der Scandinavian Tobacco Group, die alle nichtkubanischen Hoyo de Monterrey herstellt. Im Mai 2021 verlegt die Fachpresse die Fertigung in die HATSA in Danlí; Cigar Coop (2012) schrieb Cofradía. 2022 brachten Dion Giolito (Illusione) und STG eine limitierte Excalibur-Edition heraus, die in Nicaragua gerollt wurde.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('1997 verkauften Llaneza und sein Partner Villazon für 81,4 Millionen Dollar an General Cigar. Seither gehört Excalibur zu dieser Gruppe, heute eine Tochter der Scandinavian Tobacco Group, und wird in der HATSA in Danlí gefertigt — jener Fabrik, in der jahrzehntelang El Rey del Mundo, Hoyo de Monterrey und Punch gerollt wurden.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('关于 Villazon 售予 General Cigar 的时间，行业媒体（Dan Blumenthal 的讣告，2011年）定为1997年，Llaneza 1999年发表的一篇访谈则定为1996年，并给出9100万美元；两种说法在此无法定夺。此后 Excalibur 归 General Cigar 所有，后者是 Scandinavian Tobacco Group 的子公司，生产所有非古巴的 Hoyo de Monterrey。2021年5月，行业媒体把制造地点放在 Danlí 的 HATSA；Cigar Coop（2012年）写的则是 Cofradía。2022年，Dion Giolito（Illusione）与 STG 推出了一款在尼加拉瓜卷制的 Excalibur 限量版。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('1997年，利亚内萨与合伙人以8140万美元将 Villazon 售予 General Cigar。此后 Excalibur 一直属于该集团——今日为斯堪的纳维亚烟草集团的子公司——在丹利的 HATSA 厂制造；那正是数十年间卷制 El Rey del Mundo、Hoyo de Monterrey 与 Punch 的厂房。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Excalibur'
UNION ALL SELECT 'Excalibur', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('تؤرّخ الصحافة المتخصصة بيع Villazon إلى General Cigar بسنة 1997 (نعي Dan Blumenthal، 2011)، وتؤرّخه مقابلة مع Llaneza نُشرت سنة 1999 بسنة 1996 وتذكر 91 مليون دولار؛ ولا يُفصل بين الروايتين هنا. وتنتمي Excalibur منذ ذلك الحين إلى General Cigar، التابعة لمجموعة Scandinavian Tobacco Group، التي تصنع جميع سيجار Hoyo de Monterrey غير الكوبي. وفي أيار/مايو 2021 تضع الصحافة المتخصصة التصنيع في HATSA بمدينة Danlí؛ وكتبت Cigar Coop (2012) Cofradía. وفي 2022 أصدر Dion Giolito (Illusione) وSTG طبعة محدودة من Excalibur لُفّت في نيكاراغوا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Excalibur'
